// Content for Looking After You (node g63, Parenthood, Chapter 8): NEW v2 build to GDD 63 (mechanic-embodying),
// the parent's-OWN-wellbeing node and a HIGH-CARE one: you can't pour from an empty cup. 84 researched,
// India-grounded scenarios across empty-cup → your-needs-count → baby-blues-and-beyond → reach-out →
// healthy-coping → tools-and-help, each encoded as one of the shared v2 play actions (strike-rewrite / branch /
// reflect / sort / match / role-play / spot): no binary "tap the right card". Lead: strike-rewrite (bust the
// myth), branch (your move), reflect. Six modes: the empty cup (spot burnout; busts "good parents sacrifice
// everything": self-care is part of childcare, not selfish; struggling is not failing), your needs count
// (protect your needs, identity & a little time of your own without guilt; you're still a whole person), baby
// blues and beyond (normalise the common, passing baby blues AND recognise postpartum depression & anxiety: in
// yourself, a partner, and in FATHERS too; frightening intrusive thoughts treated as a SYMPTOM and a cue to get
// help, never a verdict), reach out (help-seeking is strength not weakness; build a support net; you needn't be in
// crisis to deserve help), healthy coping (safe strategies under load: rest, breathe, move, connect, accept help;
// unhealthy coping gently swapped out; NEVER any pain/discomfort technique), tools & help (a breathing space, a
// help-finder and crisis routing). HIGH-CARE and non-shaming: any sign of postnatal depression/anxiety, or any
// crisis, is met with warmth and an IMMEDIATE route to help (concern + resources); healthy coping only and
// explicitly NOT therapy: always signposting professional care; includes fathers and addresses joint-family
// pressure & stigma. Builds on Mind & Belonging (g49) and Bounce (g39); protects the parent so they can do
// everything else in Chapter 8. India: postpartum depression affects ~1 in 5 (about 22%) Indian mothers, nearly
// double the global average and badly under-recognised amid heavy expectations and stigma: and fathers can be
// affected too (~1 in 10); routes to Tele-MANAS 14416, a doctor, and emergency 112. gameId
// "looking-after-you".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"ly-001","cat":"empty-cup","type":"strike-rewrite","hook":"\"A good parent sacrifices everything and needs nothing for themselves.\"","myth":{"un":"A good parent sacrifices everything and needs nothing for themselves.","re":"You can't pour from an empty cup; looking after yourself is part of looking after your child, not selfish.","why":"A depleted parent has less to give."},"relearn":"Self-care is part of childcare, not selfishness; an empty cup pours nothing.","persona":"Divya","source":"empty cup"},
  {"id":"ly-002","cat":"empty-cup","type":"strike-rewrite","hook":"\"Burnout is just normal tiredness you should push through.\"","myth":{"un":"Burnout is just normal tiredness you should push through.","re":"Parental burnout is real, ongoing exhaustion, detachment and feeling overwhelmed, and it's a signal to rest and get support, not push harder.","why":"Burnout is a signal, not a weakness."},"relearn":"Parental burnout is real and a signal to rest and get support, not just tiredness to push through.","persona":"Divya","source":"burnout is real"},
  {"id":"ly-003","cat":"empty-cup","type":"sort","hook":"Sort: a sign of parental burnout to take seriously, or ordinary busy-day tiredness?","items":[{"id":"a","text":"Feeling constantly drained and detached"},{"id":"b","text":"A single rough, sleepless night"},{"id":"c","text":"Dreading each day, nothing left to give"},{"id":"d","text":"Being tired after a long outing"},{"id":"e","text":"Weeks of feeling numb to everyone"},{"id":"f","text":"A sleepy afternoon after a heavy lunch"}],"bins":[{"id":"burnout","label":"Burnout signal","valence":"uhoh"},{"id":"ordinary","label":"Ordinary tiredness","valence":"neutral"}],"key":{"a":"burnout","b":"ordinary","c":"burnout","d":"ordinary","e":"burnout","f":"ordinary"},"relearn":"Constant drain, dread and weeks of numbness are burnout signals; a rough night or post-lunch tiredness is ordinary.","persona":"any","source":"burnout vs tired"},
  {"id":"ly-004","cat":"empty-cup","type":"branch","persona":"Divya","source":"refuel to give","hook":"You're running on empty but feel guilty even thinking about your own needs.","steps":[{"prompt":"At five o'clock you realise you haven't eaten or sat down all day. What do you do?","options":[{"text":"Sit and eat while the baby naps","then":"The food is warm and the chair is still. You feel a little more steady.","best":true},{"text":"Clean the kitchen while the baby sleeps","then":"The kitchen shines. Your head is foggy by dinner."},{"text":"Grab a biscuit standing at the counter","then":"You get through the evening on sugar and nerves."},{"text":"Wait until everyone else has eaten","then":"The house eats. There's little left, and you're too tired to mind."}],"why":"Feeding yourself is part of caring for the baby, and a small break counts."},{"prompt":"Your mother-in-law says a good mother puts her baby first, always. What do you say?","options":[{"text":"Say a rested mother gives more, so you'll rest a little","then":"She hesitates. \"Hmm. Well, rest a little.\"","best":true},{"text":"Nod and say nothing, then push on through the evening","then":"She looks satisfied. You push on with your head down."},{"text":"Snap that she doesn't understand how hard it is","then":"She stiffens and leaves the room."},{"text":"Say she's right and skip your evening rest","then":"She smiles. You skip the rest and pay for it tomorrow."}],"why":"Resting helps you give more, and that is putting the baby first too."},{"prompt":"A friend invites you for a short walk tomorrow. What do you do?","options":[{"text":"Say yes and ask your partner to cover","then":"Your partner agrees. The walk is short and you return lighter.","best":true},{"text":"Say no, since you should be at home","then":"Your friend says maybe another time. The day stays inside."},{"text":"Say yes, then cancel at the last minute","then":"She says it's fine. The afternoon lengthens."},{"text":"Say you'll come when the baby is older","then":"She says of course. Nothing gets booked."}],"why":"A little time of your own is a real need and helps you feel like yourself."}],"debrief":"Caring for yourself refuels your capacity to parent; depleting yourself helps no one.","relearn":"Refuel as part of caring for your child; self-depletion isn't devotion."},
  {"id":"ly-005","cat":"empty-cup","type":"match","hook":"Match each sign to what it's telling you.","pairs":[{"left":"Constant exhaustion and dread","right":"You're burning out, rest and get support"},{"left":"Snapping at everyone","right":"Your reserves are empty, refill them"},{"left":"Feeling numb to things you loved","right":"A signal to reach out for help"},{"left":"Getting ill again and again","right":"Your body is asking for real rest"},{"left":"No interest in anything that's yours","right":"Protect a small thing just for you"}],"relearn":"Exhaustion, short temper, numbness, illness and lost interest are signals to rest, refill, reach out and protect your own time.","persona":"any","source":"what signs tell you"},
  {"id":"ly-006","cat":"empty-cup","type":"reflect","hook":"Lensy: looking after yourself isn't taking away from your child; it's part of what you give them. Sit right?","prompt":"What do you think?","options":["Sits right","Part of giving","For them too"],"affirm":"Self-care isn't taken from your child; a steadier, refuelled parent is part of what you give them.","relearn":"Looking after yourself is part of what you give your child, not something taken from them.","persona":"any","source":"part of giving"},
  {"id":"ly-007","cat":"empty-cup","type":"spot","hook":"Lensy: spot the two unhealthy responses to running on empty, the ones that make it worse.","scene":[{"id":"a","text":"Resting and accepting help when you can","trick":false},{"id":"b","text":"Pushing harder until you collapse","trick":true},{"id":"c","text":"Naming the burnout and reaching out","trick":false},{"id":"d","text":"Hiding how bad it is so no one worries","trick":true},{"id":"e","text":"Letting a partner take a shift tonight","trick":false}],"why":"Pushing to collapse and hiding how bad it is both deepen burnout; resting, naming it and sharing the load refill you.","relearn":"Push-to-collapse and hiding it worsen burnout; rest, naming it and shared shifts help.","persona":"Vikram","source":"healthy response"},
  {"id":"ly-008","cat":"empty-cup","type":"strike-rewrite","hook":"\"If I admit I'm struggling as a parent, I'm failing.\"","myth":{"un":"If I admit I'm struggling as a parent, I'm failing.","re":"Struggling is not failing; parenting is genuinely hard, and naming the struggle is the brave first step to coping.","why":"Honesty about struggle is strength."},"relearn":"Admitting you're struggling isn't failing; it's the brave first step toward getting the support you need.","persona":"Divya","source":"struggle isn't failing"},
  {"id":"ly-009","cat":"empty-cup","type":"branch","persona":"Divya","source":"small refills","hook":"You haven't had a moment to yourself in so long you've stopped noticing how depleted you are.","steps":[{"prompt":"You catch your reflection and can't remember the last time you felt rested. What do you do?","options":[{"text":"Admit you're running low and pick one refill today","then":"You choose a quiet cup of tea. It feels small and real.","best":true},{"text":"Tell yourself it's the baby stage and push on","then":"You push on. The tiredness settles in for another month."},{"text":"Plan a big getaway for later this year","then":"The plan is exciting. Today is as empty as yesterday."},{"text":"Add more chores so you feel productive","then":"The list grows. So does the fog in your head."}],"why":"Noticing you're running low is the first step to refilling."},{"prompt":"Your partner Ajay offers to take the baby for twenty minutes. What do you do?","options":[{"text":"Accept and use the time only for you","then":"You sit in the sun for twenty minutes. The baby is fine and so are you.","best":true},{"text":"Accept, then spend it on chores","then":"The chores are done. You're still empty."},{"text":"Refuse since he's had a long day","then":"He says okay. The offer doesn't come again this week."},{"text":"Accept, then hover to check on him","then":"You keep checking, and never quite settle."}],"why":"A partner's offer is a real refill, and it's yours to use."},{"prompt":"By Friday the baby has a rough day, and any time for yourself vanishes. What do you do?","options":[{"text":"Take a two-minute pause anyway, and try again tomorrow","then":"Two slow breaths by the window. Tomorrow feels a bit more possible.","best":true},{"text":"Decide there's no point trying this week","then":"The week ends. The tiredness quietly returns."},{"text":"Blame yourself and plan a longer break for next week","then":"The list grows. So does the pressure."},{"text":"Wait for a quieter month to look after yourself","then":"The quiet month doesn't arrive."}],"why":"Small refills survive rough days, and even two minutes keeps the habit going."}],"debrief":"Protect small, regular refills; don't wait for a free day that never arrives.","relearn":"Build tiny regular refills in now; don't wait for a someday free day."},
  {"id":"ly-010","cat":"empty-cup","type":"reflect","hook":"Lensy: even the most devoted parent has limits, and respecting yours keeps you in the game. Land okay?","prompt":"What's your take?","options":["Lands okay","I have limits","Respect them"],"affirm":"Every parent has limits; respecting yours, rather than overriding them, is what keeps you going for your child.","relearn":"Even the most devoted parent has limits; respecting yours keeps you going.","persona":"any","source":"respect limits"},
  {"id":"ly-011","cat":"empty-cup","type":"sort","hook":"Sort: protects a parent from burnout, or speeds it up?","items":[{"id":"a","text":"Accepting help and sharing the load"},{"id":"b","text":"Doing everything alone, always"},{"id":"c","text":"Small daily moments of rest"},{"id":"d","text":"Guilt over any break"},{"id":"e","text":"Letting some tasks be 'good enough'"},{"id":"f","text":"Comparing yourself to other parents"}],"bins":[{"id":"protects","label":"Protects you","valence":"pos"},{"id":"speeds","label":"Speeds burnout","valence":"neg"}],"key":{"a":"protects","b":"speeds","c":"protects","d":"speeds","e":"protects","f":"speeds"},"relearn":"Accepting help, small rests and 'good enough' protect you; doing it all alone, break-guilt and comparison speed burnout.","persona":"any","source":"protect vs speed"},
  {"id":"ly-012","cat":"empty-cup","type":"branch","persona":"Priya","source":"support a parent","hook":"Your fellow parent Kavya admits over chai that she's completely burnt out.","steps":[{"prompt":"Kavya says she's ashamed of how she feels. What do you say?","options":[{"text":"Say it's common and nothing to be ashamed of","then":"Her shoulders drop. \"Really? I thought it was just me.\"","best":true},{"text":"Tell her everyone copes and to toughen up","then":"She nods and stops talking."},{"text":"Tell her to be grateful for what she has","then":"She whispers: \"I am.\" The shame deepens."},{"text":"Say you feel the same and talk about yourself","then":"You talk for ten minutes. She goes quiet and listens."}],"why":"Saying it's common eases the shame and lets her keep talking."},{"prompt":"Kavya says she doesn't even know where to start. What do you say?","options":[{"text":"Ask what would help most this week","then":"She thinks. \"Sleep. An hour to myself.\"","best":true},{"text":"Give her a long list of tips to try","then":"She thanks you, then feels more overwhelmed."},{"text":"Tell her to book a spa day","then":"She smiles. \"With what time?\""},{"text":"Say she'll figure it out","then":"She nods. She doesn't have a plan."}],"why":"Asking what she needs keeps her in charge of her own recovery."},{"prompt":"Kavya says her husband thinks she's exaggerating. What do you say?","options":[{"text":"Offer to sit with her while she talks to him","then":"She looks relieved. \"I'd like that.\"","best":true},{"text":"Tell her to stop bringing it up with him","then":"She nods. The gap between them grows."},{"text":"Say you'll tell him yourself on her behalf","then":"She winces. \"Please don't. I want to say it.\""},{"text":"Say he's probably just tired too","then":"She nods. Her exhaustion is still unheard."}],"why":"Offering to sit beside her lets her tell him without being talked over."},{"prompt":"Two weeks later, Kavya is still exhausted. What do you do?","options":[{"text":"Suggest she also talk to a doctor or Tele-MANAS 14416","then":"She nods. \"Maybe it's time. Can you help me find one?\"","best":true},{"text":"Tell her to push through a little longer","then":"She nods. The weeks continue."},{"text":"Stop checking in, since you've said your piece","then":"She waits for your message. It doesn't come."},{"text":"Say she should be over it by now","then":"She looks stung and doesn't reply."}],"why":"Support and a doctor or helpline go further than pushing, and it's not her fault."}],"debrief":"Meet a burnt-out parent with 'it's common, not shameful' and help finding support, never 'toughen up'.","relearn":"Support a burnt-out parent with warmth and help, not 'toughen up'."},
  {"id":"ly-013","cat":"your-needs-count","type":"strike-rewrite","hook":"\"Once you're a parent, your own needs and identity stop mattering.\"","myth":{"un":"Once you're a parent, your own needs and identity stop mattering.","re":"You're still a whole person with real needs and an identity; keeping them alive makes you a steadier parent.","why":"A self is the ground you parent from."},"relearn":"Your needs and identity still matter as a parent; keeping them alive makes you steadier, not selfish.","persona":"Divya","source":"you still matter"},
  {"id":"ly-014","cat":"your-needs-count","type":"sort","hook":"Sort: a legitimate parent's need, or a 'selfish' want to feel guilty about?","items":[{"id":"a","text":"Some sleep and rest"},{"id":"b","text":"A little time for yourself"},{"id":"c","text":"Adult connection and support"},{"id":"d","text":"Keeping one thing you love"},{"id":"e","text":"A meal you eat sitting down"},{"id":"f","text":"Help with the night feeds"}],"bins":[{"id":"need","label":"Legitimate need","valence":"pos"},{"id":"guilt","label":"Nothing to feel guilty for","valence":"pos"}],"key":{"a":"need","b":"guilt","c":"need","d":"guilt","e":"need","f":"guilt"},"relearn":"Rest, a little time, connection, a thing you love, a calm meal and help at night are all legitimate needs.","persona":"any","source":"needs not guilt"},
  {"id":"ly-015","cat":"your-needs-count","type":"strike-rewrite","hook":"\"Taking any time for yourself makes you a bad, selfish parent.\"","myth":{"un":"Taking any time for yourself makes you a bad, selfish parent.","re":"A little time for yourself refills you and models healthy self-respect for your child; it's good parenting.","why":"Modelling self-respect teaches your child."},"relearn":"Taking a little time for yourself isn't selfish; it refills you and models self-respect for your child.","persona":"Divya","source":"time isn't selfish"},
  {"id":"ly-016","cat":"your-needs-count","type":"branch","persona":"Divya","source":"reclaim identity","hook":"You feel you've vanished into being \"just a parent\" and miss who you were.","steps":[{"prompt":"Your old friend Meera invites you for a Saturday coffee. What do you do?","options":[{"text":"Say yes and ask your partner to cover an hour","then":"Meera sends three hearts. Saturday now has something in it that is yours.","best":true},{"text":"Say you'll come next time, when things calm down","then":"Meera replies kindly. \"Next time\" has no date yet."},{"text":"Say yes, but only if the baby comes along the whole time","then":"Meera says of course. The talk stays on the baby and you leave feeling the same."},{"text":"Say you have nothing to talk about these days","then":"Meera writes back that she'd love to hear about anything. You leave it unanswered."}],"why":"A small plan of your own brings back the part of you that isn't only \"parent\"."},{"prompt":"Your partner Arjun spots your old sketchbook on the shelf and asks about it. What do you do?","options":[{"text":"Say you miss drawing and try ten minutes tonight","then":"You sketch a wonky mango. It takes ten minutes and you smile anyway.","best":true},{"text":"Say it's from another life and put it back","then":"Arjun nods. The sketchbook goes back behind the cookbooks."},{"text":"Say you'll start again once the baby is older","then":"Arjun agrees. The sketchbook stays shut for another year."},{"text":"Say you miss it, but drawing feels selfish now","then":"Arjun says it isn't. You tell yourself he's only being kind."}],"why":"Ten minutes of something you love is small enough to actually do."},{"prompt":"At a family function, an aunt introduces you only as \"the baby's mother\". What do you do?","options":[{"text":"Smile and add your name and something you're up to","then":"The aunt asks a follow-up question. For a minute, someone is curious about you.","best":true},{"text":"Let it pass. It's simpler that way","then":"The moment goes by. You feel a little more invisible in the crowd."},{"text":"Correct her sharply in front of everyone","then":"The room goes quiet. She is stung and the moment turns awkward."},{"text":"Joke that you've forgotten who you were","then":"People laugh. You laugh too, and it stings afterwards."}],"why":"Saying who you are, warmly, keeps you a whole person in the room."},{"prompt":"Weeks on, a voice in your head says the old you is gone for good. What do you do?","options":[{"text":"List three things that are still you and keep one this week","then":"The list surprises you. You put a walk on Thursday and keep it.","best":true},{"text":"Accept that the old you is gone for good","then":"The list of what you miss gets longer. The days feel flatter."},{"text":"Wait for a big change, like going back to work","then":"Months could pass. Small pieces are lost while you wait."},{"text":"Try to bring back everything at once this weekend","then":"By Sunday night you're exhausted and drop all of it."}],"why":"The old you isn't gone, and small pieces you keep make you steadier for your child."}],"debrief":"Reclaim small pieces of your identity; the 'old you' isn't gone for good, and you parent better whole.","relearn":"Reclaim bits of who you are. Parenthood needn't erase you."},
  {"id":"ly-017","cat":"your-needs-count","type":"match","hook":"Match each small act to the need it meets.","pairs":[{"left":"Ten quiet minutes with chai","right":"A moment to breathe"},{"left":"A call with an old friend","right":"Adult connection"},{"left":"Twenty minutes on a hobby","right":"Keeping your own spark"},{"left":"A short walk alone","right":"Space to clear your head"},{"left":"An early night to bed","right":"Rest you've been missing"}],"relearn":"Small acts, a quiet chai, a friend's call, a hobby, a walk, an early night, each meet a real need that keeps a parent whole.","persona":"any","source":"acts meet needs"},
  {"id":"ly-018","cat":"your-needs-count","type":"reflect","hook":"Lensy: your child benefits from a parent who is also still a person. Feel the truth of that?","prompt":"What do you think?","options":["I feel it","Still a person","True"],"affirm":"A child benefits from a parent who remains a whole person, not one who has erased themselves entirely.","relearn":"Your child benefits from a parent who's also still a whole person.","persona":"any","source":"still a person"},
  {"id":"ly-019","cat":"your-needs-count","type":"role-play","persona":"Divya","source":"ask without guilt","hook":"You want an hour to yourself today and need your partner Kiran to cover.","setup":"He is on the sofa with the baby.","steps":[{"prompt":"Kiran looks up and asks: \"You seem restless. What's up?\"","options":[{"text":"\"I need an hour to myself today to recharge. Can you take over?\"","then":"Kiran looks surprised, then nods. \"Okay. Tell me how to do it right.\"","best":true},{"text":"\"Sorry to ask. Ignore me if it's too much. I'll manage somehow.\"","then":"Kiran frowns. \"Manage what? Tell me what's going on.\""},{"text":"\"Nothing. I'm just tired, I suppose. Never mind me.\"","then":"Kiran doesn't quite buy it. \"You keep saying that. What do you need?\""},{"text":"\"You never give me any time to myself. Ever.\"","then":"Kiran stiffens. \"That's not fair. But tell me what would help.\""}],"why":"Asking plainly for an hour is clear and easy for him to say yes to."},{"prompt":"Kiran says: \"Tell me what would help. I want to get it right.\"","options":[{"text":"\"An hour on my own today. It'll help me be a better parent.\"","then":"Kiran smiles. \"Fair enough. That makes sense.\"","best":true},{"text":"\"Forget it. It's selfish to want time when there's so much to do.\"","then":"Kiran shakes his head. \"It isn't selfish. Say it anyway.\""},{"text":"\"Everything, honestly! I'm exhausted and you never help!\"","then":"Kiran flinches. \"That's harsh, but I hear you. Where do we start?\""},{"text":"\"Nothing much. I'll ask another day, maybe.\"","then":"Kiran nods, unsure. \"Let's work out today at least.\""}],"why":"Saying what the hour is for shows it's a need, not a whim."},{"prompt":"Kiran says: \"Let's sort today. What time, and what do I need to do?\"","options":[{"text":"\"Now until six. Feeds at four, and there's milk in the fridge.\"","then":"Kiran repeats it. \"Four o'clock feed. Got it. Enjoy yourself.\"","best":true},{"text":"\"Whenever suits you. I'll fit in around you and the baby.\"","then":"Kiran shrugs. \"Okay.\" You end up back in forty minutes."},{"text":"\"I'll be back at some point. You'll work it out.\"","then":"Kiran looks unsure. \"Some point when?\""},{"text":"\"Let me write out a full list of instructions first.\"","then":"Kiran waits while you write. The hour shrinks to twenty minutes."}],"why":"A clear time and a short handover let him take charge and let you relax."},{"prompt":"Later, Kiran asks: \"Can we make it a regular thing?\"","options":[{"text":"\"Yes. One hour, the same day each week, and you get one too.\"","then":"Kiran grins. \"Tuesdays for you, Saturdays for me?\"","best":true},{"text":"\"Let's see how the month goes first.\"","then":"Kiran nods. The month goes by without a plan."},{"text":"\"It's fine. Only when I'm desperate.\"","then":"Kiran nods. By the time you ask, you're already frayed."},{"text":"\"No. It felt selfish. I'll just ask when I must.\"","then":"Kiran looks unconvinced. The next hour doesn't arrive."}],"why":"A regular slot for both of you keeps the break from vanishing."}],"relearn":"Asking plainly and guilt-free for what you need makes it likelier to happen and models healthy needs."},
  {"id":"ly-020","cat":"your-needs-count","type":"spot","hook":"Spot the two beliefs that quietly erase a parent's own self.","scene":[{"id":"a","text":"Guarding a little time of your own","trick":false},{"id":"b","text":"Feeling you must be 'on' every single hour","trick":true},{"id":"c","text":"Staying connected to who you are","trick":false},{"id":"d","text":"Believing your needs must always come last","trick":true},{"id":"e","text":"Keeping one thing that's just yours","trick":false}],"why":"'On every hour' and 'needs always last' are the beliefs that erase you; guarding time and staying yourself keep you whole.","relearn":"Keep your self alive by guarding a little time and staying connected to who you are.","persona":"any","source":"self alive"},
  {"id":"ly-021","cat":"your-needs-count","type":"strike-rewrite","hook":"\"A parent's only job is the child; their own happiness is irrelevant.\"","myth":{"un":"A parent's only job is the child; their own happiness is irrelevant.","re":"A parent's wellbeing shapes the home and the child; your happiness matters in its own right and for them.","why":"Happy parents help raise happy kids."},"relearn":"Your happiness as a parent matters, both in itself and because it shapes the home your child grows up in.","persona":"Vikram","source":"your happiness matters"},
  {"id":"ly-022","cat":"your-needs-count","type":"branch","persona":"Priya","source":"both fit","hook":"Relatives imply that wanting time or space makes you ungrateful for your child.","steps":[{"prompt":"At dinner an aunt sighs that parents today want too much \"me time\". What do you do?","options":[{"text":"Say you love your child and you still need some time","then":"The aunt raises an eyebrow. Your partner squeezes your hand under the table.","best":true},{"text":"Laugh it off and say you barely get any anyway","then":"Some people laugh. The aunt takes it as agreement and sighs again."},{"text":"Apologise and say you'll manage without any","then":"The aunt looks satisfied. You feel your evening plans quietly shrink."},{"text":"Argue that she never had your kind of pressure","then":"Voices rise and the table goes quiet. She is offended and nothing changes."}],"why":"You can love your child and need time, and saying both calmly holds your ground."},{"prompt":"Later that week you plan an hour out, and a cousin texts that it seems soon to leave the baby. What do you reply?","options":[{"text":"Say your partner has the baby and you'll be back refreshed","then":"She sends a thumbs up. Your partner smiles as you leave.","best":true},{"text":"Cancel the hour, since it isn't worth the comments","then":"The comments stop. So does the hour, and the evening feels smaller."},{"text":"Say you already feel guilty enough without her advice","then":"She goes quiet. The message feels sharper than you meant it."},{"text":"Write a long message justifying every minute of it","then":"You spend the hour drafting. The hour was meant to be for you."}],"why":"A short, calm answer protects your hour without a family fight."},{"prompt":"You're worn out and your partner Sonal asks what you need. What do you say?","options":[{"text":"Name it plainly: an hour on Saturday and an early night","then":"Sonal nods and puts both in the calendar. \"Done. I'll take the baby.\"","best":true},{"text":"Say you're fine and it's the baby who needs things","then":"Sonal nods and moves on. Your tiredness stays exactly where it was."},{"text":"Shrug and say you don't know","then":"Sonal waits, then says she'll leave you to it. Nothing changes."},{"text":"List every complaint from the last few months","then":"Sonal gets defensive. The list is long, but the plan is missing."}],"why":"Naming a specific need is easier to meet than hoping it gets noticed."},{"prompt":"Weeks later, you're about to leave for an hour to yourself when your child cries. Guilt rushes back. What do you do?","options":[{"text":"Hug your child, say you'll be back, and go","then":"The crying fades after a few minutes. You return to a calm, cuddly child.","best":true},{"text":"Stay home and cancel, since guilt says love means always being there","then":"The hour is lost. The tiredness comes back that night."},{"text":"Leave in a rush and check your phone every five minutes","then":"The hour slips by watching a screen instead of resting."},{"text":"Cut the hour to fifteen minutes just to be safe","then":"You get home early, less rested and more guilty for asking."}],"why":"A calm goodbye lets your child settle and lets you truly rest."}],"debrief":"Loving your child and having your own needs both fit; don't suppress one to prove the other.","relearn":"You can adore your child and still have needs; don't suppress them to seem grateful."},
  {"id":"ly-023","cat":"your-needs-count","type":"reflect","hook":"Lensy: needing rest, help and a self doesn't make you less of a parent; it makes you a sustainable one. Agree?","prompt":"What's your take?","options":["Agree","Sustainable","Not less"],"affirm":"Needing rest, help and a sense of self makes you a sustainable parent, not a lesser one.","relearn":"Needing rest, help and a self makes you a sustainable parent, not a worse one.","persona":"any","source":"sustainable parent"},
  {"id":"ly-024","cat":"your-needs-count","type":"sort","hook":"Sort: a healthy way to hold your identity as a parent, or one that erases you?","items":[{"id":"a","text":"Both devoted parent and your own person"},{"id":"b","text":"Only ever 'someone's mum or dad'"},{"id":"c","text":"Needs voiced and met sometimes"},{"id":"d","text":"Needs always last, forever"},{"id":"e","text":"Keeping one hobby or friendship alive"},{"id":"f","text":"Giving up everything that was yours"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"erases","label":"Erases you","valence":"neg"}],"key":{"a":"healthy","b":"erases","c":"healthy","d":"erases","e":"healthy","f":"erases"},"relearn":"Being a devoted parent and your own person, with needs and one thing kept alive, is healthy; total self-erasure isn't.","persona":"any","source":"hold identity"},
  {"id":"ly-025","cat":"baby-blues-and-beyond","type":"strike-rewrite","hook":"\"Any sadness after birth is just weakness you should hide.\"","myth":{"un":"Any sadness after birth is just weakness you should hide.","re":"Mild 'baby blues', tearfulness and mood swings in the first days, are very common and usually pass; they're not weakness.","why":"Early blues are a normal, passing wave."},"relearn":"Mild 'baby blues' in the first days are very common and usually pass; they're not weakness to hide.","persona":"Divya","source":"baby blues"},
  {"id":"ly-026","cat":"baby-blues-and-beyond","type":"strike-rewrite","hook":"\"Postnatal depression isn't real; new mothers just need to cheer up.\"","myth":{"un":"Postnatal depression isn't real; new mothers just need to cheer up.","re":"Postpartum depression and anxiety are real, common medical conditions, affecting around one in five mothers in India, and they need care, not 'cheer up'.","why":"It's an illness, not an attitude."},"relearn":"Postpartum depression and anxiety are real, common conditions needing care, not a 'cheer up'.","persona":"Divya","source":"PPD is real"},
  {"id":"ly-027","cat":"baby-blues-and-beyond","type":"sort","persona":"Divya","source":"blues or help","relearn":"A few up-and-down days that lift are likely blues; weeks of low mood, lost interest or constant worry mean seek help.","hook":"Sort: likely short-lived baby blues, or a sign to seek help for postnatal depression or anxiety?","items":[{"id":"a","text":"Tearful and up-and-down for a few days"},{"id":"b","text":"Low, hopeless or anxious for weeks"},{"id":"c","text":"Mood lifting as the first week passes"},{"id":"d","text":"Losing interest in the baby or yourself"},{"id":"e","text":"Mood swings that settle by two weeks"},{"id":"f","text":"Constant racing worry that won't switch off"}],"bins":[{"id":"blues","label":"Likely baby blues","valence":"pos"},{"id":"help","label":"Seek help","valence":"tell"}],"key":{"a":"blues","b":"help","c":"blues","d":"help","e":"blues","f":"help"}},
  {"id":"ly-028","cat":"baby-blues-and-beyond","type":"match","persona":"Divya","source":"step by signs","relearn":"Rest for brief blues, a doctor for lasting symptoms, urgent help for scary thoughts: the step follows how deep the feelings run.","hook":"Match each duration and depth to the gentle next step.","pairs":[{"left":"A few teary days that ease","right":"Rest and support; it usually passes"},{"left":"Low or anxious for two weeks or more","right":"Talk to a doctor or helpline"},{"left":"Frightening thoughts about self or baby","right":"Reach for help right away"},{"left":"Constant racing worry you can't calm","right":"Mention anxiety to a doctor"},{"left":"Numbness and no joy in the baby","right":"Raise it with someone you trust"}]},
  {"id":"ly-029","cat":"baby-blues-and-beyond","type":"strike-rewrite","hook":"\"Only mothers get depressed after a baby; fathers are unaffected.\"","myth":{"un":"Only mothers get depressed after a baby; fathers are unaffected.","re":"Fathers can get postnatal depression too; research suggests around one in ten, so partners should watch out for each other.","why":"Both parents can be affected."},"relearn":"Fathers can get postnatal depression too (research suggests around one in ten); both partners should watch out for each other.","persona":"Vikram","source":"dads too"},
  {"id":"ly-030","cat":"baby-blues-and-beyond","type":"branch","persona":"Divya","source":"tell someone","hook":"For weeks you've felt low, anxious and cut off from your baby, and you're scared to say so.","steps":[{"prompt":"Your mother-in-law asks why you've gone so quiet lately. What do you say?","options":[{"text":"Say it's beyond tiredness and you want to see a doctor","then":"She goes quiet, then nods. \"Tell me when the appointment is.\"","best":true},{"text":"Say you're only tired and it will pass once you sleep","then":"She hands you the baby and moves on. The heaviness is still there that night."},{"text":"Say it's just the baby blues and you'll wait a few more weeks","then":"She agrees it's the blues. Another week goes by and the feeling hasn't shifted."},{"text":"Ask the new-mothers WhatsApp group whether this is normal","then":"Some say it's normal. You still feel alone, and nobody mentions a doctor."}],"why":"Weeks of low, anxious feelings deserve a doctor's eyes, and saying so early makes help easier."},{"prompt":"Your partner Karan sits beside you and asks softly if something is wrong. What do you say?","options":[{"text":"Tell him the truth: weeks of feeling low and far from the baby","then":"He takes your hand. \"Thank you for telling me. What do you need?\"","best":true},{"text":"Say it's nothing and he shouldn't worry","then":"He nods, unsure, and the moment passes. You feel more alone."},{"text":"Say you should be enjoying this, so it must be your fault","then":"He says it isn't, but you can't quite believe him yet."},{"text":"Say you'll sort it out yourself once the baby sleeps through","then":"He says okay, though he looks unsure. The nights stay long and you stay alone with it."}],"why":"Telling him plainly brings a second pair of hands, and how you feel is never your fault."},{"prompt":"A week on, the low feeling is still there and the baby's checkup is today. What do you do?","options":[{"text":"Tell the doctor how you've felt for weeks","then":"The doctor listens without hurry and says it is treatable. She sets up a follow-up.","best":true},{"text":"Talk only about the baby's weight and sleep patterns","then":"The checkup goes smoothly. You leave with the baby's numbers and nothing said about you."},{"text":"Mention it lightly and laugh it off as new-mother nerves","then":"The doctor smiles and says all new mothers feel this way. You don't ask again."},{"text":"Save it for a calmer visit when you have more time","then":"The visit ends on time. The calmer visit doesn't come for weeks."}],"why":"Plain words are enough for a doctor to help. This is treatable and never your fault."}],"debrief":"Lasting low, anxious, disconnected feelings after birth are treatable; tell a trusted person and a doctor.","relearn":"Post-birth low mood is treatable. Reach out, because hiding it only prolongs it."},
  {"id":"ly-031","cat":"baby-blues-and-beyond","type":"spot","persona":"Divya","source":"help signs","relearn":"Lasting low or numb feelings, or losing interest in the baby or in living, are gentle cues to reach for help.","hook":"Spot the two warning signs that say 'reach for help', not just passing blues.","scene":[{"id":"a","text":"Weeks of feeling low, anxious or numb","trick":true},{"id":"b","text":"A couple of teary days that pass","trick":false},{"id":"c","text":"Losing interest in the baby or in living","trick":true},{"id":"d","text":"Mood swings that settle within two weeks","trick":false},{"id":"e","text":"Feeling tired but glad to hold the baby","trick":false}],"why":"Weeks of low or numb feelings, and losing interest in the baby or in living, are the warning signs to reach for help."},
  {"id":"ly-032","cat":"baby-blues-and-beyond","type":"branch","persona":"Vikram","source":"notice your partner","hook":"Your partner Neha has seemed hopeless and withdrawn for weeks since the birth.","steps":[{"prompt":"Neha stares out of the window while the baby sleeps. What do you do?","options":[{"text":"Sit beside her and say you've noticed she's low","then":"She looks at you, eyes filling. \"I didn't think anyone noticed.\"","best":true},{"text":"Suggest a walk outside to lift her mood a little","then":"She says maybe later. She stays where she is."},{"text":"Give her space and hope she comes round soon","then":"She stays quiet all evening. You both go to bed without talking."},{"text":"Ask her mother to talk to her instead of you","then":"Her mother calls and tells her to rest more. Neha says little afterwards."}],"why":"Gently saying what you've noticed lets her know she isn't alone with it."},{"prompt":"Later that week, Neha says quietly that she doesn't know why she feels this way. What do you say?","options":[{"text":"It's common after a birth and treatable. Let's get help","then":"Her shoulders drop a little. \"Together?\" she asks. \"Together,\" you say.","best":true},{"text":"You have a healthy baby and so much to be happy about","then":"She nods and looks away. \"I know,\" she whispers, and feels worse."},{"text":"Every new mother feels like this, so it will pass","then":"She goes quiet, and decides her feelings must not count for much."},{"text":"You just need sleep. I'll take the night feeds","then":"She sleeps longer that night. She wakes just as low."}],"why":"Naming it as common and treatable, and offering to help together, lowers the shame."},{"prompt":"Another week passes and Neha is no better. What do you do?","options":[{"text":"Offer to book a doctor's visit and go with her","then":"She agrees. The doctor listens to you both and sets up a follow-up.","best":true},{"text":"Book the visit yourself without telling her first","then":"She feels ambushed at the clinic and clams up."},{"text":"Give it one more month before you worry","then":"The month goes by. She is quieter still and you feel helpless."},{"text":"Plan outings and small gifts to cheer her up","then":"She thanks you for every one, and stays low."}],"why":"Going with her to a doctor keeps her in charge and starts real help."}],"debrief":"Weeks of hopelessness and withdrawal after birth need gently raising and support; it's treatable.","relearn":"Gently support a partner's post-birth low mood; don't wait for 'snap out of it'."},
  {"id":"ly-033","cat":"baby-blues-and-beyond","type":"reflect","hook":"Lensy: postnatal depression and anxiety are common and treatable; spotting them early changes everything. Hear that?","prompt":"What do you think?","options":["I hear it","Common & treatable","Spot it early"],"affirm":"Postnatal depression and anxiety are common and treatable, and recognising them early makes recovery far more likely.","relearn":"Postnatal depression and anxiety are common and treatable; spotting them early changes everything.","persona":"Divya","source":"common and treatable"},
  {"id":"ly-034","cat":"baby-blues-and-beyond","type":"strike-rewrite","hook":"\"Having a dark or scary thought as a new parent makes you a monster.\"","myth":{"un":"Having a dark or scary thought as a new parent makes you a monster.","re":"Intrusive, frightening thoughts can come with postnatal anxiety and don't make you bad; they're a strong cue to get support quickly.","why":"A scary thought is a symptom, not a verdict."},"relearn":"Frightening intrusive thoughts can come with postnatal anxiety and don't make you bad; they're a cue to get support.","persona":"Divya","source":"thoughts not monster"},
  {"id":"ly-035","cat":"baby-blues-and-beyond","type":"branch","persona":"Divya","source":"reach now","hook":"You keep having frightening thoughts about harming yourself or the baby, and it terrifies you.","steps":[{"prompt":"The thoughts come again while the baby sleeps. What do you do?","options":[{"text":"Call Tele-MANAS 14416 now and say how you are","then":"A calm voice answers. \"Thank you for calling. You're not alone. Tell me how you are.\"","best":true},{"text":"Tell yourself only a bad mother would think this","then":"The shame grows loud. It feels harder to tell anyone."},{"text":"Keep busy with chores until the thoughts go quiet","then":"They fade for now. They return that night and you are still alone with them."},{"text":"Read online about what the thoughts mean","then":"The articles make it feel heavier. None of them offers a person to talk to."}],"why":"The thoughts are a symptom, not a verdict, and a helpline is one call away at any hour."},{"prompt":"Your partner Rohan comes home and asks why you look so shaken. What do you say?","options":[{"text":"Tell him you've had frightening thoughts and need help today","then":"He puts his bag down and holds you. \"I'm glad you told me. We'll get help now.\"","best":true},{"text":"Say it was a hard day and change the subject","then":"He lets it go and you spend the evening alone with it."},{"text":"Tell him a little, but not the frightening part","then":"He suggests an early night. The frightening part stays unspoken."},{"text":"Ask him not to tell his parents, and say nothing more","then":"He promises, puzzled. He doesn't know what he's keeping, and nothing is planned."}],"why":"Saying it plainly to someone close means you aren't alone. It is never your fault."},{"prompt":"The next morning the thoughts are still there. What do you do?","options":[{"text":"Book a doctor's visit today and take Rohan along","then":"The clinic fits you in. The doctor makes a plan, and says to call 112 if it ever feels urgent.","best":true},{"text":"Wait a few days to see if they settle","then":"Two days pass. The thoughts stay and you feel more worn down."},{"text":"Ask a relative for a home remedy","then":"She sends herbal tea and tells you to rest. The thoughts don't stop."},{"text":"Handle it with extra rest and no visitors","then":"The quiet helps a little. The thoughts still come when the house goes still."}],"why":"A doctor can assess and support you quickly, and early help works better."},{"prompt":"Some nights are harder. One night the thoughts feel urgent, and you fear you can't keep yourself or the baby safe. What do you do?","options":[{"text":"Call 112 now, and tell anyone nearby","then":"Help is on its way, and anyone nearby stays with you.","best":true},{"text":"Wait until morning when the clinic opens","then":"The night is long and lonely. The fear does not ease."},{"text":"Text a friend to ring you tomorrow","then":"She replies with a heart. The night stays long and you stay alone with it."},{"text":"Breathe slowly and splash your face with water","then":"The breathing steadies you a little. The urgency is still there when you stop."}],"why":"When you fear you can't keep someone safe, call 112 now. Reaching out is the strong move."}],"debrief":"Frightening thoughts of harm mean reach out for help now; you deserve support, not shame.","relearn":"With frightening thoughts of harm, reach for help now; you're not alone."},
  {"id":"ly-036","cat":"baby-blues-and-beyond","type":"reflect","hook":"Lensy: if it ever feels too heavy or frightening, that's exactly when reaching out matters most. Okay?","prompt":"What's your take?","options":["Okay","I'd reach out","Thank you"],"affirm":"When feelings become too heavy or frightening, reaching out for help is the most important and caring thing to do.","relearn":"When it feels too heavy or frightening, reaching out matters most; help is there and you deserve it.","persona":"Divya","source":"reach when heavy"},
  {"id":"ly-037","cat":"reach-out","type":"strike-rewrite","hook":"\"Asking for help with parenting or your mood means you're a weak parent.\"","myth":{"un":"Asking for help with parenting or your mood means you're a weak parent.","re":"Reaching out is a strength and a skill; the strongest parents build support and ask for help when they need it.","why":"Help-seeking is wisdom, not weakness."},"relearn":"Asking for help isn't weakness; it's a strength, and strong parents build support and reach out.","persona":"Divya","source":"help is strength"},
  {"id":"ly-038","cat":"reach-out","type":"sort","hook":"Sort: a real source of support to lean on, or a barrier to push past?","items":[{"id":"a","text":"A partner, friend or family who'll listen"},{"id":"b","text":"Shame about 'admitting' you struggle"},{"id":"c","text":"A doctor or a helpline"},{"id":"d","text":"The belief you must cope alone"},{"id":"e","text":"A new-parent group who get it"},{"id":"f","text":"Worrying about what people will say"}],"bins":[{"id":"support","label":"Lean on it","valence":"pos"},{"id":"barrier","label":"Push past it","valence":"neg"}],"key":{"a":"support","b":"barrier","c":"support","d":"barrier","e":"support","f":"barrier"},"relearn":"People who'll listen, professionals and a parent group are support to lean on; shame, 'cope alone' and worry are barriers.","persona":"any","source":"support vs barrier"},
  {"id":"ly-039","cat":"reach-out","type":"branch","persona":"Divya","source":"tell one person","hook":"You're struggling, but the idea of telling anyone fills you with shame.","steps":[{"prompt":"It is the third night you have lain awake with it. What do you do?","options":[{"text":"Choose one safe person, like your sister, to tell soon","then":"You settle on your sister. Your heart still races, but the choice feels lighter.","best":true},{"text":"Keep it hidden so people still see a coping mother","then":"You rehearse your bright voice for tomorrow. The night feels longer."},{"text":"Post it in the family group and hope someone helps","then":"Twelve replies arrive at once. Most are advice, and you feel exposed."},{"text":"Wait until you can say it perfectly, and tell no one yet","then":"You draft and delete lines in your head. Morning comes with nothing said."}],"why":"One safe person is a small, doable first step, and shame shrinks once shared."},{"prompt":"The next evening your sister calls and asks how you are really doing. What do you say?","options":[{"text":"Tell her the truth: you've been struggling and felt ashamed","then":"She goes quiet, then says softly, \"I'm so glad you told me.\"","best":true},{"text":"Say it's wonderful and you're just tired, like always","then":"She laughs and chats about her week. You hang up feeling more alone."},{"text":"Say you're struggling, then laugh it off as being silly","then":"She laughs along, unsure if you meant it. The call moves on."},{"text":"Hint that things are hard, then ask all about her life","then":"She hears the hint but doesn't press. You end the call, still holding it."}],"why":"Saying it plainly to one safe person breaks the isolation."},{"prompt":"A few days later a neighbour praises how well you look. The shame returns. What do you do?","options":[{"text":"Remember it's strain, not a flaw, and text your sister","then":"She replies within minutes. \"Thinking of you. Want to talk tonight?\"","best":true},{"text":"Smile and agree that you are doing wonderfully, and leave it","then":"The neighbour beams. You walk home carrying it heavily."},{"text":"Decide it's safer to keep your feelings to yourself","then":"You retreat inside. The shame feels louder in the quiet."},{"text":"Tell yourself the other mothers cope much better than you","then":"You compare yourself to her all evening. It sinks you further."}],"why":"Shame comes back sometimes, and reaching for a safe person softens it."},{"prompt":"Weeks later the weight is still there. What do you do?","options":[{"text":"Ask your sister to help you call a doctor or Tele-MANAS 14416","then":"She stays on the line while you call. You take the first step together.","best":true},{"text":"Hold off a little longer and see if it lifts all by itself","then":"The waiting is easier than the calling, and the heaviness stays."},{"text":"Try to lift it yourself with walks and early nights","then":"The walks help a little, but the heaviness holds on."},{"text":"Tell yourself it isn't bad enough yet to need a doctor's help","then":"You carry on as you are. The weight settles in deeper."}],"why":"A doctor or Tele-MANAS 14416 can help when the weight stays. It is never your fault."}],"debrief":"Tell one safe person; sharing shrinks the shame and breaks the isolation that worsens it.","relearn":"Share with one safe person; hidden struggle and shame grow in isolation."},
  {"id":"ly-040","cat":"reach-out","type":"match","hook":"Match each part of a support net to what it offers.","pairs":[{"left":"Trusted people","right":"Everyday listening and practical help"},{"left":"A doctor or counsellor","right":"Assessment and treatment"},{"left":"A helpline (Tele-MANAS 14416)","right":"Support any time, including crises"},{"left":"A new-parent group","right":"Others who truly understand"},{"left":"Emergency 112","right":"Immediate help in real danger"}],"relearn":"Trusted people, professionals, a helpline, a peer group and the emergency line each offer real, different support.","persona":"any","source":"support net"},
  {"id":"ly-041","cat":"reach-out","type":"strike-rewrite","hook":"\"There's no real help for struggling parents anyway, so why reach out.\"","myth":{"un":"There's no real help for struggling parents anyway, so why reach out.","re":"Real help exists, doctors, counsellors, helplines like Tele-MANAS 14416, and it can genuinely turn things around.","why":"Support is closer than it feels."},"relearn":"Real help exists for struggling parents, doctors, counsellors and helplines, and it can genuinely turn things around.","persona":"any","source":"help exists"},
  {"id":"ly-042","cat":"reach-out","type":"reflect","hook":"Lensy: you weren't meant to do this alone; humans raise children in support networks, not in isolation. Resonate?","prompt":"What do you think?","options":["Resonates","Not alone","Build the net"],"affirm":"Parenting was never meant to be done in isolation; building and using a support network is how humans raise children.","relearn":"You weren't meant to parent alone; building a support network is how it's meant to work.","persona":"any","source":"not alone"},
  {"id":"ly-043","cat":"reach-out","type":"role-play","persona":"Vikram","source":"open up","hook":"You want to reach out to a friend but don't know how to start.","setup":"You call him and he picks up on the second ring.","steps":[{"prompt":"Sameer answers: \"Hey, you rarely call. What's up?\"","options":[{"text":"\"Can I be honest? I'm struggling and could use someone.\"","then":"There is a pause. \"Yaar. Of course. I'm listening.\"","best":true},{"text":"\"Everything's great. Just a bit tired, so ignore me.\"","then":"He laughs. \"Same here, bro. Everyone's tired.\""},{"text":"\"Nothing much. How's work going for you these days?\"","then":"He starts on a long story about his manager. You listen and say nothing."},{"text":"\"Just calling about the kids' cricket. Anything new?\"","then":"He talks about the match for ten minutes. The call ends easily."}],"why":"Saying honestly that you're struggling opens the door."},{"prompt":"A few days later Sameer messages: \"Still thinking about our call. How are you today?\"","options":[{"text":"\"Honestly, still heavy. Can we talk properly this weekend?\"","then":"He answers at once. \"Saturday morning. I'll come to you.\"","best":true},{"text":"\"All good. Don't worry about me.\"","then":"He sends a thumbs up. \"Okay. I'll drop by on Saturday anyway.\""},{"text":"\"Better, thanks. Let's not make it a thing, okay?\"","then":"He replies: \"Sure. I'll still come round Saturday, no agenda. I'm there if you want to talk.\""},{"text":"\"I'd rather not talk about it over text, or at all really.\"","then":"He answers gently. \"Fine, not over text. I'll drop by Saturday.\""}],"why":"Answering honestly and naming a time turns one call into steady support."},{"prompt":"On Saturday, once you have settled, Sameer says: \"I meant it. What do you need from me? I'll do whatever helps.\"","options":[{"text":"\"Just listen for now. And check in on me each week.\"","then":"He nods. \"Every Sunday. I'll put a reminder in my phone.\"","best":true},{"text":"\"Nothing, honestly. I'll sort it out myself in time.\"","then":"He frowns. \"Okay. The offer stays.\""},{"text":"\"Tell me what to do. Just fix it for me.\"","then":"He winces. \"I wish I could. I don't know how either.\""},{"text":"\"Don't tell anyone, not even your wife. Please.\"","then":"He nods slowly. \"I won't. But that's a lot to carry.\""}],"why":"A clear, small ask lets a friend help in a way that lasts."},{"prompt":"A month on, Sameer says: \"You still sound low, yaar. Have you thought of seeing someone?\"","options":[{"text":"\"You're right. Help me call Tele-MANAS 14416 or a doctor.\"","then":"He grins, relieved. \"Yes. Let's do it this week.\"","best":true},{"text":"\"Men don't need that. I'll get through it myself, yaar.\"","then":"He shrugs. \"Okay. If you change your mind, I'm here.\""},{"text":"\"Maybe later, once work calms down a little bit more.\"","then":"He nods. Work doesn't calm down, and neither do you."},{"text":"\"Let me try more gym time and better sleep first.\"","then":"He says it's worth a try. You go, and feel the same afterwards."}],"why":"A friend is a great start, and a doctor or Tele-MANAS is the next step."}],"relearn":"An honest 'I'm struggling and could use someone' opens the door to the support you actually need."},
  {"id":"ly-044","cat":"reach-out","type":"spot","hook":"Spot the two moves that quietly remove a parent's support instead of building it.","scene":[{"id":"a","text":"Letting trusted people in","trick":false},{"id":"b","text":"Insisting you must cope alone","trick":true},{"id":"c","text":"Knowing a helpline you can call","trick":false},{"id":"d","text":"Hiding every struggle behind 'I'm fine'","trick":true},{"id":"e","text":"Saving a couple of people to call","trick":false}],"why":"Insisting on coping alone and hiding behind 'I'm fine' strip away support; letting people in and saved contacts build it.","relearn":"Build support by letting people in and saving contacts, not by insisting on coping alone or hiding behind 'I'm fine'.","persona":"any","source":"build support"},
  {"id":"ly-045","cat":"reach-out","type":"branch","persona":"Priya","source":"open the door","hook":"A parent friend brushes off real distress with 'I'm fine'. You sense she is not.","steps":[{"prompt":"At the park Lata says 'I'm fine' again but can't meet your eye. What do you say?","options":[{"text":"Tell her you're around, and that wanting help is okay","then":"She looks down and nods. \"Thanks. I might take you up on that.\"","best":true},{"text":"Say 'Okay' and ask how the baby is sleeping these days","then":"She relaxes, and the topic never returns. She leaves with the same weight."},{"text":"Say: \"You're not fine. Tell me what's wrong right now.\"","then":"She stiffens and pulls back. \"I said I'm fine.\""},{"text":"Tell her she looks tired and should just sleep more","then":"She laughs tightly. \"If only.\" Nothing else is said."}],"why":"A gentle open door says help is okay to want, without pushing her through it."},{"prompt":"A week later Lata sends a photo of her baby with 'Busy day!'. What do you do?","options":[{"text":"Reply warmly and offer a walk, a call or just company","then":"She replies with a heart. \"A walk on Friday would be nice.\"","best":true},{"text":"Send back a heart and leave it there","then":"She reads it and doesn't reply. The door feels a little more closed."},{"text":"Ask her mother-in-law how she's really doing","then":"Word gets back to Lata. She feels watched and goes quiet for a while."},{"text":"Tell the other mothers in your group that she's struggling","then":"The group starts whispering. Lata senses it and keeps her distance for weeks."}],"why":"A warm, specific offer makes it easy for her to say yes."},{"prompt":"Weeks later Lata rings you, close to tears: \"I don't know how to ask for help.\" What do you do?","options":[{"text":"Listen first, then offer to help her call Tele-MANAS 14416","then":"She lets out a shaky breath. \"Can you sit with me while I call?\"","best":true},{"text":"Say everyone feels like this and it will pass soon enough","then":"She goes quiet, disappointed. \"Maybe you're right.\""},{"text":"Book a doctor's appointment for her and tell her the date","then":"She sounds overwhelmed. \"You didn't even ask me.\""},{"text":"Tell her step by step what to do, then check she's done it","then":"She tries to keep up, but feels managed and less heard."}],"why":"Listening first and offering to help her reach care respects her pace and her choice."}],"debrief":"When a parent's 'I'm fine' rings hollow, gently let them know you're there and help is okay to want.","relearn":"Offer a gentle open door when a parent's 'I'm fine' seems hollow."},
  {"id":"ly-046","cat":"reach-out","type":"reflect","hook":"Lensy: the bravest, most loving thing a struggling parent can do is reach out. Sit right?","prompt":"What's your take?","options":["Sits right","Brave & loving","I would"],"affirm":"Reaching out when struggling is among the bravest and most loving things a parent can do, for themselves and their child.","relearn":"The bravest, most loving thing a struggling parent can do is reach out.","persona":"any","source":"bravest thing"},
  {"id":"ly-047","cat":"reach-out","type":"strike-rewrite","hook":"\"I should wait until I'm completely falling apart before I get help.\"","myth":{"un":"I should wait until I'm completely falling apart before I get help.","re":"You don't have to be in crisis to deserve support; reaching out early is easier and works better than waiting for collapse.","why":"Early help beats last-resort help."},"relearn":"You don't have to be falling apart to deserve help; reaching out early is easier and more effective.","persona":"any","source":"don't wait for crisis"},
  {"id":"ly-048","cat":"healthy-coping","type":"strike-rewrite","hook":"\"There's no healthy way to cope with this much stress, so why try.\"","myth":{"un":"There's no healthy way to cope with this much stress, so why try.","re":"Small healthy strategies, rest when you can, breathe, move, connect, accept help, genuinely lower the load and build over time.","why":"Tiny healthy habits add up."},"relearn":"Small healthy coping, rest, breathing, movement, connection, accepting help, genuinely eases the load over time.","persona":"any","source":"healthy coping works"},
  {"id":"ly-049","cat":"healthy-coping","type":"sort","hook":"Sort: a healthy way to cope under parenting load, or one that quietly harms you?","items":[{"id":"a","text":"Resting and accepting help"},{"id":"b","text":"Numbing out with too much alcohol"},{"id":"c","text":"A few slow breaths or a short walk"},{"id":"d","text":"Bottling it all up alone"},{"id":"e","text":"Naming what you feel to someone"},{"id":"f","text":"Skipping sleep to keep grinding"}],"bins":[{"id":"healthy","label":"Healthy coping","valence":"pos"},{"id":"harm","label":"Quietly harmful","valence":"neg"}],"key":{"a":"healthy","b":"harm","c":"healthy","d":"harm","e":"healthy","f":"harm"},"relearn":"Rest, accepting help, breathing, a short walk and naming feelings are healthy; numbing, bottling up and skipping sleep harm you.","persona":"any","source":"healthy vs harm"},
  {"id":"ly-050","cat":"healthy-coping","type":"match","hook":"Match each load-moment to a healthy coping move.","pairs":[{"left":"Overwhelm rising","right":"Pause and take a few slow breaths"},{"left":"Touched out and tense","right":"Step away a moment if it's safe"},{"left":"Lonely and low","right":"Reach out to one person"},{"left":"Mind racing at night","right":"Rest your body even if sleep won't come"},{"left":"Snappy and short-fused","right":"Drink water and unclench your jaw"}],"relearn":"Overwhelm, tension, loneliness, a racing mind and a short fuse each have a small healthy move that steadies you.","persona":"any","source":"coping moves"},
  {"id":"ly-051","cat":"healthy-coping","type":"branch","persona":"Vikram","source":"pause and breathe","hook":"You feel your stress spiking toward snapping at your child.","steps":[{"prompt":"Your child has cried for an hour and your patience is thin. What do you do?","options":[{"text":"Lay your child somewhere safe and step back to breathe","then":"Ten slow breaths in the doorway. The crying continues, and you feel less tight.","best":true},{"text":"Keep trying until the crying stops","then":"The crying doesn't stop. The tightness gets worse."},{"text":"Raise your voice so your child stops","then":"Your child startles and cries harder. You feel awful."},{"text":"Scroll your phone to block out the crying","then":"The crying goes on. Your nerves get tighter, not looser."}],"why":"Pausing somewhere safe protects your child and gives you a moment to calm."},{"prompt":"Your partner comes in and sees you tense. What do you say?","options":[{"text":"Say you're at your limit and need five minutes","then":"Your partner takes over. \"Go. I've got them.\"","best":true},{"text":"Say everything's fine and keep going","then":"Your partner watches you for a moment, then goes back to what they were doing."},{"text":"Say your partner should have soothed them earlier","then":"Your partner bristles, and the tension in the room grows."},{"text":"Say you'll tough it out","then":"Your partner nods, but keeps watching."}],"why":"Telling your partner you're at your limit brings real backup."},{"prompt":"Later that night, the same stress builds when your child wakes again. What do you do?","options":[{"text":"Pause, breathe, and ask your partner to take a turn","then":"Your partner takes over. You sit in the dark and breathe.","best":true},{"text":"Push through silently until dawn","then":"Dawn takes forever. You feel wrung out."},{"text":"Speak sharply and say sorry afterwards","then":"Your child startles. The apology comes late."},{"text":"Wait to see if it passes on its own","then":"It doesn't pass. It builds."}],"why":"Asking for a turn when stress builds keeps everyone safe."},{"prompt":"Days later, the stress still spikes most days. What do you do?","options":[{"text":"Tell a doctor or call Tele-MANAS 14416","then":"The person on the line listens and tells you help is available.","best":true},{"text":"Keep it to yourself so you don't seem weak","then":"You keep it in. The spikes come more often."},{"text":"Wait for your child to sleep through the night","then":"Months pass, and the spikes continue."},{"text":"Rely on willpower alone","then":"Willpower runs out most evenings."}],"why":"Frequent stress spikes are worth telling a doctor or helpline, and it's not weakness."}],"debrief":"When stress spikes, if it's safe, pause and breathe before you respond; it protects your child and you.","relearn":"Pause and reset when stress spikes near snapping; a breath protects you and your child."},
  {"id":"ly-052","cat":"healthy-coping","type":"strike-rewrite","hook":"\"Coping means white-knuckling through and never showing strain.\"","myth":{"un":"Coping means white-knuckling through and never showing strain.","re":"Real coping is using supports and healthy habits and being honest about strain, not gritting your teeth alone.","why":"Sustainable coping is supported, not solo."},"relearn":"Coping isn't white-knuckling alone; it's using supports and healthy habits and being honest about strain.","persona":"Divya","source":"supported coping"},
  {"id":"ly-053","cat":"healthy-coping","type":"reflect","hook":"Lensy: you can't remove all the stress of parenting, but you can change how you carry it. Make sense?","prompt":"What do you think?","options":["Makes sense","How I carry it","I can do that"],"affirm":"You can't eliminate parenting stress, but healthy coping changes how you carry it, which is within your power.","relearn":"You can't remove all parenting stress, but you can change how you carry it.","persona":"any","source":"how you carry it"},
  {"id":"ly-054","cat":"healthy-coping","type":"spot","hook":"Spot the two coping moves that quietly harm you, not help.","scene":[{"id":"a","text":"A few minutes of fresh air or breathing","trick":false},{"id":"b","text":"Skipping meals and sleep to cope","trick":true},{"id":"c","text":"Leaning on a friend or a routine","trick":false},{"id":"d","text":"Numbing every night with a drink","trick":true},{"id":"e","text":"Resting your body when you can","trick":false}],"why":"Skipping meals and sleep and nightly numbing quietly harm you; fresh air, leaning on people and resting genuinely help.","relearn":"Healthy coping refills you, fresh air, breathing, connection, rather than depriving or numbing you further.","persona":"any","source":"genuinely healthy"},
  {"id":"ly-055","cat":"healthy-coping","type":"branch","persona":"any","source":"healthier swap","hook":"Your old unhealthy way of coping is pulling at you under this load.","steps":[{"prompt":"After a night of broken sleep, the old habit tugs hard. What do you do?","options":[{"text":"Reach for a healthier swap, like a walk or a call","then":"You step outside for a walk. The tug is still there, but quieter.","best":true},{"text":"Give in to the old habit just this once","then":"It takes the edge off for a moment. Then the tug returns stronger."},{"text":"Tell yourself you're fine and ignore it","then":"You get on with the day. The tug is waiting at night."},{"text":"Rely on willpower alone","then":"Willpower holds until mid-afternoon."}],"why":"A healthier swap gives the urge somewhere safe to go."},{"prompt":"A friend calls just as the urge peaks. What do you do?","options":[{"text":"Answer and tell her you're struggling","then":"She listens. \"Thank you for telling me. What would help?\"","best":true},{"text":"Let it ring and give in","then":"The call ends. The habit takes over for the evening."},{"text":"Answer and chat about anything but this","then":"You talk about the weather. The urge stays quietly at your side."},{"text":"Text 'busy' and promise to call later","then":"You don't call later. She hears nothing."}],"why":"Telling a friend turns a private struggle into shared support."},{"prompt":"The urge returns at night when the house is quiet. What do you do?","options":[{"text":"Use your swap and text someone you trust","then":"The swap and the text help. You get through the night.","best":true},{"text":"Wait it out by yourself","then":"You sit alone. The urge is still there at midnight."},{"text":"Distract yourself with your phone until it fades","then":"The phone keeps you up. The urge comes back."},{"text":"Give in quietly and tell nobody","then":"The habit is a secret again, and the secret is heavy."}],"why":"A swap plus one text means you're not fighting the urge alone."},{"prompt":"A week later, you slip once, and the pull is still strong. What do you do?","options":[{"text":"Tell someone, and ask a doctor or Tele-MANAS 14416 for support","then":"Your friend is glad you told her. The person on the line helps you plan what's next.","best":true},{"text":"Decide you've failed and stop trying","then":"The swap is dropped. The old habit returns."},{"text":"Hide it so no one is disappointed","then":"You carry it alone again."},{"text":"Restart the swap and keep the slip to yourself","then":"You restart quietly. The pull is hard to hold alone."}],"why":"A slip is not a failure. A trusted person and a doctor or helpline help you keep going."}],"debrief":"Under load, swap an unhealthy coping habit for a healthier one and tell someone, not willpower alone.","relearn":"Swap a harmful coping habit for a healthier one and lean on support, not willpower."},
  {"id":"ly-056","cat":"healthy-coping","type":"reflect","hook":"Lensy: even one small healthy habit, kept up, can steady a very hard season. Worth starting?","prompt":"What's your take?","options":["Worth it","One small habit","Starting"],"affirm":"Even a single small healthy habit, kept up, can meaningfully steady a parent through a very hard season.","relearn":"Even one small healthy habit, kept up, can steady a very hard season.","persona":"any","source":"one small habit"},
  {"id":"ly-057","cat":"healthy-coping","type":"sort","hook":"Sort: builds you back up under load, or wears you down further?","items":[{"id":"a","text":"Sleep when you can and good-enough food"},{"id":"b","text":"Endless doomscrolling at 3am"},{"id":"c","text":"A little movement and daylight"},{"id":"d","text":"Isolating from everyone"},{"id":"e","text":"A few minutes of quiet to yourself"},{"id":"f","text":"Skipping every meal to save time"}],"bins":[{"id":"up","label":"Builds you up","valence":"pos"},{"id":"down","label":"Wears you down","valence":"neg"}],"key":{"a":"up","b":"down","c":"up","d":"down","e":"up","f":"down"},"relearn":"Sleep, food, movement, daylight and quiet build you up; doomscrolling, isolating and skipping meals wear you down.","persona":"any","source":"up vs down"},
  {"id":"ly-058","cat":"healthy-coping","type":"role-play","persona":"Vikram","source":"offer a reset","hook":"Your partner Neha is fraying, and you want to offer a healthy reset, not a lecture.","setup":"It is the end of a long, loud evening.","steps":[{"prompt":"Neha says over the baby's cry: \"I can't keep up with any of this!\"","options":[{"text":"\"You seem stretched thin. Want a breather? I've got this.\"","then":"She blinks, her shoulders dropping a little. \"Really? Just like that?\"","best":true},{"text":"\"You just need to calm down and stop stressing so much.\"","then":"Her jaw tightens. \"Don't tell me to calm down.\""},{"text":"\"Everyone feels like this at first. It passes soon enough.\"","then":"She nods flatly. \"Sure.\" She turns back to the sink."},{"text":"\"Let's go through everything that went wrong today.\"","then":"She lists it all, and her voice cracks. She looks worse at the end."}],"why":"Naming the strain and offering cover gives her a reset instead of a lecture."},{"prompt":"Neha rubs her eyes and says: \"I don't even know what I need right now.\"","options":[{"text":"\"That's okay. Try ten minutes outside. I've got the baby.\"","then":"She hesitates, then reaches for her chappals. \"Ten minutes. Okay.\"","best":true},{"text":"\"You should know by now. Sit down and think about it.\"","then":"She stares at you. \"I can't think. That's the problem.\""},{"text":"\"Take the whole evening off. I'll figure out the rest later.\"","then":"She looks unsure. \"The whole evening? I'll only worry all the time.\""},{"text":"\"Let me look up what other new mothers do about this.\"","then":"You start reading aloud. She listens without answering, looking tired."}],"why":"A small, concrete offer is easier to accept than a big open question."},{"prompt":"The next evening Neha is short-tempered again and says: \"I'm sorry. I'm just so on edge.\"","options":[{"text":"\"No need to say sorry. Let's plan a break for you each evening.\"","then":"Her eyes fill. \"I'd like that. Thank you.\"","best":true},{"text":"\"It's fine. Just try to hold it together for the baby.\"","then":"She nods and tightens her mouth. The edge is still there."},{"text":"\"Again? I honestly don't know how much more I can take.\"","then":"She goes quiet and turns away. The evening ends in silence."},{"text":"\"Let me take the baby tonight. Tomorrow we'll see what happens.\"","then":"She is grateful for tonight. Tomorrow arrives with no plan."}],"why":"A regular plan gives her something to count on, beyond one good evening."}],"relearn":"Offering a concrete, gentle reset and covering for them helps far more than telling them to 'calm down'."},
  {"id":"ly-059","cat":"tools-and-help","type":"branch","persona":"Divya","source":"ready a plan","hook":"You want something you can actually reach for on the hardest days.","steps":[{"prompt":"You have a calm evening and a blank page. What do you do?","options":[{"text":"Write a tiny plan: breathing space, one person, one helpline","then":"You write three lines. It takes ten minutes, and you feel steadier.","best":true},{"text":"Write a long plan that covers every possible bad day","then":"You fill two pages, run out of steam, and never open it again."},{"text":"Leave it, and work it all out when the day comes","then":"The evening passes. A small worry underneath makes you wonder who you would even call."},{"text":"Bookmark ten coping articles and call that done for now","then":"You save them all and never read them."}],"why":"A tiny plan is easy to remember and to use when you're low."},{"prompt":"A few days on, you think about who you would call on a hard day. Who do you pick?","options":[{"text":"Someone who listens without fixing, and tell them so","then":"They say: \"I'd be honoured.\" You feel less alone at once.","best":true},{"text":"Whoever seems the best at coping with parenthood so far","then":"You pick her. She is busy, and you never feel you can call."},{"text":"Nobody, so as not to bother anyone with your problems","then":"There is a gap where a person should be."},{"text":"Everyone in the family group, all at the same time","then":"Nobody knows they're the one to call. The group chat gets noisy."}],"why":"One chosen person who knows they're your person is easier to reach for."},{"prompt":"A hard evening arrives and everything feels too much. What do you do?","options":[{"text":"Breathe slowly, then call someone who listens well","then":"She picks up at once. The heaviness eases with her voice.","best":true},{"text":"Push through alone and keep it to yourself","then":"You grit through it. The evening is long and cold."},{"text":"Search online for what to do while it all feels too much","then":"Pages blur together. The feeling only grows."},{"text":"Wait to see whether it passes before touching the phone","then":"It doesn't pass quickly. You watch the minutes crawl by."}],"why":"Breathing first, then reaching one person, gets you through a hard evening."},{"prompt":"A month on, you think ahead to the next hard day. What do you do?","options":[{"text":"Make or update a short plan, with a doctor's number","then":"You save the doctor's number. The plan feels sturdier.","best":true},{"text":"Decide plans don't work, since none fixes everything","then":"With no plan, the next hard day catches you bare."},{"text":"Leave things as they are and never look again","then":"Life shifts around you, and what you have fits less well."},{"text":"Write a long, complicated plan to cover every case","then":"The new version is impressive and impossible to follow in a crisis."}],"why":"A small plan you keep tuning stays useful as life changes."}],"debrief":"Ready a tiny plan now, a breathing space, a person to call, a saved helpline, for the hardest days.","relearn":"Set up your supports before the hard day; a saved plan beats figuring it out then."},
  {"id":"ly-060","cat":"tools-and-help","type":"match","hook":"Match each tool to what it's for.","pairs":[{"left":"A breathing or grounding space","right":"Calming an overwhelming moment"},{"left":"A help-finder and saved contacts","right":"Knowing where to turn fast"},{"left":"Crisis lines like Tele-MANAS 14416","right":"Support any time, including emergencies"},{"left":"A trusted person on speed-dial","right":"Everyday listening and a hand"},{"left":"A doctor's appointment","right":"Assessment and ongoing care"}],"relearn":"A grounding space, saved contacts, crisis lines, a trusted person and a doctor are the core tools for a parent's hard moments.","persona":"any","source":"the toolkit"},
  {"id":"ly-061","cat":"tools-and-help","type":"strike-rewrite","hook":"\"An app or game can replace real treatment for depression.\"","myth":{"un":"An app or game can replace real treatment for depression.","re":"This offers gentle support and signposting, not therapy; postnatal depression and anxiety need real professional care.","why":"Support tools point to care; they don't replace it."},"relearn":"This game supports and signposts but isn't therapy; postnatal depression and anxiety need professional care.","persona":"any","source":"not therapy"},
  {"id":"ly-062","cat":"tools-and-help","type":"sort","hook":"Sort: a wise move when things feel very heavy, or one to avoid?","items":[{"id":"a","text":"Calling a helpline or doctor"},{"id":"b","text":"Waiting silently for it to pass"},{"id":"c","text":"Telling a trusted person now"},{"id":"d","text":"Deciding you're not 'bad enough' for help"},{"id":"e","text":"Saving Tele-MANAS 14416 to call"},{"id":"f","text":"Hiding how heavy it really feels"}],"bins":[{"id":"wise","label":"Wise move","valence":"pos"},{"id":"avoid","label":"To avoid","valence":"neg"}],"key":{"a":"wise","b":"avoid","c":"wise","d":"avoid","e":"wise","f":"avoid"},"relearn":"Calling a helpline or doctor, telling someone and saving a line are wise; waiting silently, 'not bad enough' or hiding it keep help away.","persona":"any","source":"wise vs avoid"},
  {"id":"ly-063","cat":"tools-and-help","type":"reflect","hook":"Lensy: knowing the number before you need it is a quiet act of self-care. Worth saving them now?","prompt":"What do you think?","options":["Worth it","Saving them","Good idea"],"affirm":"Saving crisis and support numbers before you need them is a simple, powerful act of looking after yourself.","relearn":"Knowing the helpline before you need it is a quiet, powerful act of self-care.","persona":"any","source":"save the number"},
  {"id":"ly-064","cat":"tools-and-help","type":"branch","persona":"Divya","source":"reach out anyway","hook":"You're not sure your struggle is 'serious enough' to call a helpline or see a doctor.","steps":[{"prompt":"It has been a rough few weeks and the phone is in your hand. What do you do?","options":[{"text":"Reach out anyway; you needn't be in crisis to get support","then":"You call. The listener is kind and unhurried, and you feel a little lighter.","best":true},{"text":"Wait a few more weeks to see whether it gets much worse","then":"The weeks pass and the low mood settles in deeper."},{"text":"Ask a friend whether your struggle is bad enough to count","then":"She says she isn't sure. You put the phone down, still unsure."},{"text":"Compare yourself with mothers who clearly have it harder","then":"You list their troubles and shrink your own. The phone stays quiet."}],"why":"You needn't be in crisis to deserve support, and early help is easiest."},{"prompt":"A few days later your partner asks how you are. What do you say?","options":[{"text":"Tell him you've been struggling and want support","then":"His face softens. \"Thank you for telling me. How can I help?\"","best":true},{"text":"Say you're fine so that he won't make it a big deal","then":"He nods, relieved. The knot in your stomach stays where it is."},{"text":"Say it is probably nothing serious, just a passing phase","then":"He agrees quickly. Neither of you mentions it again."},{"text":"Say you'll tell him only if it ever gets really bad","then":"He says okay. He doesn't know what to watch for."}],"why":"Telling him early brings a second person into your support."},{"prompt":"A lighter day comes and you wonder whether you need help after all. What do you do?","options":[{"text":"Reach out anyway, and enjoy the lighter day too","then":"You enjoy the day and still make the call. The next one is a bit lighter too.","best":true},{"text":"Drop the idea of help, since you're clearly fine now","then":"For a week it holds. Then the heavy days return with no help lined up."},{"text":"Hold off on everything until the heaviness comes back","then":"When it returns, it feels as though you have to start again."},{"text":"Tell nobody about the lighter day, in case it jinxes it","then":"You keep the good day secret. Nobody gets to celebrate it with you."}],"why":"A lighter day is welcome, and it isn't a reason to drop support."},{"prompt":"Weeks on, a new-parent friend asks whether her struggle is 'serious enough' to call for help. What do you say?","options":[{"text":"Tell her she needn't be in crisis to deserve support","then":"Her shoulders drop. \"Thank you. I'll call this week.\"","best":true},{"text":"Tell her to wait a bit and see if it gets worse first","then":"She nods, hesitant. She holds off, and the low mood holds on."},{"text":"Tell her it's probably nothing and not to bother anyone","then":"She smiles weakly. She puts the phone away."},{"text":"Tell her other mothers have it much harder, so cope","then":"She looks down. \"You're right.\" Her voice goes flat."}],"why":"Telling her she needn't be in crisis shows her early help is fine."}],"debrief":"You needn't be 'serious enough' or in crisis to call for support; reaching out early is valid.","relearn":"Reach out even if unsure it's 'serious enough'; you needn't be in crisis."},
  {"id":"ly-065","cat":"tools-and-help","type":"match","hook":"Match a moment to the right India support.","pairs":[{"left":"Needing to talk, any time","right":"Tele-MANAS 14416 (mental health)"},{"left":"Wanting structured support","right":"A doctor or counsellor"},{"left":"Immediate danger to anyone","right":"Emergency 112, right away"},{"left":"A panic that needs to ease now","right":"A breathing or grounding space"},{"left":"Not knowing where to begin","right":"A help-finder and saved contacts"}],"relearn":"Tele-MANAS to talk, a doctor or counsellor for structured support, 112 for danger, a breathing space to ease panic, a help-finder to begin.","persona":"any","source":"right support"},
  {"id":"ly-066","cat":"tools-and-help","type":"spot","hook":"Spot the two unsustainable ways a parent might 'cope'. Tap the two red flags.","scene":[{"id":"a","text":"Small daily self-care and a support net","trick":false},{"id":"b","text":"Ignoring yourself until you break","trick":true},{"id":"c","text":"Reaching for help early and often","trick":false},{"id":"d","text":"Pushing through alone, no support","trick":true},{"id":"e","text":"Keeping a few helplines saved","trick":false}],"why":"Ignoring yourself until you break and pushing through alone aren't sustainable; daily care, early help and saved support are.","relearn":"Sustainable self-care is daily care, early help and saved support; not ignoring yourself or pushing through alone.","persona":"any","source":"unsustainable coping"},
  {"id":"ly-067","cat":"tools-and-help","type":"reflect","hook":"Lensy: a well-looked-after parent is the foundation of a well-looked-after child. Feel the weight of that?","prompt":"What's your take?","options":["Feel it","Foundation","It matters"],"affirm":"Looking after yourself is foundational, not optional: a well parent is the ground a well child grows on.","relearn":"A well-looked-after parent is the foundation of a well-looked-after child.","persona":"any","source":"the foundation"},
  {"id":"ly-068","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Once I'm coping a bit better, I can stop looking after myself again.\"","myth":{"un":"Once I'm coping a bit better, I can stop looking after myself again.","re":"Self-care is ongoing, not a one-time fix; keeping the small habits and supports is what stops you sliding back.","why":"Maintenance keeps the gains."},"relearn":"Self-care is ongoing, not a one-off; keeping small habits and supports is what prevents sliding back.","persona":"any","source":"ongoing care"},
  {"id":"ly-069","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"set the tone","hook":"You and your partner Sneha are settling in for the long haul of parenting.","setup":"The baby has finally gone to sleep.","steps":[{"prompt":"Sneha asks: \"How do we make sure we both stay okay through all this?\"","options":[{"text":"\"Let's check in honestly and never be too proud to ask for help.\"","then":"Sneha smiles. \"I'd like that. I've been hiding how tired I am.\"","best":true},{"text":"\"We'll power through and hope for the best.\"","then":"She nods slowly. \"Okay.\" She doesn't sound convinced."},{"text":"\"You're the strong one. Honestly, you'll be fine, and so will I.\"","then":"Sneha looks away. \"I don't always feel strong.\""},{"text":"\"Let's take turns resting and not dwell on the hard stuff.\"","then":"She agrees. The rota works, and the tired talk stays unsaid."}],"why":"Honest check-ins and openness to help keep you both steady."},{"prompt":"Sneha says: \"What if one of us is struggling and doesn't say so?\"","options":[{"text":"\"Then the other asks, gently and often. Nobody has to be fine alone.\"","then":"She breathes out. \"Okay. I'll ask you too.\"","best":true},{"text":"\"Then they should speak up when they're ready.\"","then":"Sneha frowns a little. \"What if they can't find the words?\""},{"text":"\"We'd notice. We know each other well enough to see it straight away.\"","then":"\"Would we?\" she says. \"We've both been so tired.\""},{"text":"\"I'd rather not think about that yet.\"","then":"She nods and lets it drop. The question stays in the room."}],"why":"Asking gently and often means neither of you waits alone."},{"prompt":"Sneha says: \"Some days I think we should just push through for the baby's sake.\"","options":[{"text":"\"Rest is part of looking after the baby. Let's take turns.\"","then":"Sneha laughs softly. \"Turns. Yes. You first on Saturday.\"","best":true},{"text":"\"You're right. The baby comes first, always.\"","then":"Sneha nods. Neither of you mentions how thin you both feel."},{"text":"\"Fine, but only until things settle down a little and the nights get easier.\"","then":"She agrees. \"Settle down\" has no date on it."},{"text":"\"Let's plan our rest after the next busy patch.\"","then":"She agrees. The next busy patch is followed by another."}],"why":"Rest is part of childcare, and taking turns keeps it fair."}],"relearn":"A shared tone of honest check-ins, shared rest and openness to help keeps both parents okay through the long haul."},
  {"id":"ly-070","cat":"empty-cup","type":"role-play","persona":"Vikram","source":"permission to rest","hook":"Your partner Komal keeps saying she's fine while clearly running on empty.","setup":"She's still wiping the counter at nine at night.","steps":[{"prompt":"Komal says: \"I'm fine. I just need to finish this one thing.\"","options":[{"text":"\"You don't have to earn rest. I've got this.\"","then":"She pauses, cloth in hand. \"Are you sure?\"","best":true},{"text":"\"Okay. Just don't stay up too late.\"","then":"She wipes and wipes. The counter isn't the point."},{"text":"\"Push through. You'll be fine. We all are.\"","then":"She nods and keeps going."},{"text":"\"You always say that. Do what you want.\"","then":"She turns away. The counter gleams."}],"why":"Telling her she doesn't have to earn rest gives her real permission."},{"prompt":"Komal says: \"There's still so much left to do tonight.\"","options":[{"text":"\"It'll wait. I'll do the bottles. Rest an hour.\"","then":"She sits, unsure. \"An hour? Really?\"","best":true},{"text":"\"Then make a list and finish it tomorrow.\"","then":"She writes a long list. The list is another job."},{"text":"\"You're right. Let's both push through tonight.\"","then":"You both work until midnight. You're both worn out."},{"text":"\"Forget it, then. I'm going to bed.\"","then":"You go to bed. She keeps wiping."}],"why":"Covering a concrete job lets her rest without leaving it all undone."},{"prompt":"The next evening, Komal sits down for a moment and says: \"I feel guilty just sitting here.\"","options":[{"text":"\"You matter too. Rest helps you and all of us.\"","then":"She lets her shoulders drop. \"Okay.\"","best":true},{"text":"\"Then don't sit. Keep going.\"","then":"She stands up. The guilt gets the last word."},{"text":"\"Guilt is normal. Just try not to think about it.\"","then":"She tries not to think about it and can't."},{"text":"\"Rest five minutes, then get back to it.\"","then":"She sets a timer and watches it the whole five minutes."}],"why":"Telling her she matters too lets her rest, and it's not selfish."}],"relearn":"Tell a depleted partner they don't have to earn rest, and cover for them so they can truly refill."},
  {"id":"ly-071","cat":"empty-cup","type":"sort","hook":"Sort: refills a depleted parent, or drains them further?","items":[{"id":"a","text":"A nap or a shared night off"},{"id":"b","text":"Saying yes to every demand"},{"id":"c","text":"A meal someone else cooks"},{"id":"d","text":"Skipping your own basic care"},{"id":"e","text":"Ten quiet minutes that are just yours"},{"id":"f","text":"Carrying guilt about every rest"}],"bins":[{"id":"refill","label":"Refills you","valence":"pos"},{"id":"drain","label":"Drains you more","valence":"neg"}],"key":{"a":"refill","b":"drain","c":"refill","d":"drain","e":"refill","f":"drain"},"relearn":"A nap, a cooked meal and ten quiet minutes refill you; yes-to-everything, skipping your own care and rest-guilt drain you.","persona":"any","source":"refill or drain"},
  {"id":"ly-072","cat":"your-needs-count","type":"role-play","persona":"Divya","source":"hold ground gently","hook":"You've planned an evening out with friends, and your aunt is visiting.","setup":"She watches you pick up your bag.","steps":[{"prompt":"Your aunt says: \"A good mother wouldn't go out and leave her baby.\"","options":[{"text":"\"Loving my baby and needing a break both fit. It helps me parent.\"","then":"Your aunt pauses. \"Well. As long as it's only an evening.\"","best":true},{"text":"\"You're right. I shouldn't be so selfish.\"","then":"Your aunt looks satisfied. You put the bag down."},{"text":"\"That's not fair. You never gave me any help.\"","then":"Your aunt stiffens. \"I did plenty. I'm just saying.\""},{"text":"\"It's only an hour. Please don't tell the others in the family.\"","then":"She sighs. \"I won't. But you should still stay in.\""}],"why":"Naming that love and needs both fit holds your ground without a fight."},{"prompt":"Your aunt says: \"In my day, we never needed breaks.\"","options":[{"text":"\"I know you managed. I'm doing it my way, and it works.\"","then":"Your aunt is quiet. \"Hm. You do look rested after them. I'll say that.\"","best":true},{"text":"\"Then I must be weaker than you were.\"","then":"Your aunt says nothing. The remark lands on you and stays."},{"text":"\"Times were different. You had more help than I do.\"","then":"Your aunt bristles. \"I raised four children.\""},{"text":"\"Maybe you're right. I'll stay in.\"","then":"She nods, pleased. \"Good. People do talk, you know.\""}],"why":"Respecting her way while keeping yours avoids both guilt and a family fight."},{"prompt":"Your aunt asks: \"And what would the family say about these evenings out?\"","options":[{"text":"\"That I'm looking after myself to look after the baby.\"","then":"Your aunt gives a short laugh. \"That's one way to say it.\"","best":true},{"text":"\"I don't care what anyone in this family thinks about me.\"","then":"Your aunt's mouth tightens. The talk ends coldly."},{"text":"\"Then I'll stay home so that nobody has anything to say.\"","then":"She smiles. The evening you needed slips away."},{"text":"\"Please don't mention it to anyone.\"","then":"Your aunt nods, but the secret feels heavy."}],"why":"A short, calm answer keeps things warm and holds your ground."}],"relearn":"Naming that love and needs coexist holds your ground without guilt or a family fight."},
  {"id":"ly-073","cat":"your-needs-count","type":"match","hook":"Match each parent need to why honouring it helps the child too.","pairs":[{"left":"Rest","right":"A calmer, more patient parent"},{"left":"Connection","right":"A less isolated, steadier parent"},{"left":"A little identity","right":"A parent who models a full life"},{"left":"Shared load","right":"A parent with more left to give"},{"left":"Time of your own","right":"A parent who returns refilled"}],"relearn":"Honouring rest, connection, identity, a shared load and time of your own makes you steadier, which helps your child.","persona":"Meena","source":"needs help kids"},
  {"id":"ly-074","cat":"baby-blues-and-beyond","type":"role-play","persona":"Vikram","source":"raise it lovingly","hook":"You think your partner Tara may have postnatal depression and want to raise it lovingly.","setup":"Tonight the baby has finally fallen asleep.","steps":[{"prompt":"Tara sits on the edge of the bed and sighs: \"I'm so tired of everything lately.\"","options":[{"text":"\"I've noticed things feel heavy for you. You're not alone.\"","then":"She turns to you, eyes wet. \"Heavy. Yes. That's exactly it.\"","best":true},{"text":"\"Sleep when the baby sleeps. You'll feel better.\"","then":"She shrugs. \"I've tried that. It doesn't help.\""},{"text":"\"Everyone's tired. You're doing great, so smile a little.\"","then":"She forces a smile. \"You're right. I'm being silly.\""},{"text":"\"Maybe you need a break from the baby for a few days.\"","then":"She pulls back. \"I don't want to be sent away from her.\""}],"why":"Saying what you've noticed, warmly, tells her she isn't alone with it."},{"prompt":"Tara says: \"I don't know why I feel like this. I should be happy.\"","options":[{"text":"\"It's not your fault. It's common after birth and treatable.\"","then":"She exhales for the first time in a while. \"Treatable? Really?\"","best":true},{"text":"\"You have a beautiful baby. Why can't you just be happy?\"","then":"She goes very still. \"I'm sorry,\" she whispers, and looks at her hands."},{"text":"\"Let's wait a few weeks and see if it passes on its own.\"","then":"She nods. The weeks go by and she says less each day."},{"text":"\"I'll ask my mother to talk to you.\"","then":"She grimaces. \"I don't want to worry her.\""}],"why":"Telling her it isn't her fault and is treatable lifts the shame."},{"prompt":"Later, Tara asks quietly: \"Is there anything that actually helps with this?\"","options":[{"text":"\"Let's see a doctor together. I'll come with you.\"","then":"She squeezes your hand. \"Okay. I don't want to go alone.\"","best":true},{"text":"\"Let's try early nights and walks for a month first.\"","then":"She agrees. A month goes by and the walks change little."},{"text":"\"I'll read up on it and tell you what to do.\"","then":"She nods. She feels she has no say in it."},{"text":"\"We could ask the family what they think.\"","then":"She winces. \"I'd rather they didn't know.\""}],"why":"Going together to a doctor gets her real help, and she keeps her say."}],"relearn":"Raise a partner's low mood lovingly: say you've noticed, that they're not alone, and offer to get support together."},
  {"id":"ly-075","cat":"baby-blues-and-beyond","type":"sort","persona":"any","source":"caring vs harmful","relearn":"'Common and treatable', 'you're not alone' and 'let's call the doctor' are caring; 'snap out of it', 'good mothers don't' or 'making a drama' are harmful.","hook":"Sort: a caring, accurate response to a struggling new parent, or a harmful one?","items":[{"id":"a","text":"'This is common and treatable, let's get help'"},{"id":"b","text":"'Snap out of it, others manage'"},{"id":"c","text":"'You're not alone, I'm here'"},{"id":"d","text":"'Good mothers don't feel this way'"},{"id":"e","text":"'Let's call the doctor together'"},{"id":"f","text":"'Stop making a drama of a baby'"}],"bins":[{"id":"caring","label":"Caring & accurate","valence":"pos"},{"id":"harmful","label":"Harmful","valence":"neg"}],"key":{"a":"caring","b":"harmful","c":"caring","d":"harmful","e":"caring","f":"harmful"}},
  {"id":"ly-076","cat":"reach-out","type":"role-play","persona":"Divya","source":"call a helpline","hook":"You finally decide to call a helpline but feel nervous about it.","setup":"You dial Tele-MANAS 14416 and a calm voice answers.","steps":[{"prompt":"The listener says: \"Hello, I'm here to listen. How can I help today?\"","options":[{"text":"\"Hi, I'm a new parent and I've been struggling lately.\"","then":"\"Thank you for calling. I'm listening. Take your time.\"","best":true},{"text":"\"Sorry, never mind. It's probably nothing at all.\"","then":"\"It's not nothing. You called. Please stay a moment.\""},{"text":"\"I'm calling for a friend, really. She isn't doing well.\"","then":"\"I'm glad you're looking out for her. Is there something for you too?\""},{"text":"\"Can you just tell me what's wrong with me?\"","then":"\"I can't diagnose, but I can listen. Tell me what's been happening.\""}],"why":"A simple, honest opening is all a helpline needs."},{"prompt":"The listener says gently: \"There's no rush. I'm here for as long as you need.\"","options":[{"text":"\"I've been low for weeks and I'm scared I'm failing my baby.\"","then":"\"Thank you for telling me. Being low is not failing.\"","best":true},{"text":"\"It's fine. I'll manage. I just wanted to hear a voice.\"","then":"\"A voice is a good reason to call. You needn't say more than you want.\""},{"text":"\"I should go. The baby needs feeding, sorry.\"","then":"\"Of course. Before you go, can I say one thing?\""},{"text":"\"I can't say it. It's too embarrassing to put into words.\"","then":"\"That's okay. You don't need perfect words to be heard.\""}],"why":"Saying how you feel, even roughly, lets the listener help."},{"prompt":"The listener says: \"However much you share, you don't have to manage alone. Shall we think about a next step?\"","options":[{"text":"\"Yes please. Could you help me find a doctor near me?\"","then":"\"Yes. Let's go through it together, one step at a time.\"","best":true},{"text":"\"No, this was enough. I'll call again if it gets worse.\"","then":"\"That's fine. The line is open any time you want it.\""},{"text":"\"Can you fix it for me over the phone right now?\"","then":"\"I can't fix it on the phone, but I can help you reach people who can.\""},{"text":"\"Could you speak to my family and explain for me?\"","then":"\"I can't do that, but I can help you find the words to tell them.\""}],"why":"Asking for a doctor turns the call into a plan."}],"relearn":"A simple, honest opening is all a helpline needs; you don't have to have the words perfect to get support."},
  {"id":"ly-077","cat":"reach-out","type":"match","hook":"Match each worry about reaching out to the reassuring truth.","pairs":[{"left":"'I'll be judged'","right":"Helplines and doctors support, not judge"},{"left":"'It's not bad enough'","right":"You don't have to be in crisis to call"},{"left":"'Nothing will help'","right":"Support genuinely changes things"},{"left":"'I'll be a burden'","right":"People who care are glad to be trusted"},{"left":"'No one understands'","right":"Many parents feel exactly this way"}],"relearn":"Each worry about reaching out has a reassurance: no judgement, no threshold, real help, no burden, and you're not alone.","persona":"any","source":"worry to truth"},
  {"id":"ly-078","cat":"reach-out","type":"spot","hook":"Spot the two moves that keep a struggling parent stuck instead of getting support.","scene":[{"id":"a","text":"Telling a trusted person","trick":false},{"id":"b","text":"Hiding it to protect your image","trick":true},{"id":"c","text":"Calling a doctor or helpline","trick":false},{"id":"d","text":"Waiting until you've completely collapsed","trick":true},{"id":"e","text":"Saving a helpline before you need it","trick":false}],"why":"Hiding to protect an image and waiting for collapse keep you stuck; telling someone and calling for help are the strong moves.","relearn":"The strong moves are telling someone and calling for help; hiding to look fine and waiting for collapse keep you stuck.","persona":"any","source":"strong move"},
  {"id":"ly-079","cat":"healthy-coping","type":"role-play","persona":"Priya","source":"steer gently","hook":"A friend is coping with stress in an unhealthy way, and you want to steer her gently.","setup":"You sit together on her steps while the babies nap.","steps":[{"prompt":"Rekha admits: \"It's the only thing that gets me through the evening.\"","options":[{"text":"\"I get why you reach for it. Walk or chat with me next time?\"","then":"Rekha's shoulders drop. \"A walk with you? I'd like that.\"","best":true},{"text":"\"You're going to ruin your life doing that.\"","then":"Rekha goes red. \"Forget I said anything.\""},{"text":"\"Everyone has something like that. It's not a big deal.\"","then":"Rekha laughs, relieved but unmoved. \"Exactly. Nothing to worry about.\""},{"text":"\"You should stop, for your baby's sake.\"","then":"She looks down. \"Now I feel even worse.\""}],"why":"Understanding first, then a real alternative, keeps her talking to you."},{"prompt":"The next week Rekha sighs on the phone: \"Tonight is going to be a hard one.\"","options":[{"text":"\"Come over. We'll take the babies for a walk and talk.\"","then":"She sounds lighter. \"Give me twenty minutes. I'll bring the stroller.\"","best":true},{"text":"\"Then have it, just not around the baby.\"","then":"She says okay. You hang up, and the evening looks the same as always."},{"text":"\"Just try harder tonight. You know you can do it.\"","then":"She goes quiet. \"Right. I'll try.\" Her voice is flat."},{"text":"\"Text me afterwards, so I can check that you didn't have it.\"","then":"She goes quiet. \"I'm not a child.\" The call ends quickly."}],"why":"A concrete invitation offers the safer swap just when she needs it."},{"prompt":"Weeks on, Rekha says: \"Some nights it still feels too heavy to cope with.\"","options":[{"text":"\"That sounds heavy. Shall we call Tele-MANAS 14416 together?\"","then":"She takes a breath. \"Okay. Tonight, with you next to me.\"","best":true},{"text":"\"Try more walks and calls. They'll work if you stick to them.\"","then":"She nods, though the heavy nights carry on. She doesn't bring it up again."},{"text":"\"Everyone has heavy nights. That's part of being a parent.\"","then":"She smiles thinly. \"I suppose so.\" The subject closes."},{"text":"\"Try the habit less often and see how it goes.\"","then":"She agrees. A week on she is counting nights, and feeling worse."}],"why":"Coping tools are support, and heavy nights that continue deserve a helpline or doctor."}],"relearn":"A gentle, non-judging offer of a healthier alternative helps a friend far more than a harsh warning."},
  {"id":"ly-080","cat":"healthy-coping","type":"sort","hook":"Sort: a coping habit that helps in the long run, or one that costs you later?","items":[{"id":"a","text":"Talking it out with someone"},{"id":"b","text":"Numbing out every night"},{"id":"c","text":"A short daily wind-down"},{"id":"d","text":"Running on caffeine and no sleep"},{"id":"e","text":"Asking for help before you break"},{"id":"f","text":"Snapping and bottling the rest"}],"bins":[{"id":"helps","label":"Helps long-term","valence":"pos"},{"id":"costs","label":"Costs you later","valence":"neg"}],"key":{"a":"helps","b":"costs","c":"helps","d":"costs","e":"helps","f":"costs"},"relearn":"Talking it out, a daily wind-down and early help pay off; nightly numbing, no sleep and bottling up cost you later.","persona":"any","source":"helps vs costs"},
  {"id":"ly-081","cat":"healthy-coping","type":"match","hook":"Match each hard feeling to a healthy first response.","pairs":[{"left":"Overwhelmed","right":"Slow your breath, drop your shoulders"},{"left":"Isolated","right":"Message one person"},{"left":"Wired and exhausted","right":"Rest your body even if sleep won't come"},{"left":"On the edge of snapping","right":"Step out of the room for a minute"},{"left":"Numb and flat","right":"Step into daylight or fresh air"}],"relearn":"Overwhelm, isolation, wired exhaustion, near-snapping and numbness each have a gentle first response that steadies you.","persona":"any","source":"feeling to response"},
  {"id":"ly-082","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"one tap away","hook":"You want your phone set up so that help is one tap away on a bad day.","setup":"You raise it with your partner Isha over dinner.","steps":[{"prompt":"Isha asks: \"Where would we even start with that?\"","options":[{"text":"\"Let's save Tele-MANAS and our doctor first.\"","then":"Isha reaches for her phone. \"Give me the numbers. Tele-MANAS first.\"","best":true},{"text":"\"We'll look up numbers if we ever really need them.\"","then":"Isha shrugs. \"I suppose. It still bothers me, though.\""},{"text":"\"I'll sort it out on my own quietly and tell you when it's all done.\"","then":"She nods. If it comes to it, she won't know whom to call."},{"text":"\"Let's just save one number for now and see.\"","then":"Isha agrees. The one number sits alone on the list."}],"why":"Saved contacts turn a frantic search into a single tap."},{"prompt":"Isha asks: \"Would you want people on it too, or only helplines and the doctor?\"","options":[{"text":"\"Two people we trust, who'd pick up any time.\"","then":"\"My sister and your friend Arun,\" Isha says. \"I'll message them both today.\"","best":true},{"text":"\"Everyone we know, just in case.\"","then":"Isha laughs. Forty names later, nobody can tell whom to call first."},{"text":"\"Just the doctor. Family will only worry.\"","then":"Isha frowns. \"The clinic shuts at eight, though.\""},{"text":"\"Leave people off the list. The helplines are enough for the hard days.\"","then":"She nods slowly. \"A helpline won't know us, though.\""}],"why":"A couple of trusted people give everyday help that a helpline can't."},{"prompt":"Isha says: \"And what if it's a really bad day and nothing feels doable?\"","options":[{"text":"\"We breathe together, then call Tele-MANAS or our doctor. 112 if anyone's in danger.\"","then":"Isha nods. \"One tap. I'll pin them to the home screen.\"","best":true},{"text":"\"We'll cross that bridge when we get to it. There's no need to plan for a bad day now.\"","then":"Isha nods, though her shoulders stay tight."},{"text":"\"I'll sort it out and you can rest.\"","then":"She thanks you, and you both notice how much you'd be carrying alone."},{"text":"\"We ask around until somebody answers.\"","then":"Isha sighs. \"At midnight, who is that going to be?\""}],"why":"Breathing, then a saved line, and 112 for danger, make a bad day manageable."}],"relearn":"Saving help contacts in advance means that on a bad day support is one tap away, not a frantic search."},
  {"id":"ly-083","cat":"tools-and-help","type":"role-play","persona":"Divya","source":"when to get help","hook":"Your partner Kabir has seemed low since the baby came and keeps brushing it off.","setup":"You sit together over evening tea.","steps":[{"prompt":"Kabir asks: \"How would I even know when to get real help?\"","options":[{"text":"\"If it lasts weeks, gets heavier or scares you, go. Sooner is fine too.\"","then":"Kabir lets out a breath. \"So I don't have to wait until it's terrible.\"","best":true},{"text":"\"Only when you've reached the point where you can't function at all.\"","then":"Kabir nods. \"Right. I'm still functioning, then.\" He doesn't ask again."},{"text":"\"You'll just know when it gets really bad.\"","then":"Kabir frowns. \"What if I don't?\""},{"text":"\"If it lasts more than a few weeks, that's when to go.\"","then":"Kabir nods. \"So until then I just wait it out.\""}],"why":"Clear signs, and \"sooner is fine\", help someone act in time."},{"prompt":"Kabir says: \"I keep thinking it would be a fuss over nothing.\"","options":[{"text":"\"It's never a fuss. Early help is easier, and you deserve it now.\"","then":"He smiles a little. \"Okay. That helps.\"","best":true},{"text":"\"Maybe you're right. Let's see how the week goes.\"","then":"\"Yes,\" he says. \"One more week.\" He looks relieved and unsure."},{"text":"\"Fuss or not, I'll be the one to decide for you when it's time to go.\"","then":"Kabir stiffens. \"I want a say in it too.\""},{"text":"\"Everyone feels like this after a baby. It passes.\"","then":"He nods, but whatever he's feeling goes unsaid."}],"why":"You don't need to be in crisis to deserve help."},{"prompt":"Kabir says: \"Okay. Could you keep an eye on me too?\"","options":[{"text":"\"Yes, and you watch me too. Weekly check-ins, and a doctor whenever either of us wants.\"","then":"Kabir grins. \"Sunday evenings, then. Tea again.\"","best":true},{"text":"\"Yes, and if I see anything worrying I'll go ahead and book the doctor myself.\"","then":"Kabir sighs. \"I'd rather we decided that together.\""},{"text":"\"I'll say something if it looks really bad.\"","then":"He nods. You both know \"really bad\" comes late."},{"text":"\"We each need to manage our own moods, really.\"","then":"Kabir goes quiet. It feels like a door quietly closing."}],"why":"Agreeing to watch out for each other means neither of you waits alone."}],"relearn":"Give a clear, warm threshold: lasting, heavier or frightening. Saying sooner is okay helps a partner act in time."},
  {"id":"ly-084","cat":"tools-and-help","type":"spot","hook":"Spot the two responses that fail a parent's mental health. Tap the two red flags.","scene":[{"id":"a","text":"Meeting struggle with warmth and resources","trick":false},{"id":"b","text":"Telling them it's nothing, move on","trick":true},{"id":"c","text":"Helping them reach real care","trick":false},{"id":"d","text":"Shaming them for not coping","trick":true},{"id":"e","text":"Sitting with them while they call for help","trick":false}],"why":"\"It's nothing, move on\" and shaming them both fail a parent's mental health; warmth, resources and helping reach care honour it.","relearn":"A parent's mental health deserves warmth and real resources, never 'it's nothing' or shame for not coping.","persona":"any","source":"treat it seriously"},
  {"id":"ly-1080","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Divya","source":"blues pass","relearn":"Tearful, up-and-down days right after birth are common baby blues and usually pass within about two weeks.","hook":"\"If you cry in the first week after birth, something is wrong with you.\"","myth":{"un":"If you cry in the first week after birth, something is wrong with you.","re":"Tearfulness and mood swings in the first days are common 'baby blues' and usually settle within about two weeks.","why":"Early hormonal swings are normal and passing."}},
  {"id":"ly-1081","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Divya","source":"beyond two weeks","relearn":"Low or anxious feelings lasting beyond about two weeks may be PPD or anxiety and are a cue to seek care, not to keep waiting.","hook":"\"If the sadness lasts past two weeks, just wait longer and it'll fix itself.\"","myth":{"un":"If the sadness lasts past two weeks, just wait longer and it'll fix itself.","re":"Low, anxious or numb feelings lasting beyond about two weeks may be postpartum depression or anxiety, which need care, not more waiting.","why":"Lasting symptoms are a signal to seek help, not to wait."}},
  {"id":"ly-1082","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Divya","source":"not cheer up","relearn":"Postpartum depression is a real, treatable condition that needs care and support, not 'just think positive'.","hook":"\"A new mother who feels low just needs to think positive and count her blessings.\"","myth":{"un":"A new mother who feels low just needs to think positive and count her blessings.","re":"Postpartum depression is a real, treatable medical condition, not an attitude; it needs care and support, not 'just cheer up'.","why":"It is an illness, not a failure of gratitude."}},
  {"id":"ly-1083","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Vikram","source":"dads affected","relearn":"Fathers can get postnatal depression too; both partners should watch out for and support each other.","hook":"\"Fathers can't get depressed after a baby; that's a women-only thing.\"","myth":{"un":"Fathers can't get depressed after a baby; that's a women-only thing.","re":"Fathers can get postnatal depression too; research suggests around one in ten, so partners should watch out for each other.","why":"Both parents can be affected after a birth."}},
  {"id":"ly-1084","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Divya","source":"scary thought symptom","relearn":"A frightening intrusive thought can come with postnatal anxiety; it doesn't make you bad, it's a cue to get support.","hook":"\"A frightening thought about your baby means you're a danger and a bad parent.\"","myth":{"un":"A frightening thought about your baby means you're a danger and a bad parent.","re":"Frightening intrusive thoughts can come with postnatal anxiety and don't make you bad; they're a cue to get support quickly.","why":"A scary thought is a symptom, not a verdict."}},
  {"id":"ly-1085","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Divya","source":"numb is real","relearn":"Feeling numb or disconnected can be a symptom of postpartum depression, not proof you don't love your baby; it's treatable.","hook":"\"Feeling numb or disconnected from your baby just means you don't love them.\"","myth":{"un":"Feeling numb or disconnected from your baby just means you don't love them.","re":"Feeling numb or disconnected can be a symptom of postpartum depression, not a measure of love, and it can be treated.","why":"Numbness is a symptom that lifts with care."}},
  {"id":"ly-1086","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Vikram","source":"men ask too","relearn":"A father naming his struggle and asking for help is being strong, not weak; fathers deserve support too.","hook":"\"A father who admits he's struggling after the baby is weak and unmanly.\"","myth":{"un":"A father who admits he's struggling after the baby is weak and unmanly.","re":"Naming a struggle and asking for help is a strength for any parent; fathers struggle too and deserve support.","why":"Reaching out is strength, not weakness."}},
  {"id":"ly-1087","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Divya","source":"breastfeeding myth","relearn":"PPD is treatable and a doctor can find care that fits feeding; ask rather than assume you must just suffer through it.","hook":"\"If you have postnatal depression you can never get treatment while feeding the baby.\"","myth":{"un":"If you have postnatal depression you can never get treatment while feeding the baby.","re":"Postnatal depression is treatable, and a doctor can find care that fits feeding; ask rather than assuming you must suffer on.","why":"A doctor can tailor safe care to your situation."}},
  {"id":"ly-1088","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"any","source":"early help","relearn":"You needn't hit rock bottom to deserve help; naming low feelings early makes recovery easier.","hook":"\"You must hit rock bottom before postnatal depression counts enough to get help.\"","myth":{"un":"You must hit rock bottom before postnatal depression counts enough to get help.","re":"You don't have to be at your lowest to deserve help; naming low feelings early makes recovery easier.","why":"Early help works better and is kinder to you."}},
  {"id":"ly-1089","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Divya","source":"not your fault","relearn":"Postpartum depression is no one's fault; it can affect any parent and is treatable, not a punishment.","hook":"\"Getting postnatal depression means you did something wrong in your pregnancy.\"","myth":{"un":"Getting postnatal depression means you did something wrong in your pregnancy.","re":"Postpartum depression is no one's fault; it can affect any new parent and is a treatable condition, not a punishment.","why":"It is an illness, not a fault or a punishment."}},
  {"id":"ly-1090","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Meena","source":"appetite sleep","relearn":"Lasting changes in sleep or appetite plus low mood can be signs of postnatal depression worth raising with a doctor.","hook":"\"Losing your appetite or sleep for weeks after birth is just normal new-parent life.\"","myth":{"un":"Losing your appetite or sleep for weeks after birth is just normal new-parent life.","re":"Big, lasting changes in sleep or appetite alongside low mood can be signs of postnatal depression worth mentioning to a doctor.","why":"Lasting body-and-mood changes are worth a check."}},
  {"id":"ly-1091","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Divya","source":"happiest time","relearn":"You can love your baby and still feel low; struggling after birth is human and treatable, not ingratitude.","hook":"\"Everyone says this is the happiest time, so if you feel awful you must be ungrateful.\"","myth":{"un":"Everyone says this is the happiest time, so if you feel awful you must be ungrateful.","re":"You can love your baby and still feel low or anxious; struggling after birth is human and treatable, not ingratitude.","why":"Love and low mood can exist at the same time."}},
  {"id":"ly-1092","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Vikram","source":"partner watch","relearn":"Partners should watch out for each other; gently naming a loved one's low mood can open the door to help.","hook":"\"It's not a partner's place to notice or mention the other one's low mood after a baby.\"","myth":{"un":"It's not a partner's place to notice or mention the other one's low mood after a baby.","re":"Partners should watch out for each other; gently naming a loved one's low mood with care can open the door to help.","why":"A caring word can be the first step to support."}},
  {"id":"ly-1093","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"Divya","source":"anxiety counts","relearn":"Constant racing worry or dread after a baby is postnatal anxiety, just as real as low mood and treatable.","hook":"\"Only crying sadness is real; constant racing worry after a baby doesn't count.\"","myth":{"un":"Only crying sadness is real; constant racing worry after a baby doesn't count.","re":"Postnatal anxiety, with constant racing worry or dread, is just as real as low mood and is treatable with support.","why":"Anxiety after birth is real and treatable too."}},
  {"id":"ly-1094","cat":"baby-blues-and-beyond","type":"strike-rewrite","persona":"any","source":"treatable hope","relearn":"Postnatal depression is treatable; with support most parents come to feel like themselves again.","hook":"\"If postnatal depression hits, you'll feel this way forever and nothing helps.\"","myth":{"un":"If postnatal depression hits, you'll feel this way forever and nothing helps.","re":"Postnatal depression is treatable; with the right support most parents feel like themselves again over time.","why":"It is treatable, and people do recover."}},
  {"id":"ly-1095","cat":"baby-blues-and-beyond","type":"sort","persona":"Divya","source":"blues vs help","relearn":"Brief up-and-down days that lift are likely blues; weeks of low, numb or hopeless feelings are signs to seek help.","hook":"Sort each into likely passing baby blues, or a sign to seek help.","items":[{"id":"a","text":"Teary and up-and-down for a few days"},{"id":"b","text":"Low or anxious most days for weeks"},{"id":"c","text":"Mood lifting as the first week passes"},{"id":"d","text":"Losing interest in the baby or in living"},{"id":"e","text":"Mood swings that settle by two weeks"},{"id":"f","text":"Feeling numb or hopeless that won't lift"}],"bins":[{"id":"blues","label":"Likely baby blues","valence":"pos"},{"id":"help","label":"Seek help","valence":"tell"}],"key":{"a":"blues","b":"help","c":"blues","d":"help","e":"blues","f":"help"}},
  {"id":"ly-1096","cat":"baby-blues-and-beyond","type":"sort","persona":"any","source":"caring vs harmful","relearn":"'Common and treatable', 'you're not alone' and 'let's call the doctor' are caring; 'snap out of it' or 'good mothers don't' are harmful.","hook":"Sort each reply to a struggling new parent into caring, or harmful.","items":[{"id":"a","text":"'This is common and treatable, let's get help'"},{"id":"b","text":"'Snap out of it, others manage fine'"},{"id":"c","text":"'You're not alone, I'm here with you'"},{"id":"d","text":"'Good mothers don't feel this way'"},{"id":"e","text":"'Let's call the doctor together'"},{"id":"f","text":"'Stop being so dramatic about a baby'"}],"bins":[{"id":"caring","label":"Caring & accurate","valence":"pos"},{"id":"harmful","label":"Harmful","valence":"neg"}],"key":{"a":"caring","b":"harmful","c":"caring","d":"harmful","e":"caring","f":"harmful"}},
  {"id":"ly-1097","cat":"baby-blues-and-beyond","type":"sort","persona":"Divya","source":"normal vs flag","relearn":"Tiredness that eases with rest is ordinary; constant dread, weeks without joy or thoughts of being apart are worth flagging.","hook":"Sort each into ordinary tired new-parent days, or a sign worth flagging.","items":[{"id":"a","text":"Yawning through a broken-sleep morning"},{"id":"b","text":"Dreading each day with constant racing worry"},{"id":"c","text":"Feeling rusty but glad to hold the baby"},{"id":"d","text":"No joy in anything for weeks on end"},{"id":"e","text":"A hard hour that passes after a rest"},{"id":"f","text":"Feeling you and the baby would be better apart"}],"bins":[{"id":"ordinary","label":"Ordinary tired","valence":"pos"},{"id":"flag","label":"Worth flagging","valence":"uhoh"}],"key":{"a":"ordinary","b":"flag","c":"ordinary","d":"flag","e":"ordinary","f":"flag"}},
  {"id":"ly-1098","cat":"baby-blues-and-beyond","type":"sort","persona":"Vikram","source":"dad signs","relearn":"Settling in with support is just adjusting; weeks of hopelessness, withdrawal or numbing with drink mean check with a doctor, dads too.","hook":"Sort each father's experience into just adjusting, or worth checking with a doctor.","items":[{"id":"a","text":"Tired but proud carrying the routine"},{"id":"b","text":"Irritable and hopeless for weeks"},{"id":"c","text":"Nervous at first, then settling in"},{"id":"d","text":"Withdrawing from the baby and everyone"},{"id":"e","text":"Finding his feet with some support"},{"id":"f","text":"Drinking more to numb a low mood"}],"bins":[{"id":"adjusting","label":"Just adjusting","valence":"pos"},{"id":"check","label":"Check with a doctor","valence":"tell"}],"key":{"a":"adjusting","b":"check","c":"adjusting","d":"check","e":"adjusting","f":"check"}},
  {"id":"ly-1099","cat":"baby-blues-and-beyond","type":"sort","persona":"any","source":"myth vs true","relearn":"PPD being real and treatable, a scary thought being a symptom, and early help working better are true; the rest are myths to set down.","hook":"Sort each statement about post-birth mood into a myth, or a true thing.","items":[{"id":"a","text":"PPD is real and treatable"},{"id":"b","text":"Only mothers get low after a baby"},{"id":"c","text":"A scary thought is a symptom, not a verdict"},{"id":"d","text":"You must wait until you collapse to get help"},{"id":"e","text":"Early help works better"},{"id":"f","text":"Struggling means you're a bad parent"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"}},
  {"id":"ly-1100","cat":"baby-blues-and-beyond","type":"sort","persona":"Divya","source":"who to tell","relearn":"A doctor, a helpline and a trusted listener can genuinely help; people who shame, compare or say 'just hide it' only add pressure.","hook":"Sort each into a person who can genuinely help, or one who only adds pressure.","items":[{"id":"a","text":"A doctor who can assess and treat"},{"id":"b","text":"A relative who says 'don't shame us'"},{"id":"c","text":"A helpline counsellor any time"},{"id":"d","text":"A neighbour who compares you to others"},{"id":"e","text":"A trusted friend who listens"},{"id":"f","text":"Someone who tells you to just hide it"}],"bins":[{"id":"help","label":"Can help","valence":"pos"},{"id":"pressure","label":"Adds pressure","valence":"neg"}],"key":{"a":"help","b":"pressure","c":"help","d":"pressure","e":"help","f":"pressure"}},
  {"id":"ly-1101","cat":"baby-blues-and-beyond","type":"sort","persona":"Divya","source":"now vs soon","relearn":"Frightening thoughts of harm or 'no point being here' mean reach for help right away; lasting low mood or extra worry are things to raise soon.","hook":"Sort each into reach for help right away, or raise it soon with someone.","items":[{"id":"a","text":"Frightening thoughts of harming self or baby"},{"id":"b","text":"Feeling flat and tearful for a couple of weeks"},{"id":"c","text":"Feeling there's no point in being here"},{"id":"d","text":"Low energy and little interest lately"},{"id":"e","text":"A sudden urge that scares you badly"},{"id":"f","text":"Worrying more than usual about the baby"}],"bins":[{"id":"now","label":"Right away","valence":"uhoh"},{"id":"soon","label":"Raise it soon","valence":"tell"}],"key":{"a":"now","b":"soon","c":"now","d":"soon","e":"now","f":"soon"}},
  {"id":"ly-1102","cat":"baby-blues-and-beyond","type":"sort","persona":"Priya","source":"support net parts","relearn":"Friends, family and neighbours give everyday support; doctors, counsellors and therapists give trained care, and a parent's net needs both.","hook":"Sort each support into everyday listening, or trained care.","items":[{"id":"a","text":"A friend who hears you out over chai"},{"id":"b","text":"A doctor who can assess and treat"},{"id":"c","text":"A sister who takes the baby for an hour"},{"id":"d","text":"A counsellor on a mental-health helpline"},{"id":"e","text":"A neighbour who drops off a hot meal"},{"id":"f","text":"A trained therapist for talk therapy"}],"bins":[{"id":"everyday","label":"Everyday support","valence":"pos"},{"id":"trained","label":"Trained care","valence":"tell"}],"key":{"a":"everyday","b":"trained","c":"everyday","d":"trained","e":"everyday","f":"trained"}},
  {"id":"ly-1103","cat":"baby-blues-and-beyond","type":"match","persona":"Divya","source":"sign to step","relearn":"Rest for brief blues, a doctor for lasting symptoms, urgent help for scary thoughts: the step follows how deep the feelings run.","hook":"Match each post-birth experience to its gentle next step.","pairs":[{"left":"A few teary days that ease by two weeks","right":"Rest and lean on support"},{"left":"Low or anxious most days for weeks","right":"Talk to a doctor or helpline"},{"left":"Frightening thoughts of self or baby","right":"Reach for help right away"},{"left":"Constant racing worry you can't calm","right":"Mention anxiety to a doctor"},{"left":"Feeling numb, no joy in the baby","right":"Raise it with a trusted person"}]},
  {"id":"ly-1104","cat":"baby-blues-and-beyond","type":"match","persona":"any","source":"myth to truth","relearn":"Each myth has a kinder truth: PPD is treatable, fathers are affected, a scary thought is a symptom, help is strength, early help works best.","hook":"Match each post-birth myth to the truth that replaces it.","pairs":[{"left":"PPD isn't real, just cheer up","right":"A real, treatable condition"},{"left":"Only mothers are affected","right":"Fathers can get it too"},{"left":"A scary thought makes you a monster","right":"It's a symptom, a cue to get help"},{"left":"Asking for help is weak","right":"Reaching out is a strength"},{"left":"Wait until you collapse","right":"Early help works better"}]},
  {"id":"ly-1105","cat":"baby-blues-and-beyond","type":"match","persona":"Priya","source":"support to role","relearn":"A parent's net has parts: friends for listening, family for practical help, a doctor for treatment, a helpline any time, a counsellor for structure.","hook":"Match each support to what it does best for a struggling parent.","pairs":[{"left":"A trusted friend","right":"Everyday listening and a kind ear"},{"left":"A family member nearby","right":"Practical help with the baby and chores"},{"left":"A doctor","right":"Assessment and treatment"},{"left":"A mental-health helpline","right":"Support to talk to any time of day"},{"left":"A counsellor","right":"Structured sessions to work things through"}]},
  {"id":"ly-1106","cat":"baby-blues-and-beyond","type":"match","persona":"Vikram","source":"dad feeling to fact","relearn":"A father's fears meet facts: dads are affected, help is strength, you needn't be alone, both parents matter, it's never too late to ask.","hook":"Match each thing a struggling father feels to a steadying fact.","pairs":[{"left":"\"Real men don't get low after a baby\"","right":"Fathers can be affected too"},{"left":"\"Asking for help means I've failed\"","right":"Reaching out is a strength"},{"left":"\"I should push through alone\"","right":"You needn't do this alone"},{"left":"\"My low mood doesn't matter, only hers\"","right":"Both parents matter"},{"left":"\"It's too late to say anything\"","right":"It's never too late to reach out"}]},
  {"id":"ly-1107","cat":"baby-blues-and-beyond","type":"match","persona":"Divya","source":"worry to reassurance","relearn":"Each worry has a reassurance: a thought isn't an act, numbness isn't a verdict, you're not alone, help is care, recovery takes time.","hook":"Match each new-parent worry to a true reassurance.","pairs":[{"left":"\"A scary thought means I'll act on it\"","right":"A thought is a symptom, not an act"},{"left":"\"Numb means I don't love my baby\"","right":"Numbness is a symptom, not a verdict"},{"left":"\"I'm the only one who feels this\"","right":"It's common after a birth"},{"left":"\"Getting help means they'll take the baby\"","right":"Help is care, not punishment"},{"left":"\"I should be over this by now\"","right":"Recovery takes time"}]},
  {"id":"ly-1108","cat":"baby-blues-and-beyond","type":"match","persona":"any","source":"route to need","relearn":"Each support fits a moment: Tele-MANAS 14416 any time, a doctor for treatment, a parents' group for company, 112 for danger.","hook":"Match each India support to the moment it fits.","pairs":[{"left":"Tele-MANAS 14416","right":"Talk to mental-health support any time"},{"left":"A parents' support group","right":"Others who've felt the same"},{"left":"A doctor","right":"Assessment and ongoing treatment"},{"left":"Emergency 112","right":"Immediate danger to anyone right now"},{"left":"A trusted person","right":"Everyday listening and company"}]},
  {"id":"ly-1109","cat":"baby-blues-and-beyond","type":"match","persona":"Divya","source":"blues vs ppd traits","relearn":"Early, brief, self-easing low mood points to baby blues; lasting low mood, numbness or constant dread points to PPD or anxiety.","hook":"Match each trait to whether it points to baby blues or to PPD.","pairs":[{"left":"Starts in the first days after birth","right":"Typical of baby blues"},{"left":"Eases on its own within about two weeks","right":"Usually baby blues passing"},{"left":"Lasts well beyond two weeks","right":"May be postpartum depression"},{"left":"Includes lost interest or numbness","right":"A sign to seek help for PPD"},{"left":"Comes with constant dread and racing worry","right":"May be postnatal anxiety"}]},
  {"id":"ly-1110","cat":"baby-blues-and-beyond","type":"branch","persona":"Divya","source":"weeks low tell","hook":"For weeks you've felt low, anxious and disconnected from your baby, and scared to say so.","steps":[{"prompt":"Your friend Meera calls and asks how motherhood is going. What do you say?","options":[{"text":"Say it's been hard and you've felt low for weeks","then":"Meera pauses. \"Thank you for telling me. I'm listening.\"","best":true},{"text":"Say it's wonderful and send lots of baby photos","then":"Meera coos at the photos. You hang up feeling more alone."},{"text":"Say you're just adjusting and change the subject","then":"She lets it go. The real feeling stays unspoken."},{"text":"Joke that every new mother feels a bit low and move on","then":"Meera laughs along. The real weight of it never comes out."}],"why":"Saying it plainly to one person lets someone start helping you."},{"prompt":"Later that week, a thought tells you to be grateful and stay quiet. What do you do?","options":[{"text":"Decide to see a doctor about these weeks","then":"The thought softens. You call the clinic and ask for the earliest slot.","best":true},{"text":"Agree with the thought and stop talking about it all","then":"The house is quiet. You feel the weight more, and tell no one."},{"text":"Write it in a diary and show nobody","then":"The page holds it for now. Nobody who could help knows."},{"text":"Wait until the baby is older to feel better","then":"The months go on. The low feeling stays with you."}],"why":"Low mood after birth is not ingratitude. A doctor can help, and it is never your fault."},{"prompt":"Your partner Kabir finds you crying and asks what's wrong. What do you do?","options":[{"text":"Tell him about the weeks and ask him to see a doctor with you","then":"He sits down beside you. \"Of course. Let's go together.\"","best":true},{"text":"Say it's just hormones and it will pass with time","then":"He nods, relieved, and goes to check on the baby."},{"text":"Say you only need a few more hours of sleep","then":"He promises to take the night shift. The low feeling stays for the whole day."},{"text":"Tell him, but ask him not to push for a doctor","then":"He agrees, uneasy. The two of you carry it, and no help comes."}],"why":"Bringing your partner along means you have company, and help starts sooner."}],"debrief":"Lasting low, anxious, disconnected feelings after birth are treatable; tell a trusted person and a doctor.","relearn":"Post-birth low mood that lasts is treatable. Reaching out helps; hiding it only prolongs it."},
  {"id":"ly-1111","cat":"baby-blues-and-beyond","type":"branch","persona":"Vikram","source":"partner withdrawn","hook":"Your partner Isha has seemed hopeless and withdrawn for weeks since the birth.","steps":[{"prompt":"Isha leaves her food untouched again and lets the baby's cries wait for you. What do you do?","options":[{"text":"Say you're worried and ask what she needs","then":"She looks up slowly. \"I don't know. I just feel empty.\"","best":true},{"text":"Tell her she must eat and push the plate closer","then":"She takes a bite to please you. The emptiness stays."},{"text":"Tell yourself she's tired and give it a few weeks","then":"The weeks pass. She eats less and talks less."},{"text":"Tell your parents so they can talk to her","then":"Your mother tells Isha to smile more for the baby. She goes to the bedroom."}],"why":"Saying you're worried, then asking, invites her to speak without pressure."},{"prompt":"Later, Isha says quietly that she should be coping better than this. What do you say?","options":[{"text":"It's not your fault. It can be treated, and we'll get help","then":"Tears slip down her face. She leans into your shoulder.","best":true},{"text":"Don't say that. You're a wonderful mother to our baby","then":"She gives a thin smile. \"That's not what I meant,\" she murmurs."},{"text":"You just need rest. I'll take the night feeds tonight","then":"She sleeps more. The heaviness is still there when she wakes."},{"text":"Every new mother struggles, Isha. Don't worry.","then":"She nods and stops talking about it."}],"why":"Saying it isn't her fault and can be treated opens the door to help."},{"prompt":"At dinner, your mother says Isha is being lazy and should keep busy. What do you do?","options":[{"text":"Say calmly that Isha is unwell and needs a doctor","then":"Your mother goes quiet. After dinner, Isha agrees you'll call the doctor together.","best":true},{"text":"Stay silent to keep the peace at the table","then":"Dinner ends politely. Isha goes to bed early and says nothing."},{"text":"Snap that your mother has no idea what she's saying","then":"Your mother is stung and leaves the table. Isha shrinks in her chair."},{"text":"Agree that fresh air and a few chores might help","then":"Isha clears the dishes without a word. She looks further away than before."}],"why":"Standing beside Isha, calmly, and getting her seen shows her the illness is real."}],"debrief":"Weeks of hopelessness and withdrawal after birth need gently raising and support; it's treatable.","relearn":"Gently support a partner's lasting low mood; don't wait for them to 'snap out of it'."},
  {"id":"ly-1112","cat":"baby-blues-and-beyond","type":"branch","persona":"Vikram","source":"dad own low","hook":"You're a new father, flat and irritable for weeks, telling yourself men don't get this.","steps":[{"prompt":"A colleague asks why you've been so short-tempered at work. What do you say?","options":[{"text":"Say you've felt off since the baby arrived","then":"He nods. \"That sounds heavy. Have you told anyone?\"","best":true},{"text":"Say work has been heavy and leave it there","then":"He shrugs and the chat moves on. You feel unseen."},{"text":"Say new fathers just have to get on with it","then":"He laughs and agrees. You go back to your desk feeling worse."},{"text":"Say the only problem is that you aren't sleeping","then":"He says his baby was the same. You go home no lighter."}],"why":"Admitting you've felt off is the first step toward finding out why."},{"prompt":"Your partner Anita says you've been snapping at her and the baby. What do you do?","options":[{"text":"Tell her you've felt flat and want to see a doctor","then":"Her face softens. \"Thank you for telling me. I'll come if you like.\"","best":true},{"text":"Promise you'll try harder to stay patient from now on","then":"She nods, unsure. Two days later the same tension is back."},{"text":"Say she's the tired one and she's being sensitive again","then":"She stares at you, then leaves the room without answering."},{"text":"Say men don't feel down over this and drop the subject","then":"She goes quiet. The distance stays between you."}],"why":"Telling her plainly and booking a doctor treats this as real, and it is not your fault."},{"prompt":"At a family lunch, an uncle jokes that only mothers get low after a baby. What do you do?","options":[{"text":"Say calmly that fathers can struggle after a baby too","then":"The table goes quiet. Your cousin says, \"Me too, after my son.\"","best":true},{"text":"Laugh along and change the subject to the food","then":"The laugh comes easily. Inside, you feel more alone."},{"text":"Snap that he knows nothing about it, in front of everyone","then":"The uncle looks offended and the lunch turns tense."},{"text":"Say nothing, and wonder if he's right about fathers","then":"You leave early, with a polite excuse. The doubt follows you home."}],"why":"Naming the myth makes room for other fathers, and what you share about yourself is your choice."}],"debrief":"Fathers can develop postnatal depression; naming it and seeing a doctor is a strong, caring move.","relearn":"Fathers can struggle after a baby too; naming it and seeing a doctor is strength, not weakness."},
  {"id":"ly-1113","cat":"baby-blues-and-beyond","type":"branch","persona":"Arjun","source":"dads get pnd too","hook":"Weeks after the baby arrived you feel numb and low, but think dads don't get this.","steps":[{"prompt":"At the baby's checkup, the doctor asks if you're doing okay too. What do you say?","options":[{"text":"Say you've felt numb and low for weeks","then":"The doctor nods. \"Thank you for saying so. Let's talk about it.\"","best":true},{"text":"Say you're fine and it's your partner who needs care","then":"The doctor turns back to the baby. The question doesn't come again."},{"text":"Say dads don't really feel this way","then":"The doctor smiles politely and writes the baby's weight."},{"text":"Say you'll bring it up at another visit","then":"The visit ends. The next one is two months away."}],"why":"Telling a doctor plainly lets them check on you, not only the baby."},{"prompt":"Later, you read that postnatal depression can affect fathers too. What do you do?","options":[{"text":"Take it seriously and book your own visit","then":"You book a slot for the week. It feels like a heavy thing set down.","best":true},{"text":"Decide yours must be milder than others' and skip it","then":"The days pass. The numbness is still there each morning."},{"text":"Tell yourself you would know if it were serious","then":"You wait to feel worse. Nothing changes and nothing gets checked."},{"text":"Read more about it but tell no one","then":"The reading helps you understand. You still carry it alone."}],"why":"Fathers get it too, and an early visit is easier than waiting for it to grow."},{"prompt":"Your brother asks over chai why you've gone so quiet. What do you say?","options":[{"text":"Say you've been low since the baby and need a doctor","then":"He puts his cup down. \"I'm glad you told me. I'll be around.\"","best":true},{"text":"Say you're just tired from the night feeds and work","then":"He nods. \"Babies do that.\" He doesn't ask again."},{"text":"Say fathers aren't supposed to say things like this","then":"He shifts, unsure what to answer, and changes the topic."},{"text":"Laugh and say it's nothing, then talk cricket scores","then":"The chai goes down easily. The low feeling stays unspoken."}],"why":"Telling someone you trust means you are no longer holding it alone."}],"debrief":"Postnatal depression affects fathers as well; a flat, hopeless stretch is worth raising.","relearn":"Fathers get postnatal depression too; a flat, hopeless stretch is worth raising with a doctor."},
  {"id":"ly-1114","cat":"baby-blues-and-beyond","type":"branch","persona":"Divya","source":"in-law dismiss","hook":"You tell your aunty you feel low, and she says to stop bringing shame and just stay busy.","steps":[{"prompt":"Her words replay at night and the low feeling is still there. What do you do?","options":[{"text":"Save a doctor's number and Tele-MANAS 14416","then":"You save both. It feels like a small door left open.","best":true},{"text":"Follow her advice and fill every hour with work","then":"The house is spotless. You fall into bed emptier than before."},{"text":"Decide she's right and stop thinking about it","then":"The thoughts go quiet on the surface. They wait underneath."},{"text":"Wait for her to raise it again before doing anything","then":"She doesn't. Days pass and you tell no one else."}],"why":"You can respect her and still keep a door open to a doctor or helpline."},{"prompt":"Your partner Sameer sees you scrubbing the kitchen at midnight and asks why. What do you say?","options":[{"text":"Tell him you feel low and busy isn't helping","then":"He takes the cloth gently. \"Sit with me. Tell me more.\"","best":true},{"text":"Say you can't sleep and there's no reason","then":"He yawns and says to rest soon. He goes to bed."},{"text":"Say you're just keeping busy, as Aunty said","then":"He nods, satisfied, and doesn't ask more."},{"text":"Say it's nothing and ask him not to ask again","then":"He agrees, though he glances back at you on the way out."}],"why":"Telling him what you feel gives you an ally, and it isn't your fault."},{"prompt":"Aunty visits and asks if you've stopped being so gloomy. What do you do?","options":[{"text":"Thank her, then call the doctor once she leaves","then":"She stays for tea. That evening you book an appointment for Thursday.","best":true},{"text":"Say you're much better, and put off calling","then":"She smiles and moves on. Another week passes without a call."},{"text":"Ask her permission to see a doctor","then":"She says there's no need. You let the idea rest."},{"text":"Argue that she doesn't understand at all","then":"The room goes tense. She leaves early and hurt."}],"why":"Thanking her and still calling the doctor keeps the peace and your route to help."},{"prompt":"A neighbour who heard from Aunty says that seeing a doctor for low mood would only start gossip. What do you do?","options":[{"text":"See a doctor anyway, and tell only people you trust","then":"You sit in the doctor's room that week. She listens and takes you seriously.","best":true},{"text":"Drop the idea of a doctor to avoid any talk","then":"The days pass quietly. The low feeling doesn't go with the gossip."},{"text":"Ask the neighbour to decide what you should do","then":"She tells you to wait. You leave feeling uncertain."},{"text":"Wait until any talk dies down first","then":"Weeks slip by. The gossip fades. The low feeling doesn't."}],"why":"Your wellbeing matters more than gossip. Going quietly is still getting help."}],"debrief":"If family dismisses your low mood, you can still reach a doctor or helpline; your wellbeing matters.","relearn":"If relatives dismiss your low mood, you can still reach a doctor or helpline; you matter."},
  {"id":"ly-1115","cat":"baby-blues-and-beyond","type":"branch","persona":"Divya","source":"first appointment","hook":"You've decided to get help but freeze, unsure how to even start the conversation.","steps":[{"prompt":"The clinic's number is on your screen and your thumb hovers. What do you do?","options":[{"text":"Jot a few honest lines, then call","then":"You write three plain lines, then dial. The phone starts to ring.","best":true},{"text":"Wait until you can explain it perfectly","then":"Perfect words don't come. Another day goes by without the call."},{"text":"Put the phone down and try again tomorrow","then":"Tomorrow arrives with the same hovering thumb."},{"text":"Ask a friend what to say and call later","then":"She sends you tips. The call stays on your list."}],"why":"You don't need perfect words. A few honest lines are enough to start."},{"prompt":"When you get through, the receptionist asks how she can help. What do you say?","options":[{"text":"Ask for a doctor's slot about how you've been feeling","then":"She finds you one on Thursday morning.","best":true},{"text":"Say it's probably nothing and you're wasting her time","then":"She gently books you in anyway. You feel you've made yourself small."},{"text":"Book only the baby's check, and hope to mention yourself","then":"She books the baby's slot. You'll have to raise yourself there."},{"text":"Say you'll call back another day and hang up","then":"The line goes quiet. Days pass before you dare to call back and book."}],"why":"You don't have to explain to reception. Asking for a slot for yourself is enough."},{"prompt":"On the day, you have a few lines written on a page, and the doctor is waiting. What do you do?","options":[{"text":"Read your lines aloud, even if your voice shakes","then":"The doctor listens closely. \"Thank you. That took courage. Let's talk.\"","best":true},{"text":"Fold the page away and say you're fine","then":"The doctor nods and moves on. The page stays in your bag."},{"text":"Start with the baby and hope she asks about you","then":"She asks about feeds and sleep. Your lines stay folded."},{"text":"Say you've forgotten what you meant to say","then":"The doctor waits kindly. You leave with the words unsaid."}],"why":"Reading a few lines aloud is a real start, and it is never your fault."}],"debrief":"You don't need perfect words; a few honest lines to a doctor or helpline are enough to start.","relearn":"You don't need perfect words to ask for help; a few honest lines to a doctor or helpline are enough."},
  {"id":"ly-1116","cat":"baby-blues-and-beyond","type":"branch","persona":"Vikram","source":"both struggling","hook":"Both you and your partner feel low and snappy weeks after the birth, each pretending to be fine.","steps":[{"prompt":"Sunita snaps about the unwashed bottles, then says she's fine. What do you say?","options":[{"text":"Say you're not fine either and ask how she is","then":"She lets out a shaky breath. \"No. I'm not.\"","best":true},{"text":"Say you're fine too and wash the bottles","then":"She thanks you stiffly. Neither of you says more."},{"text":"Say you're both just tired and it will pass","then":"She agrees quickly. The tension stays in the room."},{"text":"Tell her to rest while you cope on your own","then":"She goes to lie down. You stay up feeling alone."}],"why":"Admitting you're not fine gives her permission to say the same."},{"prompt":"Sunita's mother calls and asks if the two of you are managing. What do you say?","options":[{"text":"Say honestly that you're both finding it hard","then":"Her mother is quiet, then says, \"I'll come this weekend and help.\"","best":true},{"text":"Say you're managing beautifully","then":"Her mother laughs happily. You hang up feeling more alone."},{"text":"Say Sunita is a bit tired and nothing more","then":"She tells Sunita to rest more. Sunita gives a tight smile."},{"text":"Say you're busy and will call back later","then":"You don't call back. Nobody knows how things are."}],"why":"Being honest lets family step in to help, instead of guessing."},{"prompt":"At 3am, you're both up with the baby and worn thin. What do you do?","options":[{"text":"Plan so one of you sleeps a full stretch tonight","then":"One of you sleeps four hours straight. The morning is less sharp.","best":true},{"text":"Both stay up to show you can cope","then":"The night drags. By morning neither of you has said a kind word."},{"text":"Argue about which of you is more tired tonight","then":"You both say things you don't mean. The baby cries louder."},{"text":"Scroll your phones and say little","then":"The screens glow. The silence between you deepens."}],"why":"A shared plan for rest is a small, real way of looking after each other."},{"prompt":"A couple of weeks on, the low feeling hasn't lifted for either of you. What do you do?","options":[{"text":"See a doctor, each of you, and tell one relative","then":"Both of you get seen. Sunita's mother takes the baby for an afternoon.","best":true},{"text":"Wait for the baby to sleep through the night","then":"Months could pass. Neither of you is sure the feeling will wait."},{"text":"Keep the 'I'm fine' act, but cheerfully","then":"The act gets smoother. The two of you feel further apart."},{"text":"Only Sunita goes, since mothers get this","then":"She goes alone. You stay quiet about how flat you feel too."}],"why":"Both parents can be affected, so both deserve care. It's not a failing in either of you."}],"debrief":"Both parents can struggle at once; naming it and seeking support together beats pretending to be fine.","relearn":"Both parents can struggle at once; naming it together and seeking support beats two 'I'm fine' acts."},
  {"id":"ly-1117","cat":"baby-blues-and-beyond","type":"branch","persona":"Divya","source":"numb no joy","hook":"For weeks nothing brings you joy and you feel numb, even holding your baby.","steps":[{"prompt":"Your mother-in-law coos at the baby and says you must be so happy. What do you say?","options":[{"text":"Say you've felt numb lately and want to ask a doctor","then":"She looks surprised, then says, \"Beta, go and ask. I'll watch the baby.\"","best":true},{"text":"Smile and agree you're so happy","then":"She beams. You smile until she leaves, then sit very still."},{"text":"Say you're tired and leave it there","then":"She says every mother is tired. The numbness goes unmentioned."},{"text":"Say quietly that maybe you aren't cut out for this","then":"She tuts kindly and says you'll learn. The thought settles in you."}],"why":"Naming the numbness and asking a doctor is a steadier start than hiding it."},{"prompt":"At night, a thought says a real mother would feel love by now. What do you do?","options":[{"text":"Treat it as a symptom to tell a doctor about","then":"The thought loses some weight. You note it down for the visit.","best":true},{"text":"Believe the thought and hide how you feel","then":"The thought grows louder. You hold the baby and say nothing."},{"text":"Act extra loving and hope feelings follow","then":"You perform tenderness all day. The numbness stays behind it."},{"text":"Wait for the love to arrive on its own","then":"The weeks continue. The waiting feels lonelier each day."}],"why":"Numbness after birth is a symptom, not proof of being a bad mother."},{"prompt":"Your partner Neel says you seem far away, even with the baby, and asks what's wrong. What do you say?","options":[{"text":"Tell him about the numbness and ask for a doctor","then":"He sits beside you. \"Thank you for telling me. We'll do it together.\"","best":true},{"text":"Say you're just worn out and it will pass","then":"He nods, though he watches you carefully."},{"text":"Say you're a bad mother and he should take over","then":"He protests, but takes the baby. The shame stays with you."},{"text":"Say nothing and hand him the baby","then":"He takes her gently. Neither of you says a word."}],"why":"Telling him plainly gets you help, and none of this is your fault."}],"debrief":"Weeks of numbness and no joy can be a symptom of PPD; tell a doctor rather than blaming yourself.","relearn":"Weeks of numbness and no joy can be a symptom of PPD worth telling a doctor, not proof you're a bad parent."},
  {"id":"ly-1118","cat":"baby-blues-and-beyond","type":"branch","persona":"Priya","source":"friend confides","hook":"Your friend Rekha, a new mother, asks to talk to you alone over tea.","steps":[{"prompt":"Rekha whispers that she has cried every day for weeks and doesn't know why. What do you say?","options":[{"text":"Thank her for telling you and listen without fixing","then":"She lets out a long breath. \"I haven't said this to anyone.\"","best":true},{"text":"Tell her everyone feels this way and to toughen up","then":"She nods and looks down. After a long pause she speaks again, more quietly."},{"text":"Tell her she's lucky to have a healthy baby","then":"She whispers, \"I know.\" Her eyes fill again."},{"text":"Say it's probably hormones and will pass","then":"She wants to believe it. Nothing changes that week."}],"why":"Listening without fixing tells her that it is safe to speak."},{"prompt":"Rekha says she's ashamed and afraid people will judge her. What do you say?","options":[{"text":"Say it isn't her fault and that help exists","then":"She wipes her eyes. \"Really? Nobody said that to me.\"","best":true},{"text":"Say she'd better not tell anyone in the family","then":"She nods. The secret sits heavier between you."},{"text":"Say she should try to think happier thoughts","then":"She tries, and feels worse for failing."},{"text":"Say she's being too hard on herself and leave it","then":"She nods politely and changes the topic."}],"why":"Telling her it isn't her fault and help exists eases the shame."},{"prompt":"A few days later, Rekha messages that she's still crying and asks what she should do. What do you say?","options":[{"text":"Ask if she'd like your help booking a doctor","then":"She says yes, hesitant. You sit with her while she makes the call.","best":true},{"text":"Suggest she waits until the baby is older","then":"Months could pass. She waits, and the crying continues."},{"text":"Send her a list of home remedies","then":"She thanks you and tries a few. The crying continues."},{"text":"Book the appointment and tell her the time","then":"She feels rushed and doesn't turn up."}],"why":"Offering help and asking first respects her pace, and gets her seen."},{"prompt":"A week later, Rekha texts that she's feeling fine now and there's no need for any fuss. What do you do?","options":[{"text":"Check in warmly and offer to help whenever she is ready","then":"She replies with a heart. \"Maybe next week. Thank you.\"","best":true},{"text":"Let it go, since she says she's fine","then":"You don't ask again. Weeks pass in silence."},{"text":"Insist she sees a doctor, or you'll tell her husband","then":"She feels cornered and stops replying."},{"text":"Tell mutual friends so they can persuade her","then":"She hears about it from others and feels exposed."}],"why":"Staying close while respecting her choices keeps the door open."}],"debrief":"When a friend confides weeks of crying, listen warmly and help her reach a doctor; that's real care.","relearn":"When a friend confides weeks of crying, warm listening and helping her reach a doctor is real care."},
  {"id":"ly-1119","cat":"baby-blues-and-beyond","type":"branch","persona":"any","source":"crisis route","hook":"Your friend Nisha, a new parent, says she feels there's no point being here anymore.","steps":[{"prompt":"Nisha says it quietly and looks away. What do you do?","options":[{"text":"Stay with her and say you're glad she told you","then":"She lets out a shaky breath and looks back at you.","best":true},{"text":"Change the subject and talk about the baby","then":"She answers politely. The words stay unsaid between you."},{"text":"Tell her not to talk like that","then":"She nods and goes silent. She looks smaller."},{"text":"Say she's just exhausted and needs sleep","then":"She agrees faintly. You both know it wasn't only that."}],"why":"Staying and listening tells her she isn't alone, and none of it is her fault."},{"prompt":"Nisha says she doesn't want you to tell anyone. What do you say?","options":[{"text":"Say you're staying, and she deserves real help","then":"She cries quietly. \"Okay,\" she whispers. \"Okay.\"","best":true},{"text":"Promise to keep it secret and check back next week","then":"She relaxes. The week feels long and nobody else knows."},{"text":"Say she has a baby to live for","then":"She nods, and the guilt joins the heaviness."},{"text":"Say you'll only tell her mother-in-law","then":"She stiffens. You realise she may not want that."}],"why":"You can't carry this alone, and neither can she. Staying while help comes is care."},{"prompt":"Nisha is quiet, then says she doesn't know what to do next. What do you do?","options":[{"text":"Call Tele-MANAS 14416 together, right now","then":"A calm voice answers. \"I'm here. Take your time.\"","best":true},{"text":"Suggest she sleeps on it and you'll talk tomorrow","then":"She lies down, and you sit in the next room. The evening is long and quiet."},{"text":"Search online for ways to feel better","then":"The articles are long and none offers a person to talk to."},{"text":"Ask a relative to come and cheer her up","then":"The relative arrives cheerful. Nisha smiles until she leaves."}],"why":"A helpline gives her a trained person to talk to, any time."},{"prompt":"Later that evening, Nisha says she may not be safe alone tonight. What do you do?","options":[{"text":"Call 112 and stay with her until help arrives","then":"You hold her hand while you wait. Help arrives calmly.","best":true},{"text":"Ask her to promise she'll be okay tonight","then":"She promises to please you. The fear is still there."},{"text":"Wait until morning and call her doctor","then":"The night is long. The fear does not ease with the hour."},{"text":"Take the baby and let her rest alone","then":"The house is quiet. She is alone with the fear."}],"why":"When someone may not be safe, call 112 and stay. Being with her matters."},{"prompt":"A week later, Nisha says she feels better and needs no more help. What do you do?","options":[{"text":"Stay close and encourage her to see the doctor","then":"She smiles. \"I will. Will you come to the next visit?\"","best":true},{"text":"Celebrate and stop checking in so often","then":"You give her space. She feels the quiet more than you expect."},{"text":"Say it was probably just a passing phase","then":"She nods. She stops mentioning it to anyone."},{"text":"Ask her to prove that she's really fine now","then":"She feels tested and goes quiet."}],"why":"Recovery goes best with ongoing care and someone close by."}],"debrief":"If a parent says there's no point being here, stay with them and reach urgent help now; they shouldn't be alone.","relearn":"If a parent feels there's no point being here, stay close and reach urgent help now; they shouldn't be alone."},
  {"id":"ly-1120","cat":"baby-blues-and-beyond","type":"branch","persona":"Divya","source":"meds worry","hook":"A doctor suggests treatment for postnatal depression, but you worry it means you've failed.","steps":[{"prompt":"The doctor waits for your reaction to the suggestion. What do you say?","options":[{"text":"Say you fear failing, ask your questions, and accept care","then":"The doctor nods. \"Many mothers feel that. Needing care isn't failing.\" She explains the plan.","best":true},{"text":"Say you'll think about it and leave","then":"The doctor hands you a card. The card stays in your bag."},{"text":"Say yes quickly without asking what it involves","then":"You leave with a plan you don't fully understand."},{"text":"Say your family won't approve and drop it","then":"The doctor writes a note. Nothing else is arranged."}],"why":"Voicing your fear and asking questions lets you accept care knowing what it involves."},{"prompt":"Your partner Dev asks what the doctor said. What do you do?","options":[{"text":"Tell him what the doctor said and how you feel","then":"He listens, then holds you. \"Thank you for telling me. What do you need?\"","best":true},{"text":"Say it was just tiredness","then":"He nods, believing you. You feel a flicker of relief, then loneliness."},{"text":"Say you'll decide about the plan alone","then":"He respects it. You carry the decision alone."},{"text":"Ask him whether you really need any of it","then":"He says he doesn't know. Neither of you does."}],"why":"Sharing with your partner turns it into shared support."},{"prompt":"A friend says people who need treatment for their mood are weak. What do you do?","options":[{"text":"Say needing care is human and not weakness","then":"She pauses. \"I hadn't thought about it that way.\"","best":true},{"text":"Decide to stay away from care so nobody thinks you're weak","then":"You let her words stand. You start planning how to get by without help."},{"text":"Agree and stop mentioning it to anyone at all","then":"She changes the subject. You feel more alone."},{"text":"Argue with her until she goes quiet again","then":"She leaves upset. You feel drained, not lighter."}],"why":"Needing care is human, not weak, and you may be glad you sought it."},{"prompt":"A few weeks on, you feel a little steadier and wonder if you need any more care. What do you do?","options":[{"text":"Talk to the doctor before deciding anything","then":"The doctor listens and says how to decide together. You leave with a clear plan.","best":true},{"text":"Let it all go now that you feel a little better","then":"For a few days you feel fine. Then the old heaviness returns."},{"text":"Ask a friend whether you need any more care","then":"She says she isn't sure. You are none the wiser."},{"text":"Quietly decide on your own that you're done","then":"You tell no one. Nobody can see how you're really doing."}],"why":"A doctor can judge how you are really doing, so decisions belong in that talk."}],"debrief":"Accepting treatment for PPD is caring for yourself and your baby, not a failure.","relearn":"Accepting treatment for postnatal depression is caring for yourself and your baby, not a failure."},
  {"id":"ly-1121","cat":"baby-blues-and-beyond","type":"spot","persona":"Divya","source":"help signs","relearn":"Lasting low or numb feelings and lost interest in the baby or in living are the cues to reach for help.","hook":"Spot the two warning signs that mean 'reach for help', not passing blues.","scene":[{"id":"a","text":"Weeks of feeling low, anxious or numb","trick":true},{"id":"b","text":"A couple of teary days that pass","trick":false},{"id":"c","text":"Losing all interest in the baby or in living","trick":true},{"id":"d","text":"Mood swings that settle by two weeks","trick":false},{"id":"e","text":"Feeling a bit rusty but glad to hold the baby","trick":false}],"why":"Weeks of low or numb feelings, and losing interest in the baby or in living, are the signs that mean reach for help."},
  {"id":"ly-1122","cat":"baby-blues-and-beyond","type":"spot","persona":"any","source":"harmful replies","relearn":"'Snap out of it' and 'good mothers don't' are the harmful replies; warmth and 'let's get help' is what cares.","hook":"Spot the two harmful replies to a struggling new parent.","scene":[{"id":"a","text":"'This is common and treatable, let's get help'","trick":false},{"id":"b","text":"'Snap out of it, others manage fine'","trick":true},{"id":"c","text":"'You're not alone, I'm here'","trick":false},{"id":"d","text":"'Good mothers don't feel this way'","trick":true},{"id":"e","text":"'Let's call the doctor together'","trick":false}],"why":"'Snap out of it' and 'good mothers don't feel this way' shame a struggling parent and block help."},
  {"id":"ly-1123","cat":"baby-blues-and-beyond","type":"spot","persona":"Divya","source":"flag vs ordinary","relearn":"Constant dread and weeks without any joy are red flags worth raising, beyond ordinary new-parent tiredness.","hook":"Spot the two red flags that aren't just ordinary new-parent tiredness.","scene":[{"id":"a","text":"Yawning through a broken-sleep week","trick":false},{"id":"b","text":"Constant dread you can't switch off for weeks","trick":true},{"id":"c","text":"A hard hour that eases after a rest","trick":false},{"id":"d","text":"No joy in anything for weeks on end","trick":true},{"id":"e","text":"Feeling rusty but settling into the routine","trick":false}],"why":"Constant dread that won't lift and weeks without any joy are red flags, not ordinary tiredness."},
  {"id":"ly-1124","cat":"baby-blues-and-beyond","type":"spot","persona":"Vikram","source":"dad red flags","relearn":"Withdrawing for weeks and numbing low mood with drink are signs a father should check with a doctor; dads affected too.","hook":"Spot the two warning signs that a new father may need to check with a doctor.","scene":[{"id":"a","text":"Tired but proud carrying the routine","trick":false},{"id":"b","text":"Withdrawing from the baby and everyone for weeks","trick":true},{"id":"c","text":"Nervous at first, then settling in","trick":false},{"id":"d","text":"Drinking more to numb a lasting low mood","trick":true},{"id":"e","text":"Finding his feet with some support","trick":false}],"why":"Weeks of withdrawing from everyone and drinking to numb low mood are signs a father should check with a doctor."},
  {"id":"ly-1125","cat":"baby-blues-and-beyond","type":"spot","persona":"any","source":"myths to catch","relearn":"'Only mothers are affected' and 'wait until you collapse' are myths; fathers are affected too and early help is best.","hook":"Spot the two myths about post-birth mood.","scene":[{"id":"a","text":"PPD is real and treatable","trick":false},{"id":"b","text":"Only mothers get low after a baby","trick":true},{"id":"c","text":"A scary thought is a symptom, not a verdict","trick":false},{"id":"d","text":"You must collapse before you deserve help","trick":true},{"id":"e","text":"Early help works better","trick":false}],"why":"'Only mothers get low' and 'you must collapse before you deserve help' are the myths to set down."},
  {"id":"ly-1126","cat":"baby-blues-and-beyond","type":"spot","persona":"Divya","source":"urgent signs","relearn":"Frightening thoughts of harm and feeling there's no point being here mean reach for help right away.","hook":"Spot the two signs that mean reach for help right away, not just soon.","scene":[{"id":"a","text":"Feeling flat and tearful for a couple of weeks","trick":false},{"id":"b","text":"Frightening thoughts of harming self or baby","trick":true},{"id":"c","text":"Low energy and little interest lately","trick":false},{"id":"d","text":"Feeling there's no point in being here","trick":true},{"id":"e","text":"Worrying a bit more than usual about the baby","trick":false}],"why":"Frightening thoughts of harm and 'no point being here' mean reach for help right away; the others can be raised soon."},
  {"id":"ly-1127","cat":"baby-blues-and-beyond","type":"spot","persona":"Vikram","source":"shaming words","relearn":"'Why can't you just be happy' and 'others cope, so should you' shame; warmth and shared help is what supports.","hook":"Spot the two things a partner says that shame instead of support.","scene":[{"id":"a","text":"\"You're not alone; let's get help together\"","trick":false},{"id":"b","text":"\"Why can't you just be happy? We have a baby\"","trick":true},{"id":"c","text":"\"I've noticed how heavy things feel for you\"","trick":false},{"id":"d","text":"\"Other women cope, so should you\"","trick":true},{"id":"e","text":"\"Take a rest; I've got the baby\"","trick":false}],"why":"'Why can't you just be happy' and 'other women cope, so should you' shame a struggling parent instead of supporting them."},
  {"id":"ly-1128","cat":"baby-blues-and-beyond","type":"reflect","persona":"Divya","source":"baby blues vs pnd","relearn":"Weepy baby blues usually lift within two weeks; if low mood lasts longer, it may be postnatal depression worth checking.","hook":"Lensy: the weepy baby blues usually fade within two weeks; if it lasts longer, it's worth a check. Make sense?","prompt":"What do you think?","options":["Makes sense","Two-week mark","I'd check in"],"affirm":"Short-lived weepy baby blues are normal, but low mood that drags past a couple of weeks deserves a check for postnatal depression."},
  {"id":"ly-1129","cat":"baby-blues-and-beyond","type":"reflect","persona":"Divya","source":"sleep and recovery","relearn":"Sleep loss makes new-parent moods harder; sharing night feeds and resting when the baby sleeps protects your mind too.","hook":"Lensy: brutal sleep loss makes new-parent moods harder, so sharing nights and resting when baby sleeps protects you. Fair?","prompt":"What's your take?","options":["Fair","Share the nights","Rest counts"],"affirm":"Severe sleep loss strains a new parent's mood, so sharing night duties and resting when the baby sleeps is real self-care, not laziness."},
  {"id":"ly-1130","cat":"baby-blues-and-beyond","type":"reflect","persona":"Divya","source":"thought not verdict","relearn":"A scary thought is a symptom, not a verdict; it doesn't make you a bad parent, it's a cue to get support.","hook":"Lensy: a scary thought is a symptom, not a verdict, and it never makes you a bad parent. Sit with that?","prompt":"How does that land?","options":["It lands","A symptom","Not my verdict"],"affirm":"A frightening thought can be a symptom of postnatal anxiety; it doesn't define you, and it's a cue to get gentle support."},
  {"id":"ly-1131","cat":"baby-blues-and-beyond","type":"reflect","persona":"Vikram","source":"dads too","relearn":"Fathers can struggle after a baby too; reaching out is a strength that's just as much yours.","hook":"Lensy: fathers can struggle after a baby too, and reaching out is just as much your right. Feel that?","prompt":"What do you think?","options":["I feel it","Dads too","My right too"],"affirm":"Fathers can be affected after a baby, and asking for help is a strength that's just as much yours to claim."},
  {"id":"ly-1132","cat":"baby-blues-and-beyond","type":"reflect","persona":"Divya","source":"love and low","relearn":"You can love your baby deeply and still feel low; the low mood is treatable, not a sign you love less.","hook":"Lensy: you can love your baby with all your heart and still feel low, and both can be true. Okay?","prompt":"What's your take?","options":["Both true","Okay","I love them"],"affirm":"Loving your baby and feeling low can be true at once; the low mood is a treatable feeling, not a sign you love any less."},
  {"id":"ly-1133","cat":"baby-blues-and-beyond","type":"reflect","persona":"any","source":"not your fault","relearn":"Postnatal depression is no one's fault; you deserve care simply because you're struggling, no need to earn it.","hook":"Lensy: postnatal depression is no one's fault, and you don't have to earn the right to feel better. Hear it?","prompt":"How does that sit?","options":["I hear it","Not my fault","I deserve care"],"affirm":"Postnatal depression is no one's fault, and you deserve care and recovery simply because you're struggling."},
  {"id":"ly-1134","cat":"baby-blues-and-beyond","type":"reflect","persona":"Divya","source":"early help","relearn":"You don't have to wait until you collapse; early help is gentler and works better.","hook":"Lensy: you don't have to wait until you collapse; early help is gentler and works better. Take that in?","prompt":"What do you think?","options":["Taking it in","Early help","No need to wait"],"affirm":"You don't have to reach crisis to deserve support; naming low feelings early makes recovery easier and kinder."},
  {"id":"ly-1135","cat":"baby-blues-and-beyond","type":"reflect","persona":"Priya","source":"not alone","relearn":"Many parents have felt this way after a baby and come through with support; you're not alone in it.","hook":"Lensy: so many parents have felt this way and come through it; you're not alone in it. Okay?","prompt":"What's your take?","options":["Okay","Not alone","Others came through"],"affirm":"Many parents have felt low after a baby and come through with support; you're not alone, and it can get better."},
  {"id":"ly-1136","cat":"baby-blues-and-beyond","type":"role-play","persona":"Vikram","source":"raise it lovingly","hook":"Your partner Ritu has seemed hollow since the birth, and you want to raise your worry with love, not alarm.","setup":"It's late afternoon, and the baby is asleep in the next room.","steps":[{"prompt":"Ritu stirs her cold tea and says: \"Sorry, I'm terrible company lately.\"","options":[{"text":"\"No need to be sorry. I've been worried about you.\"","then":"Her eyes fill. \"You noticed? I thought I was hiding it.\"","best":true},{"text":"\"You're not terrible. Come on, cheer up.\"","then":"She tries a smile, and her eyes stay flat."},{"text":"\"It's just the sleepless nights. Nap this afternoon.\"","then":"She nods. She naps and wakes just as hollow."},{"text":"\"Let's have friends over to lift your mood.\"","then":"She says she'd rather not, and goes quiet. The idea hangs in the room."}],"why":"Naming your worry gently tells her she isn't a burden."},{"prompt":"Ritu says: \"I feel nothing, even with the baby. What kind of mother is that?\"","options":[{"text":"\"You're not a bad mother. This is treatable.\"","then":"She exhales shakily. \"You really think it can be treated?\"","best":true},{"text":"\"You're a great mother. Don't say things like that.\"","then":"She nods and stops. The words go back inside."},{"text":"\"Don't tell anyone. They'll only judge you.\"","then":"She agrees, relieved and more alone."},{"text":"\"Give it time. The love will come.\"","then":"She nods and holds the baby. The numbness stays."}],"why":"Numbness is a symptom, not a sign of a bad mother, and it can be treated."},{"prompt":"Ritu says the next morning: \"My cousin saw a doctor for this. I'm scared to go.\"","options":[{"text":"\"That's okay. I'll be beside you when we go.\"","then":"She takes a slow breath. \"Then I can do it.\"","best":true},{"text":"\"Then don't. We'll manage as we are.\"","then":"She looks relieved for a moment. The heaviness stays."},{"text":"\"I'll talk to the doctor for you.\"","then":"She stays quiet. She feels talked around."},{"text":"\"Let's wait until you feel ready in a few months.\"","then":"She nods. The months go by, and readiness doesn't arrive."}],"why":"Being beside her makes the first step less frightening, and it's her step."}],"relearn":"Raise it with love and no alarm: say you're worried, that it's treatable, and that you'll go together."},
  {"id":"ly-1137","cat":"baby-blues-and-beyond","type":"role-play","persona":"Divya","source":"tell the doctor","hook":"You're at the doctor and want to say honestly how low you've felt since the birth.","setup":"The doctor looks up from her notes.","steps":[{"prompt":"The doctor asks: \"How have you been since the birth?\"","options":[{"text":"\"For weeks I've felt low and numb. I'd like help.\"","then":"She puts down her pen. \"Thank you for telling me. Let's talk about it.\"","best":true},{"text":"\"Fine. Just tired like any new mother.\"","then":"She nods and ticks a box. \"Good. Rest when you can.\""},{"text":"\"The baby's fine. Feeds and sleep are going well.\"","then":"She checks the baby's chart. \"Feeds are on track.\""},{"text":"\"A bit down some days, but it's nothing.\"","then":"She hesitates. \"Some days? Tell me if it grows.\""}],"why":"Saying it plainly lets the doctor hear you, not only the baby's chart."},{"prompt":"Before you leave, the doctor asks: \"Has anything been bringing you joy lately?\"","options":[{"text":"\"Not really. Even holding the baby feels numb.\"","then":"She nods slowly. \"That matters. Weeks of this are worth looking at.\"","best":true},{"text":"\"Oh yes, lots. The baby is such a joy.\"","then":"She smiles. \"Lovely.\" She doesn't ask again."},{"text":"\"I'm too tired to know.\"","then":"She nods. \"Sleep is hard.\" The question drifts away."},{"text":"\"Let's not get into it. I don't want to waste your time.\"","then":"She shakes her head. \"It's not a waste.\" You stay quiet."}],"why":"Honest answers about joy help the doctor spot low mood, and it's not your fault."},{"prompt":"The doctor says: \"I'd like to see you again soon. Can you come next week?\"","options":[{"text":"\"Yes. I'll ask my partner to come along.\"","then":"She smiles. \"That would help. See you Thursday.\"","best":true},{"text":"\"I'll see how the week goes first.\"","then":"She writes a note. The week passes with no visit booked."},{"text":"\"With the baby, maybe next month.\"","then":"She nods. \"Call if you change your mind.\""},{"text":"\"I'll call if I feel worse.\"","then":"She says, \"Please don't wait for worse.\" You smile and nod."}],"why":"Coming back soon keeps help going, and a partner can share the load."}],"relearn":"Naming low, numb weeks plainly to a doctor gets you assessed and supported; brushing it off keeps help away."},
  {"id":"ly-1138","cat":"baby-blues-and-beyond","type":"role-play","persona":"Vikram","source":"father opens up","hook":"You've felt flat for weeks since becoming a father, and your old friend Manoj notices.","setup":"After cricket, he sits down beside you.","steps":[{"prompt":"Manoj asks: \"You've been quiet. How are you really?\"","options":[{"text":"\"Honestly, I've been really low since the baby.\"","then":"He turns to you. \"That sounds heavy. I'm glad you said it.\"","best":true},{"text":"\"All good. Just tired. You know how it is.\"","then":"He nods. \"Same.\" You look at the ground."},{"text":"\"Men don't get fazed by this stuff.\"","then":"He laughs, then pauses. \"Seriously, though. You seem off.\""},{"text":"\"Work is heavy. Let's talk about cricket.\"","then":"He talks about the match, then glances at you. \"You sure you're okay?\""}],"why":"Saying it honestly lets a friend step closer."},{"prompt":"Manoj says: \"My cousin says new dads can get depressed too. Is that real?\"","options":[{"text":"\"Dads can too. I think I need to talk to someone.\"","then":"He nods slowly. \"Then let's find someone.\"","best":true},{"text":"\"Probably not. I'm just overthinking things.\"","then":"He looks relieved. You feel the weight settle back."},{"text":"\"Forget it. Let's not talk about this stuff.\"","then":"He shrugs. You both look away."},{"text":"\"Maybe, but mine's just stress.\"","then":"He agrees. The stress stays and so does the flatness."}],"why":"Fathers get postnatal depression too, and saying so helps others learn."},{"prompt":"As you leave, Manoj says: \"Whatever it is, I'm around. What would help?\"","options":[{"text":"\"Sit with me while I book a doctor's visit.\"","then":"He pulls out his phone. \"Tell me the number.\"","best":true},{"text":"\"Nothing. I'll deal with it myself.\"","then":"He nods, unsure. You still deal with it alone."},{"text":"\"Just keep it between us and drop it.\"","then":"He says okay. The subject never returns."},{"text":"\"Take me out somewhere to cheer me up.\"","then":"You go out and laugh for an evening. The flatness returns."}],"why":"One clear request lets a friend help and starts real care."}],"relearn":"A father admitting he's low and may need to talk is strength; 'men don't get fazed' keeps him stuck alone."},
  {"id":"ly-1139","cat":"baby-blues-and-beyond","type":"role-play","persona":"Divya","source":"ask for the appointment","hook":"You've felt low for weeks and want to see a doctor, but your aunt has other ideas.","setup":"She pauses with the tea tray in her hands.","steps":[{"prompt":"Your aunt says: \"Stay busy, beta. Don't dwell on it.\"","options":[{"text":"\"I hear you. I'd still feel better seeing a doctor.\"","then":"She frowns. \"A doctor? Are you sure?\" She doesn't leave.","best":true},{"text":"\"You're right. I'll keep busy and say nothing.\"","then":"She nods, pleased. The heaviness stays."},{"text":"\"Maybe I'll wait until the baby is older.\"","then":"She says that's sensible. You feel the months stretch ahead."},{"text":"\"You never help. How would you know how it is?\"","then":"She stiffens and puts the tray down hard."}],"why":"Kindly holding your ground keeps both the peace and your path to help."},{"prompt":"Your aunt adds: \"And don't go running to doctors. Who would mind the baby?\"","options":[{"text":"\"I'll arrange that. I'm going to call a doctor anyway.\"","then":"She sighs. \"Well. Tell me when.\"","best":true},{"text":"\"Then I'll leave it. The baby comes first.\"","then":"She looks satisfied. The heaviness settles back in."},{"text":"\"You're right. A doctor is too much fuss.\"","then":"She pats your arm. You feel lonelier than before."},{"text":"\"Can you decide for me?\"","then":"She tells you to wait. You leave the choice with her."}],"why":"Sorting out the baby's care removes the excuse without any fight."},{"prompt":"Your aunt asks: \"And if the neighbours hear you're this low, what will they say?\"","options":[{"text":"\"It's private. I'll share it only with people I trust.\"","then":"She hesitates, then nods. \"Fair.\"","best":true},{"text":"\"You're right. I'll drop the doctor idea to avoid talk.\"","then":"She looks relieved. You feel yourself shrinking."},{"text":"\"Then I'll tell every neighbour to mind their own business.\"","then":"She gasps. \"That will only give them more to talk about.\""},{"text":"\"Maybe they'd be right that I'm weak.\"","then":"She pats your hand. The word 'weak' stays with you."}],"why":"Your wellbeing matters more than talk, and privacy is yours to keep."},{"prompt":"Later, your aunt sighs: \"I only want you well. What would actually help you?\"","options":[{"text":"\"Please watch the baby while I see a doctor.\"","then":"She nods. \"I'll be here.\"","best":true},{"text":"\"Nothing. I'll handle everything myself.\"","then":"She shrugs. You handle everything alone."},{"text":"\"Just don't tell anyone how I've been.\"","then":"She promises. Nothing else changes."},{"text":"\"Come with me and talk to the doctor for me.\"","then":"She says she'd rather not. You go feeling unsure."}],"why":"Accepting real help is part of the plan, and it makes the visit possible."}],"relearn":"Kindly holding your ground and booking a doctor protects you; giving in to 'just stay busy' buries a treatable struggle."},
  {"id":"ly-1140","cat":"baby-blues-and-beyond","type":"role-play","persona":"Priya","source":"offer a friend help","hook":"Your friend Charu, a new mother, asks you to come over and talk.","setup":"She wipes her eyes on her dupatta.","steps":[{"prompt":"Charu whispers: \"I've cried every day for weeks and I don't know why.\"","options":[{"text":"\"That sounds so heavy. I'm glad you told me.\"","then":"She lets out a shaky breath. \"I haven't said it to anyone.\"","best":true},{"text":"\"Everyone goes through it. You'll be fine.\"","then":"She nods and looks down. After a long pause she speaks again, more quietly."},{"text":"\"But you have a lovely baby. Be grateful.\"","then":"She whispers, \"I know.\" Her eyes fill again."},{"text":"\"Have you tried getting more sleep?\"","then":"She says she's trying. She looks tired and unheard."}],"why":"Listening first tells her it is safe to say more."},{"prompt":"Charu says: \"I feel like such a failure.\"","options":[{"text":"\"You're not failing. This isn't your fault.\"","then":"She wipes her eyes. \"Nobody has said that to me.\"","best":true},{"text":"\"Just don't tell anyone. They'll judge.\"","then":"She nods. The secret sits heavier between you."},{"text":"\"Try not to think like that.\"","then":"She tries. She looks like she's still thinking it."},{"text":"\"You just need a holiday.\"","then":"She laughs weakly. There is no holiday coming."}],"why":"Telling her it isn't her fault eases the shame."},{"prompt":"Charu asks: \"Do you think I should talk to someone?\"","options":[{"text":"\"Yes. Let's call Tele-MANAS 14416 together.\"","then":"She takes a breath. \"Okay. Will you stay?\" You do.","best":true},{"text":"\"Wait a bit longer. It may pass.\"","then":"She nods, unsure. The crying goes on all week."},{"text":"\"Let me call a doctor and book it for you.\"","then":"She feels rushed and says she isn't ready."},{"text":"\"Try a yoga class first.\"","then":"She says maybe. She doesn't sign up."}],"why":"Offering to sit with her while she calls makes reaching out less lonely."},{"prompt":"A few days later, Charu asks: \"If I see a doctor, will they think something's wrong with me?\"","options":[{"text":"\"Asking for support is just looking after yourself.\"","then":"She nods slowly. \"That's true. I'll try.\"","best":true},{"text":"\"Then don't go. We'll manage.\"","then":"She sighs with relief, and the crying continues."},{"text":"\"Nobody will think that. Stop worrying.\"","then":"She tries not to worry and worries anyway."},{"text":"\"Then say it's for the baby.\"","then":"She nods. Her own name stays off the form."}],"why":"Asking for support is looking after herself, and she deserves it."}],"relearn":"Offering to sit with a friend while she reaches a helpline is real care; 'everyone goes through it' shuts her down."},
  {"id":"ly-1141","cat":"baby-blues-and-beyond","type":"role-play","persona":"Vikram","source":"raise scary thought","hook":"Your partner Rina has been quiet and on edge for weeks since the birth, and tonight she wants to talk.","setup":"She grips the edge of the blanket.","steps":[{"prompt":"Rina whispers: \"I've been having scary thoughts. I don't know what's wrong with me.\"","options":[{"text":"\"Thank you for telling me. It's a symptom, not you.\"","then":"She exhales. \"You're not angry?\"","best":true},{"text":"\"Don't ever say that again. What's wrong with you?\"","then":"She flinches and goes silent."},{"text":"\"You're just exhausted. Sleep and it will go.\"","then":"She lies back. The thoughts are still there when she wakes."},{"text":"\"Tell me everything the thoughts say, step by step.\"","then":"She goes pale. \"I can't. I don't want to say them.\""}],"why":"Thanking her and calling it a symptom tells her she is safe with you."},{"prompt":"Rina asks: \"Are you angry? Do you think I'm a bad mother?\"","options":[{"text":"\"No. You're unwell, not bad. I'm here.\"","then":"She leans into you, crying quietly.","best":true},{"text":"\"No. But don't tell my parents about this.\"","then":"She nods. The secret sits between you."},{"text":"\"I'm just scared. Please stop saying it.\"","then":"She nods and holds it in."},{"text":"\"You're the best mother. It's nothing.\"","then":"She smiles thinly. \"Okay.\" It still feels like something."}],"why":"She needs to hear that she is unwell, not bad, and that it is not her fault."},{"prompt":"Rina says: \"Do we have to tell anyone?\"","options":[{"text":"\"Yes. A doctor today. I'll be with you.\"","then":"She takes your hand. \"Okay. Today.\"","best":true},{"text":"\"Let's wait a few days and see.\"","then":"She agrees. The days feel longer."},{"text":"\"Only my mother, so she can help.\"","then":"Rina winces. \"I'd rather not tell her yet.\""},{"text":"\"We'll manage between us for now.\"","then":"She nods. Between you there is now only worry."}],"why":"A doctor can help quickly, and going together shows her she isn't alone."},{"prompt":"That evening, Rina says: \"The thoughts are stronger tonight. I'm scared.\"","options":[{"text":"\"I'm calling Tele-MANAS 14416 now.\"","then":"A calm voice answers. \"Thank you for calling. If it's urgent, call 112.\"","best":true},{"text":"\"Try to sleep. We'll see a doctor later.\"","then":"She lies down, tense. Sleep doesn't come."},{"text":"\"Just breathe and count to ten.\"","then":"She tries. The breathing helps a little, and the fear remains."},{"text":"\"Let's wait until morning, then decide.\"","then":"The night is long. She grips your hand until dawn."}],"why":"Calling now gets trained support at once, and 112 is there if anyone is in danger."}],"relearn":"Respond with calm care: 'Thank you for telling me. It's a symptom, not you.' Then get help together."},
  {"id":"ly-1142","cat":"baby-blues-and-beyond","type":"role-play","persona":"Divya","source":"ask partner for backup","hook":"You're struggling and need your partner to step in so you can reach help.","setup":"Your partner Sid is folding laundry while the baby fusses.","steps":[{"prompt":"Sid looks up and asks: \"You look worn out. What's going on?\"","options":[{"text":"\"I'm not coping. Can you take the baby so I can call?\"","then":"He puts the laundry down. \"Of course. Tell me what you need.\"","best":true},{"text":"\"Nothing. I'll manage everything myself like always.\"","then":"He pauses. \"You don't look like you're managing. Talk to me.\""},{"text":"\"I'm fine. Just do the laundry.\"","then":"He folds a shirt, then stops. \"You're not fine, though, are you?\""},{"text":"\"You wouldn't understand. Never mind.\"","then":"He looks hurt. \"Try me,\" he says, and waits."}],"why":"Saying you're not coping and what you need is what lets Sid step in."},{"prompt":"Sid says: \"I want to help, but I've got a big work call in ten minutes.\"","options":[{"text":"\"Then take the baby after it, so I can call for help.\"","then":"He nods. \"Deal. I'll take her the minute I'm off.\"","best":true},{"text":"\"Forget it. Your work always comes first.\"","then":"He sighs. \"That's not fair. I said I want to help.\""},{"text":"\"Okay. I'll just do it all myself, as usual.\"","then":"He hesitates, then goes to his call. You're still alone with it."},{"text":"\"Never mind. I'll sort it out when I feel better.\"","then":"He says okay and goes to his call. You don't feel better."}],"why":"A specific time makes it easy for Sid to say yes, and keeps his work fair."},{"prompt":"Later, Sid asks: \"Is there someone we could call about how you've been?\"","options":[{"text":"\"Tele-MANAS 14416, and then I'll book a doctor.\"","then":"He nods. \"I'll sit with the baby. Take as long as you need.\"","best":true},{"text":"\"I don't know yet. I'll search online later.\"","then":"He nods. The search stays on your list."},{"text":"\"Nobody. Talking to you is enough for now.\"","then":"He says he's glad you told him. Nothing else is arranged."},{"text":"\"My mother-in-law, so she can tell me what to do.\"","then":"\"She'll help if we ask,\" he says. \"But what do you think you need?\""}],"why":"Naming who you'll call turns a hard moment into a real plan."}],"relearn":"Asking a partner to take the baby so you can call for help shares the load; 'I'll manage myself' keeps you depleted."},
  {"id":"ly-900","cat":"empty-cup","type":"strike-rewrite","hook":"\"Looking after myself is a luxury I'll get to once the kids are grown.\"","myth":{"un":"Looking after myself is a luxury I'll get to once the kids are grown.","re":"Your own care isn't a someday luxury; a refuelled parent shows up steadier today, so caring for yourself is caring for them now.","why":"An empty cup pours nothing this year either."},"relearn":"Self-care isn't a luxury for later; a refuelled parent gives more now.","persona":"Divya","source":"not a luxury"},
  {"id":"ly-901","cat":"empty-cup","type":"strike-rewrite","hook":"\"My parents managed four kids with no help, so I shouldn't need a break.\"","myth":{"un":"My parents managed four kids with no help, so I shouldn't need a break.","re":"Comparing your load to an idealised past doesn't change that you're depleted now; needing rest is human, not weakness.","why":"Your limits are real whatever others endured."},"relearn":"Old comparisons don't erase your real limits; needing a break is human.","persona":"Vikram","source":"old comparisons"},
  {"id":"ly-902","cat":"empty-cup","type":"strike-rewrite","hook":"\"A real mother runs on love alone and never gets tired.\"","myth":{"un":"A real mother runs on love alone and never gets tired.","re":"Love is real, but it doesn't replace sleep, food or rest; getting tired doesn't make you any less devoted.","why":"Devotion and depletion can sit together."},"relearn":"Love doesn't replace rest; being tired doesn't make you less devoted.","persona":"Divya","source":"love alone myth"},
  {"id":"ly-903","cat":"empty-cup","type":"strike-rewrite","hook":"\"If I rest while the baby naps, I'm being lazy.\"","myth":{"un":"If I rest while the baby naps, I'm being lazy.","re":"Resting when you can isn't laziness; it's how you refill so you can keep going, and a refilled parent copes far better.","why":"Rest is fuel, not failure."},"relearn":"Resting when the baby sleeps is refuelling, not laziness.","persona":"Divya","source":"nap rest"},
  {"id":"ly-904","cat":"empty-cup","type":"strike-rewrite","hook":"\"Burnout is something only people with stressful jobs get, not parents at home.\"","myth":{"un":"Burnout is something only people with stressful jobs get, not parents at home.","re":"Caring for a child round the clock is relentless work; burnout from it is real, with the same exhaustion, detachment and overwhelm.","why":"Unpaid care still depletes you."},"relearn":"Caregiving burnout is real; it isn't only for stressful paid jobs.","persona":"any","source":"home burnout"},
  {"id":"ly-905","cat":"empty-cup","type":"strike-rewrite","hook":"\"I should be enjoying every second; if I'm exhausted, something's wrong with me.\"","myth":{"un":"I should be enjoying every second; if I'm exhausted, something's wrong with me.","re":"You can love your child deeply and still find the days exhausting; the two aren't in conflict, and the tiredness isn't a flaw.","why":"Hard and precious can both be true."},"relearn":"Loving your child and finding it exhausting can both be true; you're not flawed.","persona":"Divya","source":"enjoy every second"},
  {"id":"ly-906","cat":"empty-cup","type":"strike-rewrite","hook":"\"Asking my husband to share the night feeds means I've failed as a mother.\"","myth":{"un":"Asking my husband to share the night feeds means I've failed as a mother.","re":"Sharing the load isn't failure; raising a child is a two-person job, and a rested parent is a steadier one for the baby.","why":"Shared care refills the cup."},"relearn":"Sharing night feeds isn't failure; it's how you both stay steady.","persona":"Divya","source":"share night feeds"},
  {"id":"ly-907","cat":"empty-cup","type":"strike-rewrite","hook":"\"I'll rest when I collapse; until then I just keep going.\"","myth":{"un":"I'll rest when I collapse; until then I just keep going.","re":"Waiting to collapse before you rest leaves you, and your child, worse off; small refills now prevent the crash later.","why":"Stopping the slide beats picking up the pieces."},"relearn":"Don't wait to collapse to rest; small refills now prevent the crash.","persona":"any","source":"rest before collapse"},
  {"id":"ly-908","cat":"empty-cup","type":"strike-rewrite","hook":"\"Hiring help or using a creche means I'm pushing my child away.\"","myth":{"un":"Hiring help or using a creche means I'm pushing my child away.","re":"Accepting help with the load isn't pushing your child away; it gives you space to refill and return more present, not less.","why":"Help shared is care, not abandonment."},"relearn":"Accepting help isn't pushing your child away; it lets you return more present.","persona":"Priya","source":"accept help"},
  {"id":"ly-909","cat":"empty-cup","type":"strike-rewrite","hook":"\"One good night's sleep and my burnout will be cured.\"","myth":{"un":"One good night's sleep and my burnout will be cured.","re":"Burnout isn't one bad night; it builds over weeks and needs ongoing rest and support to lift, not a single early night.","why":"A signal that deep needs more than a nap."},"relearn":"Burnout isn't fixed by one night's sleep; it needs ongoing rest and support.","persona":"Vikram","source":"not one night"},
  {"id":"ly-910","cat":"empty-cup","type":"strike-rewrite","hook":"\"Saying 'I'm exhausted' out loud will make everyone think I can't cope.\"","myth":{"un":"Saying 'I'm exhausted' out loud will make everyone think I can't cope.","re":"Naming exhaustion isn't proof you can't cope; it's the honest first step that lets people actually help you.","why":"Naming it opens the door to support."},"relearn":"Saying you're exhausted isn't a confession of failure; it lets people help.","persona":"Divya","source":"naming exhaustion"},
  {"id":"ly-911","cat":"empty-cup","type":"sort","hook":"Sort each into a burnout warning sign, or an ordinary off-day feeling.","items":[{"id":"a","text":"Weeks of dreading getting out of bed"},{"id":"b","text":"Yawning after one short night"},{"id":"c","text":"Feeling nothing when the baby smiles"},{"id":"d","text":"Wanting an early night after a busy day"},{"id":"e","text":"Snapping at everyone, every single day"},{"id":"f","text":"A bit grumpy when you skip lunch"}],"bins":[{"id":"sign","label":"Burnout warning sign","valence":"uhoh"},{"id":"ordinary","label":"Ordinary off-day","valence":"neutral"}],"key":{"a":"sign","b":"ordinary","c":"sign","d":"ordinary","e":"sign","f":"ordinary"},"relearn":"Weeks of dread, numbness and daily snapping are burnout signs; one tired night or skipped lunch is an ordinary off-day.","persona":"any","source":"sign vs off-day"},
  {"id":"ly-912","cat":"empty-cup","type":"sort","hook":"Sort: does this fill your cup back up, or quietly drain it more?","items":[{"id":"a","text":"Ten quiet minutes with a cup of chai"},{"id":"b","text":"Saying yes to every relative's request"},{"id":"c","text":"A short walk while a partner watches the baby"},{"id":"d","text":"Skipping meals to get more done"},{"id":"e","text":"Letting someone else cook tonight"},{"id":"f","text":"Scrolling guilt about not doing more"}],"bins":[{"id":"fills","label":"Fills your cup","valence":"pos"},{"id":"drains","label":"Drains it more","valence":"neg"}],"key":{"a":"fills","b":"drains","c":"fills","d":"drains","e":"fills","f":"drains"},"relearn":"Quiet chai, a short walk and accepting a cooked meal fill you; yes-to-everything, skipped meals and guilt-scrolling drain you.","persona":"any","source":"fills vs drains"},
  {"id":"ly-913","cat":"empty-cup","type":"sort","hook":"Sort: a thought that keeps your cup empty, or one that helps you refill it?","items":[{"id":"a","text":"\"Resting now means I'll cope better later\""},{"id":"b","text":"\"Needing a break makes me a bad parent\""},{"id":"c","text":"\"I can ask for help without shame\""},{"id":"d","text":"\"I must do it all alone or I've failed\""},{"id":"e","text":"\"My limits are real and worth respecting\""},{"id":"f","text":"\"Good parents never get tired\""}],"bins":[{"id":"refill","label":"Helps you refill","valence":"pos"},{"id":"empty","label":"Keeps you empty","valence":"neg"}],"key":{"a":"refill","b":"empty","c":"refill","d":"empty","e":"refill","f":"empty"},"relearn":"\"Rest helps me cope,\" \"I can ask for help\" and \"my limits are real\" refill you; the all-alone, never-tired thoughts keep you empty.","persona":"Divya","source":"refilling thoughts"},
  {"id":"ly-914","cat":"empty-cup","type":"branch","persona":"Meena","source":"host dinner limit","hook":"It's 4pm and you haven't eaten or sat down, and your in-laws ask you to host dinner tonight.","steps":[{"prompt":"Your mother-in-law waits for your answer. What do you say?","options":[{"text":"Say you're spent today and ask for another evening","then":"She blinks, then nods. \"Another day is fine, beta.\"","best":true},{"text":"Say yes and quietly rearrange your entire afternoon","then":"You say yes. The afternoon vanishes into shopping and chopping."},{"text":"Say yes and expect your husband to take over","then":"You say yes. Your husband doesn't know he's meant to help."},{"text":"Say you'll try and see how you feel later","then":"She takes that as a yes and calls the relatives."}],"why":"Kindly naming your limit protects your fuel and keeps the relationship warm."},{"prompt":"Later, your mother-in-law says the relatives have been looking forward to it. What do you say?","options":[{"text":"Suggest a simple meal, with everyone bringing a dish","then":"She considers it. \"That could work.\"","best":true},{"text":"Insist on cooking the full meal yourself","then":"You say it firmly. By evening your legs feel shaky."},{"text":"Say nothing and let her plan a bigger menu","then":"She adds two more dishes. You nod and say nothing."},{"text":"Apologise again and again for the trouble","then":"She says it's fine, and nothing about the evening changes."}],"why":"A simpler plan lets you host without draining yourself."},{"prompt":"On the evening of the dinner, the guests arrive early and you're already tired. What do you do?","options":[{"text":"Ask your husband Sanjay to host for an hour","then":"He nods and greets the guests. You sit for the first time all day.","best":true},{"text":"Smile and keep serving through it","then":"The guests praise the food. You feel your energy drain."},{"text":"Snap that you're tired and everyone should help","then":"The room goes quiet. Nobody knows what to do."},{"text":"Hide in the bedroom until they leave","then":"You get a rest, and the guests wonder where you are."}],"why":"Handing over hosting for an hour is a real, simple way to refill."}],"debrief":"On an empty day, naming your limit kindly protects your fuel; pushing through costs more.","relearn":"On an empty day, kindly naming your limit protects your fuel."},
  {"id":"ly-915","cat":"empty-cup","type":"branch","persona":"Divya","source":"ten minutes daily","hook":"You haven't done a single thing just for yourself in months, and you've stopped noticing how flat you feel.","steps":[{"prompt":"The baby is asleep and you have ten free minutes. What do you do?","options":[{"text":"Have tea and put on one favourite song","then":"The song is small and familiar. You feel like yourself for a moment.","best":true},{"text":"Fold the laundry instead","then":"The pile is smaller. You aren't."},{"text":"Scroll your phone until the time runs out","then":"The minutes vanish. You feel just as flat afterwards."},{"text":"Save them for later, in case you need them","then":"The baby wakes early. The ten minutes never happen."}],"why":"Ten minutes for just you is a refill, not a luxury."},{"prompt":"Three days later, a mountain of dishes waits. What do you do?","options":[{"text":"Leave the dishes and take your ten minutes anyway","then":"The dishes wait. You come back to them steadier.","best":true},{"text":"Do the dishes first and hope time is left","then":"There's no time left, and the day ends."},{"text":"Take five minutes and feel guilty for the rest","then":"You sit, tense. You wonder if it counted."},{"text":"Skip today and double up tomorrow","then":"Tomorrow has its own mountain."}],"why":"Guarding the ten minutes keeps the habit alive on the days it's hardest."},{"prompt":"Your mother-in-law sees you sitting still and asks why you're not working. What do you say?","options":[{"text":"Say it's your ten minutes and you'll be back soon","then":"She raises an eyebrow, then nods. \"Fine. Ten minutes.\"","best":true},{"text":"Jump up and say you're only resting your feet","then":"You spring up. The ten minutes are gone."},{"text":"Say sorry and start working","then":"You start scrubbing. The flat feeling comes back."},{"text":"Say you'll do it when she isn't around","then":"You start hiding your ten minutes."}],"why":"Saying it plainly protects your ten minutes without a fight."}],"debrief":"You refill in small daily sips, not one big recharge; ten guarded minutes beats a weekend that never comes.","relearn":"Refill in small daily sips now, not a someday weekend."},
  {"id":"ly-916","cat":"empty-cup","type":"branch","persona":"Divya","source":"coffee with friend","hook":"A friend you haven't seen since the baby invites you for coffee, and your first thought is guilt for wanting to go.","steps":[{"prompt":"Your friend Nandini texts to fix a time on Saturday. What do you do?","options":[{"text":"Say yes and ask your partner to mind the baby","then":"Your partner says of course. You text Nandini a time.","best":true},{"text":"Decline, since staying home is what a mother does","then":"Nandini says maybe another time. Saturday passes at home."},{"text":"Say maybe and let the day slip by","then":"She waits, then makes other plans."},{"text":"Suggest coffee at your house with the baby and chores","then":"She says fine. It doesn't feel like a break."}],"why":"Saying yes and getting cover lets you actually take the time."},{"prompt":"When you finally sit down with Nandini, your phone is in your hand. What do you do?","options":[{"text":"Put it away and tell her how it's really been","then":"She leans in. \"I've been wondering. Tell me.\"","best":true},{"text":"Check messages every few minutes to feel safe","then":"The messages are fine. The coffee goes cold."},{"text":"Keep it light and talk about the baby only","then":"The baby is a good topic. You leave with the rest unsaid."},{"text":"Cut it short, feeling guilty","then":"You end it early. The guilt stays with you."}],"why":"Being present with a friend refills you more than a quick, guilty coffee."},{"prompt":"That night, guilt whispers that you shouldn't have taken time for yourself. What do you do?","options":[{"text":"Question the guilt and plan the next meet-up","then":"The guilt quietens. You text Nandini a date.","best":true},{"text":"Believe it and promise yourself not to do it again","then":"The promise feels heavy. The house feels smaller."},{"text":"Overcompensate by cleaning until midnight","then":"The house sparkles. You're exhausted by morning."},{"text":"Text Nandini that you can't meet again for a while","then":"She sends a heart. The next plan slips away."}],"why":"A little time of your own is a real need. You're steadier when you take it."}],"debrief":"A little time of your own is a real need, not a betrayal; you come home steadier for taking it.","relearn":"Take the coffee without guilt; you return more present for it."},
  {"id":"ly-917","cat":"empty-cup","type":"branch","persona":"Vikram","source":"partner says fine","hook":"Your partner Pooja is clearly burnt out, but keeps insisting she's 'fine' and won't slow down.","steps":[{"prompt":"Pooja is folding laundry at ten at night with red eyes. What do you do?","options":[{"text":"Say what you see and offer to take tonight's load","then":"She hesitates, then lets out a breath. \"Okay. Just tonight.\"","best":true},{"text":"Take 'fine' at face value and go to bed","then":"You go to bed. She folds until midnight."},{"text":"Tell her everyone's tired and she'll cope","then":"She nods and folds faster."},{"text":"Take the laundry away without asking","then":"She snaps: \"I said I've got it.\" She looks even more tired."}],"why":"Naming what you see, kindly, and taking a shift gives her room to rest."},{"prompt":"Pooja says everything falls apart if she stops. What do you say?","options":[{"text":"Say you'll cover specific jobs so she can truly rest","then":"She hesitates. \"Which jobs?\" You name them.","best":true},{"text":"Agree that someone has to hold it all together","then":"She nods and pushes on."},{"text":"Say she's exaggerating, and it won't fall apart","then":"She stiffens. \"Easy for you to say.\""},{"text":"Say she just needs to organise her day better","then":"She looks at you. She doesn't say what she's thinking."}],"why":"Covering specific jobs makes it real, and lets her actually rest."},{"prompt":"A few days later, Pooja snaps over something small and starts crying. What do you do?","options":[{"text":"Stay calm, hold her, and say she's depleted","then":"Her body loosens. \"I'm so tired,\" she whispers.","best":true},{"text":"Snap back that you're tired too","then":"She stops crying and goes cold."},{"text":"Leave the room until she calms down","then":"When you return, she's wiped her face and gone back to work."},{"text":"Say she's overreacting to a small thing","then":"She wipes her eyes. \"You don't understand.\""}],"why":"Staying calm and seeing the depletion tells her she is safe to stop."},{"prompt":"A week on, Pooja is still worn out even after a good night's sleep. What do you do?","options":[{"text":"Suggest seeing a doctor together and offer to book it","then":"She agrees, relieved. \"I didn't want to ask.\"","best":true},{"text":"Say another good night's sleep will fix it","then":"She nods. Two weeks later, nothing has changed."},{"text":"Say she should push through until the baby is older","then":"She nods. The exhaustion continues."},{"text":"Wait for her to ask for help","then":"She doesn't ask. You both wait."}],"why":"Tiredness that one good night can't lift is worth a doctor's visit."}],"debrief":"A depleted partner often hides it; naming it kindly and taking a shift lets them actually refill.","relearn":"Name a partner's burnout gently and take a shift; don't accept 'I'm fine'."},
  {"id":"ly-918","cat":"empty-cup","type":"match","hook":"Match each empty-cup signal to what it's asking of you.","pairs":[{"left":"Snapping at the kids over tiny things","right":"Reserves are low, take a breather"},{"left":"Numb where you used to feel joy","right":"A signal to rest and reach out"},{"left":"Dreading the alarm before the day","right":"A cue to share the load"},{"left":"Getting sick and run-down again","right":"Your body wants real rest"},{"left":"No interest in anything yours","right":"Protect a small thing for you"}],"relearn":"Snapping, numbness, dread, illness and lost interest all ask you to refill, rest, share the load and protect your time.","persona":"any","source":"signal to need"},
  {"id":"ly-919","cat":"empty-cup","type":"match","hook":"Match each empty-cup myth to the truth that frees you.","pairs":[{"left":"Good parents sacrifice everything","right":"A depleted parent has less to give"},{"left":"Burnout is just normal tiredness","right":"It's a signal to rest, not push on"},{"left":"Asking for help means I've failed","right":"Sharing the load is wise and human"},{"left":"Resting is selfish when they need me","right":"Refilling is how you keep going"},{"left":"I should cope alone like others","right":"No one raises a child in isolation"}],"relearn":"Sacrifice-all, just-tiredness, help-is-failure and rest-is-selfish are myths; the truths free you to refill.","persona":"any","source":"myth to truth"},
  {"id":"ly-920","cat":"empty-cup","type":"reflect","hook":"Lensy: when your cup is full, the people you love get the best of you, not the leftovers. Sit right?","prompt":"What's your take?","options":["Sits right","The best, not leftovers","Worth refilling"],"affirm":"A refilled parent gives from fullness, not scraps; looking after your own cup is part of looking after them.","relearn":"A full cup gives your child the best of you, not the leftovers.","persona":"any","source":"best not leftovers"},
  {"id":"ly-921","cat":"empty-cup","type":"reflect","hook":"Lensy: noticing you're running low isn't weakness; it's the awareness that lets you do something before you crash. Land okay?","prompt":"What do you think?","options":["Lands okay","Awareness, not weakness","Good to notice early"],"affirm":"Noticing you're depleted early is a strength; it's what lets you refill before burnout, not a sign you're failing.","relearn":"Noticing you're running low early is awareness, not weakness.","persona":"Divya","source":"noticing is strength"},
  {"id":"ly-922","cat":"empty-cup","type":"reflect","hook":"Lensy: you're allowed to find this hard and love your child fiercely at the same time. Both can be true. Feel right?","prompt":"How does that sit?","options":["Feels right","Both can be true","I needed that"],"affirm":"Finding parenting exhausting takes nothing away from your love; the two live side by side, and you're doing okay.","relearn":"You can find it hard and love them fiercely at once; both are true.","persona":"any","source":"hard and loving"},
  {"id":"ly-923","cat":"empty-cup","type":"spot","hook":"Lensy: spot the two traps that keep a depleted parent running on empty.","scene":[{"id":"a","text":"\"Rest when you can; you'll cope better\"","trick":false},{"id":"b","text":"\"Real parents push through and never stop\"","trick":true},{"id":"c","text":"\"It's okay to let someone share the load\"","trick":false},{"id":"d","text":"\"Taking a break now would just be selfish\"","trick":true},{"id":"e","text":"\"Naming you're tired is the brave first step\"","trick":false}],"why":"\"Push through and never stop\" and \"a break is selfish\" keep the cup empty; the others let you refill.","relearn":"Push-forever and break-is-selfish keep you empty; rest, sharing and naming it refill you.","persona":"any","source":"empty-cup traps"},
  {"id":"ly-924","cat":"empty-cup","type":"spot","hook":"Lensy: spot the two unhealthy responses to burnout, the moves that make an empty cup worse.","scene":[{"id":"a","text":"Going to bed earlier for a few nights","trick":false},{"id":"b","text":"Living on coffee, skipping meals to keep going","trick":true},{"id":"c","text":"Asking family to take the baby an afternoon","trick":false},{"id":"d","text":"Cutting out the one hobby that recharges you","trick":true},{"id":"e","text":"Telling your partner you're at your limit","trick":false}],"why":"Coffee-and-no-meals and cutting your one recharge deepen burnout; rest, shared care and honesty refill you.","relearn":"Coffee-and-no-meals and dropping your recharge worsen burnout; rest and honesty help.","persona":"Divya","source":"unhealthy responses"},
  {"id":"ly-925","cat":"empty-cup","type":"role-play","persona":"Meena","source":"ask MIL for break","hook":"You're scraped to nothing, and you want to ask for a real break without a fight.","setup":"Your mother-in-law hands you another list.","steps":[{"prompt":"She says: \"Also, the guests come tomorrow, so please clean the front room.\"","options":[{"text":"\"I'm empty today. I need an hour to rest first.\"","then":"She frowns. \"An hour? Well. Only an hour.\"","best":true},{"text":"\"It's fine. I'll manage everything somehow.\"","then":"She nods, satisfied. You feel your legs give a little."},{"text":"\"Why is it always me who has to do this?\"","then":"She stiffens. \"Don't talk to me like that.\""},{"text":"\"I'll do it tonight after the baby sleeps.\"","then":"She nods, pleased. Tonight you'll have nothing left."}],"why":"Naming that you're empty and asking for an hour is clear and fair."},{"prompt":"She adds: \"There's so much to do before the guests come.\"","options":[{"text":"\"I know. I'll rest for an hour, then do the front room.\"","then":"She sighs. \"All right. One hour, then.\"","best":true},{"text":"\"Then I'll just keep going without a break.\"","then":"She nods. You keep going, wobbly."},{"text":"\"Fine. I only wanted you to know I'm tired.\"","then":"She says okay. You feel more alone."},{"text":"\"You never think about how tired I am.\"","then":"She goes quiet, offended. The tension holds."}],"why":"Resting first, then doing the room, makes the request easy to accept."},{"prompt":"She says: \"Beta, are you unwell? You look pale.\"","options":[{"text":"\"I'm worn out. Could you help with the cleaning?\"","then":"She hesitates. \"I'll do the front room. You rest.\"","best":true},{"text":"\"I'm fine. Just a little headache. That's all.\"","then":"She tuts. \"Take some water.\""},{"text":"\"I'm okay. I'll manage all of it myself.\"","then":"She nods. You go on managing."},{"text":"\"Anyone would look pale with a list like this.\"","then":"She stiffens. \"Are you blaming me?\""}],"why":"Saying you're worn out and asking for a specific bit of help is honest and workable."}],"relearn":"Naming you're empty and asking for an hour's rest is how you refill; 'I'll manage somehow' just empties you further."},
  {"id":"ly-926","cat":"empty-cup","type":"role-play","persona":"Priya","source":"friend confides burnout","hook":"Your friend Tanvi has seemed worn down for weeks, and today she finally opens up.","setup":"She stirs her tea without drinking it.","steps":[{"prompt":"Tanvi says: \"I'm so burnt out, and I'm ashamed of it.\"","options":[{"text":"\"Burnout is common, not shameful. I'm glad you told me.\"","then":"Her shoulders drop. \"Really? I thought I was the only one.\"","best":true},{"text":"\"Everyone copes somehow. Just push through it for now.\"","then":"She nods and goes quiet."},{"text":"\"You'll be fine. You're so strong and always manage.\"","then":"She smiles thinly. She doesn't feel strong."},{"text":"\"You should be grateful for what you have in life.\"","then":"She whispers: \"I am.\" The shame deepens."}],"why":"Saying it's common and not shameful lets her breathe."},{"prompt":"Tanvi says: \"I just want to sleep for a week.\"","options":[{"text":"\"You need real rest. What would help most?\"","then":"She thinks. \"An afternoon off. And someone to listen.\"","best":true},{"text":"\"Then book a holiday. That'll fix it.\"","then":"She laughs shortly. \"With what money and time?\""},{"text":"\"You can't. The kids need you.\"","then":"She nods. The guilt settles in."},{"text":"\"Try to think about the good parts instead.\"","then":"She nods. The good parts feel far away."}],"why":"Asking what would help keeps the support real and hers."},{"prompt":"Tanvi says: \"I don't know who to talk to.\"","options":[{"text":"\"Let's call Tele-MANAS 14416 together.\"","then":"She nods and takes a breath. \"Okay. Stay with me.\"","best":true},{"text":"\"Talk to me. I'll fix things for you.\"","then":"She feels a bit better, and no plan has been made."},{"text":"\"Nobody. Just keep it between us.\"","then":"She nods. You are the only door she has."},{"text":"\"Just wait it out. It'll lift.\"","then":"She agrees. The weeks go by."}],"why":"Helping her find a helpline or doctor eases the load beyond one friend."}],"relearn":"Telling a burnt-out friend it's common, not shameful, and helping them find support eases the load; 'push through' deepens it."},
  {"id":"ly-1260","cat":"healthy-coping","type":"strike-rewrite","hook":"\"Real coping means handling everything on your own, no help.\"","myth":{"un":"Real coping means handling everything on your own, no help.","re":"Healthy coping leans on supports and small habits; doing it all alone isn't strength, it's the fast road to burnout.","why":"Supported coping lasts; solo coping cracks."},"relearn":"Healthy coping leans on supports and small habits, not on handling everything alone.","persona":"Divya","source":"not solo"},
  {"id":"ly-1261","cat":"healthy-coping","type":"strike-rewrite","hook":"\"Taking deep breaths is too small to help with this much stress.\"","myth":{"un":"Taking deep breaths is too small to help with this much stress.","re":"A few slow breaths really do calm a flooded body in the moment; small grounding isn't a cure, but it steadies you to act.","why":"Slow breathing settles the body's alarm."},"relearn":"A few slow breaths genuinely calm a flooded moment; small grounding steadies you, even if it isn't a cure.","persona":"any","source":"breathing helps"},
  {"id":"ly-1262","cat":"healthy-coping","type":"strike-rewrite","hook":"\"If a coping habit feels good in the moment, it must be doing me good.\"","myth":{"un":"If a coping habit feels good in the moment, it must be doing me good.","re":"Some quick fixes soothe now but cost you later; healthy coping is what leaves you steadier afterwards, not just relieved.","why":"Real coping holds up the next day too."},"relearn":"A habit that feels good now isn't always healthy; healthy coping leaves you steadier afterwards, not just relieved.","persona":"any","source":"feels good vs is good"},
  {"id":"ly-1263","cat":"healthy-coping","type":"strike-rewrite","hook":"\"I have no time for self-care, so coping skills aren't for me.\"","myth":{"un":"I have no time for self-care, so coping skills aren't for me.","re":"Healthy coping fits in minutes, three breaths, a glass of water, one text, and those tiny moves still steady a hard day.","why":"Small coping needs minutes, not hours."},"relearn":"Healthy coping fits in minutes; tiny moves like a few breaths or one text still steady a hard day.","persona":"Divya","source":"coping in minutes"},
  {"id":"ly-1264","cat":"healthy-coping","type":"strike-rewrite","hook":"\"Coping is about gritting your teeth until the feeling goes away.\"","myth":{"un":"Coping is about gritting your teeth until the feeling goes away.","re":"Healthy coping isn't forcing a feeling away; it's letting it pass while you steady yourself with a breath, a pause, a kind word.","why":"Feelings ease faster when not fought."},"relearn":"Coping isn't forcing a feeling away; it's steadying yourself, breathe, pause, be kind, while it passes.","persona":"Vikram","source":"let it pass"},
  {"id":"ly-1265","cat":"healthy-coping","type":"strike-rewrite","hook":"\"Asking my partner to take over so I can breathe is just me being weak.\"","myth":{"un":"Asking my partner to take over so I can breathe is just me being weak.","re":"Tapping out for a few minutes to reset is a skilled coping move, not weakness; it returns you calmer to your child.","why":"A short reset makes you steadier."},"relearn":"Tapping out for a short reset is a skilled coping move, not weakness; you return calmer to your child.","persona":"Vikram","source":"tap out reset"},
  {"id":"ly-1266","cat":"healthy-coping","type":"strike-rewrite","hook":"\"Once I find one coping trick, I'm sorted for every hard day.\"","myth":{"un":"Once I find one coping trick, I'm sorted for every hard day.","re":"Different days need different tools; a small kit, breath, a walk, a call, a rest, beats relying on a single trick.","why":"A varied kit fits more moments."},"relearn":"No single trick fits every day; a small kit, breath, a walk, a call, a rest, copes with more moments.","persona":"any","source":"a small kit"},
  {"id":"ly-1267","cat":"healthy-coping","type":"strike-rewrite","hook":"\"Coping skills should fix how I feel, and if they don't, I'm doing it wrong.\"","myth":{"un":"Coping skills should fix how I feel, and if they don't, I'm doing it wrong.","re":"Coping makes a hard moment more bearable, it isn't a cure; if distress stays heavy, that's a cue to reach for real help.","why":"Coping eases; lasting distress needs care."},"relearn":"Coping makes a moment bearable, not cured; if distress stays heavy, reach for real help.","persona":"any","source":"coping not cure"},
  {"id":"ly-1268","cat":"healthy-coping","type":"sort","hook":"Sort: a safe, kind coping move, or one that hurts you and crosses the line?","items":[{"id":"a","text":"Resting and a few slow breaths"},{"id":"b","text":"Punishing yourself when you slip"},{"id":"c","text":"A short walk in fresh air"},{"id":"d","text":"Toughing it out by hurting yourself"},{"id":"e","text":"Calling someone you trust"},{"id":"f","text":"Going without food as a penance"}],"bins":[{"id":"safe","label":"Safe & kind","valence":"pos"},{"id":"harmful","label":"Hurts you","valence":"neg"}],"key":{"a":"safe","b":"harmful","c":"safe","d":"harmful","e":"safe","f":"harmful"},"relearn":"Healthy coping is always safe and kind, rest, breath, a walk, a call; anything that hurts or punishes you is never a coping skill.","persona":"any","source":"safe vs harmful"},
  {"id":"ly-1269","cat":"healthy-coping","type":"sort","hook":"Sort: a grounding move that calms an overwhelmed moment, or one that winds it up more?","items":[{"id":"a","text":"Naming five things you can see"},{"id":"b","text":"Replaying the worst worry on loop"},{"id":"c","text":"Feeling your feet on the floor"},{"id":"d","text":"Reading angry posts to vent"},{"id":"e","text":"Slowing your out-breath"},{"id":"f","text":"Bottling it and forcing a smile"}],"bins":[{"id":"calms","label":"Calms you","valence":"pos"},{"id":"winds","label":"Winds you up","valence":"neg"}],"key":{"a":"calms","b":"winds","c":"calms","d":"winds","e":"calms","f":"winds"},"relearn":"Naming what you see, feeling your feet and slowing your breath ground you; looping the worry, doomreading and forcing a smile wind you up.","persona":"any","source":"grounding moves"},
  {"id":"ly-1270","cat":"healthy-coping","type":"sort","hook":"Sort: a kind self-talk that helps you cope, or a harsh one that drains you?","items":[{"id":"a","text":"\"This is hard, I'm doing my best\""},{"id":"b","text":"\"I'm a terrible parent for struggling\""},{"id":"c","text":"\"One moment at a time is enough\""},{"id":"d","text":"\"Everyone copes better than me\""},{"id":"e","text":"\"It's okay to ask for help\""},{"id":"f","text":"\"I should never feel this way\""}],"bins":[{"id":"kind","label":"Kind & steadying","valence":"pos"},{"id":"harsh","label":"Harsh & draining","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Kind self-talk, this is hard, I'm doing my best, one moment at a time, steadies you; harsh self-blame drains you further.","persona":"Divya","source":"self-talk"},
  {"id":"ly-1271","cat":"healthy-coping","type":"sort","hook":"Sort: a steadying routine for a hard week, or a coping crutch that costs you?","items":[{"id":"a","text":"A regular bedtime wind-down"},{"id":"b","text":"Endless tea and zero sleep"},{"id":"c","text":"A short daily walk outdoors"},{"id":"d","text":"Skipping meals to push through"},{"id":"e","text":"A weekly check-in with a friend"},{"id":"f","text":"Scrolling till 3am to switch off"}],"bins":[{"id":"steady","label":"Steadies you","valence":"pos"},{"id":"crutch","label":"Costs you","valence":"neg"}],"key":{"a":"steady","b":"crutch","c":"steady","d":"crutch","e":"steady","f":"crutch"},"relearn":"A wind-down, a walk and a friend check-in steady you; endless tea, skipped meals and 3am scrolling cost you.","persona":"any","source":"routine vs crutch"},
  {"id":"ly-1272","cat":"healthy-coping","type":"sort","hook":"Sort: a coping move that brings you toward people, or one that pulls you into isolation?","items":[{"id":"a","text":"Texting a friend when low"},{"id":"b","text":"Cancelling on everyone for weeks"},{"id":"c","text":"Sitting with family for chai"},{"id":"d","text":"Hiding how hard it really is"},{"id":"e","text":"Joining a parents' group chat"},{"id":"f","text":"Going quiet so no one notices"}],"bins":[{"id":"toward","label":"Toward people","valence":"pos"},{"id":"isolate","label":"Into isolation","valence":"neg"}],"key":{"a":"toward","b":"isolate","c":"toward","d":"isolate","e":"toward","f":"isolate"},"relearn":"Texting a friend, chai with family and a parents' group bring you toward people; cancelling, hiding and going quiet isolate you.","persona":"any","source":"toward vs isolate"},
  {"id":"ly-1273","cat":"healthy-coping","type":"sort","hook":"Sort: an honest way to handle a flare of anger, or one that just feeds it?","items":[{"id":"a","text":"Stepping out for a minute to cool down"},{"id":"b","text":"Snapping at whoever is nearest"},{"id":"c","text":"Naming \"I'm overwhelmed right now\""},{"id":"d","text":"Slamming things to let it out"},{"id":"e","text":"Slow breaths till the heat drops"},{"id":"f","text":"Stewing and replaying it for hours"}],"bins":[{"id":"cools","label":"Cools it down","valence":"pos"},{"id":"feeds","label":"Feeds it","valence":"neg"}],"key":{"a":"cools","b":"feeds","c":"cools","d":"feeds","e":"cools","f":"feeds"},"relearn":"Stepping out, naming it and slow breaths cool anger; snapping, slamming and stewing only feed it.","persona":"Vikram","source":"anger flare"},
  {"id":"ly-1274","cat":"healthy-coping","type":"sort","hook":"Sort: a way to rest that actually refills you, or 'rest' that leaves you more frazzled?","items":[{"id":"a","text":"Twenty quiet minutes lying down"},{"id":"b","text":"Doomscrolling on the sofa"},{"id":"c","text":"Sitting outside with a chai"},{"id":"d","text":"Watching the news on a loop"},{"id":"e","text":"A short nap when the baby sleeps"},{"id":"f","text":"Cleaning the whole house instead"}],"bins":[{"id":"refills","label":"Actually rests you","valence":"pos"},{"id":"frazzles","label":"Leaves you frazzled","valence":"neg"}],"key":{"a":"refills","b":"frazzles","c":"refills","d":"frazzles","e":"refills","f":"frazzles"},"relearn":"Quiet lying-down, chai outside and a short nap truly rest you; doomscrolling, news loops and 'just one more chore' don't.","persona":"any","source":"real rest"},
  {"id":"ly-1275","cat":"healthy-coping","type":"sort","hook":"Sort: a small body-care that helps you cope, or neglect that wears you thin?","items":[{"id":"a","text":"Drinking enough water through the day"},{"id":"b","text":"Living on tea and skipped meals"},{"id":"c","text":"Eating something, even simple"},{"id":"d","text":"Staying up far past your limit"},{"id":"e","text":"Sleeping when the chance comes"},{"id":"f","text":"Ignoring your body's signals"}],"bins":[{"id":"care","label":"Body-care","valence":"pos"},{"id":"neglect","label":"Neglect","valence":"neg"}],"key":{"a":"care","b":"neglect","c":"care","d":"neglect","e":"care","f":"neglect"},"relearn":"Water, eating something and sleeping when you can help you cope; skipped meals, no sleep and ignored signals wear you thin.","persona":"any","source":"body care"},
  {"id":"ly-1276","cat":"healthy-coping","type":"match","hook":"Match each coping skill to what it does for you.","pairs":[{"left":"Slow breathing","right":"Settles a flooded, racing body"},{"left":"A short walk outside","right":"Clears your head and shifts your mood"},{"left":"Calling a friend","right":"Eases the weight of carrying it alone"},{"left":"A simple meal and water","right":"Steadies your body so you can think"},{"left":"A short nap","right":"Takes the sharp edge off exhaustion"}],"relearn":"Breathing, a walk, a call, a meal and a nap each do a real job, settling, clearing, easing, steadying, softening, under load.","persona":"any","source":"skill to job"},
  {"id":"ly-1277","cat":"healthy-coping","type":"match","hook":"Match each unhealthy coping habit to a gentler, healthier swap.","pairs":[{"left":"Numbing with a late drink","right":"A warm bath or wind-down ritual"},{"left":"Doomscrolling at midnight","right":"Putting the phone down and resting"},{"left":"Bottling it all in","right":"Saying it out loud to one person"},{"left":"Skipping meals to push on","right":"Grabbing something easy to eat"},{"left":"Snapping under pressure","right":"Stepping out for a minute first"}],"relearn":"Each unhealthy habit has a kinder swap, a wind-down, real rest, saying it aloud, eating, stepping out, reached for with warmth.","persona":"Priya","source":"swaps"},
  {"id":"ly-1278","cat":"healthy-coping","type":"match","hook":"Match each India-everyday hard moment to a doable coping move.","pairs":[{"left":"Crying baby, no help at home","right":"Lay them down safe, breathe, regroup"},{"left":"In-laws' advice piling up","right":"Step to another room for two minutes"},{"left":"Up all night, dragging by noon","right":"Rest when the baby naps, skip a chore"},{"left":"Tense over money worries","right":"Name one worry to your partner"},{"left":"No time to yourself all day","right":"Take ten minutes on the balcony"}],"relearn":"Even on the hardest India-everyday days, a safe pause, a step away, a nap, a shared worry or balcony minutes help.","persona":"Divya","source":"everyday moves"},
  {"id":"ly-1279","cat":"healthy-coping","type":"match","hook":"Match each tired thought to a kinder reframe that helps you cope.","pairs":[{"left":"\"I can't do anything right\"","right":"\"I'm doing a hard job, tired, not failing\""},{"left":"\"I should manage alone\"","right":"\"Accepting help is part of coping\""},{"left":"\"This will never ease\"","right":"\"Hard seasons do pass, bit by bit\""},{"left":"\"I have no time to cope\"","right":"\"A few breaths still count\""},{"left":"\"Resting is lazy\"","right":"\"Rest is how I refill to give\""}],"relearn":"A harsh thought met with a kinder, true reframe, tired not failing, help is coping, this passes, makes the load easier to carry.","persona":"Divya","source":"reframe thoughts"},
  {"id":"ly-1280","cat":"healthy-coping","type":"match","hook":"Match each grounding tool to the moment it fits.","pairs":[{"left":"Five slow out-breaths","right":"Panic rising in your chest"},{"left":"Feet flat, notice the floor","right":"Spinning out, unmoored"},{"left":"Name five things you see","right":"Thoughts racing too fast"},{"left":"Cool water on your wrists","right":"Hot, flushed and overwhelmed"},{"left":"Hum or sip slowly","right":"Throat tight, can't settle"}],"relearn":"Different grounding tools fit different moments, breath for panic, feet for spinning, naming for racing, cool water and humming to settle.","persona":"any","source":"tool to moment"},
  {"id":"ly-1281","cat":"healthy-coping","type":"match","hook":"Match each healthy coping move to the load it eases.","pairs":[{"left":"Sharing the night feeds","right":"Bone-deep sleep deprivation"},{"left":"A walk with the pram","right":"Feeling cooped up and flat"},{"left":"A vent to a fellow parent","right":"Feeling no one understands"},{"left":"Saying no to one extra thing","right":"An over-full, impossible day"},{"left":"A few minutes of quiet","right":"Touched out and over-stimulated"}],"relearn":"Sharing feeds, a walk, a vent, a 'no' and a little quiet each ease a specific load that parenting piles on.","persona":"Priya","source":"move to load"},
  {"id":"ly-1282","cat":"healthy-coping","type":"branch","persona":"Divya","source":"2am racing","hook":"It's 2am, the baby finally settled, and your mind won't stop racing.","steps":[{"prompt":"You lie down and your thoughts start racing. What do you do?","options":[{"text":"Rest your body and slow your breathing","then":"Your body eases, even as your mind stays busy.","best":true},{"text":"Grab your phone and scroll until you're wired","then":"The screen glows. You're more awake than before."},{"text":"Get up and do the dishes to use the time","then":"The dishes are done and you're still wide awake."},{"text":"Lie there arguing with your thoughts","then":"The argument gets louder. Sleep gets further."}],"why":"Resting your body and slowing your breath helps even when sleep doesn't come."},{"prompt":"The baby stirs at 4am and you feel raw. What do you do?","options":[{"text":"Ask your partner to take the next stretch","then":"Your partner takes over. You sleep for two hours, deeply.","best":true},{"text":"Stay up so you catch every sound","then":"You listen all night. The day is a blur."},{"text":"Drink strong coffee to push through the day","then":"The coffee wakes you and jangles you. You crash mid-afternoon."},{"text":"Tell yourself sleep doesn't matter","then":"You run on nothing. By noon you're near tears."}],"why":"Sharing the night shift is a real refill, not a luxury."},{"prompt":"By lunchtime the racing thoughts return in the quiet. What do you do?","options":[{"text":"Rest twenty minutes and tell a doctor if it stays","then":"You rest. The thoughts loosen a little.","best":true},{"text":"Fill the whole hour with chores to outrun them","then":"The chores are done. The thoughts run just as fast."},{"text":"Scroll social media until the baby wakes again","then":"The scrolling makes the thoughts louder."},{"text":"Wait for tonight to sort itself out","then":"Tonight comes. The thoughts arrive with it."}],"why":"Resting during the day helps, and racing thoughts that stay are worth a doctor's visit."}],"debrief":"When your mind races at night, rest your body and slow your breath; scrolling winds you tighter.","relearn":"At 2am, rest your body and breathe slowly; scrolling wires you instead."},
  {"id":"ly-1283","cat":"healthy-coping","type":"branch","persona":"any","source":"nightly drink","hook":"You've started having an extra drink most nights just to switch off.","steps":[{"prompt":"It's ten at night and the baby is finally down. What do you do?","options":[{"text":"Have a warm shower, tea and one favourite song","then":"It's slower than a drink and still works a little.","best":true},{"text":"Pour the usual extra drink","then":"It takes the edge off. The habit grows another night."},{"text":"Pour a smaller drink and call it a compromise","then":"The drink is smaller. The habit is the same."},{"text":"Scroll on the sofa until you feel numb","then":"You feel numb and not rested."}],"why":"A small wind-down ritual gives your mind somewhere else to go."},{"prompt":"Your partner Imran mentions the bottle is emptying faster. What do you say?","options":[{"text":"Say you've been using it to switch off and want a swap","then":"He nods. \"Thank you for telling me. Let's find one.\"","best":true},{"text":"Say it's harmless and he's overreacting","then":"He shrugs, unconvinced. The bottle keeps emptying."},{"text":"Say you'll cut down quietly on your own","then":"You cut down. You also stay alone with it."},{"text":"Say nothing and move the bottle","then":"He notices. Neither of you says a word."}],"why":"Telling him what it's for opens the door to a swap and support."},{"prompt":"A hard day makes the old habit pull strongly. What do you do?","options":[{"text":"Text Imran or a friend and do something calming","then":"The text and the calm get you to bed. The habit doesn't win.","best":true},{"text":"Have the drink and tell yourself just tonight","then":"You have one and stop there. The next night, the pull is back."},{"text":"Skip dinner and go straight to bed","then":"You lie awake, hungry and tense."},{"text":"Tough it out alone with willpower","then":"Willpower is thin at the end of a hard day."}],"why":"Reaching out and doing something calming works better than willpower alone."},{"prompt":"Later that week, the extra drink creeps back in one night. What do you do?","options":[{"text":"Tell someone without shame and restart tomorrow","then":"He says he's glad you told him. You start again tomorrow.","best":true},{"text":"Decide you've failed and give up trying","then":"The effort is dropped, and the drink is back."},{"text":"Hide it and tell no one","then":"You carry it in silence. The pull grows."},{"text":"Vow never to slip again and go it alone","then":"The vow is heavy. It breaks the following week."}],"why":"A slip is not a failure, and telling someone is how you keep going."},{"prompt":"Weeks on, you still need a drink to sleep on most nights. What do you do?","options":[{"text":"Talk to a doctor or call Tele-MANAS 14416","then":"They listen and help you plan the next step.","best":true},{"text":"Keep going, since it feels mostly under control","then":"The habit quietly grows."},{"text":"Switch to a different drink and keep it quiet","then":"The drink changes. The reason doesn't."},{"text":"Wait until it gets worse before you ask for help","then":"It gets worse. You wish you'd asked earlier."}],"why":"Needing a drink to sleep most nights is worth telling a doctor, and it's not shameful."}],"debrief":"A nightly drink-to-cope is worth swapping, gently, for a wind-down and a word to someone.","relearn":"Swap a nightly drink-to-cope for a wind-down and tell someone; don't wave it off."},
  {"id":"ly-1284","cat":"healthy-coping","type":"branch","persona":"any","source":"no self-punish","hook":"A harsh voice says you should punish yourself for not coping well.","steps":[{"prompt":"The voice gets louder after a rough evening. What do you do?","options":[{"text":"Speak to yourself kindly and sit down to rest","then":"The voice softens a little. You sit and take a slow breath.","best":true},{"text":"Obey it and skip dinner as a penalty","then":"The hunger and tiredness make the voice louder."},{"text":"Argue with it in your head all night","then":"The argument goes round and round. Sleep doesn't come."},{"text":"Push it away and keep working","then":"The voice gets quieter and comes back."}],"why":"Coping never means punishing yourself. Kindness and rest are the way."},{"prompt":"A friend messages to ask how you are. What do you do?","options":[{"text":"Tell her the voice has been harsh and ask to talk","then":"She calls straight away. \"I'm so glad you told me.\"","best":true},{"text":"Say you're fine and change the subject","then":"She replies with a smiley. The voice keeps talking."},{"text":"Say you're busy this week","then":"She says no problem. You put the phone down and sit alone with it."},{"text":"Tell her only about the baby's milestones","then":"She sends hearts. You feel further away."}],"why":"Telling a friend about the harsh voice takes away some of its power."},{"prompt":"The voice returns the next night, just as loud. What do you do?","options":[{"text":"Slow your breathing and rest your body","then":"The voice is still there, but you are steadier.","best":true},{"text":"Distract yourself with your phone until it goes quiet","then":"The phone keeps you up. The voice comes back at 3am."},{"text":"Wait for it to stop by itself","then":"It doesn't. It only gets more familiar."},{"text":"Try harder to be perfect tomorrow","then":"The bar goes up. The voice gets sharper."}],"why":"Rest and slow breath meet the voice without feeding it."},{"prompt":"After a week, the voice is still loud and you feel worn thin. What do you do?","options":[{"text":"Tell your doctor or call Tele-MANAS 14416","then":"Someone listens without judgement and helps you plan.","best":true},{"text":"Keep going, since you're nearly used to it","then":"You get more tired. The voice gets more familiar."},{"text":"Wait for a calmer month","then":"The calmer month doesn't come."},{"text":"Handle it with a strict routine","then":"The routine holds for two days."}],"why":"A harsh voice that stays is a symptom, not the truth, and help is there."}],"debrief":"Coping is never self-punishment; meet a harsh voice with kindness and rest, and reach for help if it stays.","relearn":"Coping is never hurting yourself; meet a harsh inner voice with kindness and rest."},
  {"id":"ly-1285","cat":"healthy-coping","type":"branch","persona":"Divya","source":"accept the hour","hook":"You've been carrying everything alone, and a friend offers to take the baby for an hour.","steps":[{"prompt":"Your friend Sheela waits for your answer. What do you say?","options":[{"text":"Accept the hour and thank her","then":"She smiles. \"Four o'clock, then. I'll bring snacks.\"","best":true},{"text":"Say no, so you don't seem unable to cope","then":"She says the offer stands whenever you're ready."},{"text":"Say maybe and cancel later","then":"She says fine, but you feel a small knot of guilt."},{"text":"Accept, then insist on cooking for her first","then":"You spend the morning cooking. The hour isn't restful."}],"why":"Accepting the hour is a real way to refill, not a sign of failing."},{"prompt":"Your mother-in-law hears of the offer and says a baby belongs with his mother. What do you say?","options":[{"text":"Say an hour of rest helps you care for the baby","then":"She frowns and says nothing. Then she nods slightly.","best":true},{"text":"Say sorry and promise it won't happen again","then":"She looks satisfied. You feel smaller."},{"text":"Argue that she never helped you","then":"She stiffens and the room turns cold."},{"text":"Say nothing and turn down the next offer","then":"You say no when Sheela offers again. A week later she kindly asks once more."}],"why":"An hour of rest helps you look after the baby, and it's a fair thing to say."},{"prompt":"The next time you get an hour to yourself, ten chores clamour for you. What do you do?","options":[{"text":"Pick one for ten minutes and spend the rest resting","then":"The chore is done. You rest for fifty minutes.","best":true},{"text":"Spend the whole hour on chores","then":"The chores are done. You're just as tired."},{"text":"Sit with the chores in your head and rest nowhere","then":"You sit, but you don't relax."},{"text":"Hover nearby, listening for every little cry","then":"Each whimper pulls you up. The hour ends and you haven't rested."}],"why":"One chore and a real rest stops the hour from disappearing."},{"prompt":"Sheela asks how it went and whether you'd like a regular slot. What do you say?","options":[{"text":"Say yes, and ask for the same hour each week","then":"She smiles. \"Every Thursday at four.\"","best":true},{"text":"Say it was fine but you shouldn't take more","then":"She nods. The offer stays but the door closes."},{"text":"Say you'd rather not depend on anyone","then":"She says all right. You go back to carrying it alone."},{"text":"Say maybe later","then":"Later never arrives."}],"why":"A regular slot builds a support net so the hour doesn't depend on chance."}],"debrief":"Accepting offered help and resting in it is a coping skill, not a failure to cope.","relearn":"Accepting an offer of help and resting in it is coping; refusing to look capable keeps you drained."},
  {"id":"ly-1286","cat":"healthy-coping","type":"branch","persona":"any","source":"ten minutes","hook":"On a packed day you get ten free minutes and feel guilty not doing chores.","steps":[{"prompt":"The baby naps and the sink is full. What do you do?","options":[{"text":"Sit, step outside or breathe for ten minutes","then":"You stand in the sun for ten minutes. You feel a bit lighter.","best":true},{"text":"Cram in one more chore and stay frayed","then":"The sink is cleaner. You're just as frayed."},{"text":"Start the sink 'for a minute' and lose the ten","then":"The minute becomes ten and the ten become none."},{"text":"Check the family group chat and reply to everyone","then":"Everyone gets a reply. You get nothing."}],"why":"A real ten-minute reset steadies the rest of the day."},{"prompt":"That evening, your partner asks how your day went. What do you say?","options":[{"text":"Say you want ten minutes to yourself each day","then":"Your partner nods. \"Good. I'll watch the baby after lunch.\"","best":true},{"text":"Say you did chores, nothing else","then":"Your partner nods. The day's weight goes unnoticed."},{"text":"List everything you did to prove yourself","then":"Your partner looks confused. \"I didn't ask for a list.\""},{"text":"Say you did nothing much","then":"Your partner nods, a little puzzled, and assumes it was an easy day."}],"why":"Saying you need a daily reset makes it normal, and easier to take."},{"prompt":"The next day, ten free minutes come again, and the guilt returns. What do you do?","options":[{"text":"Notice the guilt and take the ten minutes","then":"The guilt hums quietly in the background. The minutes still help.","best":true},{"text":"Give in and cram in chores","then":"The chores are done. So is your energy."},{"text":"Wait until the chores are finished to sit","then":"The chores are never finished."},{"text":"Take the minutes but scroll your phone the whole time","then":"You rest your body but not your mind."}],"why":"Guilt can sit beside you while you take the ten minutes."}],"debrief":"A rare ten free minutes are well spent on a reset, not crammed with one more chore.","relearn":"Spend a rare ten minutes resetting, not on one more chore; it steadies the day."},
  {"id":"ly-1287","cat":"healthy-coping","type":"branch","persona":"any","source":"safe pause","hook":"A wave of overwhelm builds while you're holding your crying baby.","steps":[{"prompt":"The crying won't ease and your chest is tightening. What do you do?","options":[{"text":"Lay the baby somewhere safe, step back and breathe slowly","then":"The baby keeps crying, safe in the cot. Your breathing slows a little.","best":true},{"text":"Keep rocking and tell yourself firmly to stay calm","then":"You grip the baby tighter and the tightness in your chest grows."},{"text":"Search online for why babies cry this hard, one-handed","then":"You scroll through articles. The crying and your panic both climb."},{"text":"Push through the rising panic without stopping for a pause","then":"Your arms stiffen and your patience thins with every minute."}],"why":"A safe pause steadies you and keeps the baby safe while you settle."},{"prompt":"Later that evening your partner gets home and asks how it went. What do you say?","options":[{"text":"Say it got overwhelming and ask for a proper break tomorrow","then":"He nods slowly. \"Thank you for telling me. I'll take the morning.\"","best":true},{"text":"Say it was fine, only a fussy evening like any other one","then":"He shrugs and heads to change. The tightness stays with you."},{"text":"Say you nearly lost it, which proves you are failing at this","then":"He says that's not true, but you can't quite hear him tonight."},{"text":"Say it was rough but that you'll manage better next time","then":"He says okay. No break is planned, and tomorrow looks the same."}],"why":"Naming it and asking for a specific break lets your partner really help."},{"prompt":"Over the next weeks the sudden overwhelm keeps returning. What do you do?","options":[{"text":"Tell a doctor or Tele-MANAS 14416 how often it comes","then":"The listener hears you out and helps you plan your next step.","best":true},{"text":"Assume every new parent feels this and keep coping alone","then":"You keep going. The overwhelm keeps arriving, and you keep hiding it."},{"text":"Wait until the baby sleeps through the night before you act","then":"The nights don't shorten yet. The waves keep coming."},{"text":"Try every technique you can find online, all at the same time","then":"You juggle five methods and feel more tired, not steadier."}],"why":"Coping eases a moment, and a doctor or helpline helps when it keeps coming back."}],"debrief":"When overwhelm surges with a crying baby, lay them safe, step back and breathe; it protects you both.","relearn":"If overwhelm surges, lay the baby safe, step back and breathe; it protects you both."},
  {"id":"ly-1288","cat":"healthy-coping","type":"branch","persona":"any","source":"after cost","hook":"A coping habit eases the moment but leaves you feeling worse the next day.","steps":[{"prompt":"The baby is finally asleep and the habit is calling again tonight. What do you do?","options":[{"text":"Notice what it costs tomorrow and pick something steadier","then":"You step out for a slow walk. The urge is still there, but weaker.","best":true},{"text":"Have it, and promise yourself that this is the last time","then":"It eases the evening. The promise feels thin by the next afternoon."},{"text":"Have a smaller amount than usual, just this once tonight","then":"Relief comes, and so does the same heavy morning, only a little lighter."},{"text":"Tell yourself you've earned it after everything today","then":"It feels fair in the moment. The next day is just as flat."}],"why":"Noticing the after-cost lets you choose something that holds up tomorrow."},{"prompt":"A few days later a friend asks how you're holding up. What do you say?","options":[{"text":"Tell her about the habit and ask her to walk with you","then":"She says she has one too. You plan a walk for Thursday.","best":true},{"text":"Say you're fine, just tired, and ask about her week instead","then":"She smiles and lets it go. You leave feeling as alone as before."},{"text":"Joke about it lightly and change the subject to something else","then":"She laughs along, and the real conversation never starts."},{"text":"Say you'll cut it out on your own, with no need to tell anyone","then":"She says okay. You start alone and it is harder than you expected."}],"why":"Sharing it with someone turns a private habit into a plan with company."},{"prompt":"Weeks later a rough day brings the urge back hard. What do you do?","options":[{"text":"Step out and breathe, or call a friend, instead of the habit","then":"The urge peaks, then softens. You feel steadier than after the old habit.","best":true},{"text":"Rely on willpower alone this time and hope that it holds up","then":"You hold out for an hour, then the urge wins, and you feel drained."},{"text":"Tell yourself that one slip means you have failed completely","then":"The shame makes the evening heavier. The urge grows louder."},{"text":"Wait until you feel much worse before you try anything else","then":"The day drags on. By night you are worn out and short of options."}],"why":"Swaps are practised, and a doctor is there too if the urge stays strong."}],"debrief":"If a habit soothes now but costs you tomorrow, trade it for coping that leaves you steadier.","relearn":"If a habit soothes now but you feel worse tomorrow, trade it for a steadier one."},
  {"id":"ly-1289","cat":"healthy-coping","type":"branch","persona":"Divya","source":"coping has limits","hook":"You've breathed and rested, but the heaviness hasn't lifted in weeks.","steps":[{"prompt":"Another week goes by and you wake up feeling the same. What do you do?","options":[{"text":"Book a doctor's visit and say it has lasted weeks","then":"The receptionist finds you a slot on Thursday. You feel a little lighter.","best":true},{"text":"Add more breathing exercises and earlier nights, faithfully","then":"You keep at it. The heaviness stays exactly where it was."},{"text":"Wait until the baby sleeps through the night to see","then":"The nights stay broken, and the weeks keep adding up."},{"text":"Tell yourself others have it harder and carry on regardless","then":"You push the feeling down. It sits heavier by evening."}],"why":"When self-help hasn't lifted weeks of heaviness, a doctor is the next step."},{"prompt":"Your mother-in-law notices you've been quiet and asks what's wrong. What do you say?","options":[{"text":"Tell her it has lasted weeks and you want to see a doctor","then":"She is quiet, then squeezes your hand. \"I'll mind the baby when you go.\"","best":true},{"text":"Say it's only tiredness, and that it will settle in time","then":"She nods and says everyone is tired. The subject closes."},{"text":"Say nothing is wrong and go to your room to rest alone","then":"She frowns but lets you go. The door closes on a long evening."},{"text":"Say you should just be more grateful for the baby","then":"She agrees warmly. You feel worse for having said it."}],"why":"Saying it plainly gives family a way to support you."},{"prompt":"One night the heaviness feels too big to hold. What do you do?","options":[{"text":"Call Tele-MANAS 14416 and say how heavy it has been","then":"A calm voice listens, then helps you plan what to do tonight and tomorrow.","best":true},{"text":"Tell yourself you have done enough already and do nothing more","then":"The night stays long, and no one else knows how it feels."},{"text":"Scroll on your phone until you finally fall asleep","then":"You sleep late. The heaviness is waiting when you wake."},{"text":"Wait for morning and see whether it lifts by itself","then":"Morning comes slowly. The heaviness hasn't moved."}],"why":"Help fits weeks of heaviness, and Tele-MANAS is there at any hour."}],"debrief":"Coping eases moments, but weeks of heaviness that won't lift are a cue to reach for a doctor or helpline.","relearn":"When self-help can't lift weeks of heaviness, reach for a doctor or helpline."},
  {"id":"ly-1290","cat":"healthy-coping","type":"reflect","hook":"Lensy: coping isn't about never struggling; it's about how gently you meet yourself when you do. Sit right?","prompt":"What do you think?","options":["Sits right","Meet myself gently","I can try"],"affirm":"Coping isn't never struggling; it's meeting yourself with a little gentleness when you do, which steadies the hard moments.","relearn":"Coping isn't never struggling; it's meeting yourself gently when you do.","persona":"any","source":"meet gently"},
  {"id":"ly-1291","cat":"healthy-coping","type":"reflect","hook":"Lensy: the breath you take before reacting is small, but it's one of the strongest tools you have. Feel that?","prompt":"What's your take?","options":["I feel it","One breath","Strong tool"],"affirm":"A single slow breath before you react is small but powerful; it gives you the space to respond rather than snap.","relearn":"One slow breath before reacting is a small but powerful tool, space to respond, not snap.","persona":"any","source":"the breath before"},
  {"id":"ly-1292","cat":"healthy-coping","type":"reflect","hook":"Lensy: choosing a coping move that's kind to your body, never one that hurts it, is always the right line. Agree?","prompt":"What do you think?","options":["Agree","Kind to my body","Always"],"affirm":"Healthy coping is always kind to your body; anything that hurts or punishes you is never a coping skill, no exceptions.","relearn":"Healthy coping is always kind to your body; nothing that hurts you is ever a coping skill.","persona":"any","source":"kind line"},
  {"id":"ly-1293","cat":"healthy-coping","type":"reflect","hook":"Lensy: you don't have to cope perfectly; a few small, safe habits kept up are more than enough. Land okay?","prompt":"What's your take?","options":["Lands okay","Not perfect","Small habits"],"affirm":"You don't need to cope perfectly; a few small, safe habits kept up gently carry you through a hard season.","relearn":"You don't have to cope perfectly; a few small safe habits, kept up, are enough.","persona":"Divya","source":"not perfect"},
  {"id":"ly-1294","cat":"healthy-coping","type":"reflect","hook":"Lensy: reaching for a healthy way to cope, instead of an old harmful one, is a quiet win worth honouring. Resonate?","prompt":"What do you think?","options":["Resonates","A quiet win","Worth honouring"],"affirm":"Every time you choose a healthy coping move over an old harmful one, that's a real, quiet win worth honouring in yourself.","relearn":"Choosing a healthy coping move over an old harmful one is a quiet win worth honouring.","persona":"any","source":"quiet win"},
  {"id":"ly-1295","cat":"healthy-coping","type":"reflect","hook":"Lensy: accepting help on a heavy day isn't the opposite of coping; it IS coping. Hear that?","prompt":"What's your take?","options":["I hear it","Help is coping","Makes sense"],"affirm":"Accepting help on a heavy day is one of the wisest coping moves there is; it isn't the opposite of coping at all.","relearn":"Accepting help on a heavy day isn't the opposite of coping; it is coping.","persona":"any","source":"help is coping"},
  {"id":"ly-1296","cat":"healthy-coping","type":"reflect","hook":"Lensy: a hard moment usually passes faster when you stop fighting the feeling and just breathe through it. Make sense?","prompt":"What do you think?","options":["Makes sense","Breathe through","I'll try"],"affirm":"Feelings tend to crest and pass; breathing through a hard moment, instead of fighting it, often lets it move sooner.","relearn":"A hard feeling often passes sooner when you breathe through it instead of fighting it.","persona":"any","source":"passes faster"},
  {"id":"ly-1297","cat":"healthy-coping","type":"reflect","hook":"Lensy: knowing one or two coping moves you can reach for on a bad day is a quiet kind of safety. Worth keeping a couple?","prompt":"What's your take?","options":["Worth it","Keep a couple","Good idea"],"affirm":"Having one or two go-to coping moves ready means a bad day has somewhere to land; that's a quiet kind of safety.","relearn":"Keeping one or two go-to coping moves ready gives a bad day somewhere to land.","persona":"Divya","source":"go-to moves"},
  {"id":"ly-1298","cat":"healthy-coping","type":"spot","hook":"Spot the two coping moves that cross the line into harming yourself.","scene":[{"id":"a","text":"Resting and slowing your breath","trick":false},{"id":"b","text":"Going without sleep to punish yourself","trick":true},{"id":"c","text":"Stepping outside for some air","trick":false},{"id":"d","text":"Skipping meals as self-discipline","trick":true},{"id":"e","text":"Leaning on a friend for support","trick":false}],"why":"Sleep-deprivation as punishment and skipping meals harm you; rest, air and leaning on a friend are safe coping.","relearn":"Coping never harms you; rest, air and support are safe, while sleep-deprivation or skipping meals as 'discipline' are not.","persona":"any","source":"crosses line"},
  {"id":"ly-1299","cat":"healthy-coping","type":"spot","hook":"Spot the two 'coping' habits that quietly cost you more than they give.","scene":[{"id":"a","text":"A short daily wind-down","trick":false},{"id":"b","text":"Numbing out with a screen for hours","trick":true},{"id":"c","text":"A walk or some daylight","trick":false},{"id":"d","text":"Bottling it all up alone","trick":true},{"id":"e","text":"Talking it through with someone","trick":false}],"why":"Hours of numbing-out and bottling up alone cost you more than they give; a wind-down, a walk and talking it through truly help.","relearn":"Numbing for hours and bottling up alone cost you; a wind-down, daylight and talking it through genuinely help.","persona":"any","source":"costs more"},
  {"id":"ly-1300","cat":"healthy-coping","type":"spot","hook":"Spot the two responses to overwhelm that wind you up instead of steadying you.","scene":[{"id":"a","text":"Slowing your breath","trick":false},{"id":"b","text":"Replaying the worst-case on loop","trick":true},{"id":"c","text":"Feeling your feet on the floor","trick":false},{"id":"d","text":"Snapping at whoever's nearest","trick":true},{"id":"e","text":"Naming what you feel out loud","trick":false}],"why":"Looping the worst-case and snapping at someone wind you up; breathing, grounding and naming the feeling steady you.","relearn":"When overwhelmed, breathe, ground and name it to steady yourself, rather than looping the worst-case or snapping.","persona":"Vikram","source":"winds vs steadies"},
  {"id":"ly-1301","cat":"healthy-coping","type":"spot","hook":"Spot the two unhealthy ways of coping a stressed parent might slip into.","scene":[{"id":"a","text":"Asking a friend to take the baby an hour","trick":false},{"id":"b","text":"Drinking every night to switch off","trick":true},{"id":"c","text":"Resting when the baby naps","trick":false},{"id":"d","text":"Picking fights to release the tension","trick":true},{"id":"e","text":"Breathing through the hardest moments","trick":false}],"why":"Nightly drinking to switch off and picking fights are unhealthy; asking for help, resting and breathing are healthy coping.","relearn":"Nightly drinking and picking fights are unhealthy coping; asking for help, resting and breathing are healthy.","persona":"any","source":"unhealthy slips"},
  {"id":"ly-1302","cat":"healthy-coping","type":"spot","hook":"Spot the two harsh self-talk lines that drain you, not the kind ones that help.","scene":[{"id":"a","text":"\"This is hard and I'm doing my best\"","trick":false},{"id":"b","text":"\"I'm failing my child by struggling\"","trick":true},{"id":"c","text":"\"One moment at a time is okay\"","trick":false},{"id":"d","text":"\"I don't deserve a break\"","trick":true},{"id":"e","text":"\"It's okay to need help\"","trick":false}],"why":"'I'm failing' and 'I don't deserve a break' are draining and untrue; kind, true self-talk helps you cope.","relearn":"Harsh self-talk like 'I'm failing' or 'I don't deserve a break' drains you; kind, true words help you cope.","persona":"Divya","source":"harsh self-talk"},
  {"id":"ly-1303","cat":"healthy-coping","type":"spot","hook":"Spot the two 'rests' that don't actually refill a tired parent.","scene":[{"id":"a","text":"Lying down quietly for a bit","trick":false},{"id":"b","text":"Doomscrolling the whole break","trick":true},{"id":"c","text":"Sitting outside with a chai","trick":false},{"id":"d","text":"Watching anxious news on a loop","trick":true},{"id":"e","text":"A short nap when you can","trick":false}],"why":"Doomscrolling and looping anxious news don't refill you; lying down, chai outside and a short nap genuinely rest you.","relearn":"Doomscrolling and news loops aren't real rest; quiet lying-down, chai outside and a nap genuinely refill you.","persona":"any","source":"fake rest"},
  {"id":"ly-1304","cat":"healthy-coping","type":"spot","hook":"Spot the two moves that pull a struggling parent deeper into isolation.","scene":[{"id":"a","text":"Texting one person when low","trick":false},{"id":"b","text":"Cancelling on everyone for weeks","trick":true},{"id":"c","text":"Sitting with family for a chat","trick":false},{"id":"d","text":"Hiding how hard things really are","trick":true},{"id":"e","text":"Joining a parents' group","trick":false}],"why":"Cancelling on everyone and hiding the struggle deepen isolation; texting, sitting with family and a group keep you connected.","relearn":"Cancelling on people and hiding the struggle isolate you; texting, family time and a group keep you connected.","persona":"any","source":"isolation moves"},
  {"id":"ly-1305","cat":"healthy-coping","type":"role-play","persona":"Vikram","source":"offer reset partner","hook":"Your partner Kavya snaps, and you can see she is overwhelmed. You want to offer a reset, not a fight.","setup":"The baby has been crying for an hour.","steps":[{"prompt":"Kavya snaps: \"Why is nothing ever done properly in this house?\"","options":[{"text":"\"You seem flooded. Take five minutes outside. I've got the baby.\"","then":"She stares, then lets out a breath. \"Five minutes. Okay.\"","best":true},{"text":"\"Don't take it out on me. Just deal with it.\"","then":"Her voice rises. \"Deal with it? That's all you have to say?\""},{"text":"\"Fine. I'll do everything myself then, since I can't do it right.\"","then":"She folds her arms. \"That's not what I said.\""},{"text":"\"You always get like this when you're tired.\"","then":"She turns away sharply. \"Don't tell me how I always am.\""}],"why":"Naming the overwhelm and offering a covered break calms things faster than firing back."},{"prompt":"Later Kavya sits down and says: \"I didn't mean to shout. I don't know what's wrong with me.\"","options":[{"text":"\"Nothing is wrong with you. You're overwhelmed. Talk to me?\"","then":"She wipes her eyes. \"It has been building for weeks.\"","best":true},{"text":"\"It's fine. Just try not to do it again, and we'll move on.\"","then":"She nods stiffly. \"I'll try.\" She won't meet your eye."},{"text":"\"You have been shouting a lot lately, and I have noticed.\"","then":"Her face crumples. \"I know. That's what scares me.\""},{"text":"\"Forget it. We're both just tired and that's all it is.\"","then":"She lets it go, though her hands stay tight in her lap."}],"why":"Saying she isn't broken, only overwhelmed, opens the door to honesty."},{"prompt":"The next day Kavya says: \"I keep feeling like this. Maybe I should ask someone.\"","options":[{"text":"\"I'll come with you. Let's book the doctor together.\"","then":"She exhales. \"Thank you. I didn't want to go alone.\"","best":true},{"text":"\"Give it another week. You might just be tired.\"","then":"She nods, unsure. The week passes and she says less each day."},{"text":"\"Ask your mother. She'll know what to do.\"","then":"She winces. \"I don't want to worry her yet.\""},{"text":"\"I'm not sure it's that serious, honestly.\"","then":"She shrinks a little. \"Maybe you're right. Forget I said it.\""}],"why":"Going with her to a doctor turns her wish into a plan, and she doesn't go alone."}],"relearn":"Naming the overwhelm and offering a covered five-minute reset calms things far better than firing back."},
  {"id":"ly-1306","cat":"healthy-coping","type":"role-play","persona":"Priya","source":"steer friend","hook":"A friend has been leaning on an unhealthy habit to get through the baby months.","setup":"She tells you quietly, not meeting your eyes.","steps":[{"prompt":"Your friend Meera says: \"I've been drinking every night since the baby. I'm so ashamed.\"","options":[{"text":"\"No judgement. You needed something. Walk or call with me?\"","then":"Her eyes fill with tears. \"Thank you for not judging me.\"","best":true},{"text":"\"You really need to stop that. It's bad for you.\"","then":"She flushes. \"I know it is. I shouldn't have told you.\""},{"text":"\"Lots of mothers have a drink at night. It's normal.\"","then":"She smiles weakly. \"Maybe. It doesn't feel normal to me.\""},{"text":"\"Don't tell anyone else. People will talk and judge you.\"","then":"She nods, shrinking. \"I won't.\" She looks even more alone."}],"why":"Warmth without judgement helps her stay open, and a gentle alternative gives her a next step."},{"prompt":"A few days later Meera says: \"I had it again last night. I hate that I did.\"","options":[{"text":"\"One night doesn't undo anything. What made last night so hard?\"","then":"She thinks. \"The baby was up until three, and I felt so alone.\"","best":true},{"text":"\"Then you're clearly not trying hard enough.\"","then":"Her face closes. \"I am trying. You don't know what it's like.\""},{"text":"\"Don't be so hard on yourself. Have it and try again tomorrow.\"","then":"She sighs. \"Okay. Tomorrow.\" The evening ends as before."},{"text":"\"Give me the bottle and I'll throw all of it away today.\"","then":"She stiffens. \"You can't decide that for me.\""}],"why":"Getting curious about the hard moment helps her more than blame or taking over."},{"prompt":"Weeks later Meera says: \"I can't sleep without it, and I feel low all day.\"","options":[{"text":"\"Let's see a doctor together, or call Tele-MANAS 14416.\"","then":"She nods slowly. \"I think I need that. Will you stay with me?\"","best":true},{"text":"\"Try one more week of walks with me before anything else.\"","then":"She agrees. The walks are lovely, and the low feeling stays."},{"text":"\"Just switch to something lighter for now.\"","then":"She tries. A week later she is sleeping no better and feeling flat."},{"text":"\"Sleep will fix itself once the baby sleeps better.\"","then":"She nods. The weeks keep going and she says nothing more."}],"why":"Lasting low mood and needing it to sleep call for a doctor. Shame never helps."}],"relearn":"Warmth plus a gentle healthier offer helps a friend swap an unhealthy habit far more than a blunt warning."},
  {"id":"ly-1307","cat":"healthy-coping","type":"role-play","persona":"Divya","source":"self before snap","hook":"You feel yourself about to snap at your child over something small.","setup":"It has been a long day and your patience is thin.","steps":[{"prompt":"Your toddler tips the dal onto the floor and giggles: \"Oops, Amma!\"","options":[{"text":"\"I'm overwhelmed, not a bad parent. Let me breathe first.\"","then":"You breathe once. Your toddler blinks up at you. \"Amma okay?\"","best":true},{"text":"\"What's wrong with me? I can't even handle a spilt bowl.\"","then":"Your toddler's smile fades. \"Amma sad?\" Your chest tightens."},{"text":"\"Not again! Why can you never be careful with anything?\"","then":"Your toddler's lip trembles and the giggle stops. \"Sorry, Amma.\""},{"text":"\"It's fine. It's fine. Don't cry.\" (through gritted teeth)","then":"Your toddler watches your face and goes very quiet."}],"why":"A kind, true line gives you a second to breathe before you respond."},{"prompt":"Your toddler asks: \"Amma, are you cross?\"","options":[{"text":"\"I felt cross, but it's not your fault. I'll take a breath.\"","then":"Your toddler nods gravely and pats your knee. \"Breath.\"","best":true},{"text":"\"No, I'm fine. Go and play, and don't worry about Amma.\"","then":"Your toddler frowns, unsure. The tightness stays in the room."},{"text":"\"Yes! You never listen to me and you make everything harder!\"","then":"Your toddler's eyes widen and she starts to cry."},{"text":"\"I'm just a bad Amma today, and you deserve a better one.\"","then":"Your toddler climbs into your lap, confused. \"No, Amma.\""}],"why":"Naming your feeling simply, without blaming her, teaches her that feelings can be said out loud."},{"prompt":"Later your partner asks: \"You seem wound up today. What's going on?\"","options":[{"text":"\"I was close to snapping. I need ten minutes tonight.\"","then":"Your partner puts the phone down. \"Take them. I've got her.\"","best":true},{"text":"\"Nothing. I just need to be a better mother.\"","then":"Your partner frowns. \"You're doing plenty.\" The tightness stays."},{"text":"\"Everything is fine. Please don't make it a thing.\"","then":"Your partner nods, unsure, and the evening ends in quiet."},{"text":"\"It's you. You never help with anything in this house.\"","then":"Your partner stiffens. \"That's not fair.\" The evening turns cold."}],"why":"Naming a small, concrete need lets your partner actually help you reset."}],"relearn":"A kind, true line helps you reset far better than harsh self-blame: 'I'm overwhelmed, not bad. Breathe first.'"},
  {"id":"ly-1308","cat":"healthy-coping","type":"role-play","persona":"Divya","source":"name the need","hook":"You've hit your limit after a long day alone with the baby.","setup":"Your partner Rohan finds you standing still in the kitchen.","steps":[{"prompt":"Rohan asks: \"You look worn out. What do you need right now?\"","options":[{"text":"\"Ten minutes to breathe alone. Can you take the baby?\"","then":"He nods at once. \"Go. I've got the baby.\"","best":true},{"text":"\"Nothing. I'm fine. Don't worry about me. You have enough on.\"","then":"He shrugs, unsure. \"Okay. Shout if you need me.\""},{"text":"\"I need you to just know what I need without asking.\"","then":"He looks lost. \"I'm trying. Give me a hint?\""},{"text":"\"A whole day away from all of this, starting right now.\"","then":"He rubs his neck. \"A whole day? I can't get leave tomorrow.\""}],"why":"Naming one small need lets him actually help you."},{"prompt":"A few days later Rohan says: \"I want to help. What would make the evenings easier?\"","options":[{"text":"\"Let's split them. From eight you take the baby and I rest.\"","then":"He smiles. \"Eight it is. I'll set a reminder.\"","best":true},{"text":"\"Just do more around the house. You'll work it out yourself.\"","then":"He hesitates. \"Like what, though?\" You don't have an answer."},{"text":"\"Nothing more. I'll manage evenings like before.\"","then":"He nods slowly. The evenings stay exactly as they were."},{"text":"\"Take every evening. I'll stay out of it completely.\"","then":"He swallows. \"Every night? I'll try, but I start work at seven.\""}],"why":"A concrete split gives him a job and gives you real rest."},{"prompt":"A week later Rohan finds you tearful and asks: \"This isn't just tiredness, is it?\"","options":[{"text":"\"No. It's been heavy for weeks. Can we see a doctor?\"","then":"He takes your hand. \"Thank you for saying it. Let's book it now.\"","best":true},{"text":"\"It's just tiredness. It'll pass when the baby sleeps.\"","then":"He nods, unconvinced. The heaviness is still there next week."},{"text":"\"Don't worry. It's just the chores getting to me.\"","then":"He offers to do the dishes. The heaviness is still there next week."},{"text":"\"I don't want to think about it. Please leave it.\"","then":"He backs off gently, worried. You are still on your own with it."}],"why":"Weeks of heaviness are more than tiredness, so say so and see a doctor."}],"relearn":"Naming a small, concrete need, ten minutes to breathe, lets your partner actually help you reset."},
  {"id":"ly-1309","cat":"healthy-coping","type":"role-play","persona":"Priya","source":"kinder way","hook":"A new-parent friend never rests and seems stretched thin. You want to offer a kinder way.","setup":"She waves off your concern with a tired smile.","steps":[{"prompt":"Sana says: \"I just don't think about it. Thinking makes it worse.\"","options":[{"text":"\"Pushing it down is exhausting. Want to try five minutes' rest?\"","then":"She pauses, then half-smiles. \"Five minutes. I suppose I could.\"","best":true},{"text":"\"That works. Just keep powering through like everyone does.\"","then":"She nods, relieved for a moment. \"Right. Everyone does.\""},{"text":"\"Then think about it more, and you'll get over it faster.\"","then":"She frowns. \"That sounds exhausting too.\""},{"text":"\"Have you tried herbal tea or yoga? It works for me.\"","then":"She smiles politely. \"Maybe.\" Nothing changes."}],"why":"Naming that bottling up is tiring, plus a small offer, makes rest feel possible."},{"prompt":"Later Sana says: \"I can't rest when there's so much to do. It feels wrong.\"","options":[{"text":"\"Rest is how you refill. The list will still be there.\"","then":"She sighs. \"I never thought of it like that. Okay.\"","best":true},{"text":"\"Then rest after everything is done, like the rest of us.\"","then":"She nods. Everything is never done, and she doesn't rest."},{"text":"\"Everyone feels guilty. You'll get used to it eventually.\"","then":"She shrugs. \"I suppose.\" She carries on scrubbing the pan."},{"text":"\"Then rest only when you can't stand up any more.\"","then":"She laughs, but it is not far from true for her."}],"why":"Reframing rest as refilling helps her let go of the guilt."},{"prompt":"Weeks on, Sana says: \"I'm so flat. I've stopped enjoying anything.\"","options":[{"text":"\"That's more than tired. Try a doctor or Tele-MANAS 14416.\"","then":"Her eyes fill. \"Would you come with me to call?\"","best":true},{"text":"\"Take a holiday. A change of scene will fix that for you.\"","then":"She sighs. \"We can't afford one. I suppose that's that.\""},{"text":"\"It's the baby stage. Wait a couple more weeks and see.\"","then":"She nods. Two weeks on, she says even less."},{"text":"\"Try to be grateful. Lots of people would love to have this.\"","then":"She goes quiet. \"You're right. I'm being ungrateful.\""}],"why":"Lasting flatness deserves a doctor or Tele-MANAS, and it isn't ingratitude."}],"relearn":"Gently naming that bottling-up exhausts, and offering a small real rest, beats endorsing 'power through'."},
  {"id":"ly-1310","cat":"healthy-coping","type":"role-play","persona":"any","source":"permission to rest","hook":"You promised yourself you'd rest tonight but feel guilty stopping while chores remain.","setup":"The baby has finally gone down.","steps":[{"prompt":"Your partner asks: \"The dishes are still out. Are you coming to sit?\"","options":[{"text":"\"The chores can wait. Resting now refills me for tomorrow.\"","then":"Your partner clears a space on the sofa. \"Come here. They'll keep.\"","best":true},{"text":"\"I can't rest until everything's done, however late it gets.\"","then":"Your partner sighs. \"It'll be midnight, then. I'll keep you company.\""},{"text":"\"Go ahead without me. I'll just finish the kitchen first.\"","then":"Your partner heads off, and you scrub until the clock says eleven."},{"text":"\"I'll sit for two minutes, then I'm straight back to the dishes.\"","then":"You sit for two minutes and never really relax before getting up again."}],"why":"Letting the chores wait is how you refill, and that counts."},{"prompt":"Your partner asks: \"Can I take the night feed so you sleep through?\"","options":[{"text":"\"Yes please. I'll sleep, and we can swap again soon.\"","then":"Your partner grins. \"Deal. I'll handle the bottle. Go to sleep.\"","best":true},{"text":"\"No, it's my job. I should be the one who's up.\"","then":"Your partner shrugs, worried. You're awake at two, and again at four."},{"text":"\"Only if you promise not to complain about it later.\"","then":"Your partner laughs, puzzled. \"Why would I complain?\""},{"text":"\"Take it tonight. Tomorrow I'll do everything again.\"","then":"Your partner nods slowly. The night helps, but the pattern stays the same."}],"why":"Accepting help with the load is part of looking after yourself."},{"prompt":"Your mother-in-law says: \"In my day nobody sat down before the house was clean.\"","options":[{"text":"\"It was different then. Resting helps me look after the baby.\"","then":"She pauses, then nods slowly. \"Hm. I suppose you look tired.\"","best":true},{"text":"\"You're right. I'll finish everything first from now on.\"","then":"She looks satisfied. You feel your shoulders tighten again."},{"text":"\"Then please don't tell me what to do in my own house.\"","then":"She purses her lips. The rest of the visit is stiff."},{"text":"\"I only rest when nobody is looking, so it's fine.\"","then":"She raises an eyebrow. You feel smaller, and she is no wiser."}],"why":"Explaining why rest helps, warmly, keeps family on your side."}],"relearn":"Giving yourself real permission to rest is a coping skill, not laziness. The chores can wait."},
  {"id":"ly-1311","cat":"healthy-coping","type":"role-play","persona":"Vikram","source":"earn a break","hook":"Your partner Ishan grinds through exhaustion and waves off every suggestion to rest.","setup":"It is nearly midnight and he is still folding laundry.","steps":[{"prompt":"Ishan says: \"I'll rest when everything is done. You go to bed.\"","options":[{"text":"\"You don't have to earn a break. Let's swap so you can rest.\"","then":"He looks at you a long moment. \"Fine. Ten minutes. Just ten.\"","best":true},{"text":"\"Fine. Burn yourself out then. See if I care what happens.\"","then":"He stiffens. \"Wow. Okay.\" The room goes cold."},{"text":"\"Just five more minutes, then you're done. Promise me.\"","then":"He nods, folding another shirt. Five minutes turns into an hour."},{"text":"\"Let me help you get through the whole list faster.\"","then":"You both fold in silence until one. He still hasn't rested."}],"why":"Offering a real swap says his rest matters without a fight."},{"prompt":"The next morning Ishan says over tea: \"I feel like I'm running on empty.\"","options":[{"text":"\"Then let's set aside one rest slot for you each day.\"","then":"He nods slowly. \"That sounds reasonable. Let's try it.\"","best":true},{"text":"\"Have more chai. That will get you going for a while.\"","then":"He sips. \"Maybe.\" He looks no less tired."},{"text":"\"We're all tired. Let's just get through this month.\"","then":"He nods. The month doesn't end when he hoped."},{"text":"\"Take a sick day and sleep for the whole day tomorrow.\"","then":"He laughs. \"I can't take a day off.\" Nothing else is planned."}],"why":"A small daily rest slot is easier to keep than one big break."},{"prompt":"Weeks later Ishan says: \"I'm still low, and it isn't lifting.\"","options":[{"text":"\"Fathers struggle too. Let's book a doctor, and I'll come along.\"","then":"His voice cracks. \"I thought men weren't supposed to say this.\"","best":true},{"text":"\"Give it a few more weeks. Most dads get over it on their own.\"","then":"He nods, but stops mentioning it. The low feeling stays."},{"text":"\"Don't tell anyone. They'll think you can't cope with fatherhood.\"","then":"He agrees, and the secret sits between you both."},{"text":"\"Try a new hobby and see if that helps you feel more like you.\"","then":"He tries one. It's a nice hour, and the low feeling is still there."}],"why":"Fathers struggle too, and a doctor is the right next step when low won't lift."}],"relearn":"'You don't have to earn a break' plus a real swap helps a depleted partner accept rest as coping."},
  {"id":"ly-1312","cat":"healthy-coping","type":"role-play","persona":"Divya","source":"ask for what helps","hook":"A relative keeps pushing draining advice when what you need is a moment to breathe.","setup":"Your aunt arrives with a bag of tips.","steps":[{"prompt":"Your aunt says: \"Never let him sleep alone, boil everything twice, feed hourly!\"","options":[{"text":"\"Thank you. I need ten quiet minutes. Could you hold the baby?\"","then":"She blinks, then holds out her arms. \"Give him to me.\"","best":true},{"text":"\"You're right. I'll keep going. I shouldn't need a rest.\"","then":"She nods, pleased. You feel yourself sag inside."},{"text":"\"Please stop telling me what to do in my own house.\"","then":"She stiffens. \"I only came to help.\" The kitchen turns cold."},{"text":"\"Lovely tips. Write them down and I'll try them all tonight.\"","then":"She writes down eleven tips. You feel more tired."}],"why":"Asking for exactly what helps lets her be useful without draining you."},{"prompt":"Later your aunt says: \"It's nearly five. Shouldn't you be starting dinner?\"","options":[{"text":"\"Could someone else cook tonight? I really need a break.\"","then":"She thinks. \"Your husband makes a decent dal. I'll ask him.\"","best":true},{"text":"\"Yes, of course. I'll cook first and rest tomorrow.\"","then":"She nods, satisfied. Tomorrow's rest slips away too."},{"text":"\"I'll skip dinner myself. There's no time to eat anyway.\"","then":"She tuts. You go to bed hungry and even more drained."},{"text":"\"Fine. I'll do both at once with the baby on my hip.\"","then":"She goes to sit. You cook with an aching back and a tightening chest."}],"why":"Asking for the cooking to be shared protects your break. It needn't all fall on you."},{"prompt":"The next day your aunt says: \"You look tired. Why not sleep when the baby sleeps?\"","options":[{"text":"\"Thanks, Aunty. Could you keep watch so I really can?\"","then":"She smiles. \"Yes. Go and lie down. I'll call you.\"","best":true},{"text":"\"I've chores when the baby sleeps. That's the whole point.\"","then":"She sighs. \"Then the chores are the problem, aren't they?\""},{"text":"\"I don't need rest. I'm fine, honestly.\"","then":"She raises an eyebrow, unconvinced. Nothing changes."},{"text":"\"Everyone says that. It's not helpful advice at all.\"","then":"She goes quiet, hurt. The afternoon drags."}],"why":"Turning her advice into a real offer of help lets it work."},{"prompt":"Weeks later your aunt asks: \"Are you still that tired? Is something wrong?\"","options":[{"text":"\"It's more than tired, Aunty. Come to a doctor with me?\"","then":"She takes your hand. \"Of course, beta. When shall we go?\"","best":true},{"text":"\"No, I'm fine. Please don't worry about me at all, Aunty.\"","then":"She studies you for a moment, then lets it go."},{"text":"\"It's just the baby stage. It will pass soon enough.\"","then":"She nods, though she seems unsure. The weeks go on."},{"text":"\"Don't tell your sister. She'll only worry about me.\"","then":"She agrees, uneasy. She wishes she could do more."}],"why":"When tiredness lingers for weeks, a doctor is the next step, with family beside you."}],"relearn":"Warmly naming what you actually need, a few quiet minutes, lets a relative help you cope instead of draining you."},
  {"id":"ly-1170","cat":"reach-out","type":"strike-rewrite","hook":"\"A real parent handles everything themselves; needing help means you couldn't cope.\"","myth":{"un":"A real parent handles everything themselves; needing help means you couldn't cope.","re":"No one raises a child alone; asking for help is a normal, capable thing parents have always done together.","why":"Humans raise children in a web of hands, never solo."},"relearn":"Needing help doesn't mean you failed to cope; sharing the load is how parenting has always worked.","persona":"Divya","source":"never solo"},
  {"id":"ly-1171","cat":"reach-out","type":"strike-rewrite","hook":"\"If I ask my in-laws for help, they'll think I'm a useless mother and never let it go.\"","myth":{"un":"If I ask my in-laws for help, they'll think I'm a useless mother and never let it go.","re":"Asking family for specific help is a strength; most relatives want to be useful, and a clear ask makes it easier for them.","why":"A concrete request invites support, not judgement."},"relearn":"Asking family for specific help is capable, not useless; a clear ask makes it easier for everyone.","persona":"Divya","source":"ask in-laws"},
  {"id":"ly-1172","cat":"reach-out","type":"strike-rewrite","hook":"\"Men don't talk about this stuff; I should just deal with it on my own.\"","myth":{"un":"Men don't talk about this stuff; I should just deal with it on my own.","re":"Fathers struggle too, and opening up is strength, not weakness; staying silent only makes the load heavier.","why":"Silence isn't strength; reaching out is."},"relearn":"Fathers can and should reach out; opening up is strength, and silence only makes the load heavier.","persona":"Vikram","source":"men talk too"},
  {"id":"ly-1173","cat":"reach-out","type":"strike-rewrite","hook":"\"Reaching out is just dumping my problems on people who have their own lives.\"","myth":{"un":"Reaching out is just dumping my problems on people who have their own lives.","re":"Letting someone help isn't a burden; people who care often feel closer and glad to be trusted with it.","why":"Being trusted to help is a gift, not a weight."},"relearn":"Reaching out isn't burdening people; those who care are usually glad to be trusted and to help.","persona":"any","source":"not a burden"},
  {"id":"ly-1174","cat":"reach-out","type":"strike-rewrite","hook":"\"A counsellor is only for people who are truly broken, not for someone like me.\"","myth":{"un":"A counsellor is only for people who are truly broken, not for someone like me.","re":"Counselling is for ordinary people under strain, not only crises; talking it through early is practical, not shameful.","why":"Support is preventive, not a last resort."},"relearn":"Counselling is for ordinary parents under strain, not only the 'broken'; early support is practical and wise.","persona":"Divya","source":"counsellor is for you"},
  {"id":"ly-1175","cat":"reach-out","type":"strike-rewrite","hook":"\"Once I tell people I'm struggling, they'll always see me as the weak one.\"","myth":{"un":"Once I tell people I'm struggling, they'll always see me as the weak one.","re":"Honesty usually earns respect, not pity; people trust someone who can name a struggle and reach for help.","why":"Naming a struggle reads as courage, not weakness."},"relearn":"Sharing a struggle usually earns respect, not pity; naming it and reaching out reads as courage.","persona":"any","source":"not the weak one"},
  {"id":"ly-1176","cat":"reach-out","type":"strike-rewrite","hook":"\"Other parents seem to manage fine, so it must just be me failing at this.\"","myth":{"un":"Other parents seem to manage fine, so it must just be me failing at this.","re":"Most parents struggle quietly behind a calm face; you're comparing your insides to their outsides, not failing.","why":"Calm faces hide hard days everywhere."},"relearn":"Other parents struggle quietly too; you're comparing your insides to their outsides, not failing alone.","persona":"Divya","source":"not just you"},
  {"id":"ly-1177","cat":"reach-out","type":"strike-rewrite","hook":"\"Helplines are only for emergencies, so calling one for how I feel is overreacting.\"","myth":{"un":"Helplines are only for emergencies, so calling one for how I feel is overreacting.","re":"Tele-MANAS 14416 is there for everyday hard feelings too, not only crises; you needn't be at breaking point to call.","why":"Support lines are for the whole range, not only the worst day."},"relearn":"A helpline like Tele-MANAS 14416 is for everyday hard feelings too; you needn't be at breaking point to call.","persona":"any","source":"not only emergencies"},
  {"id":"ly-1178","cat":"reach-out","type":"strike-rewrite","hook":"\"If I reach out and they can't fix it instantly, there was no point in asking.\"","myth":{"un":"If I reach out and they can't fix it instantly, there was no point in asking.","re":"Being heard already lightens the load, even before anything is solved; support is a process, not an instant fix.","why":"Feeling less alone is itself a real change."},"relearn":"Reaching out helps even when nothing's fixed instantly; being heard lightens the load on its own.","persona":"any","source":"heard helps"},
  {"id":"ly-1179","cat":"reach-out","type":"strike-rewrite","hook":"\"Talking about how hard it is will just make me feel worse and more pathetic.\"","myth":{"un":"Talking about how hard it is will just make me feel worse and more pathetic.","re":"Saying it out loud usually loosens its grip; what's named and shared tends to feel lighter, not heavier.","why":"Spoken worries shrink; bottled ones grow."},"relearn":"Talking about it usually loosens its grip; what's named and shared tends to feel lighter, not worse.","persona":"any","source":"saying it lightens"},
  {"id":"ly-1180","cat":"reach-out","type":"strike-rewrite","hook":"\"I'll reach out later, once things calm down and I'm less of a mess.\"","myth":{"un":"I'll reach out later, once things calm down and I'm less of a mess.","re":"The mess is exactly when support helps most; waiting for calm before asking usually means never asking.","why":"Help is for the hard middle, not the tidy after."},"relearn":"You don't have to wait until you're 'less of a mess'; the hard middle is exactly when reaching out helps most.","persona":"Divya","source":"not waiting for calm"},
  {"id":"ly-1181","cat":"reach-out","type":"sort","hook":"Sort: a real step toward reaching out, or a story that keeps you stuck and silent?","items":[{"id":"a","text":"Texting one friend 'tough week, can we talk?'"},{"id":"b","text":"'I'll burden them, better not'"},{"id":"c","text":"Booking a slot with your doctor"},{"id":"d","text":"'Real parents don't need this'"},{"id":"e","text":"Saving Tele-MANAS 14416 in your phone"},{"id":"f","text":"'I'll sort myself out alone somehow'"}],"bins":[{"id":"step","label":"A step toward help","valence":"pos"},{"id":"stuck","label":"A story that keeps you stuck","valence":"neg"}],"key":{"a":"step","b":"stuck","c":"step","d":"stuck","e":"step","f":"stuck"},"relearn":"Texting a friend, booking a doctor and saving a helpline are real steps; 'I'll burden them' or 'cope alone' keep you stuck.","persona":"any","source":"step vs stuck"},
  {"id":"ly-1182","cat":"reach-out","type":"sort","hook":"Sort: who to lean on for this, or the wrong door for this kind of help?","items":[{"id":"a","text":"A scary thought: a doctor or helpline"},{"id":"b","text":"A school WhatsApp group of strangers"},{"id":"c","text":"Practical load: a trusted relative"},{"id":"d","text":"Someone who always one-ups your pain"},{"id":"e","text":"Lasting low mood: a counsellor or GP"},{"id":"f","text":"A person who'll repeat it to gossip"}],"bins":[{"id":"right","label":"Right door","valence":"pos"},{"id":"wrong","label":"Wrong door","valence":"neg"}],"key":{"a":"right","b":"wrong","c":"right","d":"wrong","e":"right","f":"wrong"},"relearn":"Match the worry to the right door: doctor or helpline for scary or lasting feelings, a trusted relative for the load.","persona":"any","source":"right door"},
  {"id":"ly-1183","cat":"reach-out","type":"sort","hook":"Sort: a strong way to ask for help, or a way that quietly cancels the ask?","items":[{"id":"a","text":"'I need an hour's break on Sunday'"},{"id":"b","text":"'It's fine, only if you're not busy'"},{"id":"c","text":"'Can you take the night feed tonight?'"},{"id":"d","text":"Hinting and hoping they notice"},{"id":"e","text":"'I'm struggling and want to talk'"},{"id":"f","text":"Asking then saying 'forget it, never mind'"}],"bins":[{"id":"strong","label":"A clear ask","valence":"pos"},{"id":"cancels","label":"Cancels itself","valence":"neg"}],"key":{"a":"strong","b":"cancels","c":"strong","d":"cancels","e":"strong","f":"cancels"},"relearn":"A clear, specific ask gets help; hinting, over-apologising or 'never mind' quietly cancel the request.","persona":"any","source":"clear ask"},
  {"id":"ly-1184","cat":"reach-out","type":"sort","hook":"Sort: makes a support net stronger, or a thread that weakens it?","items":[{"id":"a","text":"Two or three people who can step in"},{"id":"b","text":"Relying on one person for everything"},{"id":"c","text":"Letting people return a favour"},{"id":"d","text":"Cutting off everyone when low"},{"id":"e","text":"Naming what you need out loud"},{"id":"f","text":"Pretending you're always fine"}],"bins":[{"id":"stronger","label":"Strengthens the net","valence":"pos"},{"id":"weaker","label":"Weakens the net","valence":"neg"}],"key":{"a":"stronger","b":"weaker","c":"stronger","d":"weaker","e":"stronger","f":"weaker"},"relearn":"A net of a few people, give-and-take and naming needs holds; one-person reliance, withdrawing and 'always fine' fray it.","persona":"any","source":"stronger net"},
  {"id":"ly-1185","cat":"reach-out","type":"sort","hook":"Sort: a fear about reaching out that's worth gently challenging, or a fact that's actually true?","items":[{"id":"a","text":"'They'll judge me as a bad parent'"},{"id":"b","text":"Helplines are free and confidential"},{"id":"c","text":"'I'll be a burden forever'"},{"id":"d","text":"You can ask before you're in crisis"},{"id":"e","text":"'No one could understand this'"},{"id":"f","text":"Many parents feel exactly this way"}],"bins":[{"id":"fear","label":"Fear to challenge","valence":"uhoh"},{"id":"fact","label":"Reassuring fact","valence":"pos"}],"key":{"a":"fear","b":"fact","c":"fear","d":"fact","e":"fear","f":"fact"},"relearn":"'They'll judge me', 'I'll burden them', 'no one understands' are fears; help is free, early and shared by many parents.","persona":"any","source":"fear vs fact"},
  {"id":"ly-1186","cat":"reach-out","type":"sort","hook":"Sort: a sign it's time to widen your circle and reach out, or an ordinary patch most parents have?","items":[{"id":"a","text":"Carrying it alone for weeks now"},{"id":"b","text":"One stressful, busy fortnight"},{"id":"c","text":"Snapping at everyone, then crying"},{"id":"d","text":"A tiring week of broken sleep"},{"id":"e","text":"Feeling you have no one to call"},{"id":"f","text":"A rough day that a chat fixed"}],"bins":[{"id":"reach","label":"Time to reach out","valence":"tell"},{"id":"ordinary","label":"An ordinary patch","valence":"neutral"}],"key":{"a":"reach","b":"ordinary","c":"reach","d":"ordinary","e":"reach","f":"ordinary"},"relearn":"Weeks alone, snapping then crying, or having no one to call say widen your circle; a tiring week is an ordinary patch.","persona":"any","source":"time to widen"},
  {"id":"ly-1187","cat":"reach-out","type":"sort","hook":"Sort: something within your control when reaching out, or something you can let go of?","items":[{"id":"a","text":"Choosing one safe person to start with"},{"id":"b","text":"Whether they have a perfect answer"},{"id":"c","text":"Being honest about how it really is"},{"id":"d","text":"How they secretly feel about you"},{"id":"e","text":"Picking a calm moment to talk"},{"id":"f","text":"Fixing everything in one conversation"}],"bins":[{"id":"yours","label":"In your control","valence":"pos"},{"id":"letgo","label":"You can let go","valence":"neutral"}],"key":{"a":"yours","b":"letgo","c":"yours","d":"letgo","e":"yours","f":"letgo"},"relearn":"You control who you tell, your honesty and your timing; let go of their perfect answer or fixing it all at once.","persona":"any","source":"yours to control"},
  {"id":"ly-1188","cat":"reach-out","type":"branch","persona":"Divya","source":"hit send","hook":"You've drafted a message to a friend saying you're struggling, but your thumb hovers over send.","steps":[{"prompt":"You read it once more, and doubt creeps in. What do you do?","options":[{"text":"Send it as it is, before doubt talks you out of it","then":"The message shows as delivered. Your stomach flips, and you feel lighter.","best":true},{"text":"Save it as a draft, for when you feel ready","then":"You put the phone down. The draft is still there three days later."},{"text":"Soften it to 'a bit tired lately' before you send","then":"The softer message goes out. Your friend replies with a sleepy emoji."},{"text":"Show it to your partner first and see if it's needed","then":"He says maybe wait until the weekend. The weekend comes and goes."}],"why":"Sending it while you have the words is what opens the door."},{"prompt":"One evening your friend Anjali calls and asks how you are really doing. What do you say?","options":[{"text":"Say honestly you've been struggling and need to talk","then":"She goes quiet, then says, \"Tell me everything. I've got time.\"","best":true},{"text":"Say all is good, just busy, and change the subject","then":"She goes along with it. The chance passes quietly."},{"text":"Make a joke about how sleepless the nights are","then":"She laughs. The joke covers what you really feel."},{"text":"Say you'll talk properly later, then let it slip away","then":"Later never comes, and the call ends there."}],"why":"An honest answer to an open question invites real support."},{"prompt":"A week later Anjali rings again. She says she can tell it's hard and wants to help. What do you say?","options":[{"text":"Ask for something small and clear, like a weekly call","then":"She says instantly, \"Every Sunday, then. I'll put it in my phone.\"","best":true},{"text":"Say there is nothing anyone can really do about it","then":"She goes quiet. \"Okay. But I'm here if you change your mind.\""},{"text":"Say \"don't worry about me\" and ask about her week","then":"She talks for twenty minutes. You hang up having said nothing."},{"text":"Ask her to take over everything and check in every single day","then":"She sounds anxious. \"I can try, but every day feels like a lot.\""}],"why":"A small, clear ask is easy to say yes to, and it lasts."}],"debrief":"When you've found the words, send them; a 'for later' draft just keeps you alone with it.","relearn":"Send the honest message now; waiting for the 'right time' often means never reaching out."},
  {"id":"ly-1189","cat":"reach-out","type":"branch","persona":"Divya","source":"accept the offer","hook":"You're worn out, but accepting help feels like admitting you can't manage.","steps":[{"prompt":"Your mother says she'll take the baby on Saturday afternoon. What do you say?","options":[{"text":"Thank her and say yes, and plan to rest while she has him","then":"Her face lights up. \"I'll bring his blanket. You just sleep.\"","best":true},{"text":"Say you can manage on your own, thanks","then":"She nods, a little hurt. \"Okay. But the offer stands.\""},{"text":"Say yes, then spend the afternoon cleaning and cooking","then":"She takes the baby happily. You finish the kitchen and feel as tired as before."},{"text":"Say maybe next time, when things calm down","then":"She smiles and lets it go. Things don't calm down."}],"why":"Saying yes and actually resting refuels you, and she feels useful too."},{"prompt":"The next weekend she offers again and says you look tired. What do you do?","options":[{"text":"Say yes and tell her what would help most","then":"She writes it down. \"Nap first. Then I'll make dal for tomorrow.\"","best":true},{"text":"Say you aren't that tired","then":"She raises an eyebrow but says nothing. You feel worn through."},{"text":"Say yes but leave a long list of rules and call every hour","then":"She sighs quietly. Your phone rings in your hand all afternoon."},{"text":"Say yes, but stay in the next room the whole time","then":"She sighs quietly at the doorway. You hear every cry and rest very little."}],"why":"Accepting again and naming what helps makes it work for both of you."},{"prompt":"Your mother-in-law says: \"A mother should never hand over her baby.\" What do you say?","options":[{"text":"Thank her, and say a rested mother is better for the baby","then":"She pauses, then says softly, \"Hm. Maybe I did tire out at your age.\"","best":true},{"text":"Agree with her and cancel your mother's next visit for good","then":"Your mother-in-law nods, satisfied. You feel your shoulders tighten again."},{"text":"Decide she's right and feel guilty about taking any help","then":"She nods, and the guilt sits with you through every rest you take."},{"text":"Say she's old-fashioned and walk out of the room upset","then":"She goes red. The house is tense for the rest of the day."}],"why":"Answering warmly and standing by help keeps peace and keeps your rest."}],"debrief":"Accepting help isn't failing; it refuels you and lets the person who offered feel useful.","relearn":"Say yes to genuine offers of help; accepting it is capable parenting, not defeat."},
  {"id":"ly-1190","cat":"reach-out","type":"branch","persona":"Divya","source":"hold your plan","hook":"A relative says counselling is 'for mad people', and your courage to seek it shrinks.","steps":[{"prompt":"That night you still have a counsellor's number open on your phone. What do you do?","options":[{"text":"Keep your plan and quietly book a first session","then":"You book Thursday at four. Your hands shake, but your shoulders drop.","best":true},{"text":"Delete the number to avoid a fight at home","then":"The screen clears. The house is calm, and you are still on your own."},{"text":"Wait until Aunty approves, however long that takes","then":"You picture waiting for her approval. The weeks stretch out in front of you."},{"text":"Argue with her tomorrow until she admits she's wrong","then":"You rehearse it half the night. It leaves you tired and no closer to a session."}],"why":"Someone else's stigma doesn't decide your care, so protect your plan."},{"prompt":"Your partner asks why you've been on the phone so much. What do you say?","options":[{"text":"Say you want counselling, and ask him to keep it private","then":"He looks surprised, then nods. \"Okay. I'll keep it between us.\"","best":true},{"text":"Say it's nothing important, just a chat with a friend","then":"He shrugs and lets it go. You keep the secret alone."},{"text":"Tell the whole family at dinner so nobody hears it secondhand","then":"The table goes quiet, then noisy. Aunty says her piece loudly."},{"text":"Say you'd like to go, but only if he agrees first","then":"He hesitates. \"Let me think about it.\" You wait on his answer."}],"why":"Sharing it privately with your partner gives you support at home."},{"prompt":"At a family function Aunty asks whether you are still being silly about counselling. What do you say?","options":[{"text":"Say calmly that your health is yours to look after","then":"She raises an eyebrow but lets it drop. You say no more than you want to.","best":true},{"text":"Agree you were being silly, and let the whole plan go","then":"She smiles, satisfied. You feel small for the rest of the evening."},{"text":"Say she knows nothing about modern life","then":"Her face hardens. The relatives take sides for the rest of the function."},{"text":"Say you're unsure counselling is for people like you","then":"She looks pleased. Her words loop in your head and your plan feels foolish."}],"why":"A calm line protects your care, without a fight or saying more than you want."},{"prompt":"Weeks later another remark from Aunty makes you doubt yourself again. What do you do?","options":[{"text":"Tell someone on your side that you still want help","then":"Your friend listens and reminds you why you wanted help. The doubt loosens.","best":true},{"text":"Put counselling off until things calm down at home","then":"The house stays calm. The heaviness does not."},{"text":"Stop mentioning it to anyone, so nobody can comment","then":"There are fewer remarks and less support, and you carry more alone."},{"text":"Try to win Aunty over before you do anything more","then":"She refuses loudly, and the argument spills into the evening."}],"why":"When doubt returns, lean on someone on your side and keep going."}],"debrief":"Someone else's stigma doesn't decide your care; keep your plan to get the support you need.","relearn":"Don't let a relative's stigma talk you out of help; counselling is for ordinary people under strain."},
  {"id":"ly-1191","cat":"reach-out","type":"branch","persona":"any","source":"midnight text","hook":"A friend texts at midnight that they 'can't do this anymore'.","steps":[{"prompt":"Their message is still on your screen and you're unsure what to type. What do you send?","options":[{"text":"Say you're here and ask how they are right now","then":"They reply after a minute. \"Thank you. I didn't know who else to tell.\"","best":true},{"text":"Tell them to sleep and talk tomorrow, then put the phone down","then":"You lie awake, wondering about them. No reply comes yet."},{"text":"Send a long list of reasons life is worth living","then":"They read it and reply with a single word. \"Thanks.\""},{"text":"Say everyone feels like this at times and it will pass","then":"They send back a thumbs up and go quiet."}],"why":"Staying with them warmly tells them they aren't alone."},{"prompt":"A little later they write that they're exhausted and scared of tomorrow. What do you do?","options":[{"text":"Share Tele-MANAS 14416 and offer to stay while they call","then":"They write back: \"Okay. Stay with me while I call?\"","best":true},{"text":"Give them the number, then say you need to sleep","then":"They thank you flatly. The chat ends and they are alone again."},{"text":"Ring their family straight away without telling them","then":"Their family turns up, and your friend feels taken over rather than heard."},{"text":"Suggest calming videos and a warm drink","then":"They reply, \"Maybe.\" They are still where they were."}],"why":"A helpline number plus your presence gives a real route to help."},{"prompt":"The next morning you haven't heard from them. What do you do?","options":[{"text":"Check in gently and ask how they are today","then":"They reply within the hour. \"I slept a little. Thank you for asking.\"","best":true},{"text":"Wait for them to reach out first","then":"The morning passes quietly. They don't message, and neither do you."},{"text":"Send a cheerful meme as if nothing happened","then":"They send a laughing face. Nothing about last night is mentioned."},{"text":"Tell the whole friend group so they can all reach out","then":"Five messages arrive at once. They go silent, feeling exposed."}],"why":"A gentle check-in shows the concern was real and still is."},{"prompt":"Days later they message that they're frightened they can't keep themselves safe tonight. What do you do?","options":[{"text":"Call 112 now and stay with them until help arrives","then":"A calm voice on 112 takes their address. You keep messaging until help reaches them.","best":true},{"text":"Tell them to hold on and message you in the morning","then":"They reply 'okay'. The night stretches out, with no one nearby."},{"text":"Suggest a walk and a hot drink first, and see how it feels","then":"They write that nothing has lifted. They are still on their own with it."},{"text":"Ask them to sleep on it and call a doctor tomorrow","then":"They send back one word. The night is long and they are alone with it."}],"why":"When someone can't keep safe tonight, call 112 and stay with them until help comes."}],"debrief":"When a friend signals real distress, stay warmly, remind them struggling isn't their fault, and share a route to help.","relearn":"Meet a friend's 'I can't anymore' with warmth, presence and a helpline: Tele-MANAS 14416, crisis 112."},
  {"id":"ly-1192","cat":"reach-out","type":"branch","persona":"Divya","source":"don't back down","hook":"You tell your partner you've been struggling, and he says 'We'll be fine. Don't make a big deal.'","steps":[{"prompt":"He has already turned back to the TV. What do you do?","options":[{"text":"Repeat calmly that you're not fine and need this heard","then":"He mutes the TV. \"Okay. What do you mean by struggling?\"","best":true},{"text":"Back down and tell him to ignore what you just said","then":"He nods and turns the sound up. The need slips out of view."},{"text":"Say nothing and leave the room to cry alone","then":"He hears the door click, and thinks it's tiredness."},{"text":"Say it again louder, saying he never listens to you","then":"He snaps back. \"See? This is why I said don't make a big deal.\""}],"why":"Restating it clearly keeps your need on the table."},{"prompt":"The next morning his mother visits and says all new mothers get emotional and should get on with it. What do you do?","options":[{"text":"Say calmly it's more than emotions and needs a doctor","then":"She looks unsure, then nods. \"Well. Do take care.\"","best":true},{"text":"Agree it's just emotions and carry on with all the chores","then":"She looks pleased. You feel your chest tighten again."},{"text":"Ask her to tell your partner off for not listening to you","then":"She bristles. \"I won't take sides.\" Now she's irritated with you too."},{"text":"Change the subject and offer her more tea and biscuits","then":"She lets it go. The morning goes on and nothing has been said."}],"why":"Naming it calmly, even to family, protects your need for care."},{"prompt":"A week later you're still struggling, and your partner hasn't raised it again. What do you do?","options":[{"text":"Book a doctor's visit and ask him to come with you","then":"He hesitates, then nods. \"Okay. I'll take the morning off.\"","best":true},{"text":"Wait for him to bring it up first","then":"Another week goes by. He doesn't, and you feel more alone."},{"text":"Tell yourself he's right and try harder","then":"You push through the week. By Friday you feel much emptier."},{"text":"Stop saying anything, since he'll only dismiss it again","then":"The house is quiet. You are on your own with it."}],"why":"A doctor takes your struggle seriously, and he can support you too."}],"debrief":"If your reaching-out gets waved away, stay clear that you're not fine and need it taken seriously.","relearn":"If someone minimises your struggle, restate it clearly; don't let 'we'll be fine' bury a need."},
  {"id":"ly-1193","cat":"reach-out","type":"branch","persona":"any","source":"smallest step","hook":"You want support but every option feels like too much, and you don't know where to begin.","steps":[{"prompt":"You have a spare minute and a head full of ideas. What do you do?","options":[{"text":"Pick the smallest step, such as saving one number","then":"You save Tele-MANAS 14416. It takes ten seconds, and something eases.","best":true},{"text":"Sort all the options and work out the perfect plan first","then":"You make a list of twelve things, then close the phone, tired."},{"text":"Wait until you can face it all at once","then":"The minute passes. The list is still there and still too big."},{"text":"Ask everyone you know what you should do","then":"Six people reply with six different plans, and you feel even more stuck."}],"why":"One tiny step starts things moving, while a perfect plan stalls."},{"prompt":"The next day a friend asks how you're doing. What do you do?","options":[{"text":"Say it's been heavy, and ask for one small thing","then":"She says, \"Of course. Shall I call you tonight?\"","best":true},{"text":"Say you're fine and ask about her week","then":"She talks happily. The call ends with nothing changed."},{"text":"Give a long, tangled account of everything at once","then":"She tries to follow, then says, \"That sounds huge. I don't know where to start either.\""},{"text":"Say you'd love help but can't say with what","then":"She says to tell her whenever. The offer hangs in the air."}],"why":"One small, clear ask is easy for a friend to say yes to."},{"prompt":"A few weeks on, the heaviness is still there. What do you do?","options":[{"text":"Take one more step: call Tele-MANAS 14416 or a doctor","then":"The listener is calm and clear. You leave the call with one next step.","best":true},{"text":"Decide small steps are pointless and stop trying","then":"The list stays untouched, and the heaviness settles in a little more."},{"text":"Keep repeating the same small thing and hope it's enough","then":"You carry on. The heaviness doesn't shift, and you don't ask anyone."},{"text":"Wait until you can sort everything out in one go","then":"Another week goes by. The list only gets longer."}],"why":"Small steps add up, and a doctor or helpline is a natural next one."}],"debrief":"You don't have to fix everything; pick the smallest step, like one text or one saved number.","relearn":"Start with the smallest step, not the whole plan; one text or call is enough to begin."},
  {"id":"ly-1194","cat":"reach-out","type":"branch","persona":"Priya","source":"gentle check-in","hook":"A new-parent friend has gone quiet for two weeks, and you wonder if you're overstepping.","steps":[{"prompt":"Your last message to Jaya is still unanswered. What do you do?","options":[{"text":"Send a gentle note: thinking of you, no need to reply","then":"A tick appears on your message. You feel better for having said it.","best":true},{"text":"Assume she just wants her space and say nothing at all","then":"The days pass. Your silence sits beside hers."},{"text":"Ask mutual friends what Jaya has been up to lately","then":"Word gets back to Jaya. She feels watched and stops answering."},{"text":"Send a long message asking why she is ignoring you","then":"Jaya reads it and feels pressured. She still doesn't reply."}],"why":"A no-pressure note tells her someone noticed, without asking for anything."},{"prompt":"A few days later you meet Jaya at the chemist and she says: \"All fine, just busy!\" What do you do?","options":[{"text":"Say you've missed her and suggest a walk sometime","then":"She hesitates, then smiles. \"A walk. Maybe Thursday.\"","best":true},{"text":"Take her word and chat about the weather instead","then":"She relaxes. You both part with things unsaid."},{"text":"Tell her she looks awful and must be depressed","then":"Her face closes. \"I'm fine, really.\" She hurries off."},{"text":"Say \"good to hear\" and rush off, since you're late","then":"She gives a bright wave. The chance goes by."}],"why":"A warm, specific invitation makes it easy for her to say yes."},{"prompt":"A week later Jaya calls, her voice shaking, and says she doesn't know who to tell. What do you do?","options":[{"text":"Listen, tell her she isn't alone, and offer to find a doctor","then":"She lets out a long breath. \"Thank you. Would you come with me?\"","best":true},{"text":"Tell her exactly what she should do about it, step by step","then":"She goes quiet, overwhelmed, and feels less heard."},{"text":"Say she has so much to be thankful for, with a healthy baby","then":"She goes quiet. \"You're right. I'm sorry.\""},{"text":"Say you'll ask her husband to sort it all out for her","then":"Her voice tightens. \"Please don't. I haven't told him.\""}],"why":"Listening first and offering to help find care shows you're on her side."}],"debrief":"A gentle 'thinking of you, no pressure' check-in can reach a quiet parent who feels invisible.","relearn":"When a parent goes quiet, a gentle no-pressure check-in is reaching out for them, not overstepping."},
  {"id":"ly-1195","cat":"reach-out","type":"branch","persona":"any","source":"free routes","hook":"Money is tight and you assume any real support must be expensive and out of reach.","steps":[{"prompt":"You've felt low for weeks and wonder who could help. What do you do?","options":[{"text":"Try free routes first: Tele-MANAS 14416, a government doctor","then":"You save the number. A free call, and a clinic nearby, feel possible.","best":true},{"text":"Save up for a private clinic before doing anything","then":"The savings crawl up. The weeks slip by and the low feeling stays."},{"text":"Give up, since real help is only for people who can pay","then":"You put the phone away. The low feeling stays exactly as it was."},{"text":"Ask a relative for money without saying what it's for","then":"Your uncle says he'll think about it. You don't feel able to explain."}],"why":"Free routes exist and are real, so cost need not block help."},{"prompt":"At dinner your mother-in-law says talking to strangers about family troubles never helps. What do you do?","options":[{"text":"Say calmly that free, confidential help is real and works","then":"She is quiet, then shrugs. \"Well. Just be careful.\"","best":true},{"text":"Drop any idea of getting help, to keep the peace at home","then":"She smiles, satisfied. The low feeling stays with you."},{"text":"Wait until she goes away to visit family before doing anything","then":"Her trip is months off. The weeks go by and nothing changes."},{"text":"Argue that she's wrong until she finally admits it","then":"The argument runs on. She won't give in, and neither will you."}],"why":"Calmly standing by free help keeps that route open, whoever doubts it."},{"prompt":"Weeks on, still low, you hear the government hospital has a free slot on Tuesday. It clashes with your errands. What do you do?","options":[{"text":"Take the slot and ask someone to cover the errands","then":"Your sister agrees to cover them. You feel light as you go.","best":true},{"text":"Skip it; the errands come first","then":"The errands get done. The appointment is gone."},{"text":"Wait for a slot that fits everything perfectly","then":"No slot ever fits everything. The weeks go by."},{"text":"Decide a private clinic is the only serious option","then":"You look at the fees and stop. The government slot lapses."}],"why":"Free care is real care, so take the slot and make room for it."}],"debrief":"Cost needn't block support: Tele-MANAS 14416 and public doctors are real, free routes.","relearn":"Support isn't only for those who can pay; Tele-MANAS 14416 and government doctors are free and real."},
  {"id":"ly-1196","cat":"reach-out","type":"match","hook":"Match each thing holding you back from reaching out to the gentle reframe.","pairs":[{"left":"'I should handle this myself'","right":"No one parents entirely alone"},{"left":"'It's not serious enough'","right":"You needn't be in crisis to ask"},{"left":"'They'll think less of me'","right":"Naming a struggle earns respect"},{"left":"'I don't want to burden them'","right":"People who care are glad to help"},{"left":"'Nothing will change'","right":"Being heard already lightens it"}],"relearn":"Each block has a reframe: you're not meant to cope alone, early help is valid, and being heard helps.","persona":"any","source":"block to reframe"},
  {"id":"ly-1197","cat":"reach-out","type":"match","hook":"Match each part of a parent's support net to the kind of help it gives.","pairs":[{"left":"A close friend or sibling","right":"A listening ear on an ordinary hard day"},{"left":"A neighbour or cousin nearby","right":"Quick practical hands in a pinch"},{"left":"Your doctor or counsellor","right":"Assessment and proper treatment"},{"left":"Tele-MANAS 14416","right":"A trained voice any hour, any day"},{"left":"Emergency 112","right":"Immediate help when anyone's in danger"}],"relearn":"A full net has listening friends, practical neighbours, professionals, a 24-hour helpline and an emergency line.","persona":"any","source":"net's parts"},
  {"id":"ly-1198","cat":"reach-out","type":"match","hook":"Match each first move to the next door it opens.","pairs":[{"left":"Telling one trusted person","right":"You stop carrying it in secret"},{"left":"Booking a doctor's appointment","right":"A proper look at what's going on"},{"left":"Saving the helpline number","right":"Help is one tap away on a bad day"},{"left":"Joining a new-parent group","right":"People who truly get it"},{"left":"Asking a relative for a break","right":"Real rest to refuel"}],"relearn":"Each first move opens a door: secrecy ends, you get assessed, help is ready, you find peers and you actually rest.","persona":"any","source":"move opens door"},
  {"id":"ly-1199","cat":"reach-out","type":"match","hook":"Match each way of asking to how it usually lands.","pairs":[{"left":"'Could you take Sunday morning?'","right":"Clear, easy to say yes to"},{"left":"'Only if it's really no trouble…'","right":"Easy to wave away, often unmet"},{"left":"'I'm not okay and want to talk'","right":"Honest, opens a real conversation"},{"left":"Hinting and hoping they notice","right":"Often missed, leaves you resentful"},{"left":"'Forget it, I'll manage'","right":"Cancels the help you actually need"}],"relearn":"Clear, honest asks land and get met; over-apologising, hinting and self-cancelling usually leave you unsupported.","persona":"any","source":"how asks land"},
  {"id":"ly-1200","cat":"reach-out","type":"match","hook":"Match each India support route to when it fits best.","pairs":[{"left":"A heavy week, want to talk it out","right":"Tele-MANAS 14416, any time"},{"left":"Structured ongoing support","right":"A counsellor for regular sessions"},{"left":"Lasting low mood after birth","right":"Your doctor for assessment"},{"left":"Immediate danger to anyone","right":"Emergency 112, straight away"},{"left":"Daily load feels too much","right":"A trusted person to share it with"}],"relearn":"Tele-MANAS for talking, a counsellor for structured help, a doctor for assessment, 112 for danger, trusted people for the daily load.","persona":"any","source":"route fits when"},
  {"id":"ly-1201","cat":"reach-out","type":"match","hook":"Match each silent thought to a braver thing you could say out loud.","pairs":[{"left":"'I have to seem like I'm coping'","right":"'Honestly, I'm finding this hard'"},{"left":"'I'll just manage somehow'","right":"'Could you help me with this bit?'"},{"left":"'They don't need my problems'","right":"'Can I talk something through?'"},{"left":"'I'm probably overreacting'","right":"'This is weighing on me, can we chat?'"},{"left":"'I'll be fine eventually'","right":"'I need some real support now'"}],"relearn":"Each silent 'I'll cope' has a braver line that lets someone in and turns reaching out into words.","persona":"any","source":"thought to words"},
  {"id":"ly-1202","cat":"reach-out","type":"match","hook":"Match each parent's situation to a fitting first person to reach out to.","pairs":[{"left":"Scary thoughts that frighten you","right":"A doctor or Tele-MANAS 14416 now"},{"left":"Drowning in chores and feeds","right":"A relative who can lend hands"},{"left":"Lonely with no adult to talk to","right":"An old friend or a parent group"},{"left":"Unsure if it's 'normal'","right":"Your GP for a calm, honest check"},{"left":"A partner who seems low too","right":"Each other, gently and openly"}],"relearn":"Different struggles fit different first contacts: a doctor or helpline, a relative, a friend, your GP, your partner.","persona":"any","source":"situation to person"},
  {"id":"ly-1203","cat":"reach-out","type":"match","hook":"Match each myth about asking for help to the truth that replaces it.","pairs":[{"left":"Asking for help is weakness","right":"It's a skill the strongest parents use"},{"left":"You must be in crisis to call","right":"Early help is easier and works better"},{"left":"Real help doesn't exist","right":"Doctors, counsellors and helplines do"},{"left":"Only mothers need this","right":"Fathers struggle and reach out too"},{"left":"Reaching out burdens people","right":"Those who care are glad to be there"}],"relearn":"The myths about help fall to truths: it's a strength, early help works, real routes exist, and dads need it too.","persona":"any","source":"myth to truth"},
  {"id":"ly-1204","cat":"reach-out","type":"reflect","hook":"Lensy: think of one person who'd want to know you're struggling. There's almost always at least one. True for you?","prompt":"What comes up?","options":["There is someone","I can name one","Not sure yet"],"affirm":"Most of us have at least one person who'd genuinely want to know; naming them is the first thread of your net.","relearn":"There's usually at least one person who'd want to know you're struggling; naming them starts your support net.","persona":"any","source":"name one person"},
  {"id":"ly-1205","cat":"reach-out","type":"reflect","hook":"Lensy: imagine a friend told you they were struggling. You'd want them to reach out, right? The same kindness is yours.","prompt":"What's your take?","options":["Same kindness for me","I'd want them to","Worth remembering"],"affirm":"You'd never call a struggling friend weak for reaching out; that same compassion is allowed to point at you.","relearn":"The kindness you'd give a struggling friend who reaches out is yours to claim too.","persona":"any","source":"same kindness"},
  {"id":"ly-1206","cat":"reach-out","type":"reflect","hook":"Lensy: reaching out isn't a sign you're failing; it's a sign you're taking your own care seriously. Sit right?","prompt":"What do you think?","options":["Sits right","Taking care seriously","I can hold that"],"affirm":"Asking for help is something capable, caring people do; it shows you're taking your wellbeing seriously, not failing.","relearn":"Reaching out shows you're taking your care seriously; it's a capable move, not a failure.","persona":"any","source":"taking care seriously"},
  {"id":"ly-1207","cat":"reach-out","type":"reflect","hook":"Lensy: you don't need to have the perfect words to reach out. 'I'm not okay' is more than enough to start. Okay?","prompt":"What's your take?","options":["That's enough","I can say that","Good to know"],"affirm":"You don't need polished words; a simple 'I'm not okay, can we talk?' is a complete, brave way to start.","relearn":"You needn't have the perfect words; 'I'm not okay' is enough to begin reaching out.","persona":"any","source":"words enough"},
  {"id":"ly-1208","cat":"reach-out","type":"reflect","hook":"Lensy: every strong parent you admire leans on someone you can't see. No one does this truly alone. Resonate?","prompt":"What comes up?","options":["Resonates","No one's truly alone","Hadn't thought of it"],"affirm":"The parents who seem to manage are leaning on people you can't see; needing a net is the rule, not the exception.","relearn":"Even the parents who seem to manage lean on a hidden net; needing support is the rule, not the exception.","persona":"any","source":"hidden net"},
  {"id":"ly-1209","cat":"reach-out","type":"reflect","hook":"Lensy: reaching out today doesn't commit you to anything big. It's just letting one person in. Feel okay to try?","prompt":"What do you think?","options":["Feels okay","Just one person","I could try"],"affirm":"Reaching out can be tiny and low-stakes; letting one person in today commits you to nothing more than that.","relearn":"Reaching out can start small and commit you to nothing big; today it's just letting one person in.","persona":"any","source":"low stakes"},
  {"id":"ly-1210","cat":"reach-out","type":"reflect","hook":"Lensy: the part of you that wants to reach out is the wise part. It's worth listening to. Hear that?","prompt":"What's your take?","options":["I hear it","That's the wise part","I'll listen"],"affirm":"The quiet nudge to reach out is your wiser self looking after you; it's worth trusting over the voice that says 'don't'.","relearn":"The part of you that wants to reach out is your wiser self; it's worth trusting over the 'cope alone' voice.","persona":"any","source":"wise part"},
  {"id":"ly-1211","cat":"reach-out","type":"reflect","hook":"Lensy: building a support net now isn't weakness; it's you setting your family up to be steadier. Worth doing?","prompt":"What comes up?","options":["Worth doing","Steadier family","I'll start"],"affirm":"Quietly building a net of people and numbers now is foresight, not weakness; it steadies your whole family.","relearn":"Building a support net now is foresight that steadies your family, not a sign of weakness.","persona":"any","source":"set up steadier"},
  {"id":"ly-1212","cat":"reach-out","type":"role-play","persona":"Divya","source":"go-to person","hook":"You want to ask a close friend to be your go-to person on hard days, but it feels awkward to make it official.","setup":"You are walking with Isha to the market.","steps":[{"prompt":"Isha says: \"You've seemed quiet lately. Everything okay?\"","options":[{"text":"\"Can I lean on you through this? I'd love a go-to person.\"","then":"Her face softens. \"Yes. I'd love that. Tell me what you need.\"","best":true},{"text":"\"Don't worry about me. I'll only call for a real emergency.\"","then":"She looks a little sad. \"Okay. But you don't need an emergency.\""},{"text":"\"Oh, just tired. Tell me about your week instead.\"","then":"She chats for a while. The moment to ask has passed."},{"text":"\"I'm okay. It's silly, and you have enough on your plate.\"","then":"She shakes her head. \"It isn't silly, but okay.\" She lets it lie."}],"why":"Asking plainly for a go-to person makes support real."},{"prompt":"On Sunday evening Isha writes: \"Thinking of you. How's this week been?\"","options":[{"text":"\"Hard. Could you call me at lunch for ten minutes?\"","then":"She replies at once. \"Every weekday at one, then.\"","best":true},{"text":"\"All fine here. Ignore me. I'm just being sensitive.\"","then":"She sends a heart. Nothing else is said."},{"text":"\"Busy but fine. Tell me about yours instead.\"","then":"She tells you about hers. You listen, and hold your own back."},{"text":"\"Hard, but I don't want to bore you with it.\"","then":"She writes: \"You couldn't.\" You still don't say more."}],"why":"A small, specific ask is easy for her to say yes to."},{"prompt":"Later Isha says: \"I hope you know I don't mind being asked.\"","options":[{"text":"\"Thank you. I'll ring you on the hard nights too.\"","then":"She smiles. \"Anytime. I'll keep my phone on.\"","best":true},{"text":"\"I know, but I hate feeling like a burden to you.\"","then":"She squeezes your arm. \"You aren't one, but I hear you.\""},{"text":"\"I'll only ask you if it's something really serious.\"","then":"She nods. \"Okay.\" She looks unsure. You hold back again."},{"text":"\"I don't want anyone else to know that I asked.\"","then":"She nods. \"Okay. But it's nothing to be ashamed of.\""}],"why":"Using the offer on hard days keeps the support real."},{"prompt":"Weeks on, Isha says: \"You've sounded low for a while. Should we ask a doctor?\"","options":[{"text":"\"Yes. Will you come with me, and help me book it?\"","then":"She takes a breath. \"Yes. Let's book it tonight.\"","best":true},{"text":"\"You're enough for me. I don't need anyone else.\"","then":"She smiles, unsure. \"I'm always here. But a doctor can help in ways I can't.\""},{"text":"\"Not yet. I'll wait until I'm sure it's serious.\"","then":"She nods and lets it lie. Another month passes."},{"text":"\"A doctor is a bit much. Let's just keep talking.\"","then":"She agrees, though she looks worried."}],"why":"A friend is a great support, and a doctor adds care she can't give."}],"relearn":"Naming someone as your go-to person makes support real; people are usually glad and honoured to be asked."},
  {"id":"ly-1213","cat":"reach-out","type":"role-play","persona":"Vikram","source":"open door for him","hook":"Your friend Nikhil, a new father, hints he's struggling. You want to open the door for him.","setup":"You are on the balcony over evening chai.","steps":[{"prompt":"Nikhil laughs and says: \"Just tired, yaar. Nothing a holiday wouldn't fix.\"","options":[{"text":"\"For what it's worth, this stuff hit me hard too. I'm here.\"","then":"His laugh fades. \"Really? You never said.\"","best":true},{"text":"\"Yeah, the tiredness is brutal. You'll get used to it.\"","then":"He nods, half smiling. \"Yeah. I suppose so.\""},{"text":"\"Then you need a holiday. Take a week off, bro.\"","then":"He shrugs. \"Can't. Work won't allow it.\" The chat moves on."},{"text":"\"Hang in there. We all just get on with it.\"","then":"He nods stiffly, and the moment closes over."}],"why":"Sharing that you struggled too gives him permission to drop the act."},{"prompt":"A few days later Nikhil says quietly: \"I sometimes feel nothing about the baby. Is that awful?\"","options":[{"text":"\"It's not awful. Dads get this too, and it's treatable.\"","then":"He looks up, startled. \"Treatable? I thought I was the only one.\"","best":true},{"text":"\"You'll feel it soon. Give it a few more months yet.\"","then":"He nods and looks away. \"I hope so.\""},{"text":"\"Don't say that. You're a good father to that baby.\"","then":"He goes still. \"Okay.\" He changes the subject to cricket."},{"text":"\"Have you told your wife? She'll be really hurt if not.\"","then":"His face drops. \"That's why I haven't.\""}],"why":"Saying it isn't awful, and that dads get this too, takes the shame out."},{"prompt":"A week later Nikhil says quietly: \"I don't want my wife or family to know I'm struggling.\"","options":[{"text":"\"Then start with a private doctor. I'll come along.\"","then":"He lets out a long breath. \"Okay. Just once, to see.\"","best":true},{"text":"\"Okay. Keep it to yourself then. It'll pass.\"","then":"He nods. The weeks pass and he says nothing more."},{"text":"\"You have to tell her tonight. She has a right to know.\"","then":"He flinches. \"Not tonight. I can't.\" He stops talking."},{"text":"\"Try a walk and a journal each day. You'll see.\"","then":"He nods, but doesn't look convinced. He thanks you and leaves."}],"why":"A private first step, like a doctor, respects his fear and gets him help."}],"relearn":"Sharing that you struggled too gives another father permission to drop the 'just tired' act and open up."},
  {"id":"ly-1214","cat":"reach-out","type":"role-play","persona":"Divya","source":"first call","hook":"You're calling Tele-MANAS 14416 for the first time and your voice catches.","setup":"The line clicks, and a warm voice answers.","steps":[{"prompt":"The listener says warmly: \"I'm here. Take a moment. What brings you to call today?\"","options":[{"text":"\"I'm a parent and I've been really low for weeks.\"","then":"\"Thank you for saying that. That takes courage. I'm listening.\"","best":true},{"text":"\"Sorry, I don't know why I'm calling. It's probably nothing.\"","then":"\"You called, so something matters. Take your time.\""},{"text":"\"I think I'm just tired. Maybe I shouldn't have called.\"","then":"\"I'm glad you did. Tired can carry a lot. Tell me more.\""},{"text":"\"I'm calling about a friend. She isn't sleeping or eating.\"","then":"\"It's kind that you worry for her. I'd like to hear about you too.\""}],"why":"An honest start, even a shaky one, is all the listener needs."},{"prompt":"The listener says: \"There's no wrong way to say it. How have the last few weeks been for you?\"","options":[{"text":"\"I feel flat and teary. I've stopped enjoying things.\"","then":"\"That does sound heavy. Thank you for putting it into words.\"","best":true},{"text":"\"I don't want to burden you with all of it.\"","then":"\"You're not a burden. This is exactly what I'm here for.\""},{"text":"\"It's mostly just tiredness. It isn't serious, really.\"","then":"\"Tiredness can be real and heavy. It still deserves care.\""},{"text":"\"Can you tell me if I'm a bad mother?\"","then":"\"Struggling doesn't make you a bad parent. It means you're carrying a lot.\""}],"why":"Describing how it feels, even roughly, helps the listener understand."},{"prompt":"The listener asks: \"Before we finish, would it help to plan one small next step together?\"","options":[{"text":"\"Yes please. Could we plan a doctor visit?\"","then":"\"Yes. Let's think about who could go with you, and when.\"","best":true},{"text":"\"No, talking was enough. I feel better already.\"","then":"\"I'm glad. You can call again whenever you want to.\""},{"text":"\"Can you tell me what to do to fix myself?\"","then":"\"There's nothing to fix. A doctor can help. Shall we plan that?\""},{"text":"\"I'll think about it. I might call back one day.\"","then":"\"Of course. The line is always open. Take care of yourself.\""}],"why":"Planning a doctor visit turns a good call into lasting support."}],"relearn":"A trained listener only needs an honest start; 'I've been low and didn't know where to turn' is enough to begin."},
  {"id":"ly-1215","cat":"reach-out","type":"role-play","persona":"Vikram","source":"together","hook":"Your partner Sneha keeps saying she's fine, but you can see she is sinking.","setup":"It is late and the baby is finally asleep.","steps":[{"prompt":"Sneha says, staring at the wall: \"I'm fine. Really. Just tired.\"","options":[{"text":"\"I don't think either of us is fine. Can we get support together?\"","then":"She turns to you, eyes wet. \"I didn't want to say it first.\"","best":true},{"text":"\"If you say you're fine, I'll believe you. Don't blame me later.\"","then":"She stiffens. \"Blame you for what?\""},{"text":"\"You're always tired. Everyone is, so stop dwelling on it.\"","then":"She looks down. \"I'm not dwelling.\" Her voice is small."},{"text":"\"Fine. I'll let you rest. Just tell me if it gets worse.\"","then":"She nods. She won't say it, and you both know it."}],"why":"Saying neither of you is fine, and offering to get support together, opens a door."},{"prompt":"A few days later Sneha says: \"I keep crying for no reason. Something is wrong with me.\"","options":[{"text":"\"Nothing is wrong with you. This is common, and help works.\"","then":"She wipes her face. \"Really? It feels so shameful.\"","best":true},{"text":"\"You have a healthy baby. You have nothing to cry about.\"","then":"She goes very still. \"You're right. Sorry.\""},{"text":"\"It's hormones. It will settle if you just rest more.\"","then":"She nods, unconvinced. \"I've been resting.\""},{"text":"\"Don't say that to anyone. They'll worry for no reason.\"","then":"She nods and goes quiet. She looks lonelier."}],"why":"Telling her it is common and that help works lifts the shame."},{"prompt":"The next evening Sneha asks quietly: \"What if a doctor says it's just me being weak?\"","options":[{"text":"\"It's not weakness, and I'll be with you the whole time.\"","then":"Her shoulders ease a little. \"Okay. Will you come?\"","best":true},{"text":"\"Then we'll ignore the doctor and wait a while longer.\"","then":"She nods. The weeks go by and the crying does not stop."},{"text":"\"Then don't go. We'll manage it ourselves at home.\"","then":"She relaxes for a moment, then looks worried again."},{"text":"\"They won't. And if they do, we'll just carry on as before.\"","then":"She smiles thinly. \"I suppose.\" She isn't convinced."}],"why":"Telling her it isn't weakness, and coming along, makes the first step possible."},{"prompt":"One evening Sneha says: \"I want to see a doctor, but I'm scared. Must I tell them everything?\"","options":[{"text":"\"Say only what you're ready for. I'll sit beside you.\"","then":"She breathes out. \"Okay. That I can do.\"","best":true},{"text":"\"Yes, every detail. Otherwise it won't work.\"","then":"She looks more frightened. \"I don't think I can.\""},{"text":"\"I'll tell the doctor for you so you don't have to.\"","then":"She goes quiet. \"I wanted to say it myself.\""},{"text":"\"Let's skip it. You're doing a bit better lately, aren't you?\"","then":"She hesitates. \"A bit.\" The visit slips to next month."}],"why":"Letting her set the pace, with you beside her, makes the visit possible."}],"relearn":"Naming 'neither of us is fine, and that's okay' and offering to seek help together opens a door 'are you okay?' can't."},
  {"id":"ly-1216","cat":"reach-out","type":"role-play","persona":"Divya","source":"both with respect","hook":"Weeks of low mood have you thinking of a doctor, but your aunt trusts prayer alone.","setup":"She raises it over morning tea.","steps":[{"prompt":"Your aunt says: \"Just pray and be patient, beta. God will take care of it.\"","options":[{"text":"\"I'll keep praying, and I'm also going to see a doctor.\"","then":"She sighs, then nods slowly. \"Both, then. I'll pray for you too.\"","best":true},{"text":"\"Fine. I won't bother with a doctor. You know best.\"","then":"She looks satisfied. By evening you are quietly looking up clinics anyway."},{"text":"\"Prayer is useless. Doctors are the only thing that works.\"","then":"Her face hardens. \"How dare you say that in this house.\""},{"text":"\"I'll pray, and think about a doctor if it gets worse.\"","then":"She nods. \"Wise.\" The weeks pass and it does not get better."}],"why":"You can honour her faith and still see a doctor, as for any health matter."},{"prompt":"Later, over tea, your aunt says: \"A doctor for the mind, beta? People would talk.\"","options":[{"text":"\"I hear you. It's a health visit, like any other doctor.\"","then":"She thinks. \"Like my knee doctor?\" Then she nods slowly. \"Hm. Maybe.\"","best":true},{"text":"\"You're right. I won't go, so nobody has anything to say.\"","then":"She nods, pleased. You feel the plan shrinking."},{"text":"\"That's old-fashioned. Everyone goes to doctors now.\"","then":"She bristles. \"Old-fashioned? I raised three children.\""},{"text":"\"Maybe a few more weeks of prayer first, then I'll see.\"","then":"She smiles. \"Yes. Give it time.\" The weeks pass."}],"why":"Listening to her worry, then holding your plan, keeps peace and keeps care."},{"prompt":"One evening your mother-in-law says: \"In our family, we never needed doctors for this.\"","options":[{"text":"\"I respect that. I want to be well for the baby, so I'm going.\"","then":"She purses her lips, then softens. \"Do go, then.\"","best":true},{"text":"\"Okay. I'll skip it and just try harder.\"","then":"She nods with relief. You feel yourself tighten with it."},{"text":"\"Then your family never had to cope with a baby like mine.\"","then":"She gasps. \"Enough.\" The room goes cold."},{"text":"\"Maybe you're right. I'll wait until the baby is older.\"","then":"She nods, relieved. The months ahead feel long and heavy."}],"why":"Respect plus clarity about your own health keeps family close."},{"prompt":"A week on your aunt asks: \"So, beta. What have you decided about the doctor?\"","options":[{"text":"\"Booking it this week. And I'd love your prayers too.\"","then":"She squeezes your hand. \"Then I'll come along and hold the baby.\"","best":true},{"text":"\"Not yet. I'm still thinking it over, to be honest.\"","then":"She nods. The days go by and nothing is booked."},{"text":"\"No. I decided to let it go and rely on prayer.\"","then":"She nods happily. You feel the heaviness settle in again."},{"text":"\"That's my business. Please stop asking about it.\"","then":"She stiffens. \"I only ask because I love you.\""}],"why":"Booking the visit and welcoming her prayers lets you honour both."}],"relearn":"You can respect a relative's faith and still seek medical help; mental health deserves a doctor like any health issue."},
  {"id":"ly-1217","cat":"reach-out","type":"role-play","persona":"Divya","source":"weekly check","hook":"You want to ask your sister to check in on you weekly while things are hard, without sounding dramatic.","setup":"You call your sister after the baby's bedtime.","steps":[{"prompt":"Pooja says: \"Hey, you! How are things going with the little one?\"","options":[{"text":"\"Would you message me each week to see how I'm doing?\"","then":"She answers straight away. \"Every Sunday. I'd love to.\"","best":true},{"text":"\"Ignore me. I'm being silly. You have enough on your plate.\"","then":"She laughs, unsure. \"You're never silly.\" The moment passes."},{"text":"\"All good. Tell me about your kids instead.\"","then":"She chats about her kids for half an hour. You don't mention it."},{"text":"\"Come over sometime, if you're free. No pressure at all.\"","then":"She says she'll try. No day is fixed."}],"why":"A clear, small ask lets your sister help in a way that lasts."},{"prompt":"On Sunday evening Pooja writes: \"Thinking of you. How's this week been?\"","options":[{"text":"\"Hard. Can I call you for ten minutes tonight?\"","then":"She rings within a minute. \"Tell me everything.\"","best":true},{"text":"\"Good, thanks. Nothing much to report this week!\"","then":"She sends a thumbs up. The message thread stays short."},{"text":"\"Busy but fine. Tell me all about yours instead.\"","then":"She tells you about her week. You listen, and hold your own back."},{"text":"\"Hard, but I don't want to bore you with all of it.\"","then":"She writes: \"You never bore me.\" You still don't say more."}],"why":"Answering honestly turns a message into a real check-in."},{"prompt":"A month on Pooja says: \"You don't sound like yourself lately. Is it more than tired?\"","options":[{"text":"\"Maybe. Will you help me talk to a doctor about it?\"","then":"Her voice is soft. \"Yes. I'll sit with you while you call.\"","best":true},{"text":"\"No, it's just tired. I'm fine, honestly.\"","then":"She sounds unsure. \"Okay. But tell me if it changes.\""},{"text":"\"Maybe, but a doctor will just say what you said.\"","then":"She laughs gently. \"Maybe. But a doctor could really help.\""},{"text":"\"Please don't tell Ma. She'll only worry.\"","then":"She hesitates. \"I won't. But I'd like to help you more.\""}],"why":"Your sister is a great start, and a doctor adds care she can't give."}],"relearn":"Asking someone to check in regularly builds a steady thread of support; a clear small ask is easy to say yes to."},
  {"id":"ly-1218","cat":"reach-out","type":"role-play","persona":"Priya","source":"swap notes","hook":"At a parents' meet-up you sense someone is barely holding it together. You want to gently let them know they're not alone.","setup":"You sit beside her while the toddlers play.","steps":[{"prompt":"Farah says with a bright smile: \"Oh, I'm fine. And you?\"","options":[{"text":"\"Some days with mine are tough too. Swap notes sometime?\"","then":"Her smile wobbles. \"Sometimes I think I'm the only one.\"","best":true},{"text":"\"You look like you're managing so well. How do you do it?\"","then":"She laughs, tight. \"Oh, you know. Somehow.\""},{"text":"\"Me too. Just tired. Isn't everyone?\"","then":"She smiles politely. \"Of course.\" The chat drifts off."},{"text":"\"You look exhausted. Have you even eaten today?\"","then":"She flushes. \"I'm fine, really.\" She turns to the toddlers."}],"why":"Admitting your own hard days invites her to be honest."},{"prompt":"At the next meet-up Farah's eyes are red. She says: \"Sorry. Long night.\"","options":[{"text":"\"No need to be sorry. Want to step outside for a few minutes?\"","then":"She nods gratefully. \"Yes. Just a few.\"","best":true},{"text":"\"Long nights are the worst. Push through. It gets better.\"","then":"She nods, blinking. \"I'm sure you're right.\""},{"text":"\"Try not to cry here. People will start to wonder.\"","then":"Her eyes fill. \"I know. Sorry.\" She stays, staring at the floor."},{"text":"\"Go home and rest. I'll tell everyone you were unwell.\"","then":"She shakes her head. \"Home is lonelier.\" She stays, saying nothing real."}],"why":"Offering a quiet moment away gives her space without shame."},{"prompt":"A little later, as the toddlers play, Farah says quietly: \"I don't know why I feel so empty. Everyone else seems happy.\"","options":[{"text":"\"Many parents feel it and don't say. You aren't alone.\"","then":"She lets out a shaky breath. \"Really? It feels so lonely.\"","best":true},{"text":"\"You should be grateful. You have a healthy baby.\"","then":"She goes very quiet. \"You're right. I'm sorry.\""},{"text":"\"Find a new hobby. That will fill the time nicely.\"","then":"She half smiles. \"I don't have the energy for hobbies.\""},{"text":"\"It's only a phase. Give it a couple more months.\"","then":"She nods, though her eyes say she doubts it."}],"why":"Saying you aren't alone opens the door without judging her feelings."},{"prompt":"Before she leaves, Farah says: \"Maybe I should talk to someone. Where would I even start?\"","options":[{"text":"\"A doctor or Tele-MANAS 14416 is a start. I'll sit with you.\"","then":"Her face relaxes. \"Yes. Would you?\"","best":true},{"text":"\"Just talk to me. You don't need anyone else.\"","then":"She nods, though she looks unsure it will be enough."},{"text":"\"Ask the other mothers in the group what worked for them.\"","then":"She looks around the room and shrinks. \"I couldn't ask them.\""},{"text":"\"Wait until the next meet-up and see how you feel.\"","then":"She agrees. The next meet-up comes, and she looks worse."}],"why":"A doctor or Tele-MANAS gives her a real route, and you can sit beside her."}],"relearn":"Admitting your own hard days invites a struggling parent to be honest, where false praise can leave them more alone."},
  {"id":"ly-1219","cat":"reach-out","type":"role-play","persona":"Divya","source":"tell ma","hook":"You finally want to tell your own mother you've been struggling, even though you usually protect her from worry.","setup":"You call her on a quiet evening.","steps":[{"prompt":"Your mother picks up warmly: \"Beta! How are you and the baby?\"","options":[{"text":"\"Ma, this has been hard and I don't want to hide it anymore.\"","then":"She goes quiet, then says gently, \"Tell me, beta. I'm here.\"","best":true},{"text":"\"Everything's perfect. Don't worry. I just called to say hi.\"","then":"She laughs, pleased. \"Good. I worry too much.\""},{"text":"\"We're fine. I'm only a little tired, Ma.\"","then":"She clucks. \"Sleep when the baby sleeps, beta.\""},{"text":"\"Can you come over next week? I'll explain then.\"","then":"She sounds anxious. \"Explain what? Tell me now.\""}],"why":"Letting your mother in brings support and brings you closer."},{"prompt":"A few days later your mother calls back: \"I've been thinking about you all week.\"","options":[{"text":"\"Thank you, Ma. I'd love it if you could visit and help.\"","then":"Her voice lifts. \"I'll take the morning train.\"","best":true},{"text":"\"Don't worry, Ma. I've got it under control.\"","then":"She hesitates. \"If you say so, beta.\" She still worries."},{"text":"\"Sorry, Ma. I didn't mean to worry you.\"","then":"She sighs. \"Never be sorry for that. I'd rather know than guess.\""},{"text":"\"Just pray for me, Ma. That's all I need.\"","then":"She promises to pray every day. The nights stay as long as ever."}],"why":"Saying what would really help lets her be useful."},{"prompt":"Your mother says: \"In my time we just carried on. But you sound different, beta. Is it tiredness or something more?\"","options":[{"text":"\"It's been weeks, Ma. It's more than tired. I want a doctor.\"","then":"She is quiet, then says, \"Then we'll go together.\"","best":true},{"text":"\"You may be right. Maybe I'm just being dramatic, Ma.\"","then":"She agrees gently, though her voice stays worried. \"Still, tell me how I can help.\""},{"text":"\"Nobody understands. It was different for you back then.\"","then":"She sounds stung. \"I only want to help.\""},{"text":"\"I'll wait and see, Ma. Please don't tell Papa or anyone.\"","then":"She promises reluctantly. The weeks slip by."}],"why":"Saying it's more than tired and that you want a doctor turns worry into action."},{"prompt":"Your mother asks: \"Beta, what can I do to help you right now?\"","options":[{"text":"\"Come on Tuesdays so I can nap, and ring me nightly.\"","then":"She writes it down. \"Tuesdays and evenings. Done.\"","best":true},{"text":"\"Nothing, Ma. I'll manage on my own. Please don't worry.\"","then":"She hesitates. \"Beta, I'm your mother.\" She still tries to help."},{"text":"\"Just tell me that it will all pass very soon, Ma.\"","then":"She says it will. It comforts you for a moment, and no plan is made."},{"text":"\"Please don't tell anyone else in the family about this.\"","then":"She promises. She carries it quietly and wishes she could do more."}],"why":"A concrete ask lets her help in ways you'll feel."}],"relearn":"Letting a parent in instead of protecting them from worry often brings real support and brings you closer, not further."},
  {"id":"ly-1220","cat":"reach-out","type":"spot","hook":"Spot the two lines that quietly talk a struggling parent OUT of reaching for help.","scene":[{"id":"a","text":"'It's okay to ask before things get bad'","trick":false},{"id":"b","text":"'Strong parents handle it on their own'","trick":true},{"id":"c","text":"'A helpline is there any time'","trick":false},{"id":"d","text":"'Don't bother people with your problems'","trick":true},{"id":"e","text":"'Telling someone makes it lighter'","trick":false}],"why":"'Strong parents handle it alone' and 'don't bother people' are lies that keep parents silent and stuck.","relearn":"Watch for 'handle it alone' and 'don't bother people'; both talk a parent out of reaching for help.","persona":"any","source":"talk-you-out lines"},
  {"id":"ly-1221","cat":"reach-out","type":"spot","hook":"Spot the two responses that would shut a friend down instead of helping them open up.","scene":[{"id":"a","text":"'That sounds so hard, tell me more'","trick":false},{"id":"b","text":"'At least you have a healthy baby'","trick":true},{"id":"c","text":"'You're not alone, I'm right here'","trick":false},{"id":"d","text":"'Others have it far worse than you'","trick":true},{"id":"e","text":"'Want me to help you find some support?'","trick":false}],"why":"'At least…' and 'others have it worse' dismiss the feeling and teach the parent to stop sharing.","relearn":"'At least…' and 'others have it worse' shut a parent down; 'tell me more' and 'I'm here' help them open up.","persona":"any","source":"shut-down lines"},
  {"id":"ly-1222","cat":"reach-out","type":"spot","hook":"Spot the two moves that keep a parent isolated rather than building their support net.","scene":[{"id":"a","text":"Saving a couple of people to call","trick":false},{"id":"b","text":"Turning down every offer of help","trick":true},{"id":"c","text":"Joining a local new-parent group","trick":false},{"id":"d","text":"Cancelling plans whenever you feel low","trick":true},{"id":"e","text":"Telling one trusted person the truth","trick":false}],"why":"Refusing all help and withdrawing whenever you're low are exactly what shrink a net when you most need one.","relearn":"Turning down every offer and cancelling when low isolate you; saved contacts, a group and honesty build the net.","persona":"any","source":"isolating moves"},
  {"id":"ly-1223","cat":"reach-out","type":"spot","hook":"Spot the two 'reasons' to delay that are really just the struggle talking you out of help.","scene":[{"id":"a","text":"'Booking a doctor now is a good idea'","trick":false},{"id":"b","text":"'I'll reach out once I feel better'","trick":true},{"id":"c","text":"'Early help is easier than late'","trick":false},{"id":"d","text":"'It's not bad enough to bother anyone'","trick":true},{"id":"e","text":"'Saving the number takes a minute'","trick":false}],"why":"'Once I feel better' and 'not bad enough' are delays that keep parents from the early help that works best.","relearn":"'Once I feel better' and 'not bad enough' are delays; early help is easier and you deserve it now.","persona":"any","source":"delay reasons"},
  {"id":"ly-1224","cat":"reach-out","type":"spot","hook":"Spot the two beliefs that keep a father suffering in silence after a baby.","scene":[{"id":"a","text":"'Fathers can struggle too, that's okay'","trick":false},{"id":"b","text":"'A man should provide and not feel'","trick":true},{"id":"c","text":"'Opening up to my partner is strength'","trick":false},{"id":"d","text":"'If I admit this, I'm letting them down'","trick":true},{"id":"e","text":"'A doctor can help me with this too'","trick":false}],"why":"'A man shouldn't feel' and 'admitting it lets them down' are myths that trap fathers in silence.","relearn":"'Men shouldn't feel' and 'admitting it lets them down' keep fathers silent; both are myths, and dads can reach out.","persona":"Vikram","source":"father silence"},
  {"id":"ly-1225","cat":"reach-out","type":"spot","hook":"Spot the two things that would NOT actually happen when you call a mental-health helpline.","scene":[{"id":"a","text":"A trained person listens without judging","trick":false},{"id":"b","text":"They put your name in a public record","trick":true},{"id":"c","text":"You can call free, any time","trick":false},{"id":"d","text":"They tell your family you couldn't cope","trick":true},{"id":"e","text":"You talk as little or as much as you like","trick":false}],"why":"A helpline won't make you public or report you to family; these false fears stop parents from calling.","relearn":"Helpline fears like 'they'll record me' or 'tell my family' are false; calls are free and confidential.","persona":"any","source":"helpline myths"},
  {"id":"ly-1226","cat":"reach-out","type":"spot","hook":"Spot the two lines that make a parent feel ashamed for needing help, not supported.","scene":[{"id":"a","text":"'Anyone would find this stage hard'","trick":false},{"id":"b","text":"'In our day we just got on with it'","trick":true},{"id":"c","text":"'Let's find you someone to talk to'","trick":false},{"id":"d","text":"'Good mothers don't need helplines'","trick":true},{"id":"e","text":"'It's brave of you to say something'","trick":false}],"why":"'We just got on with it' and 'good mothers don't need helplines' shame a parent for the strength of reaching out.","relearn":"'We just got on with it' and 'good mothers don't need help' shame; warmth and 'let's find you support' encourage.","persona":"any","source":"shaming lines"},
  {"id":"ly-1227","cat":"reach-out","type":"spot","hook":"Spot the two replies that miss a quiet cry for help instead of meeting it.","scene":[{"id":"a","text":"'You don't seem yourself, want to talk?'","trick":false},{"id":"b","text":"'You're fine, you always bounce back'","trick":true},{"id":"c","text":"'I'm here whenever you're ready'","trick":false},{"id":"d","text":"'Stop being so negative all the time'","trick":true},{"id":"e","text":"'Should we call someone together?'","trick":false}],"why":"'You're fine, you bounce back' and 'stop being negative' brush past distress; the others open a door to help.","relearn":"'You're fine' and 'stop being negative' miss a cry for help; 'want to talk?' and 'I'm here' meet it.","persona":"any","source":"missed cues"},
  {"id":"ly-1350","cat":"tools-and-help","type":"strike-rewrite","hook":"\"A breathing space is just woo-woo; it won't do anything for me.\"","myth":{"un":"A breathing space is just woo-woo; it won't do anything for me.","re":"Slow breathing genuinely calms the body's alarm in an overwhelming moment, buying you a steadier minute to think.","why":"Slow breathing settles the body's stress response."},"relearn":"A few slow breaths really do calm the body's alarm; a grounding space is a real, simple tool, not woo-woo.","persona":"Divya","source":"breathing works"},
  {"id":"ly-1351","cat":"tools-and-help","type":"branch","persona":"any","source":"safe pause","hook":"It's been a long evening with the baby, and nothing you try is working.","steps":[{"prompt":"Your heart is racing and the crying goes on. What do you do?","options":[{"text":"Lay the baby safely down and take ten slow breaths","then":"The baby cries in the cot, safe. Ten breaths later your chest loosens.","best":true},{"text":"Carry the baby faster and faster from room to room","then":"The baby cries harder at the motion, and your arms begin to shake."},{"text":"Play a loud video to drown out the crying sound","then":"The noise fills the room. The cry and your panic are both still there."},{"text":"Push on and try not to notice how much you're shaking","then":"Your hands tremble and your patience thins with every minute."}],"why":"A grounding pause steadies you, and the baby stays safe while you do it."},{"prompt":"A little later the baby is still fussing and you are still shaky. What do you do?","options":[{"text":"Ask a family member to hold the baby for ten minutes","then":"Your mother-in-law takes him. You sit down and drink some water.","best":true},{"text":"Try again alone, without bothering anyone at home","then":"You go back in, tighter than before. The fussing continues."},{"text":"Message the family group asking for tips on a crying baby","then":"Ten replies arrive, all advice, and nobody offers to take the baby."},{"text":"Keep feeding and rocking for another hour without a break","then":"The baby settles for a moment. You are nearly out of energy."}],"why":"Passing the baby to someone you trust gives you a real break."},{"prompt":"That night you think about tomorrow. What do you do?","options":[{"text":"Save Tele-MANAS 14416 and one trusted person on your phone","then":"You save both. The phone feels a bit more like a safety net.","best":true},{"text":"Trust yourself to remember what to do when it happens","then":"You feel sure. The plan lives only in your head."},{"text":"Plan to try much harder tomorrow so you won't need help","then":"You resolve to be stronger. It feels like a weight."},{"text":"Read every article you can find about crying babies","then":"You read until midnight, and nothing sticks. You feel more anxious."}],"why":"Saving help in advance makes it one tap away on a hard day."},{"prompt":"A week later the baby's crying peaks and the panic starts again. What do you do?","options":[{"text":"Lay the baby safe, breathe slowly, then call someone you trust","then":"Your friend picks up on the second ring. Your breathing starts to slow.","best":true},{"text":"Wait to see if the panic passes before doing anything","then":"The minutes crawl by. The panic builds instead of fading."},{"text":"Assume nothing will work and give up on trying","then":"You drop the tools. The crying goes on and you feel more alone with it."},{"text":"Do everything at once: rock, feed, rush and scroll","then":"You spin between all of them and steady on none."}],"why":"Your tools work best together: pause, breathe, then reach for a person."}],"debrief":"When overwhelm spikes, lay the baby down safely and take a grounding breath; a calmer you can carry on.","relearn":"Lay the baby safely down and take ten slow breaths; a grounding pause steadies an overwhelming moment."},
  {"id":"ly-1352","cat":"tools-and-help","type":"match","hook":"Match each grounding move to what it does in a hard moment.","pairs":[{"left":"Ten slow breaths, out longer than in","right":"Eases the body's alarm"},{"left":"Name five things you can see","right":"Pulls you back to the present"},{"left":"Splash cool water on your face","right":"Resets a flooded, racing feeling"},{"left":"Step onto the balcony for fresh air","right":"Gives a heavy moment some space"},{"left":"Text one trusted person 'rough day'","right":"Breaks the feeling of being alone"}],"relearn":"Slow breaths, naming what you see, cool water, fresh air and a quick text are simple grounding tools for a hard moment.","persona":"any","source":"grounding moves"},
  {"id":"ly-1353","cat":"tools-and-help","type":"reflect","hook":"Lensy: a grounding space isn't only for crises; it's for any moment that feels too big. Worth keeping close?","prompt":"What do you think?","options":["Worth it","Keep it close","Makes sense"],"affirm":"A breathing or grounding space is for everyday hard moments and the worst ones alike; knowing it's there is itself a comfort.","relearn":"A grounding space is for everyday hard moments and crises alike; having one ready is itself a tool.","persona":"any","source":"everyday tool"},
  {"id":"ly-1354","cat":"tools-and-help","type":"sort","hook":"Sort each tool: a grounding tool for the moment, or a route to real help?","items":[{"id":"a","text":"Ten slow breaths"},{"id":"b","text":"Calling Tele-MANAS 14416"},{"id":"c","text":"Naming five things you can see"},{"id":"d","text":"Booking a doctor's appointment"},{"id":"e","text":"Stepping out for fresh air"},{"id":"f","text":"Saving Tele-MANAS 14416 in your phone"}],"bins":[{"id":"ground","label":"Calm the moment","valence":"pos"},{"id":"route","label":"Route to help","valence":"tell"}],"key":{"a":"ground","b":"route","c":"ground","d":"route","e":"ground","f":"route"},"relearn":"Breathing, grounding and fresh air calm the moment; helplines, a doctor and saved contacts route you to real help; both matter.","persona":"any","source":"calm vs route"},
  {"id":"ly-1355","cat":"tools-and-help","type":"spot","hook":"Spot the two unhelpful 'tools' a stressed parent might reach for. Tap the two red flags.","scene":[{"id":"a","text":"A few slow breaths to settle","trick":false},{"id":"b","text":"Snapping at whoever's nearest to vent","trick":true},{"id":"c","text":"Texting a friend you trust","trick":false},{"id":"d","text":"Bottling it up until you boil over","trick":true},{"id":"e","text":"Stepping outside for a minute","trick":false}],"why":"Snapping to vent and bottling things up until you boil over aren't real tools; breathing, reaching out and a pause are.","relearn":"Real tools are breathing, reaching out and a pause; snapping to vent or bottling up until you boil over are not.","persona":"any","source":"not a tool"},
  {"id":"ly-1401","cat":"tools-and-help","type":"role-play","persona":"Divya","source":"stay with me","hook":"You're in tears and have rung your sister Anu.","setup":"She answers on the second ring.","steps":[{"prompt":"Anu says: \"I'm here. What do you need from me right now?\"","options":[{"text":"\"Just stay on the line and breathe with me a minute.\"","then":"Anu breathes slowly beside you. \"In, and out. I'm not going anywhere.\"","best":true},{"text":"\"Tell me what to do. Please give me a list of things to try.\"","then":"Anu offers three ideas fast. They pile up in your foggy head."},{"text":"\"Nothing, sorry. I'll sort it out on my own after this call.\"","then":"Anu stays quiet a moment. \"I'm still here if you change your mind.\""},{"text":"\"Talk about something else. Anything to distract me from this.\"","then":"Anu chatters about her week. The tears ease, though the feeling stays under them."}],"why":"Someone staying and breathing with you steadies a hard moment more than advice."},{"prompt":"Anu asks: \"Do you want me to come over?\"","options":[{"text":"\"Yes please, if you can. I don't want to be alone tonight.\"","then":"Anu is already reaching for her keys. \"Twenty minutes. Stay on the line.\"","best":true},{"text":"\"No, don't waste your evening on me. I'll be fine.\"","then":"Anu hesitates. \"Okay. Ring me back in an hour.\""},{"text":"\"Yes, but only if you're not busy with something else.\"","then":"Anu says she isn't, though her voice sounds hurried."},{"text":"\"No, I'll be fine once I've slept.\"","then":"Anu agrees reluctantly. The night is long."}],"why":"Asking for company plainly is what gets it."},{"prompt":"Anu says: \"This sounds like more than a hard day. Have you thought about talking to someone?\"","options":[{"text":"\"Yes. Will you help me call Tele-MANAS or book the doctor?\"","then":"Anu nods on the line. \"Of course. Let's do it together.\"","best":true},{"text":"\"It's nothing. I'll be fine once the baby sleeps through.\"","then":"Anu lets it drop. The heaviness stays with you."},{"text":"\"I'll think about it. Please don't tell Mum.\"","then":"Anu promises. You carry it alone, a little longer."},{"text":"\"I'd rather not. I don't want to feel like a case.\"","then":"Anu says she understands. The idea waits."}],"why":"Asking your sister to help with the first step makes reaching out doable."}],"relearn":"Asking someone to simply stay and breathe with you is a real tool; staying connected steadies a hard moment."},
  {"id":"ly-1356","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Helplines are only for people who are completely falling apart.\"","myth":{"un":"Helplines are only for people who are completely falling apart.","re":"Lines like Tele-MANAS 14416 are for any hard day; you can call just to talk things through, long before any crisis.","why":"Support lines are for everyday struggle, not only emergencies."},"relearn":"Helplines like Tele-MANAS 14416 are for any hard day, not only a breakdown; you can call just to talk.","persona":"any","source":"any hard day"},
  {"id":"ly-1357","cat":"tools-and-help","type":"branch","persona":"any","source":"save them now","hook":"You have five quiet minutes. You could set up your phone for the next bad day.","steps":[{"prompt":"The baby is napping and the house is still. What do you do?","options":[{"text":"Save Tele-MANAS 14416, your doctor and two trusted people","then":"Four contacts join your phone. It takes three minutes.","best":true},{"text":"Scroll through social media, as you've earned the break","then":"You scroll happily. Five minutes vanish, and nothing else is ready."},{"text":"Plan to save the numbers later, when there is more time","then":"More time doesn't appear. The numbers stay unsaved."},{"text":"Save only your doctor, as the rest feels like too much","then":"One number joins your phone. The other supports stay unset."}],"why":"Saving help while calm makes it one tap away on a bad day."},{"prompt":"That evening your partner asks how you feel about tomorrow. What do you say?","options":[{"text":"Tell him which numbers help on a bad day, and share them","then":"He nods. \"Send them to me. I'll save them too.\"","best":true},{"text":"Say you'll cope alone as you always do, so no need","then":"He shrugs, unsure. Nothing gets set up between you."},{"text":"Ask him to remember every one of the numbers himself","then":"He frowns. \"That's a lot for one head.\""},{"text":"Say you are fine and there is nothing to discuss","then":"He drops it. Nobody else knows where to turn if you can't."}],"why":"Sharing your numbers means help is there even when you can't reach for it."},{"prompt":"A week on, a hard afternoon hits and the baby is crying. What do you do?","options":[{"text":"Breathe slowly, then call Tele-MANAS 14416 or a friend","then":"A calm voice answers on the second ring. Your breathing starts to slow.","best":true},{"text":"Search online for help options while your heart races","then":"Pages of results blur together. Your panic rises as you scroll."},{"text":"Wait to see if it passes without touching your phone","then":"The panic doesn't pass. You are still waiting as the minutes tick on."},{"text":"Try to remember the number from memory alone, mid-panic","then":"The digits blur. You stop, embarrassed, with nothing dialled."}],"why":"Breathing first, then calling, gets help to you fast. Saved numbers make it one tap."},{"prompt":"Some weeks on, you realise a helpful number is missing. What do you do?","options":[{"text":"Add it straight away, while you feel calm and steady","then":"The number joins the rest. Your list feels complete.","best":true},{"text":"Mean to add it someday, and keep on forgetting it","then":"Days pass. The gap stays, waiting for the next hard day."},{"text":"Skip it, since you think you already have enough saved","then":"The list stays as it is. One small gap remains."},{"text":"Leave it until the next hard day and add it then","then":"The next hard day comes, and you end up searching for it mid-panic."}],"why":"A calm moment is the best time to keep your list complete."}],"debrief":"Use a calm few minutes to save help contacts; on a hard day they're one tap away, not a frantic search.","relearn":"Save Tele-MANAS, your doctor and trusted people while calm; on a bad day help is one tap, not a search."},
  {"id":"ly-1358","cat":"tools-and-help","type":"match","hook":"Match each moment to the India support that fits it.","pairs":[{"left":"You just need to talk, any time of night","right":"Tele-MANAS 14416"},{"left":"You want structured, ongoing support","right":"A doctor or counsellor"},{"left":"Someone is in immediate danger","right":"Emergency 112"},{"left":"You're not sure where to start","right":"A help-finder and saved contacts"},{"left":"The panic just needs to ease right now","right":"A breathing or grounding space"}],"relearn":"Tele-MANAS to talk, a doctor or counsellor for structured support, 112 for danger, a help-finder to start, a breathing space to ease the moment.","persona":"any","source":"matched routes"},
  {"id":"ly-1359","cat":"tools-and-help","type":"reflect","hook":"Lensy: saving a helpline number before you need it is a quiet act of self-care, like keeping a torch by the bed. Do it?","prompt":"Your take?","options":["I'll save it","Like a torch","Quiet self-care"],"affirm":"Saving support numbers before a hard day is small and powerful; on that day, you won't have to find them, they'll be right there.","relearn":"Saving a support number before you need it is quiet self-care; on the hard day it's already there, like a torch by the bed.","persona":"any","source":"torch by the bed"},
  {"id":"ly-1360","cat":"tools-and-help","type":"sort","hook":"Sort each India route: any-time talk and support, or only-for-immediate-danger?","items":[{"id":"a","text":"Tele-MANAS 14416"},{"id":"b","text":"Emergency 112 for someone in danger"},{"id":"c","text":"A counsellor you trust"},{"id":"d","text":"Calling an ambulance for immediate harm"},{"id":"e","text":"A doctor's appointment"},{"id":"f","text":"112 when there's danger right now"}],"bins":[{"id":"talk","label":"Talk & support","valence":"tell"},{"id":"danger","label":"Immediate danger","valence":"uhoh"}],"key":{"a":"talk","b":"danger","c":"talk","d":"danger","e":"talk","f":"danger"},"relearn":"Tele-MANAS, a counsellor and a doctor are for talk and support; 112 and an ambulance are for immediate danger to anyone.","persona":"any","source":"talk vs danger"},
  {"id":"ly-1361","cat":"tools-and-help","type":"spot","hook":"Spot the two thoughts that block a parent from reaching help. Tap the two red flags.","scene":[{"id":"a","text":"Keeping a helpline saved in your phone","trick":false},{"id":"b","text":"\"I'll feel silly calling a helpline\"","trick":true},{"id":"c","text":"Telling your doctor how you feel","trick":false},{"id":"d","text":"\"Others cope, so I should too\"","trick":true},{"id":"e","text":"Asking a friend to sit with you","trick":false}],"why":"\"I'll feel silly\" and \"others cope, so I should too\" block help; saving a line, telling a doctor and asking a friend open it.","relearn":"Thoughts like \"I'll feel silly\" and \"others cope\" block help; saving a line, a doctor and a friend open it.","persona":"any","source":"what blocks help"},
  {"id":"ly-1362","cat":"tools-and-help","type":"role-play","persona":"any","source":"making the call","hook":"You're trembling and the thoughts are scary, so you phone Tele-MANAS.","setup":"The line connects after a moment.","steps":[{"prompt":"A calm voice answers: \"This is Tele-MANAS. How can I help?\"","options":[{"text":"\"Hi, I'm a new parent with frightening thoughts. I need to talk.\"","then":"\"Thank you for calling. I'm here, and there's no need to explain it all.\"","best":true},{"text":"\"Sorry, never mind. It's probably nothing, so I'll just hang up now.\"","then":"The voice stays gentle. \"It's alright. I'm still here. Take your time.\""},{"text":"\"I'm calling on behalf of a friend who's been feeling low.\"","then":"\"Of course. I'm happy to talk about your friend, and you're welcome here too.\""},{"text":"\"Can you just tell me it's normal to feel like this?\"","then":"\"Many new parents feel scared. Can you tell me a little of what's happening for you?\""}],"why":"Naming a scary thought and asking to talk is the brave move. It's a symptom, not a verdict."},{"prompt":"The counsellor asks gently: \"Is there anyone with you tonight?\"","options":[{"text":"\"My partner is asleep next door. I'll wake them and tell them.\"","then":"\"Thank you. I'll stay on the line while you do.\"","best":true},{"text":"\"No one. I'd rather not bother anyone.\"","then":"\"Reaching out is never a bother. Is there someone you could call after this?\""},{"text":"\"My partner's here, but I don't want to worry them.\"","then":"\"That's a kind thought. Would it help to plan how to tell them?\""},{"text":"\"My mother-in-law is here, but she'll only say I'm overreacting.\"","then":"\"That fear is common. You can choose who to tell. Someone who'll listen matters.\""}],"why":"Telling someone close means you don't carry a frightening night alone."},{"prompt":"The counsellor says: \"Would you like to see a doctor as a next step? I can help you plan it.\"","options":[{"text":"\"Yes please. Help me plan a visit for tomorrow.\"","then":"\"Let's do that. I'll stay with you until you feel steadier.\"","best":true},{"text":"\"Yes, but I'll book it myself later this week.\"","then":"\"That's fine. Would it help to pick tomorrow's small step now?\""},{"text":"\"I feel steadier now, so I don't think I need one.\"","then":"\"I'm glad you feel steadier. Feelings like these are still worth a doctor's look.\""},{"text":"\"Only if it happens again.\"","then":"\"You don't have to wait. Early help is easier, and the line is always here.\""}],"why":"A doctor is the next step, and 112 is there if anyone is ever in danger."}],"relearn":"Naming a frightening thought and asking to talk is the brave, right move; a scary thought is a symptom, and the line is there for exactly this."},
  {"id":"ly-1363","cat":"tools-and-help","type":"strike-rewrite","hook":"\"If I dial 112, they'll think I'm overreacting and judge me.\"","myth":{"un":"If I dial 112, they'll think I'm overreacting and judge me.","re":"Emergency 112 is for immediate danger to anyone, including thoughts of harming yourself or the baby; calling is the right, responsible move.","why":"112 exists for exactly these moments; using it is responsible, not an overreaction."},"relearn":"Emergency 112 is for immediate danger to anyone, including harm thoughts; calling it is responsible, not overreacting.","persona":"any","source":"112 is for this"},
  {"id":"ly-1364","cat":"tools-and-help","type":"branch","persona":"Priya","source":"help her reach care","hook":"A new-parent friend confides she's been having dark thoughts she can't shake.","steps":[{"prompt":"Leela says it in a whisper and looks away. What do you do?","options":[{"text":"Stay warm, thank her, and don't press for details","then":"Her shoulders drop. \"I've been so afraid to say it out loud.\"","best":true},{"text":"Tell her firmly to snap out of it for the baby's sake","then":"Leela flinches and pulls her dupatta tight. She says no more."},{"text":"Ask what the thoughts are and how often they come","then":"She tears up and shakes her head. \"I can't go into it.\""},{"text":"Change the subject to something lighter for her sake","then":"Leela nods and talks about the weather. The moment closes."}],"why":"Warmth and thanks, without pressing for details, keep her talking."},{"prompt":"A little later Leela asks in a small voice whether this makes her a bad mother. What do you say?","options":[{"text":"Tell her no: it's a symptom, and help can ease it","then":"She blinks. \"A symptom? Not a sign of what I am?\"","best":true},{"text":"Tell her not to worry because it will pass on its own","then":"She nods slowly. She doesn't quite believe it."},{"text":"Say every mother has thoughts like that and it's normal","then":"She smiles a little, but stays worried. \"Maybe.\""},{"text":"Say you can't tell, and that she should ask her family","then":"She looks stricken. \"I can't. They wouldn't understand.\""}],"why":"A scary thought is a symptom, not a verdict, and it is never her fault."},{"prompt":"Leela says she is scared to tell anyone else. What do you do?","options":[{"text":"Offer to help her call Tele-MANAS 14416 or a doctor now","then":"She takes a shaky breath. \"Okay. Would you stay with me?\"","best":true},{"text":"Promise to keep it secret forever and do nothing more","then":"She thanks you. The weight stays with the two of you."},{"text":"Tell her family straight away, without asking her first","then":"Her mother rushes in. Leela feels exposed and barely speaks to you for days."},{"text":"Tell her to distract herself with some new project","then":"She nods. She takes on a project and the thoughts stay."}],"why":"Helping her reach a professional keeps her in charge and gets real care."},{"prompt":"A week later Leela tells you quietly that the thoughts are still there. What do you do?","options":[{"text":"Check in warmly and help her get to a doctor this week","then":"She agrees. \"Tuesday? I'll ask my husband to mind the baby.\"","best":true},{"text":"Tell her it's probably just stress and she'll be fine","then":"She nods. She keeps going, alone with it."},{"text":"Give her plenty of space and wait for her to come to you","then":"She doesn't come. The week ends without contact."},{"text":"Tell her sternly that she must stop dwelling on it now","then":"She winces. \"I can't switch it off.\" She goes quiet for a while."}],"why":"When thoughts stay, warm follow-up and a doctor visit matter more than space."},{"prompt":"One night Leela texts that she is frightened she can't keep herself or the baby safe. What do you do?","options":[{"text":"Call 112 now and stay with her until help arrives","then":"A calm voice answers on 112. Help is on the way, and you stay on the line.","best":true},{"text":"Tell her to lie down and try to rest it off tonight","then":"She lies down. The fear doesn't leave, and she is alone with it."},{"text":"Promise to talk it all through with her in the morning","then":"She thanks you. The night is long and no one is with her."},{"text":"Wait and see, and let her call you if it gets worse","then":"No call comes. You don't know how she is."}],"why":"When someone can't stay safe tonight, 112 brings help. It is never her fault."}],"debrief":"Meet a struggling friend with warmth and help her reach Tele-MANAS or a doctor; concern plus a route.","relearn":"Stay warm and help a struggling friend reach Tele-MANAS or a doctor; a route beats \"snap out of it\"."},
  {"id":"ly-1365","cat":"tools-and-help","type":"reflect","hook":"Lensy: knowing where to turn fast is itself a tool, even on the days you don't need it. Sit with that?","prompt":"What's your take?","options":["It's a tool","Good to know","I'll remember"],"affirm":"Just knowing the routes, a line to call, a doctor, a person, before a hard day means you're never starting from zero on it.","relearn":"Knowing where to turn fast is itself a tool; on a hard day you're never starting from zero.","persona":"any","source":"knowing the way"},
  {"id":"ly-1366","cat":"tools-and-help","type":"match","hook":"Match each tool in the kit to the job it does.","pairs":[{"left":"A breathing and grounding space","right":"Calms an overwhelming moment"},{"left":"A help-finder with saved contacts","right":"Shows where to turn, fast"},{"left":"Tele-MANAS 14416","right":"Someone to talk to any time"},{"left":"Emergency 112","right":"For immediate danger to anyone"},{"left":"A trusted person's number","right":"Everyday listening and a hand"}],"relearn":"A grounding space calms the moment, a help-finder shows the way, Tele-MANAS gives any-time talk, 112 covers danger, a trusted person gives everyday support.","persona":"any","source":"kit and jobs"},
  {"id":"ly-1367","cat":"tools-and-help","type":"sort","hook":"Sort each one: a genuine support tool, or a false 'tool' that doesn't help?","items":[{"id":"a","text":"A saved helpline number"},{"id":"b","text":"\"Just don't think about it\""},{"id":"c","text":"A breathing space you can use"},{"id":"d","text":"Hiding how bad it really is"},{"id":"e","text":"A doctor who knows your history"},{"id":"f","text":"Waiting alone for it to pass"}],"bins":[{"id":"real","label":"Real tool","valence":"pos"},{"id":"false","label":"Not a tool","valence":"neg"}],"key":{"a":"real","b":"false","c":"real","d":"false","e":"real","f":"false"},"relearn":"A saved line, a breathing space and a doctor are real tools; \"don't think about it\", hiding it and waiting alone are not.","persona":"any","source":"real vs false tools"},
  {"id":"ly-1368","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"they know where","hook":"Your partner Tara doesn't know where you keep the emergency contacts.","setup":"You sit down with her tonight.","steps":[{"prompt":"Tara asks: \"If you were struggling, who would I call?\"","options":[{"text":"\"They're saved: Tele-MANAS, our doctor and 112. Call if I'm not coping.\"","then":"Tara takes your phone and finds the favourites. \"Okay. I know where they are now.\"","best":true},{"text":"\"You'd figure out who to call if it ever came to that.\"","then":"She smiles uncertainly. \"I'd panic, honestly.\""},{"text":"\"Ring my mother first. She'll know exactly what to do.\"","then":"Tara nods. Your mother is two hours away and doesn't have the numbers either."},{"text":"\"Don't worry. I'll never be in that state, so it won't matter.\"","then":"Tara laughs a little. \"I'd still like to know.\""}],"why":"Telling her where the contacts are means either of you can reach help fast."},{"prompt":"Tara says: \"What if you tell me you're fine but you don't look it?\"","options":[{"text":"\"Then ask me twice, kindly, and stay a while. I might need the second ask.\"","then":"Tara nods. \"Twice, and I'll sit with you. Deal.\"","best":true},{"text":"\"Then leave it. I'll tell you when I'm ready to talk.\"","then":"Tara bites her lip. \"And if you never feel ready?\""},{"text":"\"Then call the doctor without asking me. I'd rather not talk about it.\"","then":"Tara looks startled. \"Without telling you first? I'd rather ask you.\""},{"text":"\"Then just trust me. If I say I'm fine, I'm fine.\"","then":"She nods, unconvinced. Two weeks on, she is still wondering."}],"why":"A second, kind ask lets a partner say what \"fine\" is hiding."},{"prompt":"Tara asks: \"What if it ever feels like someone is in danger?\"","options":[{"text":"\"Call 112 straight away. Don't wait to ask me first.\"","then":"Tara nods. \"112 first. I'll say it out loud so I remember it.\"","best":true},{"text":"\"Try Tele-MANAS first and see how it goes from there.\"","then":"Tara frowns. \"Even if it's urgent? That feels slow.\""},{"text":"\"Wait a little while and see if it passes on its own.\"","then":"She nods. The minutes pass with nobody sure what to do."},{"text":"\"Take the baby to your mother's and leave me to rest alone.\"","then":"Tara agrees. The baby is somewhere safer, but no one has called 112."}],"why":"112 is for immediate danger to anyone, so it comes first and needs no permission."}],"relearn":"Telling your partner exactly where the saved contacts are means either of you can reach help fast on the worst day."},
  {"id":"ly-1369","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Using these tools means I'm being treated; I don't need a doctor as well.\"","myth":{"un":"Using these tools means I'm being treated; I don't need a doctor as well.","re":"A breathing space and a helpline are support and signposting, not treatment; lasting low or anxious feelings still need a doctor's care.","why":"These tools point toward care; they don't replace a professional."},"relearn":"A breathing space and helpline are support and signposting, not treatment; lasting struggle still needs a doctor.","persona":"any","source":"tools aren't treatment"},
  {"id":"ly-1370","cat":"tools-and-help","type":"branch","persona":"Divya","source":"first move at 3am","hook":"It's 3am and the panic is huge. You don't know which tool to reach for first.","steps":[{"prompt":"Your heart is pounding in the dark. What do you do?","options":[{"text":"Breathe slowly, in and out, to steady yourself first","then":"Six slow breaths in, and the pounding softens a little.","best":true},{"text":"Scroll your phone in a spiral to distract yourself","then":"Bright screen, fast thumbs. The panic gets louder underneath."},{"text":"Search online for every symptom you can think of","then":"Every page names something worse. Your chest tightens again."},{"text":"Lie very still and wait for it to pass by itself","then":"You hold your breath and wait. The panic waits with you."}],"why":"Breathing steadies the body first, so you can reach for help."},{"prompt":"Some minutes pass, and the night still feels long. What do you do?","options":[{"text":"Call Tele-MANAS 14416 and say plainly how you feel","then":"A calm voice answers. \"Take your time. I'm here.\"","best":true},{"text":"Wake your partner and demand that he make it stop","then":"He wakes, dazed, and can't make it stop. He stays beside you, but the panic hasn't eased."},{"text":"Send long messages to friends who are fast asleep","then":"Nobody answers. The screen glows and the hour drags."},{"text":"Wait for morning and say nothing to anyone at all","then":"You lie there counting the minutes, as alone as when you began."}],"why":"Calling Tele-MANAS at night gives you a person, not just tips."},{"prompt":"An hour later you are still awake and wired. What do you do?","options":[{"text":"Put the phone down, breathe slowly and let yourself rest","then":"Your eyelids grow heavy, and sleep comes in pieces.","best":true},{"text":"Get up and clean the whole house to feel in control","then":"By dawn the house is spotless and you are wrung out."},{"text":"Keep scrolling on your phone until it gets light","then":"Dawn finds you hollow-eyed and wired."},{"text":"Drink strong chai to stay awake in case it returns","then":"Your heart races on the caffeine. Sleep slips further away."}],"why":"Rest and slow breathing are safe coping, and a calm body helps tomorrow."},{"prompt":"In the morning the night feels far away. What do you do?","options":[{"text":"Tell your partner or a friend, and book a doctor","then":"Your friend says she is glad you told her. The appointment is booked for Friday.","best":true},{"text":"Put it firmly behind you and never mention it again","then":"The night is closed. So is the door to help."},{"text":"Decide it was just a one-off and skip the doctor","then":"You shrug it off. The unease stays under the surface."},{"text":"Laugh about it with friends but say nothing real","then":"They laugh too. The honest part stays hidden."}],"why":"Telling someone in the daylight, and booking a doctor, keeps you from facing it alone."},{"prompt":"A week later the panic returns at night. What do you do?","options":[{"text":"Breathe first, then call Tele-MANAS 14416","then":"A calm voice answers. You steady faster than you expected.","best":true},{"text":"Tell yourself it came back because you have failed","then":"Shame joins the panic. The night feels heavier."},{"text":"Handle it silently because coping is your job alone","then":"You fight it alone again. Morning finds you exhausted."},{"text":"Skip the breathing steps and go straight to scrolling","then":"The spiral starts again, and the panic stays sharp."}],"why":"Breathing and a call are your tools, and needing them again is not failing."}],"debrief":"When you don't know where to start: breathe to steady yourself, then call Tele-MANAS 14416.","relearn":"When overwhelmed at night, breathe to steady yourself, then call Tele-MANAS 14416; calm-then-call is the first move."},
  {"id":"ly-1371","cat":"tools-and-help","type":"reflect","hook":"Lensy: a simple help-card, three numbers on the fridge, can do a lot on a day you can barely think. Make one?","prompt":"What do you think?","options":["I'll make one","On the fridge","Smart idea"],"affirm":"A help-card with a couple of numbers, where you'll see it, means that on a foggy day you don't have to remember anything to get help.","relearn":"A help-card with a few numbers, kept where you'll see it, means you needn't remember anything to get help on a foggy day.","persona":"any","source":"the help-card"},
  {"id":"ly-1372","cat":"tools-and-help","type":"match","hook":"Match each warm response to a parent in crisis with why it helps.","pairs":[{"left":"\"I'm here, you're not alone\"","right":"Calms the panic of facing it alone"},{"left":"\"Let's call someone together\"","right":"Turns a scary step into a shared one"},{"left":"\"This is a symptom, not your fault\"","right":"Lifts the shame that blocks help"},{"left":"\"We can get help any time\"","right":"Removes pressure to wait or hide"},{"left":"\"Tele-MANAS is there right now\"","right":"Points to a reachable route"}],"relearn":"Warmth plus a route, \"I'm here\", \"let's call\", \"not your fault\", \"Tele-MANAS now\", is how you meet a parent in crisis.","persona":"any","source":"warmth plus a route"},
  {"id":"ly-1373","cat":"tools-and-help","type":"sort","hook":"Sort each line you might say to a parent in crisis: warm and routing, or alarming and shaming?","items":[{"id":"a","text":"\"Let's call Tele-MANAS together right now\""},{"id":"b","text":"\"You'll ruin the baby feeling like this\""},{"id":"c","text":"\"You're not alone in this\""},{"id":"d","text":"\"Pull yourself together already\""},{"id":"e","text":"\"This is treatable; let's get help\""},{"id":"f","text":"\"What's wrong with you?\""}],"bins":[{"id":"warm","label":"Warm & routing","valence":"pos"},{"id":"harm","label":"Alarming & shaming","valence":"neg"}],"key":{"a":"warm","b":"harm","c":"warm","d":"harm","e":"warm","f":"harm"},"relearn":"Meet crisis with warmth and a route, \"let's call together\", \"not alone\", \"treatable\"; never alarm or shame like \"pull yourself together\".","persona":"any","source":"warm vs shaming"},
  {"id":"ly-1374","cat":"tools-and-help","type":"spot","hook":"Spot the two myths about these tools. Tap the two red flags.","scene":[{"id":"a","text":"\"A breathing space can ease a hard moment\"","trick":false},{"id":"b","text":"\"Saving a helpline means you're weak\"","trick":true},{"id":"c","text":"\"Knowing the routes early helps\"","trick":false},{"id":"d","text":"\"These tools cure depression alone\"","trick":true},{"id":"e","text":"\"112 is right for immediate danger\"","trick":false}],"why":"\"Saving a helpline means weak\" and \"these tools cure depression\" are the myths; the tools are strength and signposting, not a cure.","relearn":"Saving a helpline is strength, and these tools signpost, not cure; lasting struggle still needs a doctor.","persona":"any","source":"tool myths"},
  {"id":"ly-1375","cat":"tools-and-help","type":"role-play","persona":"Priya","source":"make it doable","hook":"Your new-parent friend Nisha says she'd never call a helpline.","setup":"You're having chai at her place.","steps":[{"prompt":"Nisha says: \"Calling a helpline feels too big for someone like me.\"","options":[{"text":"\"Tele-MANAS is a calm person to talk to. Ring 14416 after a rough week.\"","then":"Nisha smiles a little. \"A calm person. Maybe I'll save it tonight.\"","best":true},{"text":"\"Maybe leave it until things get really, really bad.\"","then":"Nisha nods, relieved. The number stays unsaved."},{"text":"\"Try a parenting app first. It feels less big than a phone call.\"","then":"Nisha likes that. The app gives tips, but nobody asks how she is."},{"text":"\"You're coping so well. I doubt you'll need any of that.\"","then":"Nisha laughs, pleased. She doesn't mention the nights she can't sleep."}],"why":"Calling it a calm person to talk to makes the first call feel doable."},{"prompt":"Nisha asks: \"Say I did call one day. What would I even say when they pick up?\"","options":[{"text":"\"Just say how you feel. \"It's been a rough week\" is enough to begin.\"","then":"Nisha nods slowly. \"That I can say.\"","best":true},{"text":"\"Write out a proper speech first so you sound sure of yourself when you call.\"","then":"Nisha groans. \"Then I'd never call.\""},{"text":"\"Say you're calling for a friend. It's easier that way.\"","then":"Nisha half smiles. She'd still be carrying it all herself."},{"text":"\"Wait until you know exactly what's wrong before calling them.\"","then":"Nisha nods. Without a name for it, the call keeps getting put off."}],"why":"One plain sentence about how you are is enough to start the call."},{"prompt":"Nisha says: \"Okay. Would you sit with me when I try it once?\"","options":[{"text":"\"Yes. Let's save the number now, and I'll sit with you when you call.\"","then":"Nisha saves it. \"Tonight, then, after the baby sleeps.\"","best":true},{"text":"\"Save the number and try it alone first. Tell me how it went afterwards.\"","then":"Nisha nods, but she looks a little let down."},{"text":"\"I'll wait outside. It's better if you do it on your own.\"","then":"Nisha's shoulders drop. Alone with the phone, she puts it down."},{"text":"\"Let's wait until you have something clear to say first.\"","then":"Nisha agrees. The clear thing never quite turns up."}],"why":"Company for the first call lowers the wall to trying it."}],"relearn":"Framing Tele-MANAS 14416 as just a calm person to talk to makes the first call feel doable, not a big dramatic step."},
  {"id":"ly-1376","cat":"tools-and-help","type":"branch","persona":"Divya","source":"three-step plan","hook":"You keep meaning to write down a support plan for hard days and never do.","steps":[{"prompt":"A quiet evening finally arrives. What do you do?","options":[{"text":"Jot three things: a breathing step, one person, one helpline","then":"It takes five minutes. The page sits by your bed, plain and ready.","best":true},{"text":"Tell yourself you'll remember every bit of it when the time comes","then":"The evening goes to scrolling. The plan stays half formed in your head."},{"text":"Look for the perfect app to organise it first","then":"An hour of reviews later, there is still no plan and the baby stirs."},{"text":"Ask a friend to keep your plan in her head","then":"She says of course. Nothing is written and the details stay vague."}],"why":"A short written plan is there when your mind is foggy. Memory often isn't."},{"prompt":"At four a.m. your head is foggy and the baby won't settle. What do you reach for first?","options":[{"text":"Breathe slowly, then message someone you trust","then":"Three slow breaths. Your shoulders drop and you send one short message.","best":true},{"text":"Try to recall what you had meant to do","then":"The fog wins. You can't find the steps and the panic rises a little."},{"text":"Scroll parenting forums for advice at that hour","then":"Ten tabs of clashing advice leave you more wound up than before."},{"text":"Breathe slowly and keep it to yourself","then":"Your breathing steadies, but the night still feels lonely and long."}],"why":"Breathing steadies you, and reaching a person means you aren't alone with it."},{"prompt":"Your sister Meera asks what you do on a hard day and how she can help. What do you say?","options":[{"text":"Name a calming step and a helpline, and ask her to be your person","then":"Meera nods and saves your number under favourites. \"Call any time.\"","best":true},{"text":"Say you're managing and she needn't worry","then":"Meera lets it go, though she watches you a little closely that day."},{"text":"Say you'll tell her if things ever get really bad","then":"She agrees. Neither of you knows what \"really bad\" would look like."},{"text":"Ask her to check on you daily and leave it at that","then":"She agrees warmly. Within a week the daily check-ins feel like a lot for one person."}],"why":"A full plan names your steps and your people, so no one person carries it."}],"debrief":"A written plan, a breathing step, one person, one helpline, beats remembering it on a hard day.","relearn":"Write a three-step plan: a breathing step, one person, one saved line. Memory fails on a foggy day."},
  {"id":"ly-1377","cat":"tools-and-help","type":"strike-rewrite","hook":"\"I should be able to calm myself down without any 'tools' or tricks.\"","myth":{"un":"I should be able to calm myself down without any 'tools' or tricks.","re":"Coping tools are skills anyone can use, not a sign of failing; even slowing your breath on purpose is a learned, sensible tool.","why":"Using a coping skill is competence, not weakness."},"relearn":"Coping tools are learnable skills, not a sign of failing; using one, like slowing your breath, is competence.","persona":"any","source":"tools are skills"},
  {"id":"ly-1378","cat":"tools-and-help","type":"match","hook":"Match each tool to the everyday moment it's made for.","pairs":[{"left":"Box breathing","right":"The panic of a screaming-baby moment"},{"left":"Saved doctor's number","right":"Weeks of low mood that won't lift"},{"left":"A trusted friend on speed-dial","right":"A lonely, heavy afternoon"},{"left":"Emergency 112","right":"A moment of real danger to anyone"},{"left":"A grounding walk outside","right":"Feeling trapped and overwhelmed indoors"}],"relearn":"Box breathing for panic, a saved doctor for lasting low mood, a friend for a lonely day, 112 for danger, a walk for feeling trapped.","persona":"any","source":"a tool for the moment"},
  {"id":"ly-1379","cat":"tools-and-help","type":"reflect","hook":"Lensy: you don't have to wait for a crisis to use any of these. Reaching for one early is the whole point. Agree?","prompt":"Your take?","options":["Agreed","Early is fine","That's the point"],"affirm":"Every tool here works best early, a breath, a call, a saved number, used before things pile up, not only once you're at the edge.","relearn":"Every tool here works best used early, before things pile up, not only at the edge; early is the whole point.","persona":"any","source":"use it early"},
  {"id":"ly-1380","cat":"tools-and-help","type":"sort","hook":"Sort each step of a help-finder: a first calming step, or a step that routes you onward?","items":[{"id":"a","text":"Take three slow grounding breaths"},{"id":"b","text":"Open your saved contacts list"},{"id":"c","text":"Splash water and steady yourself"},{"id":"d","text":"Tap Tele-MANAS 14416 to call"},{"id":"e","text":"Sit somewhere quiet for a minute"},{"id":"f","text":"Pick the right route for now"}],"bins":[{"id":"calm","label":"Calm yourself first","valence":"pos"},{"id":"route","label":"Route onward","valence":"tell"}],"key":{"a":"calm","b":"route","c":"calm","d":"route","e":"calm","f":"route"},"relearn":"A help-finder calms you first, breathe, splash water, sit quiet, then routes you onward, open contacts, call Tele-MANAS, pick a route.","persona":"any","source":"calm then route"},
  {"id":"ly-1381","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"nudge him","hook":"Your brother Anil, a new dad, brushes off saving any helplines.","setup":"You catch him after dinner.","steps":[{"prompt":"Anil says: \"I don't need helplines saved. That's for other people.\"","options":[{"text":"\"Save Tele-MANAS and a doctor. It takes a minute and you'll be glad.\"","then":"Anil shrugs, then pulls out his phone. \"Fine. Show me which one.\"","best":true},{"text":"\"Fair enough. It's your call, and you probably won't ever need them.\"","then":"Anil nods, relieved. The subject is closed."},{"text":"\"Dads handle this stuff better than most. You'll be fine.\"","then":"Anil grins. \"Exactly.\" He puts the phone away."},{"text":"\"I'll keep the numbers on my phone in case you ever need me.\"","then":"Anil nods. \"Sure.\" He still has nothing saved himself."}],"why":"Saved in advance, help is one tap away, and fathers struggle too."},{"prompt":"Anil says: \"Honestly, I barely sleep and I snap at everyone. That's just dad life.\"","options":[{"text":"\"That sounds heavy, and dads struggle too. Would you see a doctor?\"","then":"Anil goes quiet. \"Maybe. I didn't think it counted for men.\"","best":true},{"text":"\"Everyone's tired. It gets easier once he sleeps through.\"","then":"Anil nods. \"Yeah, that's what I figured.\""},{"text":"\"Then get more sleep and cut back on your phone in the evenings.\"","then":"Anil bristles. \"I know that. It's not so simple.\""},{"text":"\"Don't tell Mum. She'll fuss and make it worse for you.\"","then":"Anil laughs, relieved. \"Right. Between us.\""}],"why":"Saying dads struggle too, and suggesting a doctor, keeps the door open."},{"prompt":"Anil asks: \"Say I do have Tele-MANAS saved. When would I actually use it?\"","options":[{"text":"\"A bad night, or feeling low for days. Call Tele-MANAS or the doctor.\"","then":"Anil nods slowly. \"A bad night counts. Okay, good to know.\"","best":true},{"text":"\"Only if things get really serious. Not before that point.\"","then":"Anil nods. \"So, never, hopefully.\""},{"text":"\"For me, really. You just call me first and I'll deal with it.\"","then":"Anil smiles. \"Easy. But you're not always around.\""},{"text":"\"You'll know when it happens. There's no need to plan it.\"","then":"Anil shrugs and pockets his phone. It still feels like it isn't for him."}],"why":"A clear use, from a bad night to lasting low mood, makes it feel doable."}],"relearn":"Encouraging a new dad to save Tele-MANAS and a doctor now means help is one tap away if a hard day comes; fathers struggle too."},
  {"id":"ly-1382","cat":"tools-and-help","type":"branch","persona":"Divya","source":"booked together","hook":"Your mood has been heavy for weeks, and you keep putting off calling a doctor.","steps":[{"prompt":"Your friend Asha offers to sit with you while you make the call. What do you say?","options":[{"text":"Say yes and ask her to stay beside you","then":"Asha pulls a chair close. The call takes ten minutes and a slot is booked.","best":true},{"text":"Say you'll do it yourself later on","then":"Asha nods kindly. Another week goes by and the call stays unmade."},{"text":"Say it's probably tiredness and not worth a doctor","then":"Asha hesitates, then lets it go. The heaviness follows you home."},{"text":"Say yes, then find a reason to be busy when she comes","then":"Asha arrives to find you mid-chores. The call slips to another day."}],"why":"A shared first step is much easier to take than a solo one."},{"prompt":"Your partner Rohan notices you've gone quiet again and asks if you're alright. What do you say?","options":[{"text":"Tell him it's been heavy for weeks and you want a doctor's help","then":"Rohan takes your hand. \"I'm glad you told me. Can I come with you?\"","best":true},{"text":"Say it's been a long week and leave it there","then":"Rohan nods. The real worry stays unspoken between you."},{"text":"Say you don't want to worry him with it","then":"He says he'd rather know. You change the subject anyway."},{"text":"Say you'll tell him once you've sorted it out alone","then":"He agrees, but he doesn't know how to help while you keep it to yourself."}],"why":"Saying it plainly lets him help, and how you feel is never your fault."},{"prompt":"A week on, the heaviness is still there and the doctor is still on your mind. What do you do?","options":[{"text":"Ask Rohan to come with you to the doctor","then":"Rohan says yes at once and clears his Thursday.","best":true},{"text":"Give it one more week to see if it lifts","then":"The week passes. The mood is the same, and the next step feels heavier."},{"text":"Read symptoms online and decide it isn't serious","then":"Forums point both ways. You close the tab no clearer than before."},{"text":"Go for a long walk and call that enough","then":"The walk clears your head for an hour. The heaviness is waiting when you return."}],"why":"Going with support turns a stalled intention into a real step."}],"debrief":"Accepting help with the first step, like booking a doctor together, turns a stalled intention into action.","relearn":"Let a friend help with the first step, like booking a doctor together; a shared step beats a stalled \"later\"."},
  {"id":"ly-1383","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Once I've used the breathing space, the bad feeling should be gone for good.\"","myth":{"un":"Once I've used the breathing space, the bad feeling should be gone for good.","re":"A grounding space calms one moment, not the whole struggle; if low or anxious feelings keep coming back, that's a cue to reach for more help.","why":"A breathing space settles a moment; lasting feelings still need real support."},"relearn":"A grounding space calms a moment, not the whole struggle; if hard feelings keep returning, reach for more help.","persona":"any","source":"calms a moment"},
  {"id":"ly-1384","cat":"tools-and-help","type":"reflect","hook":"Lensy: the bravest, most useful thing on a kit isn't a number; it's letting yourself actually use it. True for you?","prompt":"What's your take?","options":["True","I'll use it","Letting myself"],"affirm":"A saved number, a breathing space, a doctor only help if you let yourself reach for them; giving yourself that permission is the real tool.","relearn":"Tools only help if you let yourself use them; giving yourself permission to reach for help is the real tool.","persona":"any","source":"permission to use it"},
  {"id":"ly-1385","cat":"tools-and-help","type":"match","hook":"Match each India support to the one line that describes it best.","pairs":[{"left":"Tele-MANAS 14416","right":"A mental-health line to talk any time"},{"left":"A parents' support group","right":"Others who've been through it"},{"left":"Your family doctor","right":"Assessment and ongoing care"},{"left":"Emergency 112","right":"Immediate danger to anyone"},{"left":"A trusted person","right":"Everyday listening and a hand"}],"relearn":"Tele-MANAS to talk any time, a doctor for care, a parents' group for company, 112 for danger, a trusted person for everyday help.","persona":"any","source":"who is who"},
  {"id":"ly-1386","cat":"tools-and-help","type":"spot","hook":"Spot the two unsafe 'coping tools' to drop from the kit. Tap the two red flags.","scene":[{"id":"a","text":"A slow grounding breath","trick":false},{"id":"b","text":"Skipping meals to 'tough it out'","trick":true},{"id":"c","text":"A short walk for fresh air","trick":false},{"id":"d","text":"Punishing yourself for not coping","trick":true},{"id":"e","text":"Calling someone who cares","trick":false}],"why":"Skipping meals to tough it out and self-punishment are unsafe; a tool must never involve harm or discomfort, only rest, breath, movement and connection.","relearn":"Drop any 'tool' that involves harm, like skipping meals or self-punishment; safe tools are breath, movement, rest and connection.","persona":"any","source":"drop the unsafe"},
  {"id":"ly-1387","cat":"tools-and-help","type":"role-play","persona":"Divya","source":"the agreed plan","hook":"You've never told your partner Jay what to do if you say you can't cope.","setup":"You bring it up on a quiet evening.","steps":[{"prompt":"Jay asks: \"What would you want me to do if you said you couldn't cope?\"","options":[{"text":"\"Breathe with me, then call Tele-MANAS or our doctor. Please don't leave.\"","then":"Jay nods. \"Breathe, then call. I won't leave.\"","best":true},{"text":"\"We'll deal with it somehow if it ever happens.\"","then":"Jay says okay, though he looks unsure what \"somehow\" means."},{"text":"\"Tell me I'm fine and that it will pass.\"","then":"Jay nods. \"I can do that.\" He doesn't ask what else you'd need."},{"text":"\"Call my mother straight away and let her sort the whole thing out for us.\"","then":"Jay agrees. Your mother is far away and has no doctor's number."}],"why":"Agreeing in advance makes help fast and certain."},{"prompt":"Jay says: \"What if I get it wrong and say the wrong thing?\"","options":[{"text":"\"You can't get it wrong by staying close. Breathe with me, then call.\"","then":"Jay lets out a breath. \"Staying close. That I can do.\"","best":true},{"text":"\"Then it's better if you leave me alone until I calm down.\"","then":"Jay nods. It sounds lonely, but he goes along with it."},{"text":"\"Then try to fix it. Have a list of things ready to try.\"","then":"He looks worried. \"I don't know what to put on that list.\""},{"text":"\"Say whatever comes to mind. It doesn't matter much what.\"","then":"Jay nods, unsure. He would like some kind of guide."}],"why":"Staying close and calling is enough. There's no perfect script."},{"prompt":"Jay asks: \"Should we write this down somewhere?\"","options":[{"text":"\"Yes. Put it in our notes on both phones, with the numbers.\"","then":"Jay types it in. \"Done. Both phones now.\"","best":true},{"text":"\"It's fine. We'll remember it when we need it.\"","then":"Jay smiles. Two weeks later, neither of you is sure of the steps."},{"text":"\"Only you keep a copy. I'd rather not have to look at it.\"","then":"Jay nods. The plan lives on one phone and is easy to miss."},{"text":"\"Let's write it once we have more time to sit down.\"","then":"Jay agrees. The evening goes by without anything written."}],"why":"A note both of you can see makes the plan quick to use."}],"relearn":"Agreeing in advance what your partner does if you can't cope, breathe together, call Tele-MANAS or a doctor, makes help fast and certain."},
  {"id":"ly-1388","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Crisis lines are only for thoughts of suicide; my struggle doesn't count.\"","myth":{"un":"Crisis lines are only for thoughts of suicide; my struggle doesn't count.","re":"Tele-MANAS 14416 is for any mental-health struggle, low mood, anxiety, exhaustion, not only the very worst moments; your struggle counts.","why":"These lines support the whole range of distress, not only the extreme end."},"relearn":"Tele-MANAS 14416 is for any struggle, low mood, anxiety, exhaustion, not only the worst moments; your struggle counts.","persona":"any","source":"your struggle counts"},
  {"id":"ly-1389","cat":"tools-and-help","type":"branch","persona":"any","source":"keep them ready","hook":"After a rough week you feel calmer, and the helplines you saved start to look unnecessary.","steps":[{"prompt":"You're tidying your phone on a calm Sunday. What do you do with the saved helplines?","options":[{"text":"Keep them all where you can reach them at once","then":"They stay in your favourites. It costs you nothing, and you forget them for now.","best":true},{"text":"Delete them since you feel fine now","then":"The list is tidier. You don't think of them again."},{"text":"Bury them in a folder under old apps","then":"They're still on the phone, though finding them would take a while."},{"text":"Keep your doctor's number and delete the helplines","then":"The list is shorter. The late-night line is no longer one tap away."}],"why":"A calm week doesn't mean you won't want them, and one tap is quicker than a search."},{"prompt":"A week on, a friend at the park says helplines are for people in real trouble. What do you say?","options":[{"text":"Say they're for ordinary hard days too, and offer to show her","then":"She laughs, unsure, then hands you her phone. \"Go on, show me.\"","best":true},{"text":"Agree, since you had been thinking the same","then":"She nods. Both of you go home believing help is for someone else."},{"text":"Change the subject to avoid a debate","then":"The talk moves to the baby's teething. Her doubt stays where it was."},{"text":"Say it's each to their own, and shrug","then":"She smiles and says she is fine without. The idea slips past her."}],"why":"Saying help is for ordinary days makes it easier for others to reach for it."},{"prompt":"A month on, a hard night comes and your head is foggy. What do you do first?","options":[{"text":"Breathe, then call a saved number or your person","then":"You breathe, open your phone and press call. A calm voice answers.","best":true},{"text":"Search the web for a helpline number","then":"Results crowd the screen. Twenty minutes pass before you find a line that answers."},{"text":"Tell yourself it's one bad night and lie awake","then":"The hours crawl. Morning finds you more drained than the night started."},{"text":"Wait until morning to text your person","then":"You lie awake rehearsing the message. By morning you're too tired to send it."}],"why":"Breathing first steadies you, and a saved number makes the call quick."}],"debrief":"Keep saved supports even when you feel fine; self-care is ongoing, and a ready kit beats rebuilding it.","relearn":"Keep saved supports even on good weeks; self-care is ongoing, and a ready kit beats rebuilding it."},
  {"id":"ly-1390","cat":"tools-and-help","type":"reflect","hook":"Lensy: a help-finder is just a kind way of saying 'here's where to turn', so you never face it blank. Reassuring?","prompt":"Your take?","options":["Reassuring","Never blank","Good to have"],"affirm":"A help-finder isn't a sign anything's wrong; it's a calm map of where to turn, kept ready so a hard day never finds you blank.","relearn":"A help-finder is a calm map of where to turn, kept ready so a hard day never finds you blank; that's reassurance, not alarm.","persona":"any","source":"a calm map"},
  {"id":"ly-1391","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"for all of us","hook":"At a parents' meet-up, the talk turns to mental health helplines.","setup":"Ritu, a mother of two, waves the idea away.","steps":[{"prompt":"Ritu says: \"Helplines are for other people, not people like us.\"","options":[{"text":"\"They're for all of us. I've saved Tele-MANAS and it eased bad nights.\"","then":"Ritu blinks. \"You've actually saved it? Huh. Show me.\"","best":true},{"text":"\"Maybe you're right. They're probably not for people like us.\"","then":"Ritu nods. The others nod too, and the talk moves on."},{"text":"\"Some people find them useful. I suppose it's up to each person.\"","then":"Ritu shrugs. \"Exactly. Up to them.\""},{"text":"\"Let's not get into it. This is a meet-up, not a debate.\"","then":"Ritu smiles, relieved. A few others look like they wanted to speak."}],"why":"Helplines are for everyone, and saying you use one takes the fear out."},{"prompt":"Later, over tea, Ritu asks in a low voice: \"What do people even say when they call? I'd feel silly.\"","options":[{"text":"\"You just say how you are. Nobody there thinks it's silly.\"","then":"Ritu tilts her head. \"Really? There's no script?\"","best":true},{"text":"\"Yes, it can feel silly. Better to wait until it's serious.\"","then":"Ritu nods. \"Then I'll wait. Maybe for months.\""},{"text":"\"Just say a friend needs help. That's easier to start with.\"","then":"Ritu likes that. She'd still be keeping her own feelings to herself."},{"text":"\"Honestly, talking to family works just as well, so skip it.\"","then":"Ritu relaxes. Not everyone at home is easy to talk to."}],"why":"One plain sentence about how you are is enough, and nobody there judges."},{"prompt":"Another parent, Dev, quietly asks: \"Is it really okay for a dad to call?\"","options":[{"text":"\"Yes. Fathers struggle too. Save it now so help is one tap away.\"","then":"Dev nods slowly. \"Okay. Show me how to save it.\"","best":true},{"text":"\"Sure, but dads usually manage fine without one, to be honest.\"","then":"Dev's shoulders drop. \"Right. That's what I thought.\""},{"text":"\"It's mostly for mothers, but you can try if you want.\"","then":"Dev half smiles. \"Maybe not, then.\""},{"text":"\"Call if you must, but don't tell anyone at work about it.\"","then":"Dev nods. The call feels like a secret to be ashamed of."}],"why":"Fathers struggle too, and saving the line early makes reaching out easier."}],"relearn":"Helplines are for everyone, not 'other people'; saying you've saved Tele-MANAS normalises it and takes fear out of a bad night."},
  {"id":"ly-1392","cat":"tools-and-help","type":"branch","persona":"Divya","source":"book the doctor","hook":"You've felt low since the baby came and keep wondering how long is too long.","steps":[{"prompt":"The baby is now a couple of months old and the heaviness hasn't lifted. What do you do?","options":[{"text":"Book the doctor with a short note on how you've felt","then":"You book for Thursday. The note has four lines and feels like a first step.","best":true},{"text":"Tell yourself it'll surely lift any day now, like it does for others","then":"The days pass. The story stays the same, and so does the mood."},{"text":"Wait until the baby sleeps through the night before doing anything","then":"The nights don't shorten. Your mood stays low, and the wait stretches on."},{"text":"Let your mother-in-law decide whether you need a doctor","then":"She listens kindly but isn't sure. The decision drifts, and so do the weeks."}],"why":"Low mood lasting past the early weeks is a cue to see a doctor, and a note helps."},{"prompt":"Your partner Nikhil asks how you've been sleeping and eating lately. What do you say?","options":[{"text":"Tell him plainly how low you've felt and how long","then":"Nikhil listens without interrupting. \"Let me help. I can take the baby so you can see a doctor.\"","best":true},{"text":"Say you're just tired and there's nothing more to say","then":"He nods and lets it go. Nothing shifts between you."},{"text":"Say you'd rather not go into all of that right now","then":"He respects that, but the heaviness stays yours alone."},{"text":"Say you'll explain once you've seen a doctor","then":"He agrees, yet he can't help until he knows what is going on."}],"why":"Telling him plainly brings support, and how you feel is never your fault."},{"prompt":"At a family lunch your aunt kindly says a mother's mood settles on its own with rest. What do you do?","options":[{"text":"Say you'd still like a doctor's opinion","then":"She shrugs, and your uncle quietly asks if you need a lift to the clinic.","best":true},{"text":"Nod along and quietly drop the idea of seeing anyone","then":"The lunch goes smoothly. On the way home the heaviness feels heavier."},{"text":"Argue until the table goes quiet","then":"Voices rise and lunch ends early. Your aunt is offended and nothing is settled."},{"text":"Agree with her and plan to wait another month","then":"Everyone relaxes. A month later, you're in the same place."}],"why":"Kindly holding your ground protects your care without a family fight."}],"debrief":"Lasting low mood past the early weeks is a cue to see a doctor; a note of how you've felt eases the visit.","relearn":"Lasting low mood past the early weeks is a cue to book a doctor; a note of how you've felt eases the visit."},
  {"id":"ly-1393","cat":"tools-and-help","type":"match","hook":"Match each first sign you should reach for help to the tool that fits.","pairs":[{"left":"A wave of panic right now","right":"A breathing or grounding space"},{"left":"Weeks of heavy, unlifting mood","right":"A doctor's appointment"},{"left":"A night you just can't be alone","right":"Tele-MANAS 14416 to talk"},{"left":"Immediate danger to you or baby","right":"Emergency 112, right away"},{"left":"Not knowing where to begin","right":"Your saved help-finder"}],"relearn":"Panic to a breathing space, lasting low mood to a doctor, a hard night to Tele-MANAS, danger to 112, feeling lost to your help-finder.","persona":"any","source":"sign to tool"},
  {"id":"ly-1394","cat":"tools-and-help","type":"reflect","hook":"Lensy: reaching for a tool on a hard day isn't giving up; it's exactly what the tool is for. Let that land?","prompt":"What do you think?","options":["It lands","Not giving up","That's the point"],"affirm":"Using a breathing space or making a call on a hard day is the kit working as intended, the opposite of giving up; it's looking after yourself.","relearn":"Using a tool on a hard day is the kit working as intended, not giving up; it's looking after yourself.","persona":"any","source":"not giving up"},
  {"id":"ly-1395","cat":"tools-and-help","type":"sort","hook":"Sort each statement about these tools: true, or a myth to drop?","items":[{"id":"a","text":"A breathing space can ease a hard moment"},{"id":"b","text":"Saving a helpline means you're weak"},{"id":"c","text":"You can call Tele-MANAS just to talk"},{"id":"d","text":"These tools can replace a doctor"},{"id":"e","text":"112 is right for immediate danger"},{"id":"f","text":"You must be in crisis to reach out"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth to drop","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"True: a breathing space helps, you can call Tele-MANAS to talk, 112 is for danger. Myths: saving a line is weak, tools replace a doctor.","persona":"any","source":"true or myth"},
  {"id":"ly-1396","cat":"tools-and-help","type":"strike-rewrite","hook":"\"I'll set up my support kit later, once I'm less busy.\"","myth":{"un":"I'll set up my support kit later, once I'm less busy.","re":"The busy, depleted stretch is exactly when you'll want it; a few minutes now to save a line and a doctor pays off on the worst day.","why":"A kit set up in a calm moment is ready when a hard one arrives."},"relearn":"Set up your support kit now, not 'once less busy'; a few calm minutes saving a line and a doctor pay off on the worst day.","persona":"any","source":"set it up now"},
  {"id":"ly-1397","cat":"tools-and-help","type":"role-play","persona":"Priya","source":"i'll dial with you","hook":"Your partner Ravi is clearly struggling and won't reach out.","setup":"You sit down beside him.","steps":[{"prompt":"Ravi says: \"I'm fine. I don't need to talk to anyone.\"","options":[{"text":"\"You don't have to call alone. I'll dial Tele-MANAS and sit with you.\"","then":"Ravi looks at his hands. \"Okay. Maybe. You'd stay?\"","best":true},{"text":"\"Let me know if you ever decide you want to call someone at all.\"","then":"Ravi nods. The days go by and he doesn't bring it up."},{"text":"\"Fine. I'm worried, so I'll ring your mother about you.\"","then":"Ravi tenses. \"Don't. I didn't ask you to.\""},{"text":"\"You need to be strong for the baby. Try to cheer up.\"","then":"Ravi's jaw sets. He goes quiet and turns away."}],"why":"Offering to make the call together and sit with him lowers the wall."},{"prompt":"Ravi says quietly: \"Say I did call someone. What would I even tell them?\"","options":[{"text":"\"You don't need the right words. Just say how the weeks have felt.\"","then":"Ravi lets out a long breath. \"Heavy. Just heavy.\"","best":true},{"text":"\"Then let's wait until you know what's wrong with you.\"","then":"Ravi nods. Without a name for it, the call keeps waiting."},{"text":"\"Say you're calling for a friend, if that's easier for you to start.\"","then":"Ravi almost smiles. The call would still leave his own feelings unsaid."},{"text":"\"I'll do the talking for you. You just sit and listen.\"","then":"Ravi pulls back. \"It's my life. I'd like to speak.\""}],"why":"A few honest words about how it has felt are enough to begin."},{"prompt":"Ravi asks: \"And what if they say I should see a doctor?\"","options":[{"text":"\"Then we book it together. Seeing a doctor early helps.\"","then":"Ravi nods. \"Together. Okay.\"","best":true},{"text":"\"Then say you'll think about it and we'll drop it for now.\"","then":"Ravi agrees. The idea drifts away with the evening."},{"text":"\"Then we'll see whether it gets worse first, and then decide.\"","then":"Ravi nods. Waiting sounds easier, and it's also heavier."},{"text":"\"Then I'll book it and simply tell you the date and time.\"","then":"Ravi frowns. \"I'd like to be part of choosing it.\""}],"why":"Booking together makes the next step shared and doable."}],"relearn":"Offering to make the call together, and to sit with them, lowers the wall to reaching out when a struggling partner can't start alone."},
  {"id":"ly-1398","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"build it in one go","hook":"You've got a quiet ten minutes to build your whole support kit.","setup":"You tell your partner Zoya the plan.","steps":[{"prompt":"Zoya asks: \"What should we set up first?\"","options":[{"text":"\"Let's do it all now: a breathing step, two people, doctor, Tele-MANAS.\"","then":"Zoya grabs a pen. \"Ten minutes. Breathing step first.\"","best":true},{"text":"\"Let's do the breathing step now and leave the rest for another day.\"","then":"Zoya nods. The rest waits, and no other day is chosen."},{"text":"\"Let's start with Tele-MANAS and add the rest over the next year.\"","then":"Zoya agrees. The rest keeps sliding down the list."},{"text":"\"Let's ask my sister to put a kit together for us instead.\"","then":"Zoya frowns. \"It should be ours. We're the ones who'd use it.\""}],"why":"Doing it all at once leaves no gaps for a hard day."},{"prompt":"Zoya asks: \"When we add people, who should we put down?\"","options":[{"text":"\"Two we trust who pick up at any hour and won't judge us.\"","then":"Zoya thinks. \"Meera and your brother. I'll message them tonight.\"","best":true},{"text":"\"Anyone who lives nearby. Distance matters most on a bad day.\"","then":"Zoya writes three names. Two of them never answer late."},{"text":"\"Your parents. Mine would only worry and start advising us.\"","then":"Zoya sighs. \"Then it's only my family. That feels lopsided.\""},{"text":"\"Whoever is free tonight. We can swap them later if needed.\"","then":"Zoya writes the names. \"Later\" never comes."}],"why":"Trusted, reachable people make the kit work at any hour."},{"prompt":"Zoya asks: \"Should we check it all before we stop?\"","options":[{"text":"\"Yes. Let's check each saved number once so it feels familiar.\"","then":"Zoya checks them and finds one number has a typo. She fixes it.","best":true},{"text":"\"No need. If we saved them, they'll work.\"","then":"Zoya smiles. Weeks later, one number turns out to be wrong."},{"text":"\"Let's check them later when we're calmer and less tired.\"","then":"She agrees. The check waits, and any mistakes stay hidden."},{"text":"\"I'll check them alone tomorrow. No need for both of us.\"","then":"Zoya nods. Only you know how the kit works."}],"why":"A quick check means the kit works when you're tired and foggy."}],"relearn":"Build the whole kit in one sitting: a breathing step, people, a doctor and Tele-MANAS. It leaves no gaps for a hard day."},
  {"id":"ly-1399","cat":"tools-and-help","type":"spot","hook":"Spot the two things that make a support kit useless. Tap the two red flags.","scene":[{"id":"a","text":"Numbers saved as phone favourites","trick":false},{"id":"b","text":"Numbers buried in a drawer you forget","trick":true},{"id":"c","text":"A breathing step you've practised","trick":false},{"id":"d","text":"A kit you're too ashamed to use","trick":true},{"id":"e","text":"A partner who knows the plan too","trick":false}],"why":"Numbers buried out of reach and a kit shame won't let you use are useless; keep it reachable and let yourself use it.","relearn":"A kit fails if it's buried out of reach or shame won't let you use it; keep it reachable and let yourself use it.","persona":"any","source":"useless kit"},
  {"id":"ly-1400","cat":"tools-and-help","type":"role-play","persona":"any","source":"plan in one line","hook":"You've made a plan for hard days, and your friend Leela wants one too.","setup":"You're walking home from the park.","steps":[{"prompt":"Leela asks: \"So what's your help plan? Keep it short.\"","options":[{"text":"\"Breathe, then call my person or Tele-MANAS. 112 if anyone's in danger.\"","then":"Leela repeats it. \"Breathe, call, 112. Easy enough to remember.\"","best":true},{"text":"\"It's a bit complicated. I'll explain it all properly some other time.\"","then":"Leela shrugs. \"Okay.\" The plan stays unshared."},{"text":"\"I just keep everything on my phone and hope for the best.\"","then":"Leela nods. Hoping is not quite a plan, and she can tell."},{"text":"\"I've got a huge plan with about twelve steps. It's in a folder.\"","then":"Leela laughs. \"Twelve? I'd never remember that at midnight.\""}],"why":"A plan you can say in one line is one you'll use when stressed."},{"prompt":"Leela says: \"What if my head goes blank on a bad night?\"","options":[{"text":"\"Write your steps on a note by your bed and on your phone.\"","then":"Leela nods. \"Two places. I'll do that tonight.\"","best":true},{"text":"\"You'll remember when it matters. Most people do once it's happening.\"","then":"Leela nods. On a bad night, the blank still comes."},{"text":"\"Keep the steps on your phone only. It's always with you.\"","then":"Leela agrees. The phone is across the room at four a.m."},{"text":"\"Then just wait it out until morning and try again.\"","then":"Leela sighs. Waiting alone is hard."}],"why":"A note in two places works even when your mind goes blank."},{"prompt":"Leela asks: \"And who should I be calling on a bad night?\"","options":[{"text":"\"Someone who picks up at any hour, won't judge and knows the plan.\"","then":"Leela thinks. \"My cousin Nandini. She'd never judge me.\"","best":true},{"text":"\"Whoever is closest in the family, whether or not they listen.\"","then":"Leela nods. \"My mother, then. Though she doesn't always listen.\""},{"text":"\"Anyone who lives nearby, since they can reach you fastest.\"","then":"Leela agrees. Being close by isn't the same as being kind."},{"text":"\"A kind friend, even if you haven't told her about the plan.\"","then":"Leela nods. A kind friend who doesn't know the plan can't act on it."}],"why":"A person who knows your plan and won't judge can act fast."}],"relearn":"A help plan you can say in one line, breathe, call your person or Tele-MANAS, 112 for danger, is one you'll actually use under stress."},
  {"id":"ly-1402","cat":"tools-and-help","type":"spot","hook":"Spot the two habits that leave a tool unused. Tap the two red flags.","scene":[{"id":"a","text":"Practising one slow breath on calm days","trick":false},{"id":"b","text":"Only ever planning to use it 'someday'","trick":true},{"id":"c","text":"Trying the help-finder once when calm","trick":false},{"id":"d","text":"Saving a number then forgetting it","trick":true},{"id":"e","text":"Telling a friend you've set it up","trick":false}],"why":"Always-someday and save-then-forget leave a tool unused; practising calm, trying it once and telling a friend make it familiar.","relearn":"Practising a tool on a calm day makes it familiar; only-someday or save-then-forget leave it unused.","persona":"any","source":"practise small"},
  {"id":"ly-1403","cat":"tools-and-help","type":"match","hook":"Match each private worry to a discreet way to reach support.","pairs":[{"left":"You don't want family to know yet","right":"Call Tele-MANAS 14416 quietly"},{"left":"You can't speak freely at home","right":"Step out for a walk and call"},{"left":"You'd rather not give a name","right":"A helpline you needn't identify on"},{"left":"You'd rather start in writing","right":"Note your symptoms for the doctor"},{"left":"You need a moment to yourself","right":"A breathing space, no one need know"}],"relearn":"You can reach support privately, a quiet call, a walk, a note for the doctor; you needn't explain yourself to anyone.","persona":"any","source":"quietly yours"},
  {"id":"ly-990","cat":"your-needs-count","type":"strike-rewrite","hook":"\"A good mother never needs a single moment away from her baby.\"","myth":{"un":"A good mother never needs a single moment away from her baby.","re":"Needing a short break is normal and human; a refilled parent comes back warmer, not worse.","why":"A rested parent has more patience to give."},"relearn":"Needing a short break from your baby is human, not bad mothering; you return with more to give.","persona":"Divya","source":"break is human"},
  {"id":"ly-991","cat":"your-needs-count","type":"strike-rewrite","hook":"\"Once you're a father, hobbies and friends are just selfish habits to drop.\"","myth":{"un":"Once you're a father, hobbies and friends are just selfish habits to drop.","re":"Keeping a hobby and a friend or two keeps you a whole person, which makes you a steadier dad.","why":"A father with a full life models one for his kids."},"relearn":"Keeping a hobby and friendships isn't selfish for a dad; staying whole makes you steadier.","persona":"Vikram","source":"dad stays whole"},
  {"id":"ly-992","cat":"your-needs-count","type":"strike-rewrite","hook":"\"Asking your family to share the load means you've failed as a parent.\"","myth":{"un":"Asking your family to share the load means you've failed as a parent.","re":"Accepting and asking for help with the load is meeting your needs wisely, not failing at them.","why":"Humans were never meant to raise children alone."},"relearn":"Asking family to share the load is meeting a real need, not a failure.","persona":"any","source":"share the load"},
  {"id":"ly-993","cat":"your-needs-count","type":"strike-rewrite","hook":"\"Wanting to feel like yourself again means you regret having a child.\"","myth":{"un":"Wanting to feel like yourself again means you regret having a child.","re":"Missing your old self and loving your child are not in conflict; both can be true at once.","why":"You can adore your baby and still miss who you were."},"relearn":"Missing your old self doesn't mean you regret your child; both feelings can sit together.","persona":"Divya","source":"both can be true"},
  {"id":"ly-994","cat":"your-needs-count","type":"strike-rewrite","hook":"\"A little time for your own interests is time stolen from your child.\"","myth":{"un":"A little time for your own interests is time stolen from your child.","re":"A little time of your own isn't stolen; it refills you so the hours with your child are warmer.","why":"What refills you is given back to your family."},"relearn":"A little time for your own interests isn't stolen from your child; it refills you for them.","persona":"any","source":"not stolen time"},
  {"id":"ly-995","cat":"your-needs-count","type":"strike-rewrite","hook":"\"Putting your needs anywhere but dead last makes you a bad parent.\"","myth":{"un":"Putting your needs anywhere but dead last makes you a bad parent.","re":"Your needs can sit alongside your child's, not always dead last; a depleted parent has less to give.","why":"Needs always coming last ends in burnout."},"relearn":"Your needs needn't always come dead last; meeting some of them keeps you from running empty.","persona":"Divya","source":"not dead last"},
  {"id":"ly-996","cat":"your-needs-count","type":"strike-rewrite","hook":"\"If the in-laws disapprove of you resting, you must just push through.\"","myth":{"un":"If the in-laws disapprove of you resting, you must just push through.","re":"You can respect your elders and still protect a little rest; their approval isn't worth your collapse.","why":"Pushing past empty serves no one in the home."},"relearn":"You can honour your elders and still protect rest; their disapproval isn't worth running yourself empty.","persona":"any","source":"rest and respect"},
  {"id":"ly-997","cat":"your-needs-count","type":"strike-rewrite","hook":"\"A parent who keeps their career or studies alive is neglecting the family.\"","myth":{"un":"A parent who keeps their career or studies alive is neglecting the family.","re":"Keeping your work or studies alive protects your identity and future; it isn't neglect.","why":"A parent with a self of their own parents more steadily."},"relearn":"Keeping your career or studies alive protects who you are; it isn't neglecting your family.","persona":"Priya","source":"identity matters"},
  {"id":"ly-998","cat":"your-needs-count","type":"strike-rewrite","hook":"\"Feeling guilty for having needs proves the needs are wrong.\"","myth":{"un":"Feeling guilty for having needs proves the needs are wrong.","re":"Guilt is a common feeling to learn to set down, not proof; needing things is legitimate.","why":"A feeling of guilt isn't a verdict on the need."},"relearn":"Guilt over having needs is common and learnable to set down; it doesn't make the needs wrong.","persona":"Divya","source":"guilt isn't proof"},
  {"id":"ly-999","cat":"your-needs-count","type":"strike-rewrite","hook":"\"Real parents give until there's nothing left of themselves.\"","myth":{"un":"Real parents give until there's nothing left of themselves.","re":"Giving until nothing's left isn't the goal; a parent who keeps something of themselves lasts the distance.","why":"You can't pour from an empty cup."},"relearn":"Real parenting isn't giving until you vanish; keeping some of yourself helps you go the distance.","persona":"any","source":"keep some self"},
  {"id":"ly-1000","cat":"your-needs-count","type":"strike-rewrite","hook":"\"Wanting an evening with your partner, without the baby, is irresponsible.\"","myth":{"un":"Wanting an evening with your partner, without the baby, is irresponsible.","re":"Tending your relationship is a real need too; a connected couple is steadier ground for a child.","why":"The couple is part of the home a child grows in."},"relearn":"Wanting an evening as a couple isn't irresponsible; a connected partnership steadies the whole home.","persona":"Vikram","source":"tend the couple"},
  {"id":"ly-1001","cat":"your-needs-count","type":"sort","hook":"Sort each line: keeps your sense of self alive, or quietly erases it?","items":[{"id":"a","text":"Texting one friend each week"},{"id":"b","text":"Dropping every interest you had"},{"id":"c","text":"Saying your own name to yourself"},{"id":"d","text":"Cancelling everything that was yours"},{"id":"e","text":"Keeping a song you love on"},{"id":"f","text":"Becoming only 'baby's parent'"}],"bins":[{"id":"keep","label":"Keeps your self","valence":"pos"},{"id":"erase","label":"Erases your self","valence":"neg"}],"key":{"a":"keep","b":"erase","c":"keep","d":"erase","e":"keep","f":"erase"},"relearn":"A friend, an interest, a song, your own name kept alive hold your self; dropping everything erases it.","persona":"any","source":"self alive"},
  {"id":"ly-1002","cat":"your-needs-count","type":"sort","hook":"Sort: a guilt-free way to meet a need, or a guilt trap to step out of?","items":[{"id":"a","text":"Resting while the baby naps"},{"id":"b","text":"\"I must earn any rest first\""},{"id":"c","text":"Letting your partner cook tonight"},{"id":"d","text":"\"Needing help means I'm weak\""},{"id":"e","text":"Sitting to eat instead of standing"},{"id":"f","text":"\"Other parents manage, so must I\""}],"bins":[{"id":"free","label":"Guilt-free need","valence":"pos"},{"id":"trap","label":"Guilt trap","valence":"neg"}],"key":{"a":"free","b":"trap","c":"free","d":"trap","e":"free","f":"trap"},"relearn":"Resting, sharing cooking and eating sitting down are guilt-free needs; 'earn it', 'I'm weak', 'they manage' are traps.","persona":"Divya","source":"guilt trap"},
  {"id":"ly-1003","cat":"your-needs-count","type":"sort","hook":"Sort: words that honour a parent's needs, or words that dismiss them?","items":[{"id":"a","text":"\"Your rest matters too\""},{"id":"b","text":"\"Sleep when you're dead\""},{"id":"c","text":"\"Take an hour, I've got this\""},{"id":"d","text":"\"Stop being so dramatic\""},{"id":"e","text":"\"You're allowed to miss your old life\""},{"id":"f","text":"\"A real parent never complains\""}],"bins":[{"id":"honour","label":"Honours your needs","valence":"pos"},{"id":"dismiss","label":"Dismisses them","valence":"neg"}],"key":{"a":"honour","b":"dismiss","c":"honour","d":"dismiss","e":"honour","f":"dismiss"},"relearn":"'Your rest matters', 'take an hour', 'you can miss your old life' honour needs; the rest dismiss them.","persona":"any","source":"honour vs dismiss"},
  {"id":"ly-1004","cat":"your-needs-count","type":"sort","hook":"Sort: a real need worth protecting, or a luxury you can skip without harm?","items":[{"id":"a","text":"A few hours of unbroken sleep"},{"id":"b","text":"A spotless, showroom-perfect house"},{"id":"c","text":"One adult conversation a day"},{"id":"d","text":"Replying to every message instantly"},{"id":"e","text":"A short break to breathe"},{"id":"f","text":"Hosting guests when you're spent"}],"bins":[{"id":"need","label":"Real need","valence":"pos"},{"id":"skip","label":"Can skip","valence":"neutral"}],"key":{"a":"need","b":"skip","c":"need","d":"skip","e":"need","f":"skip"},"relearn":"Sleep, one adult chat and a breather are real needs; a perfect house, instant replies and tired hosting can wait.","persona":"any","source":"need vs luxury"},
  {"id":"ly-1005","cat":"your-needs-count","type":"sort","hook":"Sort: a way to reclaim a bit of yourself, or a way to lose more of yourself?","items":[{"id":"a","text":"Booking ten minutes for a hobby"},{"id":"b","text":"Saying yes to every extra duty"},{"id":"c","text":"Naming one thing you still love"},{"id":"d","text":"Apologising for every small need"},{"id":"e","text":"Asking a friend how you really are"},{"id":"f","text":"Hiding that you're struggling"}],"bins":[{"id":"reclaim","label":"Reclaims you","valence":"pos"},{"id":"lose","label":"Loses more of you","valence":"neg"}],"key":{"a":"reclaim","b":"lose","c":"reclaim","d":"lose","e":"reclaim","f":"lose"},"relearn":"A hobby slot, naming what you love and a real chat reclaim you; over-yessing, over-apologising and hiding lose more of you.","persona":"Divya","source":"reclaim vs lose"},
  {"id":"ly-1006","cat":"your-needs-count","type":"sort","hook":"Sort: meeting your need actually serves the child, or it doesn't touch them?","items":[{"id":"a","text":"Sleeping so you're patient tomorrow"},{"id":"b","text":"Buying yet another baby gadget"},{"id":"c","text":"A walk so you return calmer"},{"id":"d","text":"Scrolling shops late at night"},{"id":"e","text":"A friend's call so you feel less alone"},{"id":"f","text":"Comparing your baby to others online"}],"bins":[{"id":"serves","label":"Serves the child too","valence":"pos"},{"id":"neutral","label":"Doesn't really","valence":"neutral"}],"key":{"a":"serves","b":"neutral","c":"serves","d":"neutral","e":"serves","f":"neutral"},"relearn":"Sleep, a calming walk and a friend's call leave you steadier for your child; gadgets, scrolling and comparing don't.","persona":"any","source":"need serves child"},
  {"id":"ly-1007","cat":"your-needs-count","type":"sort","hook":"Sort: a fair way to split the load with a partner, or one parent carrying it all?","items":[{"id":"a","text":"Taking turns with the night feeds"},{"id":"b","text":"One parent 'on' around the clock"},{"id":"c","text":"Swapping who gets a lie-in"},{"id":"d","text":"Assuming it's all the mother's job"},{"id":"e","text":"Both tracking what needs doing"},{"id":"f","text":"One parent never asked to help"}],"bins":[{"id":"shared","label":"Shared fairly","valence":"pos"},{"id":"alone","label":"One carries it all","valence":"neg"}],"key":{"a":"shared","b":"alone","c":"shared","d":"alone","e":"shared","f":"alone"},"relearn":"Turns at night, swapped lie-ins and both tracking the load share it fairly; leaving it all to one parent isn't.","persona":"Vikram","source":"split the load"},
  {"id":"ly-1008","cat":"your-needs-count","type":"sort","hook":"Sort each thought: protects your identity, or quietly surrenders it?","items":[{"id":"a","text":"\"I'm a parent and still me\""},{"id":"b","text":"\"My old goals don't count now\""},{"id":"c","text":"\"I can grow and still be myself\""},{"id":"d","text":"\"Who I was no longer matters\""},{"id":"e","text":"\"One thing of mine, I'll keep\""},{"id":"f","text":"\"There's no room left for me\""}],"bins":[{"id":"protect","label":"Protects identity","valence":"pos"},{"id":"surrender","label":"Surrenders it","valence":"neg"}],"key":{"a":"protect","b":"surrender","c":"protect","d":"surrender","e":"protect","f":"surrender"},"relearn":"'Still me', 'I can grow', 'I'll keep one thing' protect your identity; 'who I was doesn't matter' surrenders it.","persona":"any","source":"protect identity"},
  {"id":"ly-1009","cat":"your-needs-count","type":"branch","persona":"Divya","source":"take a break","hook":"You haven't had ten minutes to yourself in days, and you're fraying.","steps":[{"prompt":"The baby is finally quiet and your partner walks in. What do you do?","options":[{"text":"Ask them to take over for a short break","then":"They nod and take the baby. You sit with your tea for twenty minutes.","best":true},{"text":"Keep going, since someone has to wash the bottles","then":"The bottles get washed. Your shoulders climb higher."},{"text":"Hope they notice how tired you look","then":"They don't. They say goodnight and you feel more invisible."},{"text":"Ask for a break, but only once the house is tidy","then":"The tidying takes an hour. By then everyone is asleep, including the break."}],"why":"A short break refills you, and asking plainly is how you get it."},{"prompt":"Later, a rare ten minutes appears and the to-do list is long. What do you do with the time?","options":[{"text":"Sit, breathe slowly and stretch a little","then":"Your shoulders drop. The to-do list will still be there, and it feels lighter.","best":true},{"text":"Fold the laundry to catch up on things","then":"The basket is done. You feel no more rested than before."},{"text":"Answer messages, since you're finally free","then":"Six replies later, the time is gone and your head is fuller."},{"text":"Scroll your phone to switch off","then":"The scrolling fills the time. You return still tense and slightly dazed."}],"why":"Real rest, even ten minutes, refills you in a way that catching up doesn't."},{"prompt":"Your mother-in-law drops by and offers to watch the baby. What do you say?","options":[{"text":"Thank her and take a proper hour for yourself","then":"She waves you off with a smile. You walk to the end of the lane and back.","best":true},{"text":"Say no. You don't want to trouble her","then":"She nods, a little hurt. You spend the hour on chores."},{"text":"Say yes, but stay in the next room listening","then":"You hear every sound. The hour passes without you resting once."},{"text":"Say yes, then use the hour to cook for everyone","then":"The food is lovely. You are more tired than when she arrived."}],"why":"Accepting help and using the time for yourself is how the hour refills you."},{"prompt":"A week later, you're fraying again and no one has asked. What do you do?","options":[{"text":"Ask for a short break again and suggest a regular slot","then":"Your partner agrees to alternate evenings. It goes on the calendar.","best":true},{"text":"Wait until you hit breaking point before saying anything","then":"The breaking point comes on a Sunday, and it's louder than a request."},{"text":"Assume they'll offer, and stay quiet","then":"They assume you're fine. The week runs the same as the last."},{"text":"Ask, but apologise the whole time","then":"They say yes, though the apologies leave you feeling small."}],"why":"A regular slot keeps you from reaching empty in the first place."}],"debrief":"Asking for a short break refills you; pushing past empty only frays you more.","relearn":"When you're fraying, ask for a short break; it refills you rather than running you down."},
  {"id":"ly-1010","cat":"your-needs-count","type":"branch","persona":"any","source":"accept the invite","hook":"A friend invites you over for an hour, and guilt says you shouldn't leave the baby.","steps":[{"prompt":"Your friend Kavya texts again to ask you over at five. What do you do?","options":[{"text":"Say yes and ask your partner to cover the hour","then":"Your partner says of course. You put on a clean kurta for the first time in days.","best":true},{"text":"Say no, since the baby needs you","then":"Kavya says the door is open till seven if you change your mind."},{"text":"Say maybe and decide at five","then":"Kavya says fine. All afternoon, the guilt has room to grow."},{"text":"Say yes, but bring the baby along to ease the guilt","then":"Kavya says of course. You pack a nappy bag, and it feels less like your hour."}],"why":"Asking your partner to cover means the hour is truly yours."},{"prompt":"At half past four the baby is grizzly, your partner is home, and guilt is loud. What do you do?","options":[{"text":"Hand over calmly with a note on feeds, then go","then":"Your partner smiles and takes the baby. You head out without looking back.","best":true},{"text":"Cancel because the baby seems unsettled","then":"The baby settles at six. The evening is already lost."},{"text":"Go, but call home every ten minutes","then":"Each call pulls you back. You spend more of the hour on the phone than at Kavya's."},{"text":"Stay until the baby is fully asleep, then go late","then":"You leave at seven for twenty minutes. Kavya is polite, and you feel rushed."}],"why":"A calm handover lets your partner settle the baby and lets you truly go."},{"prompt":"A few days later, Kavya calls and asks how you're really doing. What do you say?","options":[{"text":"Tell her honestly it's been lonely and heavy lately","then":"Kavya softens. \"Thank you for telling me. I'm here whenever.\"","best":true},{"text":"Say everything's great and change the subject","then":"Kavya goes along with it. You hang up feeling as alone as before."},{"text":"Talk only about the baby for the whole call","then":"Kavya listens warmly. She never learns how you are."},{"text":"Say you feel guilty even chatting and hang up early","then":"The call ends in two minutes. The talk you needed is cut short."}],"why":"Being honest about how you are lets a friend actually reach you."}],"debrief":"Taking the hour meets a real need; declining from guilt just deepens isolation.","relearn":"A little time with a friend isn't selfish; it meets a real need and lifts isolation."},
  {"id":"ly-1011","cat":"your-needs-count","type":"branch","persona":"any","source":"hold the rest","hook":"Your mother-in-law says you rest too much for a new parent.","steps":[{"prompt":"She remarks on it again as you lie down beside the sleeping baby. What do you say?","options":[{"text":"Thank her for caring and say rest keeps you going","then":"She sniffs, but brings you a glass of water and leaves the door ajar.","best":true},{"text":"Get up at once and start on the chores she mentions","then":"You fold clothes with heavy arms. She looks pleased and says nothing more."},{"text":"Snap that she has no idea what the nights are like","then":"She stiffens. The house is tense until dinner."},{"text":"Explain at length why the nights leave you so tired","then":"She listens, unconvinced. You are more tired after explaining than before."}],"why":"A warm thank-you honours her and still protects the rest you need."},{"prompt":"That evening your partner Sameer says his mother means well and asks you to do a bit more. What do you say?","options":[{"text":"Agree she means well and say you still need your rest","then":"Sameer nods slowly. \"Okay. I'll speak to her gently.\"","best":true},{"text":"Agree to do more chores around the house to keep the peace","then":"Sameer looks relieved. Your sleep shrinks by an hour."},{"text":"Tell him to handle his mother and end the talk there","then":"Sameer goes quiet. The problem sits where it was."},{"text":"Say nothing and stew over it all night long","then":"Sameer thinks it went fine. You lie awake."}],"why":"Naming your need kindly keeps the peace without giving up your rest."},{"prompt":"Your aunt visits and praises a neighbour who \"never sits down\" with her newborn. What do you do?","options":[{"text":"Smile and say each parent needs different things","then":"The room goes still, then your aunt laughs and asks about your baby's sleep.","best":true},{"text":"Feel ashamed and resolve to match the neighbour","then":"You take on extra tasks the next day. By evening you can hardly stand."},{"text":"Criticise the neighbour to make yourself feel better","then":"The talk turns sour. You feel worse afterwards."},{"text":"Joke that you must be the lazy one in the family","then":"Everyone laughs. The joke stays with you long after they leave."}],"why":"Kindly holding to what you need keeps you steady without comparing."},{"prompt":"A week on, your mother-in-law asks you to cook for the whole family. You're exhausted. What do you do?","options":[{"text":"Thank her, say you need rest, and ask Sameer to cook","then":"She looks surprised, then shows Sameer where the spices are.","best":true},{"text":"Cook the whole feast yourself to prove you're a \"good\" mum","then":"The feast is admired. You go to bed spent and quiet."},{"text":"Refuse flatly and go to your room","then":"Her face falls. The evening is awkward and the meal is late."},{"text":"Agree, but cook something simple so it's over quickly","then":"The meal is plain and on time. You're too tired to eat much of it."}],"why":"Handing the cooking to Sameer honours her request and still keeps the rest you need."}],"debrief":"You can be gracious with an elder and still keep the rest you need; dropping it risks burnout.","relearn":"Honour an elder warmly and still keep your rest; proving yourself by collapsing helps no one."},
  {"id":"ly-1012","cat":"your-needs-count","type":"branch","persona":"Priya","source":"keep a thread","hook":"You miss the work you loved and wonder if wanting it back makes you a poor parent.","steps":[{"prompt":"A former colleague mentions an online talk on your field next week. What do you do?","options":[{"text":"Book a seat and ask your partner to cover the hour","then":"Your partner says yes. You put the date in your calendar and smile.","best":true},{"text":"Say it sounds nice but you have no time","then":"She says maybe next time. You feel a small pang."},{"text":"Book a seat, then cancel because you'd only feel guilty","then":"The seat goes to someone else. You feel the loss more than the guilt."},{"text":"Tell yourself that part of your life is over and scroll on","then":"The invitation slips away. The wish stays underneath."}],"why":"Keeping one small link to your work protects who you are."},{"prompt":"Your partner Ishan asks what you'd like to do with your Sundays. What do you say?","options":[{"text":"Say you'd like an hour a week for your work or study","then":"Ishan nods. \"Take Sunday morning. I'll do the baby.\"","best":true},{"text":"Say nothing much, since Sundays are for the baby","then":"Ishan nods and plans the day. The wish stays unspoken."},{"text":"Hint that you miss work and hope he takes the cue","then":"Ishan says he's sure you'll find time. Nothing gets planned."},{"text":"Say you'd like time for work, but only once the routine settles","then":"Ishan agrees. The routine never feels settled enough, and the ache stays."}],"why":"A small, specific ask is easier to meet than a hint or a someday."},{"prompt":"An aunt says a mother who thinks about work isn't focused on her baby. What do you do?","options":[{"text":"Say a little of what you love keeps you steadier for the baby","then":"She frowns, then says she'd never thought of it that way.","best":true},{"text":"Agree and tell yourself to stop thinking about it","then":"Everyone nods. You feel the wish curl up smaller."},{"text":"Say she's old-fashioned and walk off","then":"She is offended, and your point is lost."},{"text":"Change the subject and feel ashamed for the rest of the day","then":"The subject changes. The shame stays for the rest of the day."}],"why":"Your identity is part of what steadies your parenting."}],"debrief":"Keeping a small thread of what you love protects your identity; burying it deepens the loss.","relearn":"Keep one small thread of work or study you love; it protects who you are and steadies your parenting."},
  {"id":"ly-1013","cat":"your-needs-count","type":"branch","persona":"any","source":"not this week","hook":"You're running on empty when relatives plan a weekend visit.","steps":[{"prompt":"Your aunt calls to say she is bringing the family on Saturday. What do you do?","options":[{"text":"Gently say it's not a good week and offer a later date","then":"She pauses, then says of course. \"Let's aim for the month after.\"","best":true},{"text":"Say yes, since refusing outright might look unwelcoming","then":"She's delighted. You put the phone down with your stomach in knots."},{"text":"Say maybe and hope that she cancels before Saturday","then":"She takes it as a yes and starts planning the menu."},{"text":"Say yes and plan to cook through the night","then":"The menu grows. So does the tiredness."}],"why":"Saying \"not this week\" protects a real need without hurting the relationship."},{"prompt":"Your partner Dev asks if you're really alright this week. What do you say?","options":[{"text":"Tell him you're running on empty and need real rest","then":"Dev nods. \"Then let's cancel anything that isn't essential.\"","best":true},{"text":"Say you're fine, just a bit tired this week","then":"Dev says okay. He doesn't ask again."},{"text":"Say it's nothing and clean the kitchen twice over","then":"Dev watches you scrub. He doesn't know what to do."},{"text":"Say he never does enough and list every task he skipped","then":"Dev gets defensive. The list is long and the plan is missing."}],"why":"Saying plainly how you are lets him help before you're emptied out."},{"prompt":"Midweek, your uncle calls to ask if his family can drop by on Sunday. What do you do?","options":[{"text":"Say not this week, and offer a date once you've rested","then":"He sounds surprised, then agrees. Sunday stays free for rest.","best":true},{"text":"Say yes and prepare a full meal for everyone","then":"The meal is praised. By the time they leave, you're drained."},{"text":"Say you'll be out, then stay hidden at home all day","then":"You spend Sunday tiptoeing and ignoring calls. It's not much of a rest."},{"text":"Say yes, but only for tea and an hour","then":"They agree. The hour stretches to three, and you're worn out."}],"why":"Holding to \"not this week\" keeps the rest you need, and a later date keeps the welcome."},{"prompt":"On Sunday evening the house is a mess, and you're tempted to clean before resting. What do you do?","options":[{"text":"Do one small thing, then rest. The mess can wait","then":"The kitchen waits. You wake up steadier.","best":true},{"text":"Clean everything tonight so tomorrow is free","then":"It's midnight when you finish. Tomorrow starts tired."},{"text":"Ask Dev to help you clean it all now","then":"Dev helps, tired and quiet. You both get to bed late."},{"text":"Scroll on your phone to unwind first","then":"Forty minutes go. The mess is still there and you are more tired."}],"why":"Resting first, and leaving the mess, keeps you steady for tomorrow."}],"debrief":"Saying not this week protects a real need; hosting while empty only depletes you further.","relearn":"It's fine to say it's not a good week and rest; protecting your need isn't being unwelcoming."},
  {"id":"ly-1014","cat":"your-needs-count","type":"branch","persona":"Vikram","source":"plan couple time","hook":"You and your partner haven't had a moment together since the baby came.","steps":[{"prompt":"Your sister offers to babysit on Friday evening. What do you do?","options":[{"text":"Say yes and plan a short evening together","then":"She grins. \"Go. I've got this.\" Friday has something in it.","best":true},{"text":"Say you'll pass, since couple time feels like a luxury now","then":"Your sister shrugs. Friday looks like every other night."},{"text":"Say yes, then plan to talk about the baby all evening","then":"She agrees. Your notes for Friday fill up with feeds and routines to go over."},{"text":"Say yes, but only if it doesn't disturb the baby's routine","then":"The window shrinks to forty minutes. It hardly seems worth the trip."}],"why":"A short evening together tends a real need for both of you."},{"prompt":"Your partner Tanvi hears about your sister's offer and sighs that going out sounds like too much effort. What do you say?","options":[{"text":"Suggest something low key, like a short walk","then":"Tanvi thinks. \"A walk, then. Just an hour.\"","best":true},{"text":"Agree, since she's tired and the evening can wait","then":"Tanvi looks relieved. The evening is another one at home."},{"text":"Insist on a fancy dinner out","then":"Tanvi looks more tired at the thought. The idea fizzles out."},{"text":"Say fine, and go out by yourself","then":"The evening is quiet. Tanvi stays home feeling left out."}],"why":"A small, easy plan is more likely to happen than a grand one."},{"prompt":"When the two of you finally sit together, the talk drifts to logistics again. What do you do?","options":[{"text":"Ask one question about her, not the baby","then":"Tanvi blinks, then smiles. \"You haven't asked me that in months.\"","best":true},{"text":"Keep going through the to-do list","then":"The list gets shorter. So does the chance to talk."},{"text":"Check the baby monitor app every few minutes","then":"The screen takes most of your attention. Tanvi notices."},{"text":"Say the evening is pointless and give up on it","then":"Tanvi looks hurt. The evening ends early."}],"why":"A question about her shows the person behind the parent."},{"prompt":"A month later, a chance for couple time comes with no help lined up. What do you do?","options":[{"text":"Plan a small at-home date after the baby sleeps","then":"A candle, a snack and one show. It feels like time for the two of you.","best":true},{"text":"Skip it until help is available","then":"Weeks go by. The distance grows a little."},{"text":"Wait until things feel less busy","then":"Things don't feel less busy. The chance slips by."},{"text":"Book a big outing without any help","then":"The plan collapses at the last minute. Both of you are disappointed."}],"why":"A small at-home date keeps the two of you connected between big plans."}],"debrief":"Tending the couple is a real need, not a luxury; a short evening together steadies the whole home.","relearn":"Plan a little couple time with help lined up; a connected partnership is steadier ground for your child."},
  {"id":"ly-1015","cat":"your-needs-count","type":"branch","persona":"Divya","source":"drop the sorry","hook":"You catch yourself apologising every time you mention a need of your own.","steps":[{"prompt":"Your partner is home and you need ten minutes for a shower. What do you say?","options":[{"text":"Ask plainly: can you take the baby for ten minutes?","then":"Your partner takes the baby. \"Sure.\" The shower is unhurried.","best":true},{"text":"Say sorry three times and offer to owe them a favour","then":"Your partner says of course, but now feels vaguely guilty."},{"text":"Joke that you smell terrible and need saving by someone","then":"Your partner laughs and helps. The shower feels like a favour."},{"text":"Skip the shower and wait for them to offer","then":"Nobody offers. You go another day without one."}],"why":"A plain ask is easy to say yes to and doesn't cast the need as a burden."},{"prompt":"Your mother phones and asks how you are. You're worn out. What do you say?","options":[{"text":"Say you're tired and would love an hour of help this week","then":"She sounds pleased. \"I'll come Thursday afternoon.\"","best":true},{"text":"Say sorry to trouble her and that you're completely fine","then":"She says good, and rings off. Nothing is arranged."},{"text":"Say you're fine and ask about her day instead","then":"She talks about her knees. You listen for twenty minutes."},{"text":"Say you'd hate to be a burden, so never mind","then":"She says she doesn't mind, but you've already changed the subject."}],"why":"Naming the need, and a small ask, lets a caring person actually help."},{"prompt":"A friend asks if you'd like a walk on Thursday. You would. What do you say?","options":[{"text":"Say yes with a real smile","then":"She beams. \"Four o'clock, then. We'll go slow.\"","best":true},{"text":"Say you probably can't, but thank her warmly","then":"She says maybe another time. Thursday passes indoors."},{"text":"Say yes, then apologise for taking her time","then":"She waves it off, and the warmth dims a little."},{"text":"Say you'd love to, but you really shouldn't","then":"She says fine. You spend Thursday wishing you'd gone."}],"why":"A simple yes accepts a need being met and lets the friend enjoy it too."},{"prompt":"Your partner says you don't need to say sorry for asking. What do you say?","options":[{"text":"Thank them and try the next ask without a sorry","then":"Your partner grins. \"That's it. See? Easy.\"","best":true},{"text":"Say sorry for saying sorry","then":"You both laugh, but the habit stays the same."},{"text":"Say you can't help it and it's just who you are","then":"Your partner nods and lets it go. The habit stays where it was."},{"text":"Say they don't understand and change the subject","then":"Your partner looks taken aback. The chance to talk closes."}],"why":"Trying it without the sorry, even once, starts to loosen the habit."},{"prompt":"Next week you need one full night's sleep. What do you say?","options":[{"text":"Say plainly: I need one full night. Can you take the feeds?","then":"Your partner nods. \"Tonight. I'll wake you at seven.\"","best":true},{"text":"Say it as a joke so it isn't a real ask","then":"Your partner laughs. Nothing changes, and you stay awake."},{"text":"Say sorry first, then explain for five minutes why you're tired","then":"The ask gets lost in the explanation. You get half a night."},{"text":"Hint that you're tired and hope they offer","then":"They say you look tired and offer tea. The night is the same."}],"why":"A plain ask, without an apology, gets the rest you need."}],"debrief":"Saying a need plainly, without the sorry, gets it met and loosens the guilt; over-apologising erases it.","relearn":"State your needs plainly without apologising; the guilt loosens and you're heard more clearly."},
  {"id":"ly-1016","cat":"your-needs-count","type":"branch","persona":"any","source":"name the tasks","hook":"The whole load has landed on you, and your partner hasn't been asked to share it.","steps":[{"prompt":"Your partner Neel asks what's for dinner as you fold laundry with the baby on your hip. What do you say?","options":[{"text":"Name specific tasks: tonight's dinner and the bath are his","then":"Neel blinks, then nods. \"Dinner and the bath. Got it.\"","best":true},{"text":"Say nothing and cook so you don't seem to nag","then":"Neel eats happily. He has no idea what it cost you."},{"text":"Say you need him to help more around the house","then":"Neel says of course. Neither of you knows what \"more\" means."},{"text":"Sigh loudly and slam the cupboard","then":"Neel flinches. He doesn't know what he did wrong."}],"why":"Naming specific tasks is easier to act on than \"help more\"."},{"prompt":"That weekend Neel watches you juggle the chores and says he had no idea there was so much. What do you say?","options":[{"text":"Write the list together and split it by task","then":"Neel takes the bins, bath time and Sunday laundry. The list goes on the fridge.","best":true},{"text":"Say you shouldn't have to tell him","then":"Neel nods, ashamed. Nothing is split yet."},{"text":"Say it's fine and you'll keep doing it","then":"Neel looks relieved. The week looks the same."},{"text":"Sort the chores alone and hand him your list","then":"Neel reads it and nods. It feels handed down, and he doesn't add to it."}],"why":"A shared list turns a good intention into an actual split."},{"prompt":"A week later, a chore Neel could have taken is left undone. What do you do?","options":[{"text":"Remind him kindly and ask which chores suit him best","then":"Neel apologises and offers to own the evening dishes for good.","best":true},{"text":"Do it yourself and say nothing","then":"The task is done. You add it to a private list of grievances."},{"text":"Bring up every miss from this month at once","then":"Neel gets defensive. The list becomes the fight."},{"text":"Say this is exactly why you never asked before","then":"Neel goes quiet and stops offering to take anything on."}],"why":"A kind reminder keeps the split going without turning it into a fight."},{"prompt":"Your mother-in-law drops in, sees Neel washing dishes and looks startled. What do you do?","options":[{"text":"Say you share the work and thank Neel for it","then":"She raises an eyebrow, then picks up a dish towel herself.","best":true},{"text":"Take over and send Neel out of the kitchen","then":"Neel leaves, confused. Your mother-in-law approves."},{"text":"Explain that you just needed a break this once","then":"She nods, satisfied. The old habit of doing everything returns."},{"text":"Say nothing and let her think it's rare","then":"She leaves believing it is rare. It doesn't feel fair to Neel or to you."}],"why":"Saying out loud that you share the work makes it the normal way."}],"debrief":"Naming specific tasks shares the load fairly; carrying it all silently only breeds burnout.","relearn":"Name specific tasks to share with your partner; asking isn't nagging, and it gets you both some space."},
  {"id":"ly-1017","cat":"your-needs-count","type":"match","hook":"Match each guilty thought to the kinder truth that answers it.","pairs":[{"left":"\"I'm selfish for resting\"","right":"Rest refills what you give"},{"left":"\"I've lost who I was\"","right":"You can reclaim small pieces"},{"left":"\"Needing help means failing\"","right":"Sharing the load is wise"},{"left":"\"My needs come last, always\"","right":"They can sit alongside theirs"},{"left":"\"Wanting time is ungrateful\"","right":"Love and needs both fit"}],"relearn":"Each guilty thought has a kinder truth: rest refills you, you can reclaim yourself, and love and needs both fit.","persona":"Divya","source":"thought to truth"},
  {"id":"ly-1018","cat":"your-needs-count","type":"match","hook":"Match each unmet need to one small, doable way to meet it.","pairs":[{"left":"You're touched out","right":"Ten minutes alone with tea"},{"left":"You feel isolated","right":"A quick call to a friend"},{"left":"You've lost your spark","right":"One song or page you love"},{"left":"You're exhausted","right":"A nap while someone covers"},{"left":"You feel unseen","right":"Telling your partner how you are"}],"relearn":"Each need has a small fix: time alone, a friend's call, a loved song, a nap, or simply being heard.","persona":"any","source":"need to small fix"},
  {"id":"ly-1019","cat":"your-needs-count","type":"match","hook":"Match each part of your old self to a tiny way to keep it alive now.","pairs":[{"left":"The reader you were","right":"A few pages before sleep"},{"left":"The friend you were","right":"One message sent today"},{"left":"The cook you enjoyed being","right":"One dish you actually like"},{"left":"The walker you were","right":"A short loop with the pram"},{"left":"The you with goals","right":"One small plan kept alive"}],"relearn":"Tiny acts keep the old you alive: a few pages, a message, a dish you like, a short walk, one kept plan.","persona":"Divya","source":"keep old self"},
  {"id":"ly-1020","cat":"your-needs-count","type":"match","hook":"Match each need to the person who could help you meet it.","pairs":[{"left":"A night of better sleep","right":"Your partner taking a feed"},{"left":"A short break out","right":"A grandparent watching baby"},{"left":"Adult conversation","right":"A friend who'll listen"},{"left":"Help with the chores","right":"A sibling lending a hand"},{"left":"Feeling less alone","right":"A new-parents group"}],"relearn":"Different people can meet different needs: a partner, a grandparent, a friend, a sibling, a parents' group.","persona":"any","source":"need to helper"},
  {"id":"ly-1021","cat":"your-needs-count","type":"match","hook":"Match each thing a father might miss to a way to keep it alive.","pairs":[{"left":"Time with his own friends","right":"A short catch-up each week"},{"left":"A sport he played","right":"A quick game when he can"},{"left":"Quiet to think","right":"Ten minutes after the kids sleep"},{"left":"Feeling competent at work","right":"One task done well today"},{"left":"Closeness with his partner","right":"A real chat, not just logistics"}],"relearn":"A father stays whole by keeping friends, a sport, some quiet, pride in work and closeness with his partner.","persona":"Vikram","source":"father stays whole"},
  {"id":"ly-1022","cat":"your-needs-count","type":"match","hook":"Match each 'I should' pressure to the gentler 'I can' that frees you.","pairs":[{"left":"\"I should do it all alone\"","right":"\"I can ask for help\""},{"left":"\"I should never rest\"","right":"\"I can rest and still be good\""},{"left":"\"I should have no needs\"","right":"\"I can have needs, guilt-free\""},{"left":"\"I should be only a parent\"","right":"\"I can be a parent and me\""},{"left":"\"I should look like I'm fine\"","right":"\"I can be honest about hard\""}],"relearn":"Each harsh 'I should' has a gentler 'I can': ask for help, rest, have needs, stay yourself, be honest.","persona":"any","source":"should to can"},
  {"id":"ly-1023","cat":"your-needs-count","type":"match","hook":"Match each small refill to the kind of energy it gives back.","pairs":[{"left":"A proper meal sitting down","right":"Physical steadiness"},{"left":"Ten minutes of quiet","right":"A calmer mind"},{"left":"A laugh with a friend","right":"A lighter mood"},{"left":"A short walk outside","right":"A clearer head"},{"left":"Being truly listened to","right":"Feeling less alone"}],"relearn":"Each small refill gives something back: a meal steadies you, quiet calms you, a friend lifts you.","persona":"Priya","source":"refill to energy"},
  {"id":"ly-1024","cat":"your-needs-count","type":"match","hook":"Match each line a partner says to whether it lifts the load or adds to it.","pairs":[{"left":"\"Go rest, I've got the baby\"","right":"Lifts the load"},{"left":"\"Why's the house a mess?\"","right":"Adds to the load"},{"left":"\"What do you need today?\"","right":"Eases the load"},{"left":"\"You're with the baby all day, easy\"","right":"Adds pressure"},{"left":"\"Let's split the nights\"","right":"Shares the load"}],"relearn":"Words like 'go rest' and 'what do you need' lift the load; dismissive ones add to it, and splitting shares it.","persona":"any","source":"lifts or adds"},
  {"id":"ly-1025","cat":"your-needs-count","type":"reflect","hook":"Lensy: you are allowed to take up a little space in your own life. Sit with that for a moment.","prompt":"What comes up?","options":["I'm allowed","A little space","It's mine too"],"affirm":"You are allowed to take up a little space in your own life; your needs belong here alongside your child's.","relearn":"You're allowed a little space in your own life; your needs belong here too.","persona":"any","source":"take up space"},
  {"id":"ly-1026","cat":"your-needs-count","type":"reflect","hook":"Lensy: the person you were before is still in there, not lost, just waiting. How does that land?","prompt":"How does it land?","options":["Still in here","Not lost","Just waiting"],"affirm":"The person you were is still inside you, not erased; you can reclaim small pieces of them over time.","relearn":"The you from before isn't lost; you can reclaim small pieces of yourself over time.","persona":"Divya","source":"still in there"},
  {"id":"ly-1027","cat":"your-needs-count","type":"reflect","hook":"Lensy: having a need doesn't make you a burden; it makes you human. Does that feel true?","prompt":"Does that feel true?","options":["It feels true","Just human","Not a burden"],"affirm":"Having a need doesn't make you a burden; it makes you human, and your needs are worth voicing.","relearn":"Having needs doesn't make you a burden; it makes you human, and they're worth voicing.","persona":"any","source":"not a burden"},
  {"id":"ly-1028","cat":"your-needs-count","type":"reflect","hook":"Lensy: dads carry needs too, and saying so is strength, not weakness. Sit with that.","prompt":"What do you notice?","options":["Dads too","It's strength","I can say it"],"affirm":"Fathers have real needs and an identity too; naming them is strength, and it makes for a steadier dad.","relearn":"Fathers have needs and a self too; naming them is strength, not weakness.","persona":"Vikram","source":"dads have needs"},
  {"id":"ly-1029","cat":"your-needs-count","type":"reflect","hook":"Lensy: a child gains from a parent who is also still a whole person. Feel the truth of that?","prompt":"What's your take?","options":["I feel it","A whole person","True for me"],"affirm":"Your child gains from a parent who stays a whole person, not one who has erased themselves entirely.","relearn":"Your child gains from a parent who's also still a whole person.","persona":"any","source":"whole person gain"},
  {"id":"ly-1030","cat":"your-needs-count","type":"reflect","hook":"Lensy: you can love your child completely and still miss your old life. Both can be true. Agree?","prompt":"Does that fit?","options":["Both true","I agree","It fits"],"affirm":"You can love your child completely and still miss your old life; holding both isn't disloyalty, it's honest.","relearn":"You can adore your child and still miss your old life; holding both is honest, not disloyal.","persona":"Divya","source":"hold both"},
  {"id":"ly-1031","cat":"your-needs-count","type":"reflect","hook":"Lensy: setting down the guilt over your own needs is something you can learn, slowly. How does that sit?","prompt":"How does that sit?","options":["I can learn it","Slowly","Set it down"],"affirm":"The guilt over having needs is common and learnable to set down, a little at a time; needs and good parenting fit.","relearn":"Guilt over your needs is learnable to set down, slowly; needs and good parenting aren't in conflict.","persona":"any","source":"set down guilt"},
  {"id":"ly-1032","cat":"your-needs-count","type":"reflect","hook":"Lensy: keeping one small thing that's just yours isn't taking from your family. Does that ring true?","prompt":"Does it ring true?","options":["It rings true","Just mine","Not taking"],"affirm":"Keeping one small thing that's just yours doesn't take from your family; it keeps you whole, which gives back to them.","relearn":"Keeping one small thing that's just yours doesn't take from your family; it keeps you whole.","persona":"any","source":"one thing mine"},
  {"id":"ly-1033","cat":"your-needs-count","type":"role-play","persona":"Divya","source":"ask for sleep","hook":"You're running on broken sleep and need one proper night.","setup":"Your partner Ashwin sits down beside you.","steps":[{"prompt":"Ashwin asks: \"You look wrecked. What would help most?\"","options":[{"text":"\"One full night's sleep. Can you take the feeds tonight?\"","then":"Ashwin nods. \"Okay. Yes. Let's work it out.\"","best":true},{"text":"\"It's fine. Ignore me. I'll manage on no sleep again.\"","then":"Ashwin frowns. \"That's not fine. Tell me properly.\""},{"text":"\"Maybe a nap this afternoon. Never mind. It's not important.\"","then":"Ashwin starts to move on, then turns back. \"A nap won't cover it, will it?\""},{"text":"\"You should have noticed sooner. You always sleep so well.\"","then":"Ashwin flinches. \"That's hard to hear. What do you need?\""}],"why":"Asking clearly for one full night makes the rest likelier to happen."},{"prompt":"Ashwin says: \"I've a big meeting tomorrow, but I do want to help. What would work?\"","options":[{"text":"\"Take the feeds till two tonight, and a full night Saturday.\"","then":"Ashwin thinks. \"Two tonight, Saturday all night. That works.\"","best":true},{"text":"\"Fine, it can wait. Your meeting matters more than my sleep.\"","then":"Ashwin relaxes. Another night of broken sleep begins for you."},{"text":"\"No, it can't wait. I'll be a wreck by tomorrow.\"","then":"Ashwin looks stung. \"I'm not trying to dodge it.\""},{"text":"\"Forget it. I'll just do the feeds like always.\"","then":"Ashwin nods, uneasy. You brace for another night of feeds alone."}],"why":"A specific alternative keeps your need alive while respecting his day."},{"prompt":"Ashwin asks: \"If I do cover a night, what do I do if the baby won't settle?\"","options":[{"text":"\"Feed, change, cuddle. Wake me only if something feels wrong.\"","then":"Ashwin nods. \"Feed, change, cuddle. I've got it.\"","best":true},{"text":"\"Just wake me up and hand her over. I'll do it faster than you would.\"","then":"Ashwin looks unsure. \"Then I'm not really covering.\""},{"text":"\"Look it up online. There's a lot of advice out there.\"","then":"Ashwin scrolls, gets lost in advice and wakes the baby further."},{"text":"\"Don't worry. You'll get the hang of it by morning.\"","then":"Ashwin smiles nervously. He isn't sure."}],"why":"A short, clear handover lets him take charge so you can truly rest."},{"prompt":"A few days later, Ashwin asks: \"Should we set a regular night each week for you to sleep through?\"","options":[{"text":"\"Yes. One full night a week, and I'll take one for you too.\"","then":"Ashwin grins. \"Fridays for you, Sundays for me.\"","best":true},{"text":"\"Let's see. I don't want to be demanding about it.\"","then":"Ashwin shrugs. The week goes by without a plan."},{"text":"\"No. Sleep can wait until the baby is older.\"","then":"Ashwin looks unsure. The next tired night arrives soon."},{"text":"\"Yes, but only when it's really bad.\"","then":"Ashwin nods. By then you've already been running on empty for days."}],"why":"A regular night keeps your rest from depending on how bad things get."}],"relearn":"Asking clearly for one full night, without dismissing yourself, makes the rest you need likelier to happen."},
  {"id":"ly-1034","cat":"your-needs-count","type":"role-play","persona":"Vikram","source":"dad asks for time","hook":"You're a dad and you also need a little time of your own.","setup":"Your partner Nita finds you alone on the balcony after the baby sleeps.","steps":[{"prompt":"Nita asks: \"You've been quiet lately. Is something on your mind?\"","options":[{"text":"\"I love being a dad, and I also need a bit of time of my own.\"","then":"Nita's face softens. \"Thank you for saying so. I've wondered.\"","best":true},{"text":"\"Forget it. Dads aren't supposed to need things, are they?\"","then":"Nita frowns. \"Says who? Tell me what's going on.\""},{"text":"\"Nothing. Work has been busy. That's all.\"","then":"Nita tilts her head. \"It doesn't look like only work.\""},{"text":"\"I miss my old routine. Why can't things go back to how they were?\"","then":"Nita stiffens. \"They can't. But tell me what you miss.\""}],"why":"Naming your own need plainly is easier for a partner to meet than a silent one."},{"prompt":"Nita says: \"I'd love a little time to myself. Maybe we both need some. How would it work?\"","options":[{"text":"\"Let's plan one evening each, both on the calendar.\"","then":"Nita smiles. \"That feels fair. Mine on Wednesdays?\"","best":true},{"text":"\"Mine first, then yours if there's time left over.\"","then":"Nita frowns. \"Then it never gets to me.\""},{"text":"\"We'll see. Let's not add another thing right now.\"","then":"Nita nods slowly. Neither evening gets a date."},{"text":"\"You take yours. I'll manage without any time of my own.\"","then":"Nita shakes her head. \"No. You need some too. That's the point.\""}],"why":"A shared plan makes time for both of you, not one after the other."},{"prompt":"Nita asks: \"If you had a free evening, what would you do with it?\"","options":[{"text":"\"Something I love, like a game of cricket with my friends.\"","then":"Nita laughs. \"I'd forgotten you played.\"","best":true},{"text":"\"Nothing much. I'd probably just finish the chores I've left.\"","then":"Nita raises an eyebrow. \"That isn't a break.\""},{"text":"\"Not sure. I feel guilty even wanting one.\"","then":"Nita touches your arm. The idea stays vague."},{"text":"\"Work through the office backlog. It never ends.\"","then":"Nita sighs. It wouldn't be time for you at all."}],"why":"Time spent on something you love is what refills you."},{"prompt":"At Sunday lunch your father says: \"In my time, a dad didn't need time for himself. He just worked.\"","options":[{"text":"\"Times have changed. I'm a better dad when I've had a little time.\"","then":"Your father grunts. \"Hm. Your mother said much the same once.\"","best":true},{"text":"\"You're right. A good dad shouldn't need it.\"","then":"Your father nods, pleased. You feel a little smaller."},{"text":"\"That's why you missed so much of our childhood.\"","then":"Your father goes cold. Lunch ends stiffly."},{"text":"\"It's only one evening. I'll make up for it at work.\"","then":"Your father shrugs. It sounds like you're asking his permission."}],"why":"Answering kindly, with your reason, holds your ground without a fight."}],"relearn":"A father naming his own need plainly, for both partners, makes it real instead of quietly resented."},
  {"id":"ly-1035","cat":"your-needs-count","type":"role-play","persona":"Divya","source":"answer the relative","hook":"You've planned a short break this Saturday, and your aunt has come for tea.","setup":"She overhears you mention Saturday.","steps":[{"prompt":"Your aunt says: \"A good mother never wants a break from her baby.\"","options":[{"text":"\"I love my baby and I still need a short break. It keeps me going.\"","then":"Your aunt is quiet a moment. \"Hm.\"","best":true},{"text":"\"You're right. Wanting a break must mean I'm not good enough.\"","then":"Your aunt looks satisfied. You feel your chest tighten."},{"text":"\"That's not fair. You had plenty of help when you were raising yours.\"","then":"Your aunt bristles. \"I raised four children.\""},{"text":"\"Please don't tell anyone I asked for a break at all.\"","then":"She sighs. \"I won't.\" The secret feels heavy."}],"why":"Saying love and rest both fit answers her gently and holds your ground."},{"prompt":"Your aunt goes on: \"Nobody can look after a baby the way her mother does.\"","options":[{"text":"\"My partner can. They know the routine and she'll be fine.\"","then":"Your aunt considers that. \"Hm. They did manage on Sunday.\"","best":true},{"text":"\"You're right. Nobody can do it like me. I'll stay.\"","then":"Your aunt nods, pleased. Saturday's plan quietly fades."},{"text":"\"Then you'd better take her, since you know best.\"","then":"Your aunt gives a stiff smile. It doesn't feel kind."},{"text":"\"I don't know. I'm just tired. Maybe it's not worth it.\"","then":"Your aunt pats your hand. The doubt settles in."}],"why":"Naming who can help shows the break is planned, not careless."},{"prompt":"Your aunt asks: \"And what would a mother even do with a break?\"","options":[{"text":"\"A walk, or tea with a friend. I come back steadier.\"","then":"Your aunt smiles slightly. \"Tea with a friend. I did that once.\"","best":true},{"text":"\"I spend it feeling guilty the whole time.\"","then":"Your aunt nods. \"Well, guilt is what mothers do.\""},{"text":"\"I check on the baby every ten minutes from wherever I am.\"","then":"Your aunt laughs. \"Then it isn't much of a break.\""},{"text":"\"I do the chores. It counts as a break.\"","then":"Your aunt approves. You wonder when you last really rested."}],"why":"A break that refills you, like rest, a walk or a friend, is the point of it."}],"relearn":"Naming that love and a need for a break both fit answers the pressure without guilt or a family fight."},
  {"id":"ly-1036","cat":"your-needs-count","type":"role-play","persona":"any","source":"ask a friend over","hook":"You want a friend to come over so you're less alone all day.","setup":"You pick up the phone.","steps":[{"prompt":"Your friend Reena answers: \"Hey, you! How's the week going?\"","options":[{"text":"\"It's been a lonely week. Could you come by for an hour?\"","then":"Reena's voice softens. \"Of course. I'm free tomorrow. I'd love to.\"","best":true},{"text":"\"Fine, thanks. Busy with the baby. You know how it is.\"","then":"Reena chats about her week, then says she'd love to pop over sometime."},{"text":"\"Don't worry about me. You're busy. I shouldn't bother you.\"","then":"Reena hesitates. \"You're not bothering me. Shall I pop over tomorrow?\""},{"text":"\"It's been a week. Maybe we should catch up sometime soon.\"","then":"Reena says \"Definitely!\" and asks if tomorrow could work."}],"why":"Naming the loneliness and asking plainly is how the need gets met."},{"prompt":"Reena says: \"I could come tomorrow. Should I bring anything?\"","options":[{"text":"\"Just yourself. I mostly need the company.\"","then":"Reena laughs. \"Easiest job ever. I'll bring chai anyway.\"","best":true},{"text":"\"No, nothing. I don't want to put you to any trouble.\"","then":"Reena nods. She brings a snack anyway, and you feel a bit awkward."},{"text":"\"Just a snack. And could we keep it short? I'd hate to bother you.\"","then":"Reena agrees. The visit feels rushed before it starts."},{"text":"\"A full lunch for everyone, and some groceries too.\"","then":"Reena hesitates. It turns into an errand, not a visit."}],"why":"Naming what you actually need keeps the visit about connection."},{"prompt":"Reena asks: \"So how are you really doing?\"","options":[{"text":"\"Honestly, low and lonely, and I miss adult conversation.\"","then":"Reena listens closely. \"Thank you for telling me. That sounds heavy.\"","best":true},{"text":"\"I'm fine. Just tired. Nothing to worry about.\"","then":"Reena nods. She half believes you."},{"text":"\"Fine. Tell me about your week instead.\"","then":"Reena tells you about her office. You listen with a smile."},{"text":"\"Oh, the usual. Same as every new parent.\"","then":"Reena nods. The chance to say more slips by."}],"why":"Being honest about how you feel is how a friend can really help."},{"prompt":"Reena offers: \"Shall I come every Thursday?\"","options":[{"text":"\"Yes please. That would really help. Let's put it in both calendars.\"","then":"Reena grins. \"Thursdays at four. It's booked.\"","best":true},{"text":"\"You're sweet, but I'll manage on my own.\"","then":"Reena nods, a little unsure. The offer fades."},{"text":"\"Only if it's convenient. Don't change any plans for me.\"","then":"Reena nods. \"Okay.\" The plans slip."},{"text":"\"Maybe. We'll see how the week goes.\"","then":"Reena smiles. The week goes, and nothing gets booked."}],"why":"A regular visit, agreed together, makes the support last."}],"relearn":"Naming the loneliness and asking plainly for company meets a real need instead of hiding it."},
  {"id":"ly-1037","cat":"your-needs-count","type":"role-play","persona":"Priya","source":"keep the class","hook":"You want to keep one evening class you love.","setup":"You raise it with your partner Omar.","steps":[{"prompt":"Omar says: \"Isn't it time to drop the class now that we have the baby?\"","options":[{"text":"\"It keeps me feeling like myself. Can we try one evening a week?\"","then":"Omar rubs his neck. \"One evening. Okay. Let's see how it fits.\"","best":true},{"text":"\"I suppose I should drop it. It's selfish to keep it now that we have a baby.\"","then":"Omar looks a little uneasy. \"I didn't say selfish.\""},{"text":"\"I'm not dropping it. You can't tell me what I can or can't do.\"","then":"Omar's face closes. \"I didn't mean it like that.\""},{"text":"\"Let me think about it. I don't want to argue tonight, so let's leave it.\"","then":"Omar nods. The question hangs around all week."}],"why":"Saying what the class does for you, and asking to plan it, protects your identity."},{"prompt":"Omar asks: \"If you did keep it, which evening would suit you, and what happens with the baby?\"","options":[{"text":"\"Thursday, six to eight. You have the baby and I'll leave a plan.\"","then":"Omar nods. \"Thursday. Feeds and bath. I can do that.\"","best":true},{"text":"\"Whichever evening you're free. I'll fit around you and the baby's needs.\"","then":"Omar shrugs. \"Okay.\" Nothing is fixed."},{"text":"\"Thursday, six to eight. It's my class, so I'll manage the rest.\"","then":"Omar frowns. \"Manage how? I need to plan work.\""},{"text":"\"I'll find someone to look after the baby and tell you later.\"","then":"Omar looks a little sidelined. \"I'd rather do it myself.\""}],"why":"A fixed evening and a clear handover give him something he can say yes to."},{"prompt":"On the first evening you could go, Omar texts: \"I'm stuck at work. Can you skip tonight?\"","options":[{"text":"\"I need tonight. Can you be home by 5:30 or shall I ask my sister?\"","then":"Omar replies fast. \"Home by 5:30. Go.\"","best":true},{"text":"\"Sure. It's only a class. I'll skip tonight and stay in with the baby.\"","then":"Omar sends a thumbs-up. The class goes on without you."},{"text":"\"You promised me this evening! You always do this to me.\"","then":"Omar goes quiet. The evening feels tense."},{"text":"\"I'll ask a neighbour to cover and not bother you at all.\"","then":"Omar sends a quick \"ok\". He feels cut out of the plan."}],"why":"Holding the class night, and offering a fix, keeps the plan and the peace."},{"prompt":"A month on, Omar says: \"Honestly, I feel like we barely see each other now.\"","options":[{"text":"\"I hear you. Can we plan an evening for the two of us as well?\"","then":"Omar exhales. \"I'd like that. Let's pick a night.\"","best":true},{"text":"\"You're right. I'll drop it after this term is over.\"","then":"Omar looks relieved and slightly guilty. You feel a little smaller."},{"text":"\"You're barely home anyway, so it's fine.\"","then":"Omar stiffens. \"That's not fair.\""},{"text":"\"Then take the baby out alone and see what it's like.\"","then":"Omar's face falls. The evening ends coldly."}],"why":"Hearing him and adding couple time shows the class doesn't take from the family."},{"prompt":"A few days later, Omar asks: \"Why does the class matter so much to you?\"","options":[{"text":"\"It's where I feel like me. It steadies me as a parent.\"","then":"Omar nods slowly. \"I hadn't seen it that way.\"","best":true},{"text":"\"It's just a way to get out of the house for a bit.\"","then":"Omar nods. He files it away as a small hobby."},{"text":"\"I don't know. I'm not sure it does anymore.\"","then":"Omar looks surprised. You're doubting yourself."},{"text":"\"Because you have your job and I have nothing else.\"","then":"Omar winces. The talk turns into who has more."}],"why":"Saying what the class does for you helps him see it as part of who you are."}],"relearn":"Naming that the class keeps you yourself, and asking to plan it, protects your identity without guilt."},
  {"id":"ly-1038","cat":"your-needs-count","type":"role-play","persona":"Divya","source":"ask without sorry","hook":"You keep saying sorry every time you ask for help, and this time you want to drop it.","setup":"Your partner Rishi is putting on his shoes.","steps":[{"prompt":"Rishi asks: \"Anything you need before I go?\"","options":[{"text":"\"Could you take the baby for an hour this afternoon?\"","then":"Rishi sets his bag down. \"Sure. Let me work out the timing.\"","best":true},{"text":"\"Sorry, sorry. Only if it's really no trouble at all.\"","then":"Rishi frowns. \"You keep saying sorry. I'd rather you just said.\""},{"text":"\"No, nothing. I'm fine. Go ahead. Don't worry about me.\"","then":"Rishi pauses at the door. \"You don't look fine.\""},{"text":"\"Well, you're going out anyway, so it doesn't matter.\"","then":"Rishi frowns. \"What does that mean? You sound worn out.\""}],"why":"A plain ask, without an apology, is easy for him to say yes to."},{"prompt":"Rishi says: \"I can be back by three if that helps. How much time would actually help?\"","options":[{"text":"\"An hour is enough for a rest and a shower. Thank you.\"","then":"Rishi nods. \"An hour, then. Thanks for saying it clearly.\"","best":true},{"text":"\"Sorry, an hour is too much to ask. Half an hour is fine.\"","then":"Rishi's eyebrows lift. \"Are you sure?\""},{"text":"\"Whatever you can spare. I don't want to trouble you.\"","then":"Rishi tries to guess. He stays for forty minutes."},{"text":"\"Cancel your plans. I need you here all day, no arguments.\"","then":"Rishi frowns. \"I can't drop everything today. What's going on?\""}],"why":"Saying how long you need, with thanks, gets a clear answer."},{"prompt":"Rishi says: \"I've noticed you say sorry almost every time you ask me for something.\"","options":[{"text":"\"Fair point. I'm working on saying it plainly.\"","then":"Rishi grins. \"Good. You never need to say sorry for asking me.\"","best":true},{"text":"\"Sorry! I mean... sorry.\"","then":"Rishi laughs gently. The habit stays put."},{"text":"\"I can't help it. It's just how I am.\"","then":"Rishi nods. He stops pointing it out."},{"text":"\"Now you're annoyed about that too? Sorry.\"","then":"Rishi steps back. The talk gets stuck on the apology."}],"why":"Owning the habit lightly, and trying again, starts to loosen it."}],"relearn":"Asking plainly, without piling on apologies, gets your need met and teaches others it counts."},
  {"id":"ly-1039","cat":"your-needs-count","type":"role-play","persona":"any","source":"not just fine","hook":"You've been saying \"fine\" for weeks and want to stop.","setup":"Your partner Farhan catches your eye across the room.","steps":[{"prompt":"Farhan asks: \"How are you really doing?\"","options":[{"text":"\"Honestly, I'm running low and I miss feeling like me.\"","then":"Farhan crosses the room and sits beside you. \"Tell me more.\"","best":true},{"text":"\"I'm fine, really. Everything's totally under control.\"","then":"Farhan studies you. \"You've said that for weeks. I'm not sure I believe it.\""},{"text":"\"Just tired, like every new parent. Nothing to talk about.\"","then":"Farhan nods slowly. \"Maybe. But it's been going on for weeks.\""},{"text":"\"Not now. I don't have the energy to explain it all.\"","then":"Farhan waits, then sits down anyway. \"Okay. I'm right here.\""}],"why":"Answering honestly instead of \"fine\" lets your partner actually help."},{"prompt":"Farhan says: \"Whatever's going on, I want to help. Where would I even start?\"","options":[{"text":"\"More help with night feeds, and an hour to myself each week.\"","then":"Farhan nods. \"Two nights a week. And Sunday afternoons.\"","best":true},{"text":"\"Nothing. I'll get through it somehow.\"","then":"Farhan looks unconvinced. Nothing is arranged."},{"text":"\"You should already know what I need.\"","then":"Farhan frowns. \"I honestly don't. Help me here.\""},{"text":"\"Whatever is easiest for you. I'll fit in.\"","then":"Farhan says good, and picks the easy thing."}],"why":"Naming specific help gives him something to do."},{"prompt":"Farhan says quietly: \"I've been assuming you were coping. Was I wrong?\"","options":[{"text":"\"Yes. I made it look easy. I'll tell you sooner now.\"","then":"Farhan takes your hand. \"Please do. I'd much rather know.\"","best":true},{"text":"\"It's fine. You couldn't have known. Forget it.\"","then":"Farhan looks relieved. The old pattern sits waiting."},{"text":"\"You never notice anything. That's the whole problem.\"","then":"Farhan goes quiet, hurt. Then: \"Maybe. So help me notice.\""},{"text":"\"No, I'm coping. It's just been a bad day.\"","then":"Farhan relaxes. The weeks of saying fine go unspoken again."}],"why":"Saying yes, and promising to tell him sooner, lets him help earlier."},{"prompt":"Farhan asks: \"How will I know when things get heavy next time?\"","options":[{"text":"\"I'll tell you plainly. If it lasts weeks, we see the doctor together.\"","then":"Farhan nods. \"Deal. And you ask me too, okay?\"","best":true},{"text":"\"You'll just notice. I'm sure it'll be obvious.\"","then":"Farhan frowns. \"It wasn't obvious this time.\""},{"text":"\"I'll say fine, but you'll know if I go quiet.\"","then":"Farhan nods slowly. He doesn't like guessing."},{"text":"\"I'm sure it won't. I'll be okay.\"","then":"Farhan says okay. Neither of you has a plan."}],"why":"A plain signal, plus a doctor if it lasts weeks, gives you both a plan."}],"relearn":"Answering honestly instead of 'I'm fine' lets your partner actually share the load and meet your needs."},
  {"id":"ly-1040","cat":"your-needs-count","type":"role-play","persona":"any","source":"decline warmly","hook":"Guests want to visit, but you're spent.","setup":"Your cousin Rekha calls to fix a date.","steps":[{"prompt":"Rekha says: \"We'd love to come this weekend! Is Saturday alright?\"","options":[{"text":"\"We'd love to see you. Not this week, though. Can we plan it later?\"","then":"Rekha's voice softens. \"Of course. How about the second weekend of next month?\"","best":true},{"text":"\"Of course. Come over. I'll manage somehow. I can't really say no to you.\"","then":"Rekha cheers. You put the phone down with a tight chest."},{"text":"\"Saturday is fine. Just don't expect me to host properly.\"","then":"Rekha laughs, unsure. \"We won't stay long.\" You dread it anyway."},{"text":"\"I'll let you know. I'm not sure how I'll be feeling.\"","then":"Rekha says okay. She's not sure whether to plan."}],"why":"Saying \"not this week\" with a later date protects your rest and the bond."},{"prompt":"Rekha adds: \"My mother wants to come too, and she likes to stay the whole day.\"","options":[{"text":"\"We'd love to see her. A short visit works best for me now.\"","then":"Rekha laughs. \"Short and sweet. I'll tell her.\"","best":true},{"text":"\"She can stay all day. I'll rest once everyone has gone home.\"","then":"Rekha cheers. Your rest gets pushed back again."},{"text":"\"Then she can wait. It's not up to her.\"","then":"Rekha stiffens. \"She only wants to see you both.\""},{"text":"\"Maybe nobody should come. Send photos instead.\"","then":"Rekha goes quiet. She isn't sure if that means never."}],"why":"Warmly naming a shorter visit keeps family close and protects your rest."},{"prompt":"Rekha asks: \"Can I help with anything from far away?\"","options":[{"text":"\"A call would help. So would a meal delivered midweek.\"","then":"Rekha laughs. \"Both. Consider it done.\"","best":true},{"text":"\"No, I'm okay. I don't want to be any trouble.\"","then":"Rekha says fine. She'd have liked to help."},{"text":"\"Just tell everyone I'm fine. That's all I need.\"","then":"Rekha agrees. The next week, everyone still thinks you're fine."},{"text":"\"Ask my mother what we need. She handles all that.\"","then":"Rekha says okay, though your mother has no idea what you need."}],"why":"Naming a small, concrete kind of help lets her actually do something."}],"relearn":"Saying 'love to, just not this week' protects the rest you need while keeping the relationship warm."},
  {"id":"ly-1041","cat":"your-needs-count","type":"spot","hook":"Spot the two thoughts that talk a parent out of their own needs.","scene":[{"id":"a","text":"\"A short rest will help me be patient\"","trick":false},{"id":"b","text":"\"If I ever rest, I'm a lazy parent\"","trick":true},{"id":"c","text":"\"Asking for help is okay\"","trick":false},{"id":"d","text":"\"My needs don't matter once I'm a parent\"","trick":true},{"id":"e","text":"\"A little time for me is fair\"","trick":false}],"why":"'Resting is lazy' and 'my needs don't matter' are the thoughts that erase your needs; the rest honour them.","relearn":"Watch for thoughts like 'resting is lazy' or 'my needs don't matter'; they talk you out of real needs.","persona":"Divya","source":"needs-erasing thoughts"},
  {"id":"ly-1042","cat":"your-needs-count","type":"spot","hook":"Spot the two lines in this chat that guilt-trip a tired parent.","scene":[{"id":"a","text":"\"Take the evening, you've earned a rest\"","trick":false},{"id":"b","text":"\"My mother managed five without complaining\"","trick":true},{"id":"c","text":"\"What can I take off your plate?\"","trick":false},{"id":"d","text":"\"You chose this, so don't complain now\"","trick":true},{"id":"e","text":"\"It's okay to need a break\"","trick":false}],"why":"'My mother managed without complaining' and 'you chose this, don't complain' are the guilt-trips; the others support.","relearn":"Spot guilt-trips like 'others managed without complaining' or 'you chose this'; needs are still valid.","persona":"any","source":"guilt-trip lines"},
  {"id":"ly-1043","cat":"your-needs-count","type":"spot","hook":"Spot the two habits that quietly erase a parent's identity.","scene":[{"id":"a","text":"Keeping one hobby going, even small","trick":false},{"id":"b","text":"Dropping every friend and interest","trick":true},{"id":"c","text":"Texting an old friend now and then","trick":false},{"id":"d","text":"Never once doing anything for yourself","trick":true},{"id":"e","text":"Holding onto something you love","trick":false}],"why":"Dropping everyone and never doing anything for yourself erase your identity; keeping small things protect it.","relearn":"Spot identity-erasing habits like dropping all friends or never doing anything for yourself.","persona":"any","source":"identity-erasing habits"},
  {"id":"ly-1044","cat":"your-needs-count","type":"spot","hook":"Spot the two beliefs that stop a dad from claiming his own needs.","scene":[{"id":"a","text":"\"I can want time for myself too\"","trick":false},{"id":"b","text":"\"Real men don't need anything\"","trick":true},{"id":"c","text":"\"Sharing the load is fair\"","trick":false},{"id":"d","text":"\"A dad asking for help looks weak\"","trick":true},{"id":"e","text":"\"My wellbeing matters to my kids\"","trick":false}],"why":"'Real men don't need anything' and 'asking for help looks weak' block a dad's needs; the others claim them.","relearn":"Spot dad-myths like 'real men need nothing' or 'asking looks weak'; fathers have needs too.","persona":"Vikram","source":"dad-blocking beliefs"},
  {"id":"ly-1045","cat":"your-needs-count","type":"spot","hook":"Spot the two things on this list that aren't really needs, just guilt in disguise.","scene":[{"id":"a","text":"A few hours of unbroken sleep","trick":false},{"id":"b","text":"A perfectly tidy house at all times","trick":true},{"id":"c","text":"One real adult conversation","trick":false},{"id":"d","text":"Replying to every relative instantly","trick":true},{"id":"e","text":"A short walk to clear your head","trick":false}],"why":"A spotless house and instant replies are guilt dressed as duty; sleep, conversation and a walk are real needs.","relearn":"Spot 'needs' that are really guilt, like a flawless house, and protect the real ones instead.","persona":"any","source":"guilt as duty"},
  {"id":"ly-1046","cat":"your-needs-count","type":"spot","hook":"Spot the two ways of 'helping' that actually pile more onto a stretched parent.","scene":[{"id":"a","text":"Taking the baby so they can shower","trick":false},{"id":"b","text":"Critiquing how they fold the clothes","trick":true},{"id":"c","text":"Cooking a meal unasked","trick":false},{"id":"d","text":"Visiting, then waiting to be served","trick":true},{"id":"e","text":"Doing the dishes quietly","trick":false}],"why":"Critiquing and visiting-to-be-served add to the load; taking the baby, cooking and doing dishes truly help.","relearn":"Spot 'help' that adds work, like critiquing or visiting to be served, versus help that lifts the load.","persona":"any","source":"fake help"},
  {"id":"ly-1047","cat":"your-needs-count","type":"spot","hook":"Spot the two phrases a parent uses to talk themselves out of resting.","scene":[{"id":"a","text":"\"I'll rest once this one thing's done\"","trick":false},{"id":"b","text":"\"I don't deserve rest until it's all done\"","trick":true},{"id":"c","text":"\"A short break now would help\"","trick":false},{"id":"d","text":"\"Resting means I'm letting everyone down\"","trick":true},{"id":"e","text":"\"It's okay to stop and breathe\"","trick":false}],"why":"'I don't deserve rest until it's all done' and 'resting lets everyone down' block rest you actually need.","relearn":"Spot rest-blocking phrases like 'I don't deserve it yet' or 'resting lets people down'.","persona":"Divya","source":"rest-blocking phrases"},
];

